-- Machine-assisted English translations of repository-provided TourStory copy.
-- Apply AFTER english_story_content_seed.sql and english_story_names_seed.sql.
-- The 6 manually translated cards in the first seed are excluded here.
-- Existing English and changed Korean source are never overwritten.
-- Review proper names, historical facts, and fluency before production use.
BEGIN;
CREATE TEMP TABLE oiso_story_longform_en (spot_id bigint, field_name text, source_ko text, english text) ON COMMIT DROP;
INSERT INTO oiso_story_longform_en (spot_id, field_name, source_ko, english) VALUES
    (1, 'summary', '산내 명수관광농원은 경북 경주시 산내면 감산리에 자리 잡았다.', 'Sannae Myeongsu Tourist Farm is located in Gamsan-ri, Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (1, 'intro', '산내 명수관광농원은 경북 경주시 산내면 감산리에 자리 잡았다. 경주시청을 기점으로 25㎞가량 떨어졌다.', 'Sannae Myeongsu Tourist Farm is located in Gamsan-ri, Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 25km away from Gyeongju City Hall.'),
    (1, 'story', '자동차로 건포산업로와 단석로를 번갈아 달리면 닿는다.
도착까지 걸리는 시간은 30분 안팎이다.
캠핑장은 다양한 수목이 식재되어 있어 더없이 자연친화적이다.', 'You can reach it by driving alternately between Geonpo Industrial Road and Danseok Road.
It takes about 30 minutes to arrive.
The campsite is planted with a variety of trees, making it extremely eco-friendly.'),
    (1, 'tip', '명수원은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'At Myeongsuwon, the site type and equipment provided may vary depending on the location. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (1, 'did_you_know', '경주시청을 기점으로 25㎞가량 떨어졌다고 해요.', 'It is said to be about 25km away from Gyeongju City Hall.'),
    (2, 'summary', '(보문산카라반파크)은 경북 경주시 천군동에 자리 잡고 있다.', '(Bomunsan Caravan Park) is located in Cheongun-dong, Gyeongju-si, Gyeongsangbuk-do.'),
    (2, 'intro', '유니레저 경주지점(보문산카라반파크)은 경북 경주시 천군동에 자리 잡고 있다. 경주시청을 기점으로 8㎞가량 떨어져 있다.', 'Unileisure Gyeongju Branch (Bomunsan Caravan Park) is located in Cheongun-dong, Gyeongju-si, Gyeongsangbuk-do. It is about 8km away from Gyeongju City Hall.'),
    (2, 'story', '자동차로 산업로와 동방북길을 번갈아 달리면 닿는다.
도착까지 걸리는 시간은 15분 안팎이다.
캠핑장에는 일반캠핑 사이트 3면과 카라반 17대가 마련되어 있다.', 'You can reach it by driving alternately along Industrial Road and Dongbangbuk Road.
It takes about 15 minutes to arrive.
The campsite has three general camping sites and 17 caravans.'),
    (2, 'tip', '유니레저 경주지점에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Unileisure Gyeongju branch, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (2, 'did_you_know', '도착까지 걸리는 시간은 15분 안팎이에요.', 'It takes about 15 minutes to arrive.'),
    (3, 'summary', '경주 황성공원은 신라 때 화랑들의 훈련장으로 쓰인 역사가 있는 오래된 숲에 자리해 있다.', 'Gyeongju Hwangseong Park is located in an old forest with a history of being used as a training ground for Hwarangs during the Silla Dynasty.'),
    (3, 'intro', '경주 황성공원은 신라 때 화랑들의 훈련장으로 쓰인 역사가 있는 오래된 숲에 자리해 있다. 삼릉에 뒤지지 않는 멋스러운 소나무와 수 백 년 수령을 자랑하는 고목이 어우러져 울창한 숲을 이룬다.', 'Gyeongju Hwangseong Park is located in an old forest with a history of being used as a training ground for Hwarangs during the Silla Dynasty. Stylish pine trees that are comparable to those of Samneung and old trees that are hundreds of years old combine to form a dense forest.'),
    (3, 'story', '여름이면 솔숲 산책로에 맥문동 군락이 조성되어 수려한 풍광을 더 해주고 가을이면 느티나무, 상수리나무, 떡갈나무에 단풍이 아늑하게 물든다.
또한 도심 속 힐링 공간으로 경주 시민과 관광객의 사랑을 지속적으로 받고 있으며 문화유적 답사에 지친 여행자들의 발을 편하게 해주는 쉼터 구실을 하고 있다.
가을 10월 초순에는 격년제로 신라문화제가 개최해 볼거리를 더해준다.', 'In the summer, a colony of liriope is created along the pine forest trail, adding to the beautiful scenery, and in the fall, the zelkova, oak, and oak trees are beautifully colored with autumn leaves.
In addition, it continues to be loved by Gyeongju citizens and tourists as a healing space in the city, and serves as a resting place to ease the feet of travelers tired from exploring cultural heritage sites.
In the fall and early October, the biennial Silla Cultural Festival is held, adding to the attractions.'),
    (3, 'tip', '황성공원은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk through Hwangseong Park in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (3, 'did_you_know', '여름이면 솔숲 산책로에 맥문동 군락이 조성되어 수려한 풍광을 더 해주고 가을이면 느티나무, 상수리나무, 떡갈나무에 단풍이 아늑하게 물든다고 해요.', 'In the summer, a colony of liriope is created along the pine forest trail, adding to the beautiful scenery, and in the fall, the zelkova trees, oak trees, and oak trees are beautifully colored with autumn leaves.'),
    (4, 'summary', '경북 경주시 보불로에 위치하고 있다.', 'It is located in Bobul-ro, Gyeongju-si, Gyeongsangbuk-do.'),
    (4, 'intro', '토함산 락 글램핑은 경북 경주시 보불로에 위치하고 있다. 불국사와 보문단지에서 5분여의 거리에 있으며 탁 트인 하동 저수지가 바로 눈아래 펼쳐져 있다.', 'Tohamsan Rock Glamping is located in Bobul-ro, Gyeongju-si, Gyeongsangbuk-do. It is about 5 minutes away from Bulguksa Temple and Bomun Complex, and the open Hadong Reservoir is spread out right under your eyes.'),
    (4, 'story', '펜션과 글램핑 시설을 이용할 수 있으며 부대시설로는 야외수영장, 바베큐장, 농구장이 마련되어 있다.
글랭핑장 내에 매점은 따로 운영하지 않고, 차로 10분 거리에 중형 마트가 위치하고 있어 필요한 물품은 미리 구입해 오는 것이 좋다.
오늘의 토함산 락 글램핑은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Pensions and glamping facilities are available, and additional facilities include an outdoor swimming pool, barbecue area, and basketball court.
There is no separate store in Glang Pingjang, and there is a mid-sized supermarket 10 minutes away by car, so it is recommended to purchase necessary items in advance.
Today’s Tohamsan Rock Glamping remains a different memory for each person visiting Gyeongju.'),
    (4, 'tip', '토함산 락 글램핑 안에는 매점이 없거나 물품 구입이 어려울 수 있어요. 식재료와 음료, 필요한 장비는 도착 전에 준비하는 편이 좋아요.', 'There are no shops inside Tohamsan Rock Glamping, or it may be difficult to purchase items. It is best to prepare food, drinks, and necessary equipment before arrival.'),
    (4, 'did_you_know', '글랭핑장 내에 매점은 따로 운영하지 않고, 차로 10분 거리에 중형 마트가 위치하고 있어 필요한 물품은 미리 구입해 오는 것이 좋다고 해요.', 'There is no separate store in Glang Pingjang, and there is a medium-sized supermarket 10 minutes away by car, so it is recommended to purchase necessary items in advance.'),
    (6, 'summary', '2022년 12월 15일 개관한 신라천년서고는 박물관 소장 도서를 열람할 수 있는 박물관 내 도서관이다.', 'The Silla Millennium Library, which opened on December 15, 2022, is a library within the museum where books in the museum''s collection can be viewed.'),
    (6, 'intro', '2022년 12월 15일 개관한 신라천년서고는 박물관 소장 도서를 열람할 수 있는 박물관 내 도서관이다. 이곳은 기존에 수장고로 이용되던 건물로, 한옥 형태의 외관은 그대로 살리고 내부는 현대적으로 재해석해 리모델링했다.', 'The Silla Millennium Library, which opened on December 15, 2022, is a library within the museum where books in the museum''s collection can be viewed. This is a building that was previously used as a storage facility, and the Hanok-style exterior was preserved while the interior was remodeled and reinterpreted in a modern way.'),
    (6, 'story', '이곳에서는 국립경주박물관에서 발간한 도서뿐 아니라 국내외 전시 도록과 신라 및 경주학 관련 도서 등을 소장하고 있다.
또한 별도로 마련된 북큐레이션룸에서는 박물관 큐레이터와 사서가 함께 고른 책들을 주제에 맞춰 소개하며, 책과 관련된 다양한 행사를 진행한다.
이 건물은 한국실내건축가협회(KOSID)가 주관하는 2022년 골든 스케일 베스트어워드 협회상을 수상했다.', 'It houses not only books published by the Gyeongju National Museum, but also domestic and international exhibition catalogs and books related to Silla and Gyeongju studies.
In addition, in a separate book curation room, books selected by museum curators and librarians are introduced according to theme, and various book-related events are held.
This building won the 2022 Golden Scale Best Award Association Award hosted by the Korean Society of Interior Architects (KOSID).'),
    (6, 'tip', '국립경주박물관 신라천년서고을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju National Museum’s Silla Millennium Archives, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (6, 'did_you_know', '2022년 12월 15일 개관한 신라천년서고는 박물관 소장 도서를 열람할 수 있는 박물관 내 도서관이에요.', 'The Silla Millennium Library, which opened on December 15, 2022, is a library within the museum where you can browse the books in the museum’s collection.'),
    (8, 'summary', '서라벌 CC는 경상북도 경주시 외동읍에 위치하고 있다.', 'Seorabeol CC is located in Oedong-eup, Gyeongju-si, Gyeongsangbuk-do.'),
    (8, 'intro', '서라벌 CC는 경상북도 경주시 외동읍에 위치하고 있다. 클럽 하우스를 중심으로 좌우 능선이 36홀의 코스를 감싸고 있어 클럽 하우스에서 내려다보는 전경은 편안하면서도 와이드 하다.', 'Seorabeol CC is located in Oedong-eup, Gyeongju-si, Gyeongsangbuk-do. With the clubhouse at the center, the left and right ridges surround the 36-hole course, so the view from the clubhouse is comfortable and wide.'),
    (8, 'story', '9홀 단위로 특징이 차별화된 홀들은 서로 조화를 이루면서도 각각 독립성을 유지하여 플레이어가 최상의 조건으로 즐길 수 있다.
자연 지형을 최대한 살려 공략에 대한 묘미를 배가 시켰다.
계곡을 그대로 이용하여 코스를 조성하고, 자연계류와 연못을 재생하여 마치 자연 속에 그대로 안착된 듯한 홀을 만들었다.', 'The holes, which have differentiated characteristics in each 9-hole unit, are in harmony with each other while maintaining their independence, allowing players to enjoy the game under the best conditions.
The natural terrain was utilized as much as possible to double the excitement of the strategy.
A course was created using the valley, and natural streams and ponds were regenerated to create holes that felt as if they were nestled in nature.'),
    (8, 'tip', '서라벌CC에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Seorabeol CC. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (8, 'did_you_know', '클럽 하우스를 중심으로 좌우 능선이 36홀의 코스를 감싸고 있어 클럽 하우스에서 내려다보는 전경은 편안하면서도 와이드 하다고 해요.', 'The ridges on the left and right surrounding the clubhouse surround the 36-hole course, so the view from the clubhouse is comfortable and wide.'),
    (9, 'summary', '기존의 우리에 갇힌 동물을 밖에서 보는 것이 아니라, 커다란 새 장 속으로 직접 들어가서 새들을 만지고 어깨에 올려보고 하는 공간이다.', 'Rather than viewing animals confined in existing cages from the outside, this is a space where you can go directly into a large cage, touch the birds, and place them on your shoulder.'),
    (9, 'intro', '경주 버드파크는 기존의 우리에 갇힌 동물을 밖에서 보는 것이 아니라, 커다란 새 장 속으로 직접 들어가서 새들을 만지고 어깨에 올려보고 하는 공간이다. 동물도, 구경하는 관람객도 함께 공간에 존재하며 즐거움을 느낄 수 있는 설계로 국내 최초의 체험형 버드파크이다.', 'Gyeongju Bird Park is a space where, rather than viewing animals confined in existing cages from outside, you can go directly into a large cage, touch the birds, and place them on your shoulder. It is Korea''s first experiential bird park with a design that allows both animals and visitors to experience enjoyment by existing in the space together.'),
    (9, 'story', '조류는 물론 카피바라, 알락꼬리 원숭이, 당나귀, 등 다양한 파충류, 물고기, 동물도 함께 관람이 가능하다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 경주 버드파크은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'In addition to birds, you can also see various reptiles, fish, and animals such as capybaras, ring-tailed monkeys, and donkeys.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Gyeongju Bird Park leaves a different memory for each person who visits Gyeongju.'),
    (9, 'tip', '경주 버드파크을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Bird Park, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (9, 'did_you_know', '동물도, 구경하는 관람객도 함께 공간에 존재하며 즐거움을 느낄 수 있는 설계로 국내 최초의 체험형 버드파크이에요.', 'It is Korea''s first experiential bird park, designed so that both animals and visitors can enjoy being in the same space.'),
    (10, 'summary', '2000년 12월에 유네스코 세계유산으로 등재된 경주역사유적지구(慶州歷史遺蹟地區)는 신라시대(新羅, 57-935)의 고도인 경주의 역사와 문화를 고스란히 담고있는 유적 지구(地區)이다.', 'Gyeongju Historic Areas, registered as a UNESCO World Heritage Site in December 2000, is a historic district that contains the history and culture of Gyeongju, the ancient capital of the Silla Dynasty (57-935).'),
    (10, 'intro', '2000년 12월에 유네스코 세계유산으로 등재된 경주역사유적지구(慶州歷史遺蹟地區)는 신라시대(新羅, 57-935)의 고도인 경주의 역사와 문화를 고스란히 담고있는 유적 지구(地區)이다. 유적의 성격에 따라 모두 5개 지구로 나누어져 있는데 불교미술의 보고인 남산지구, 천년왕조의 궁궐터인 월성지구, 신라 왕을 비롯한 고분군 분포지역인 대능원지구, 신라불교의 정수인 황룡사지구, 왕경 방어시설의 핵심인 산성지구로 구분되어 있으며 52개의 지정문화유산이 세계유산지역에 포함되어 있다.', 'Gyeongju Historic Areas, registered as a UNESCO World Heritage Site in December 2000, is a historic district that contains the history and culture of Gyeongju, the ancient capital of the Silla Dynasty (57-935). According to the nature of the ruins, it is divided into five districts: Namsan District, a treasure trove of Buddhist art, Wolseong District, the site of a thousand-year-old dynasty, Daeneungwon District, the distribution area of ​​ancient tombs including Silla kings, Hwangnyongsa District, the essence of Silla Buddhism, and Sanseong District, the core of the royal defense facilities. 52 designated cultural heritage sites are included in the World Heritage Area.'),
    (10, 'story', '남산지구에는 경주 남산 미륵곡 석조 여래좌상, 경주 남산 용장사곡 삼층석탑, 남간사지석정, 경주 남산 불곡 마애여래좌상 등이 있고 월성 지구에는 경주 계림, 경주 월성, 경주 동궁과 월지, 경주 첨성대가 있다.
또한 대능원지구에는 경주 미추왕릉, 경주 오릉, 경주 노동리고분군 등이 있으며 황룡사 지구에는 경주 황룡사지, 경주 분황사 모전석탑이 산성지구에는 경주 명활성이 있다.
오늘의 경주역사유적지구 [유네스코 세계유산]은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'In the Namsan district, there are the stone seated Buddha of Mireukgok in Namsan, Gyeongju, the three-story stone pagoda of Yongjangsagok in Namsan, Gyeongju, the stone pavilion at Namgansaji, and the seated Buddha of Buddha in Bulgok, Namsan, Gyeongju. The Wolseong district includes Gyerim, Gyeongju, Wolseong, Donggung and Wolji in Gyeongju, and Cheomseongdae in Gyeongju.
Also, in the Daeneungwon district, there are Gyeongju King Michu''s Tomb, Gyeongju Oreung, and Gyeongju Nodong-ri Tomb, and in the Hwangnyongsa District, there is Gyeongju Hwangnyongsa Temple Site and Gyeongju Bunhwangsa Temple Stone Pagoda, and in the Sanseong District, Gyeongju Myeonghyeong Shrine.
Today''s Gyeongju Historic Areas [UNESCO World Heritage Site] leaves a different memory for each person who visits Gyeongju.'),
    (10, 'tip', '경주역사유적지구 [유네스코 세계유산]에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At the Gyeongju Historic Site [UNESCO World Heritage], walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (10, 'did_you_know', '2000년 12월에 유네스코 세계유산으로 등재된 경주역사유적지구(慶州歷史遺蹟地區)는 신라시대(新羅, 57-935)의 고도인 경주의 역사와 문화를 고스란히 담고있는 유적 지구(地區)이에요.', 'Gyeongju Historic Areas, registered as a UNESCO World Heritage Site in December 2000, is a historic district that contains the history and culture of Gyeongju, the ancient capital of the Silla Dynasty (57-935).'),
    (11, 'summary', '인기 걸그룹 핑클 멤버들이 출연했던 JTBC 예능프로그램 〈캠핑클럽〉 촬영지로 유명하다.', 'It is famous as a filming location for the JTBC entertainment program “Camping Club,” in which members of the popular girl group Fin.K.L. appeared.'),
    (11, 'intro', '인기 걸그룹 핑클 멤버들이 출연했던 JTBC 예능프로그램 〈캠핑클럽〉 촬영지로 유명하다. 당시 드넓은 잔디밭과 탁 트인 전망을 자랑하는 명상바위 등 경주의 매력적인 풍광들을 소개하며 시청자들의 눈길을 끌었다.', 'It is famous as a filming location for the JTBC entertainment program “Camping Club,” in which members of the popular girl group Fin.K.L. appeared. At the time, it attracted the attention of viewers by introducing the attractive scenery of Gyeongju, such as the wide lawn and Meditation Rock with an open view.'),
    (11, 'story', '신라 화랑 김유신이 수련하며 검으로 바위를 갈랐다는 이야기가 전하는 단석산 등산로 입구에 있어 화랑의 언덕이라고 이름 붙였다.
방송에서처럼 널찍한 잔디밭과 걷기 좋은 산책로, 서정적인 풍경의 저수지가 한데 어우러져 느긋하게 쉬어가기 좋다.
여름에는 노란 해바라기, 가을에는 은빛 억새가 일렁이며 계절의 정취를 만끽할 수 있다.', 'It was named Hwarang''s Hill because it is located at the entrance to the Danseok Mountain hiking trail, where the story goes that Silla Hwarang Kim Yu-shin cut rocks with a sword while training.
Just like in the broadcast, the spacious lawn, easy-to-walk trails, and reservoir with lyrical scenery all come together, making it a great place to relax.
You can enjoy the mood of the season with yellow sunflowers in summer and silver silver grass swaying in autumn.'),
    (11, 'tip', '화랑의 언덕을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Hwarang Hill, check out the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (11, 'did_you_know', '현재 관람 시간 내에 산책과 피크닉만 가능하고 캠핑이나 차박은 불가하다고 해요.', 'It is said that only walking and picnicking are allowed during the current viewing hours, and camping or car camping is not allowed.'),
    (12, 'summary', '신라 신문왕 2년(682)에 설립된 신라 최초의 국립대학인 ‘국학’이 있던 곳이다.', 'This is the location of ‘Gukhak’, the first national university of Silla, established in the 2nd year of King Sinmun of Silla (682).'),
    (12, 'intro', '경주 교촌마을은 신라 신문왕 2년(682)에 설립된 신라 최초의 국립대학인 ‘국학’이 있던 곳이다. 이 교육기관은 시대에 따라 변화하며 고려시대에는 향학, 조선시대에는 향교로 이어졌다.', 'Gyeongju Gyochon Village is the location of ‘Gukhak’, the first national university of Silla, established in the 2nd year of King Sinmun of Silla (682). This educational institution changed with the times, leading to Hyanghak during the Goryeo Dynasty and Hyanggyo during the Joseon Dynasty.'),
    (12, 'story', '마을 이름이 교동, 교촌, 교리 등으로 불린 것도 모두 향교가 있던 곳이라는 사실에서 비롯된다.
마을 주변에는 삼국유사 속 이야기보따리가 곳곳에 숨겨져 있다.
김알지가 태어난 계림, 원효스님과 요석공주의 사랑을 이어준 문천교(蚊川橋) 터, 김유신이 살던 재매정, 월정교와 충담스님, 도화녀를 사랑한 진지왕, 선덕여왕이 만든 첨성대 등 수많은 이야기의 흔적이 교촌과 남천을 따라 펼쳐져 있다.', 'The village names such as Gyo-dong, Gyochon, and Gyori all originate from the fact that they were the location of a local Confucian school.
Around the village, bundles of stories from the Samguk Yusa are hidden here and there.
Traces of numerous stories are spread along Gyochon and Namcheon, including Gyerim where Kim Al-ji was born, the site of Muncheongyo Bridge that connected the love between Monk Wonhyo and Princess Yoseok, Jaemaejeong where Kim Yu-shin lived, Woljeonggyo Bridge and Monk Chungdam, King Jinji who loved Dohwanyeo, and Cheomseongdae built by Queen Seondeok.'),
    (12, 'tip', '경주 교촌마을은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Kyochon Village in Gyeongju just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (12, 'did_you_know', '경주 교촌마을은 신라 신문왕 2년(682)에 설립된 신라 최초의 국립대학인 ‘국학’이 있던 곳이에요.', 'Gyeongju Gyochon Village is the location of ‘Gukhak’, the first national university of Silla, established in the 2nd year of King Sinmun of Silla (682).'),
    (13, 'summary', '경주 쪽샘지구는 대릉원 동쪽에 위치한 황오리 고분군(황오동, 황남동, 인왕동) 일대를 일컫는 것으로 4~6세기 신라 왕족과 귀족의 집단 묘역으로 총면적은 38만 4000㎡ 정도의 국내 대표적 신라 왕족 및 귀족 유물 발굴지다.', 'Gyeongju Jjoksaem District refers to the area of ​​the Hwangori Ancient Tombs (Hwango-dong, Hwangnam-dong, and Inwang-dong) located to the east of Daereungwon. It is a mass grave site for the Silla royal family and nobles from the 4th to 6th centuries, and is Korea''s representative excavation site for Silla royal and noble relics with a total area of ​​approximately 384,000 m2.'),
    (13, 'intro', '경주 쪽샘지구는 대릉원 동쪽에 위치한 황오리 고분군(황오동, 황남동, 인왕동) 일대를 일컫는 것으로 4~6세기 신라 왕족과 귀족의 집단 묘역으로 총면적은 38만 4000㎡ 정도의 국내 대표적 신라 왕족 및 귀족 유물 발굴지다. 1960년대 이후 이곳에 민가가 들어서면서 고분 유적의 훼손이 심각해짐에 따라 문화재청과 경주시는 고분군 발굴을 위해 이 지역 민가와 사유지 등을 사들인 뒤 2007년부터 발굴을 시작하였다.', 'Gyeongju Jjoksaem District refers to the area of the Hwangori Ancient Tombs (Hwango-dong, Hwangnam-dong, and Inwang-dong) located to the east of Daereungwon. It is a mass grave site for the Silla royal family and nobles from the 4th to 6th centuries, and is Korea''s representative excavation site for Silla royal and noble relics with a total area of approximately 384,000 m2. As private houses were built here after the 1960s, damage to the tomb ruins became more serious, and the Cultural Heritage Administration and Gyeongju City began excavating in 2007 after purchasing private houses and private land in the area to excavate the tomb group.'),
    (13, 'story', '경주시는 연면적 1,900여㎡, 2층 규모의 쪽샘지구유적발굴관을 지어 수장고와 함께 내부에 유물 발굴 공간을 직접 볼 수 있는 관람 통로 등이 설치되어 있고 2층 전체는 유리로 마감되어 쪽샘지구 발굴 현장을 한눈에 관람할 수 있도록 하였다.
국내 최대 규모의 왕족과 귀족들이 집단 묘역인 쪽샘지구 고분 발굴 현장을 일반인들이 직접 관람할 수 있는 것은 물론, 발굴 과정과 발굴된 고분에 대한 이야기와 사진 등이 전시되어 있다.
오늘의 경주쪽샘유적발굴관은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Gyeongju City built a two-story Jjoksaem Earth Relics Excavation Hall with a total floor area of 1,900 m2, and installed a storage room as well as a viewing passage to directly view the relic excavation space inside. The entire second floor was covered with glass to allow a panoramic view of the Jjoksaem Earth excavation site.
Not only can the general public directly view the excavation site of the ancient tombs in the Jjoksaem district, the largest mass grave of royal families and nobles in the country, but stories and photos about the excavation process and the excavated tombs are also on display.
Today''s Gyeongju Jjoksaem Relics Excavation Hall leaves a different memory for each person who visits Gyeongju.'),
    (13, 'tip', '경주쪽샘유적발굴관에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At the Gyeongju Jjoksaem Relics Excavation Museum, choose the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (13, 'did_you_know', '경주 쪽샘지구는 대릉원 동쪽에 위치한 황오리 고분군(황오동, 황남동, 인왕동) 일대를 일컫는 것으로 4~6세기 신라 왕족과 귀족의 집단 묘역으로 총면적은 38만 4000㎡ 정도의 국내 대표적 신라 왕족 및 귀족 유물 발굴지다고 해요.', 'Gyeongju Jjoksaem District refers to the area of the Hwangori Ancient Tombs (Hwango-dong, Hwangnam-dong, and Inwang-dong) located to the east of Daereungwon. It is a mass grave site for the Silla royal family and nobles from the 4th to 6th centuries, and is said to be Korea''s representative excavation site for Silla royal and noble relics with a total area of approximately 384,000 m2.'),
    (14, 'summary', '경주 월성은 신라 파사이사금 22년(101)에 축조된 것으로 전해지는 신라시대 왕궁터이다.', 'Wolseong in Gyeongju is the site of a royal palace during the Silla Dynasty that is said to have been built in the 22nd year of Pasaysageum (101) of the Silla Dynasty.'),
    (14, 'intro', '경주 월성은 신라 파사이사금 22년(101)에 축조된 것으로 전해지는 신라시대 왕궁터이다. 국립경주문화유산연구소에서는 2014년부터 경주 월성 발굴조사를 진행하고 있으며, 그 성과를 국민과 공유하기 위해 월성 발굴조사 교육해설 프로그램 ''월성이랑''을 운영하고 있다.', 'Wolseong in Gyeongju is the site of a royal palace during the Silla Dynasty that is said to have been built in the 22nd year of Pasaysageum (101) of the Silla Dynasty. The National Gyeongju Cultural Heritage Research Institute has been conducting an excavation of Wolseong in Gyeongju since 2014, and is operating the Wolseong Excavation Education and Interpretation Program ‘Wolseong’ to share the results with the public.'),
    (14, 'story', '연구원이 직접 발굴 성과를 해설해 주는 프로그램으로 다른 기관에서는 쉽게 접하기 어려운 특별한 현장 해설을 경험할 수 있다.
모든 프로그램은 네이버 예약을 통해 사전 예약 후 참여할 수 있다.
다양한 교육 프로그램을 운영하며 월성을 찾는 관람객에게 발굴 성과와 역사 이야기를 알기 쉽게 전달하고 있다.', 'This is a program in which researchers directly explain the excavation results, allowing you to experience special on-site commentary that is difficult to access at other institutions.
You can participate in all programs after making a reservation in advance through Naver Reservation.
We operate a variety of educational programs and deliver the excavation results and historical stories to visitors visiting Wolseong in an easy-to-understand manner.'),
    (14, 'tip', '월성이랑은 현장 방문만으로 참여하기 어려울 수 있어요. 원하는 프로그램과 해설 시간을 먼저 확인하고 사전 예약을 마친 뒤 방문해 보세요.', 'It may be difficult to participate in Wolseong Rang only by visiting the site. Please check the desired program and commentary time first and make a reservation in advance before visiting.'),
    (14, 'did_you_know', '경주 월성은 신라 파사이사금 22년(101)에 축조된 것으로 전해지는 신라시대 왕궁터이에요.', 'Wolseong in Gyeongju is the site of a royal palace during the Silla Dynasty that is said to have been built in the 22nd year of Pasaysageum (101) of the Silla Dynasty.'),
    (15, 'summary', '경상북도 경주시 화랑마을 안에 위치한 캠핑장이다.', 'This is a camping site located in Hwarang Village, Gyeongju-si, Gyeongsangbuk-do.'),
    (15, 'intro', '화랑마을 오토캠핑장은 경상북도 경주시 화랑마을 안에 위치한 캠핑장이다. 화랑마을의 다양한 체험시설과 함께 이용할 수 있어 캠핑과 휴식을 동시에 즐기기 좋다.', 'Hwarang Village Auto Camping Site is a camping site located in Hwarang Village, Gyeongju-si, Gyeongsangbuk-do. It can be used in conjunction with Hwarang Village''s various experience facilities, making it a great place to enjoy camping and relaxation at the same time.'),
    (15, 'story', '데크로 조성된 오토캠핑 사이트 25면을 운영하며, 사이트당 최대 6명까지 이용할 수 있다.
공동취사장에는 샤워장과 개수대, 분리수거장이 마련되어 있으며, 무인매점에서는 음료와 간단한 간식을 구매할 수 있다.
화재 예방을 위해 숯과 목재를 이용한 취사와 화기 사용은 제한된다.', 'There are 25 auto camping sites constructed with decks, and each site can accommodate up to 6 people.
The communal kitchen is equipped with a shower, sink, and waste sorting station, and drinks and light snacks can be purchased at the unmanned kiosk.
To prevent fire, cooking with charcoal and wood and use of open flames are restricted.'),
    (15, 'tip', '화랑마을 오토캠핑장에서는 화재 예방을 위해 사용할 수 있는 조리도구와 연료가 제한될 수 있어요. 예약 전에 취사 규정을 확인해 장비를 맞춰 준비하세요.', 'At Hwarang Village Auto Camping Site, the cooking utensils and fuel that can be used to prevent fires may be limited. Please check the cooking regulations before booking to ensure you have the right equipment.'),
    (15, 'did_you_know', '데크로 조성된 오토캠핑 사이트 25면을 운영하며, 사이트당 최대 6명까지 이용할 수 있어요.', 'We operate 25 decked auto camping sites, and each site can accommodate up to 6 people.'),
    (16, 'summary', '경주 감포에 파도와 시간이 만들어낸 자연 조각품인 전촌용굴은 해식동굴로 전촌항 인근의 해안가에서 만나볼 수 있다.', 'Jeonchon Yonggul, a natural sculpture created by waves and time in Gampo, Gyeongju, is a sea cave that can be found on the coast near Jeonchon Port.'),
    (16, 'intro', '경주 감포에 파도와 시간이 만들어낸 자연 조각품인 전촌용굴은 해식동굴로 전촌항 인근의 해안가에서 만나볼 수 있다. 사룡굴과 단용굴 두 곳이 있으며 이름에서 유추할 수 있듯 용에 관한 설화를 품고 있다.', 'Jeonchon Yonggul, a natural sculpture created by waves and time in Gampo, Gyeongju, is a sea cave that can be found on the coast near Jeonchon Port. There are two caves, Saryonggul and Danyonggul, and as can be inferred from their names, they contain stories about dragons.'),
    (16, 'story', '사룡굴에는 동서남북의 방위를 지키는 네 마리의 용이 살았고 단용굴에는 감포 마을을 지키는 용이 한 마리 살았다는 이야기가 전해진다.
용이 드나들었을 법한 통로가 보이는 두 동굴은 감포읍의 스토리텔링 걷기 길인 감포깍지길 제1, 8구간 코스의 경유지이며 동해안 트레킹코스 해파랑길 11구간을 걷다
보면 만날 수 있는 경관이기도 하다.', 'The story goes that four dragons lived in Saryong Cave, guarding the directions of north, south, east, and west, and one dragon guarded Gampo Village, in Danyong Cave.
The two caves, where passages that dragons may have entered, are visible, are stopovers on sections 1 and 8 of Gampo-eup''s storytelling walking trail, Gampo Gakjigil, and section 11 of Haeparang-gil, an east coast trekking course.
It is also a landscape that can be seen when you look at it.'),
    (16, 'tip', '전촌용굴에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'In Jeonchon Yonggul, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (16, 'did_you_know', '사룡굴에는 동서남북의 방위를 지키는 네 마리의 용이 살았고 단용굴에는 감포 마을을 지키는 용이 한 마리 살았다는 이야기가 전해져요.', 'There is a story that there lived four dragons in Saryong Cave, who guarded the north, south, east, and west, and one dragon that guarded Gampo Village, in Danyong Cave.'),
    (17, 'summary', '월계수 오토캠핑장은 경상북도 경주시 산내면에 위치한 캠핑장으로, 울창한 숲과 계곡이 어우러진 자연 속에서 여유로운 캠핑을 즐길 수 있는 곳이다.', 'Wolgyesu Auto Camping Site is a camping site located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do, and is a place where you can enjoy leisurely camping in the nature of dense forests and valleys.'),
    (17, 'intro', '월계수 오토캠핑장은 경상북도 경주시 산내면에 위치한 캠핑장으로, 울창한 숲과 계곡이 어우러진 자연 속에서 여유로운 캠핑을 즐길 수 있는 곳이다. 여름철에는 계곡에서 물놀이를 함께 즐길 수 있어 가족 단위 캠핑객들에게 인기가 많다.', 'Wolgyesu Auto Camping Site is a camping site located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do, and is a place where you can enjoy leisurely camping in the nature of dense forests and valleys. In the summer, it is popular with family campers as they can enjoy water activities together in the valley.'),
    (17, 'story', '캠핑장은 파쇄석과 데크 사이트를 갖추고 있어 취향에 맞는 공간을 선택할 수 있으며, 숲으로 둘러싸인 쾌적한 환경에서 편안한 휴식을 즐길 수 있다.
개인 트레일러와 카라반의 출입이 가능하며, 소형 반려견과 함께 캠핑을 즐길 수 있는 것도 장점이다.
관리소에서는 릴선과 화로대 등 캠핑에 필요한 장비를 대여할 수 있어 보다', 'The campsite is equipped with crushed stone and deck sites, so you can choose a space that suits your taste, and enjoy a comfortable rest in a pleasant environment surrounded by forests.
Personal trailers and caravans are allowed, and another advantage is that you can enjoy camping with small dogs.
At the management office, you can rent equipment needed for camping, such as reel lines and fire stands.'),
    (17, 'tip', '월계수 캠핑장에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Wolgyesu Campground, check the operation status and conditions of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (17, 'did_you_know', '맑은 계곡과 숲이 만들어내는 자연 풍경 속에서 힐링을 즐기기 좋은 경주의 캠핑장이에요.', 'This is a camping site in Gyeongju that is great for enjoying healing in the natural scenery created by clear valleys and forests.'),
    (18, 'summary', '세계적인 건축 거장 쿠마 켄고가 경주 대릉원과 주상절리에서 영감을 받아 설계한 경주엑스포기념관 내에 위치한 세계문화유산 미디어 홍보관이다.', 'This is a World Cultural Heritage Media Promotion Center located within the Gyeongju Expo Memorial Hall, designed by world-renowned architect Kengo Kuma, inspired by Gyeongju Daereungwon and Columnar Joints.'),
    (18, 'intro', '살롱헤리티지는 세계적인 건축 거장 쿠마 켄고가 경주 대릉원과 주상절리에서 영감을 받아 설계한 경주엑스포기념관 내에 위치한 세계문화유산 미디어 홍보관이다. 18세기 유럽에서 대화와 교류의 장이었던 살롱(Salon)을 모티브로 조성되었다.', 'Salon Heritage is a World Cultural Heritage media promotion center located within the Gyeongju Expo Memorial Hall, designed by world-renowned architect Kengo Kuma with inspiration from Gyeongju Daereungwon and Columnar Joints. It was created with the motif of the Salon, which was a place for conversation and exchange in 18th-century Europe.'),
    (18, 'story', '내부에는 미디어스크린, 미디어터널, 세계유산 서재(살롱) 등 첨단 디지털 기술을 활용한 전시 공간이 마련되어 있으며, 세계문화유산의 기원과 세계유산 도시를 다양한 콘텐츠로 소개한다.
서재에서는 세계유산 관련 자료를 살펴볼 수 있고, 미디어월에서는 퀴즈를 통해 세계유산을 더욱 흥미롭게 체험할 수 있다.
오늘의 살롱헤리티지은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Inside, there is an exhibition space using cutting-edge digital technology, including a media screen, media tunnel, and World Heritage study (salon), and the origins of World Heritage and World Heritage cities are introduced through various contents.
In the study, you can look at World Heritage-related materials, and in the media wall, you can experience World Heritage in a more interesting way through quizzes.
Today’s Salon Heritage remains a different memory for each person who visits Gyeongju.'),
    (18, 'tip', '살롱헤리티지에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Salon Heritage, the experienced environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (18, 'did_you_know', '18세기 유럽에서 대화와 교류의 장이었던 살롱(Salon)을 모티브로 조성되었다고 해요.', 'It is said that it was created with the motif of the Salon, which was a place for conversation and exchange in 18th century Europe.'),
    (19, 'summary', '찬란한 빛의 신라''는 경주엑스포대공원 천마의 궁전에서 만날 수 있는 타임리스 미디어아트 전시다.', '‘Silla of Brilliant Light’ is a timeless media art exhibition that can be seen at the Palace of Cheonma at Gyeongju Expo Grand Park.'),
    (19, 'intro', '찬란한 빛의 신라''는 경주엑스포대공원 천마의 궁전에서 만날 수 있는 타임리스 미디어아트 전시다. 미디어아트 영상을 통해 작품과 직접 교감할 수 있는 첨단 전시를 선보이며, 유네스코 세계유산인 경주의 역사와 문화유산의 가치를 생생하게 전달하는 공간이다.', '‘Silla of Brilliant Light’ is a timeless media art exhibition that can be seen at the Palace of Cheonma at Gyeongju Expo Grand Park. It is a space that presents cutting-edge exhibitions that allow direct interaction with works of art through media art videos, and vividly conveys the value of the history and cultural heritage of Gyeongju, a UNESCO World Heritage site.'),
    (19, 'story', '경주의 대표적인 유산인 첨성대, 석굴암, 불국사, 동궁과 월지 등을 다채로운 색감과 몽환적인 미디어아트로 표현한 전시로 단순히 감상만 하는 전시가 아니라, 관람객의 움직임에 따라 작품이 반응하는 양방향 체험형 전시로, 온 가족이 함께 즐기기 좋다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 천마의 궁전은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'This is an exhibition that expresses Gyeongju''s representative heritage sites, such as Cheomseongdae, Seokguram Grotto, Bulguksa Temple, Donggung Palace, and Wolji Pond, with colorful colors and dreamy media art. It is not just an exhibition to just admire, but an interactive experiential exhibition in which the works react to the movements of visitors, making it great for the whole family to enjoy together.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Cheonma Palace remains a different memory for each person who visits Gyeongju.'),
    (19, 'tip', '천마의 궁전은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Cheonma’s Palace in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (19, 'did_you_know', '경주의 대표적인 유산인 첨성대, 석굴암, 불국사, 동궁과 월지 등을 다채로운 색감과 몽환적인 미디어아트로 표현한 전시로 단순히 감상만 하는 전시가 아니라, 관람객의 움직임에 따라 작품이 반응하는 양방향 체험형 전시로, 온 가족이 함께 즐기기 좋다고 해요.', 'This is an exhibition that expresses Gyeongju''s representative heritage sites, such as Cheomseongdae, Seokguram Grotto, Bulguksa Temple, Donggung Palace, and Wolji Pond, with colorful colors and dreamy media art. It is not an exhibition to simply admire, but an interactive experiential exhibition in which the works react to the movements of visitors, making it great for the whole family to enjoy together.'),
    (20, 'summary', '경주 황성공원 내에 있는 경주 예술의전당은 천년의 전통과 현대의 다양한 문화예술이 어우러지는 문화예술 창달의 구심점으로 지역 주민들을 위한 공연, 전시 등 다양한 문화예술을 보급하기 위한 목적으로 지하 2층, 지상 5층 규모의 건물로 세워졌다.', 'Gyeongju Arts Center, located within Gyeongju Hwangseong Park, is a center for the development of culture and arts where a thousand years of tradition and various modern cultures and arts are combined. It was built as a building with two floors underground and five floors above ground for the purpose of disseminating various cultural arts such as performances and exhibitions for local residents.'),
    (20, 'intro', '경주 황성공원 내에 있는 경주 예술의전당은 천년의 전통과 현대의 다양한 문화예술이 어우러지는 문화예술 창달의 구심점으로 지역 주민들을 위한 공연, 전시 등 다양한 문화예술을 보급하기 위한 목적으로 지하 2층, 지상 5층 규모의 건물로 세워졌다. 주요 시설로는 소리 울림이 좋은 대공연장, 돌출형 무대의 소공연장, 공원과 어우러진 야외공연장과 다양한 전시가 가능한 대전시실, 365일 선덕여왕을 만날 수 있는 소전시실, 지하의 알천 갤러리로 구성되어 있다.', 'Gyeongju Arts Center, located within Gyeongju Hwangseong Park, is a center for the development of culture and arts where a thousand years of tradition and various modern cultures and arts are combined. It was built as a building with two floors underground and five floors above ground for the purpose of disseminating various cultural arts such as performances and exhibitions for local residents. The main facilities consist of a large performance hall with good sound resonance, a small performance hall with a protruding stage, an outdoor performance hall in harmony with the park, a Daejeon exhibition hall where various exhibitions can be held, a small exhibition hall where you can see Queen Seondeok 365 days a year, and the Alcheon Gallery in the basement.'),
    (20, 'story', '그 밖에 강의실과 세미나실, 회의실과 영상 자료실, 장난감 도서관, 카페 등 여러 편의시설을 갖추고 있으며 전통 클래식은 물론 국악, 뮤지컬, 어린이 공연과 경주 문화 역사를 언제든 볼 수 있는 상설전과 기획전, 현대미술과 외부 대관에 의한 전시 등을 진행한다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 경주예술의전당은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'In addition, it is equipped with various convenient facilities such as classrooms, seminar rooms, conference rooms, video archives, toy libraries, and cafes. It also hosts traditional classics as well as traditional Korean music, musicals, children''s performances, permanent and special exhibitions where Gyeongju cultural history can be viewed at any time, modern art, and exhibitions through external rentals.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Gyeongju Arts Center leaves a different memory for each person who visits Gyeongju.'),
    (20, 'tip', '경주예술의전당을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Arts Center, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (20, 'did_you_know', '주요 시설로는 소리 울림이 좋은 대공연장, 돌출형 무대의 소공연장, 공원과 어우러진 야외공연장과 다양한 전시가 가능한 대전시실, 365일 선덕여왕을 만날 수 있는 소전시실, 지하의 알천 갤러리로 구성되어 있어요.', 'The main facilities include a large performance hall with good sound resonance, a small performance hall with a protruding stage, an outdoor performance hall in harmony with the park, a Daejeon exhibition hall where various exhibitions can be held, a small exhibition hall where you can see Queen Seondeok 365 days a year, and the Alcheon Gallery in the basement.'),
    (21, 'summary', '경주시 산내면의 맑은 자연 속에 자리한 캠핑장으로 계곡과 울창한 숲이 어우러진 쾌적한 환경을 자랑한다.', 'This camping site is located in the clear nature of Sannae-myeon, Gyeongju-si, and boasts a pleasant environment with a valley and dense forest.'),
    (21, 'intro', '전원일기오토캠핑장은 경주시 산내면의 맑은 자연 속에 자리한 캠핑장으로 계곡과 울창한 숲이 어우러진 쾌적한 환경을 자랑한다. 사이트는 계곡 가까운 곳과 수영장 인근, 숲속 공간 등 다양한 형태로 구성되어 있어 취향에 맞는 캠핑을 즐길 수 있다.', 'Jeonwonilgi Auto Camping Site is a camping site located in the clear nature of Sannae-myeon, Gyeongju-si, and boasts a pleasant environment with a valley and dense forest. The sites are composed of various types, such as near a valley, near a swimming pool, or in a forest, so you can enjoy camping to suit your taste.'),
    (21, 'story', '개인 카라반과 트레일러 이용이 가능하며 소형 반려견도 목줄 착용 시 함께 입장할 수 있다.
캠핑장에는 수영장과 계곡, 어린이들이 뛰어놀기 좋은 공간 등 가족 단위 여행객을 위한 시설이 마련되어 있으며 깨끗하게 관리되는 화장실과 샤워실, 개수대 등 편의시설도 갖추고 있다.
넓은 사이트와 여유로운 분위기 속에서 자연을 만끽할 수 있으며 경주의 다양한 관광지와도 가까워 캠핑과 여행을 함께 즐기기에 좋은 곳이다.', 'Personal caravans and trailers are available, and small dogs can also enter as long as they are on a leash.
The campsite is equipped with facilities for families, including a swimming pool, a stream, and a space for children to play. It also has cleanly maintained restrooms, showers, and sinks.
You can enjoy nature in a spacious site and a leisurely atmosphere, and it is close to various tourist attractions in Gyeongju, making it a great place to enjoy camping and traveling together.'),
    (21, 'tip', '전원일기오토캠핑장에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Power Diary Auto Camping Site. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (21, 'did_you_know', '넓은 사이트와 여유로운 분위기 속에서 자연을 만끽할 수 있으며 경주의 다양한 관광지와도 가까워 캠핑과 여행을 함께 즐기기에 좋은 곳이에요.', 'You can enjoy nature in a spacious site and a leisurely atmosphere, and it is close to various tourist attractions in Gyeongju, making it a great place to enjoy camping and traveling together.'),
    (22, 'summary', '한 여름 밤 경주엑스포대공원 내 화랑숲에서 진행하는 워킹 호러 체험 콘텐츠이다.', 'This is a walking horror experience content held in Hwarang Forest in Gyeongju Expo Grand Park on a midsummer night.'),
    (22, 'intro', 'EX HORROR 시즌 6 : 신라X좀비는 한 여름 밤 경주엑스포대공원 내 화랑숲에서 진행하는 워킹 호러 체험 콘텐츠이다. 1만 5천명 이상의 관객이 찾아오는 EX HORROR는 2㎞의 화랑숲 산책로를 이용하여 각종 공포 콘텐츠를 녹여내 관람객들의 인기를 사고 있다.', 'EX HORROR Season 6: Silla EX HORROR, which attracts more than 15,000 visitors, is gaining popularity among visitors by depicting various horror contents using the 2km Hwarang Forest trail.'),
    (22, 'story', '전 연령 관람객이 체험을 할 수 있으나 노약자 및 각종 질환자는 일신상의 문제가 발생할 수 있기에 관람을 제한하고 있으며 미취학 아동의 경우 성인 보호자와 동반 입장하여야 한다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 EX HORROR 시즌 6 : 신라X좀비은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Visitors of all ages can participate in the experience, but the elderly and those with various medical conditions are restricted from viewing as they may experience personal problems. Preschool children must enter accompanied by an adult guardian.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s EX HORROR Season 6: Shinra'),
    (22, 'tip', 'EX HORROR 시즌 6 : 신라X좀비은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'EX HORROR Season 6: Shinra Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (22, 'did_you_know', '전 연령 관람객이 체험을 할 수 있으나 노약자 및 각종 질환자는 일신상의 문제가 발생할 수 있기에 관람을 제한하고 있으며 미취학 아동의 경우 성인 보호자와 동반 입장하여야 해요.', 'Visitors of all ages can participate in the experience, but the elderly and those with various medical conditions are restricted from viewing as they may experience personal problems. Preschool children must enter accompanied by an adult guardian.'),
    (23, 'summary', '2007년부터 시작된 국내 최대 규모의 아마추어 대회인 제18회 대통령배 아마추어 이스포츠 대회와 전국 장애인 선수들이 참여하는 국내 대표 장애인 이스포츠 대회인 제4회 전국 장애인 이스포츠 대회 및 초대형 풀장과 워터바운스에서 즐기는 짜릿한 경주 워터풀 페스티벌을 결합하여 이스포츠와 물놀이를 함께…', 'The 18th President''s Cup Amateur Esports Competition, the largest amateur competition in Korea that started in 2007, the 4th National Disabled Esports Competition, the country''s representative disabled esports competition in which disabled athletes from all over the country participate, and the Waterpool Festival, a thrilling race enjoyed in a very large pool and water bounce, are combined to bring together esports and water play...'),
    (23, 'intro', '2026 경주 e스포츠 페스티벌은 2007년부터 시작된 국내 최대 규모의 아마추어 대회인 제18회 대통령배 아마추어 이스포츠 대회와 전국 장애인 선수들이 참여하는 국내 대표 장애인 이스포츠 대회인 제4회 전국 장애인 이스포츠 대회 및 초대형 풀장과 워터바운스에서 즐기는 짜릿한 경주 워터풀 페스티벌을 결합하여 이스포츠와 물놀이를 함께 즐길 수 있는 시원한 여름 축제로 개최된다. 2026 경주 e스포츠 페스티벌만의 공간과 분위기 속에서 경주의 또 다른 모습을 경험할 수 있습니다.', 'The 2026 Gyeongju Esports Festival combines the 18th President''s Cup Amateur Esports Competition, the largest amateur competition in Korea that started in 2007, the 4th National Disabled Esports Competition, the country''s representative esports competition for the disabled with the participation of disabled athletes from all over the country, and the thrilling Gyeongju Waterpool Festival in a very large pool and water bounce. It will be held as a cool summer festival where you can enjoy esports and water play together. You can experience a different side of Gyeongju in the unique space and atmosphere of the 2026 Gyeongju Esports Festival.'),
    (23, 'story', '이곳은 주변의 풍경과 어우러져 방문객에게 특별한 장면을 보여줍니다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 2026 경주 e스포츠 페스티벌은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'This place blends in with the surrounding landscape and presents a special scene to visitors.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s 2026 Gyeongju Esports Festival leaves a different memory for each person who visits Gyeongju.'),
    (23, 'tip', '2026 경주 e스포츠 페스티벌에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you are planning to play in the water at the 2026 Gyeongju Esports Festival, check the operation availability and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (23, 'did_you_know', '2026 경주 e스포츠 페스티벌은 2007년부터 시작된 국내 최대 규모의 아마추어 대회인 제18회 대통령배 아마추어 이스포츠 대회와 전국 장애인 선수들이 참여하는 국내 대표 장애인 이스포츠 대회인 제4회 전국 장애인 이스포츠 대회 및 초대형 풀장과 워터바운스에서 즐기는 짜릿한 경주 워터풀 페스티벌을 결합하여 이스포츠와 물놀이를 함께 즐길 수 있는 시원한 여름 축제로 개최돼요.', 'The 2026 Gyeongju Esports Festival combines the 18th President''s Cup Amateur Esports Competition, the largest amateur competition in Korea that started in 2007, the 4th National Disabled Esports Competition, Korea''s representative esports competition for the disabled with the participation of disabled athletes from all over the country, and the thrilling Gyeongju Waterpool Festival in a very large pool and water bounce, making it a cool summer festival where you can enjoy esports and water play together.'),
    (24, 'summary', '신라의 정원을 현대적인 미디어아트와 식물 전시로 풀어낸 경주 동궁원의 테마 공간이에요.', 'This is the theme space of Donggungwon in Gyeongju, which depicts the garden of Silla through modern media art and plant exhibitions.'),
    (24, 'intro', '라원은 ‘신라의 정원’이라는 이름처럼 천년 고도의 분위기를 빛과 식물, 전시 콘텐츠로 재해석한 공간이에요. 연못과 정원을 거닐다 전시관의 미디어아트까지 이어서 감상할 수 있어 가족 나들이와 저녁 산책에 잘 어울립니다.', 'As the name ‘Garden of Silla’ suggests, Rawon is a space that reinterprets the atmosphere of a thousand-year-old ancient capital through light, plants, and exhibition content. You can walk around the pond and garden and continue enjoying the media art in the exhibition hall, making it a great place for a family outing or evening walk.'),
    (24, 'story', '낮에는 식물과 정원의 색이 중심이 되고, 해가 지면 조명이 공간의 표정을 바꿔 놓아요. 전시관과 느티나무 광장, 연못이 하나의 동선으로 이어져 있어 신라의 자연관을 현대적인 감각으로 경험할 수 있습니다.', 'During the day, the colors of the plants and garden take center stage, and when the sun sets, the lighting changes the expression of the space. The exhibition hall, zelkova tree plaza, and pond are connected through a single circulation line, allowing you to experience Silla''s view of nature with a modern sense.'),
    (24, 'tip', '해 질 무렵 입장하면 낮의 정원과 야간 조명을 함께 볼 수 있어요. 미디어아트 상영 시간과 휴관일을 먼저 확인하고, 연못 주변까지 여유 있게 걸을 수 있도록 한 시간 이상 잡아 보세요.', 'If you enter at sunset, you can see the garden during the day and the lights at night. Check the media art screening times and closing days first, and set aside an hour or more to leisurely walk around the pond.'),
    (24, 'did_you_know', '‘라원’이라는 이름에는 신라의 정원을 오늘의 방식으로 다시 보여 주려는 뜻이 담겨 있어요.', 'The name ‘Rawon’ contains the meaning of showing Silla’s garden again in today’s style.'),
    (25, 'summary', '경북 경주시 강동면 형산강 변에 자리한 자연 친화적인 캠핑장이다.', 'It is an eco-friendly camping site located along the Hyeongsan River in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (25, 'intro', '무릉관광농원은 경북 경주시 강동면 형산강 변에 자리한 자연 친화적인 캠핑장이다. 울창한 수목이 조성되어 사계절 푸른 자연을 가까이에서 느낄 수 있으며, 조용하고 여유로운 분위기 속에서 캠핑을 즐기기 좋다.', 'Mureung Tourist Farm is a nature-friendly camping site located along the Hyeongsan River in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do. Thanks to the lush greenery, you can enjoy the green nature all year round, and enjoy camping in a quiet and leisurely atmosphere.'),
    (25, 'story', '파쇄석, 자갈, 데크, 마사토 등 다양한 형태의 오토캠핑 사이트를 갖추고 있어 취향에 맞게 이용할 수 있다.
캠핑장 내에는 체험빌리지와 산책로 등 다양한 부대시설이 마련되어 있어 가족 단위 방문객에게 특히 인기가 높으며, 아이들과 함께 다양한 체험과 야외 활동을 즐기기에도 좋다.
넓은 자연 공간에서 산책과 휴식을 만끽하며 일상의 여유를 느낄 수 있어 힐링 캠핑을 원하는 이들에게도 알맞은 곳이다.', 'There are various types of auto camping sites, including crushed stone, gravel, deck, and sandstone, so you can use them to suit your preference.
The camping site is equipped with various auxiliary facilities such as an experience village and walking trails, so it is especially popular with families and is also great for enjoying various experiences and outdoor activities with children.
It is also a suitable place for those who want healing camping, as they can enjoy walking and resting in a large natural space and relax from daily life.'),
    (25, 'tip', '무릉관광농원은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'At Mureung Tourist Farm, the site type and equipment provided may vary from site to site. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (25, 'did_you_know', '울창한 수목이 조성되어 사계절 푸른 자연을 가까이에서 느낄 수 있으며, 조용하고 여유로운 분위기 속에서 캠핑을 즐기기 좋다고 해요.', 'Because of the lush greenery, you can feel the green nature up close all year round, and it is said to be a great place to enjoy camping in a quiet and leisurely atmosphere.'),
    (26, 'summary', '휴앤락캠핑장은 경북 경주시 석장동에 위치하고 있다.', 'Hu&Lock Camping Site is located in Seokjang-dong, Gyeongju-si, Gyeongsangbuk-do.'),
    (26, 'intro', '휴앤락캠핑장은 경북 경주시 석장동에 위치하고 있다. 경주 시청을 기점으로 5㎞가량 떨어져 있고 도착까지 걸리는 시간은 15분 안팎이다.', 'Hu&Lock Camping Site is located in Seokjang-dong, Gyeongju-si, Gyeongsangbuk-do. It is about 5km away from Gyeongju City Hall, and it takes about 15 minutes to arrive.'),
    (26, 'story', '나지막한 산에 캠핑장이 있지만 발아래로 내려다보는 풍경이 일품이다.
샤워장과 화장실 등 부대시설은 깔끔하게 관리가 잘 되어있고 자동차 야영장 64면이 마련되어 있으며 바닥은 모두 자갈로 이루어져 있다.
캐인 트레일러와 카라반 출입이 자유롭고 반려동물 동반 입장도 가능하다.', 'There is a camping site on a low mountain, but the view down below is spectacular.
Auxiliary facilities such as showers and toilets are neatly maintained, and there are 64 car camping sites, and the floor is all made of gravel.
Cane trailers and caravans are free to enter, and pets are also allowed.'),
    (26, 'tip', '휴앤락오토캠핑장에 반려동물과 동행할 때는 출입 가능 구역과 목줄·배변 처리 규정을 먼저 확인하세요. 다른 방문객과 동물이 놀라지 않도록 한적한 동선부터 살펴보는 것이 좋아요.', 'When accompanying your pet to Hu&Lock Auto Camping Site, first check the entry area and leash/disposal regulations. It is a good idea to start from a quiet area so as not to startle other visitors and animals.'),
    (26, 'did_you_know', '경주 시청을 기점으로 5㎞가량 떨어져 있고 도착까지 걸리는 시간은 15분 안팎이에요.', 'It is about 5km away from Gyeongju City Hall and takes about 15 minutes to arrive.'),
    (27, 'summary', '첨성대(瞻星臺)와 월성(月城) 사이에 위치해 있으며, 경주 김씨의 시조 알지(閼智)가 태어났다는 전설이 있는 유서 깊은 곳이다.', 'It is located between Cheomseongdae and Wolseong, and is a historic place where there is a legend that Alji, the founder of the Gyeongju Kim clan, was born.'),
    (27, 'intro', '경주 계림은 첨성대(瞻星臺)와 월성(月城) 사이에 위치해 있으며, 경주 김씨의 시조 알지(閼智)가 태어났다는 전설이 있는 유서 깊은 곳이다. 신라 탈해왕(脫解王) 때 회공(瓠公)이 이 숲에서 닭이 우는소리를 들었는데, 가까이 가보니 나뭇가지에 금궤(金櫃)가 빛을 내며 걸려 있었다.', 'Gyerim, Gyeongju, is located between Cheomseongdae and Wolseong, and is a historic place where there is a legend that Alji, the founder of the Gyeongju Kim clan, was born. During the reign of King Talhae of Silla, Hoegong heard the sound of a rooster crowing in this forest, and when he got closer, he saw a shining golden chest hanging on a tree branch.'),
    (27, 'story', '이 사실을 임금께 아뢰어 왕이 몸소 숲에 가서 금궤를 내렸다.
뚜껑을 열자 궤 속에서 사내아이가 나왔다
하여 성(姓)을 김(金), 이름을 알지라 하고, 본래 시림(始林), 구림(鳩林)이라 하던 이 숲을 계림(鷄林)으로 부르게 되었다.', 'After reporting this to the king, the king himself went to the forest and took down the golden chest.
When I opened the lid, a boy came out of the chest.
So, his last name was Kim and his first name was Aljira, and this forest, which was originally called Sirim or Gurim, came to be called Gyerim.'),
    (27, 'tip', '경주 계림을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyerim, Gyeongju, check out the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (27, 'did_you_know', '경내의 비는 조선 순조(純祖) 3년(1803)에 세워진 것으로 김알지 탄생에 관한 기록이 새겨져 있어요.', 'The monument in the precincts was erected in the 3rd year of King Sunjo''s reign (1803) in the Joseon Dynasty and contains a record of the birth of Kim Al-ji.'),
    (28, 'summary', '월성은 신라 궁궐이 있었던 도성이다.', 'Wolseong is the capital where the Silla palace was located.'),
    (28, 'intro', '월성은 신라 궁궐이 있었던 도성이다. 성의 모양이 반달처럼 생겼다', 'Wolseong is the capital where the Silla palace was located. The shape of the castle looks like a half moon'),
    (28, 'story', '하여 반월성·신월성이라고도 하며, 왕이 계신 성이라 하여 재성(在城)이라고도 한다.
『삼국사기』에 의하면 파사왕 22년(101)에 성을 쌓고 금성에서 이곳으로 도성을 옮겼다고 전한다.
이 성은 신라 역대 왕들의 궁성이었으며, 문무왕 때에는 안압지·임해전·첨성대 일대가 편입되어 성의 규모가 확장되었다.', 'Therefore, it is also called Banwolseong and Shinwolseong, and it is also called Jaeseong (在城) because it is the castle where the king resides.
According to Samguk Sagi (History of the Three Kingdoms), the fortress was built in the 22nd year of King Pasa''s reign (101) and the capital was moved from Geumseong to here.
This castle was the palace of successive kings of Silla, and during the reign of King Munmu, the area around Anapji, Imhaejeon, and Cheomseongdae were incorporated and the size of the castle was expanded.'),
    (28, 'tip', '경주 월성을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Wolseong, Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (28, 'did_you_know', '『삼국사기』에 의하면 파사왕 22년(101)에 성을 쌓고 금성에서 이곳으로 도성을 옮겼다고 전해요.', 'According to Samguk Sagi (History of the Three Kingdoms), the fortress was built in the 22nd year of King Pasa''s reign (101) and the capital was moved from Geumseong to here.'),
    (30, 'summary', '경북 경주에 위치한 캠핑장으로 경주의 대표 관광지인 첨성대와 불국사는 물론 포항의 영일대해수욕장과 죽도시장까지 편리하게 이동할 수 있어 연계 관광을 즐기기에 좋다.', 'This camping site is located in Gyeongju, Gyeongbuk, and is convenient for visiting Gyeongju''s representative tourist attractions, Cheomseongdae and Bulguksa Temple, as well as Pohang''s Yeongildae Beach and Jukdo Market, making it ideal for enjoying linked tourism.'),
    (30, 'intro', '봄날처럼은 경북 경주에 위치한 캠핑장으로 경주의 대표 관광지인 첨성대와 불국사는 물론 포항의 영일대해수욕장과 죽도시장까지 편리하게 이동할 수 있어 연계 관광을 즐기기에 좋다. 주변에는 다양한 음식점도 자리하고 있어 여행과 미식을 함께 즐길 수 있다.', 'Like a Spring Day is a camping site located in Gyeongju, Gyeongbuk, and is convenient for visiting Gyeongju''s representative tourist attractions, Cheomseongdae and Bulguksa Temple, as well as Pohang''s Yeongildae Beach and Jukdo Market, making it a good place to enjoy linked tourism. There are various restaurants nearby, so you can enjoy traveling and gourmet food together.'),
    (30, 'story', '캠핑장은 파쇄석 오토캠핑 사이트를 갖추고 있으며 개인 카라반과 트레일러도 이용할 수 있다.
남녀 구분 화장실과 샤워실, 개수대 등 편의시설을 깨끗하게 관리하고 있으며 어린이 놀이방과 아담한 산책로도 마련되어 가족 단위 캠핑객이 편안하게 머물기 좋다.
오늘의 봄날처럼은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The campsite has a crushed stone auto camping site, and personal caravans and trailers are also available.
Amenities such as separate male and female restrooms, shower rooms, and sinks are kept clean, and a children''s playroom and small walking trail are also provided, making it ideal for family campers to stay comfortably.
A spring day like today remains a different memory for each person who visits Gyeongju.'),
    (30, 'tip', '봄날처럼에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Just Like a Spring Day. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (30, 'did_you_know', '남녀 구분 화장실과 샤워실, 개수대 등 편의시설을 깨끗하게 관리하고 있으며 어린이 놀이방과 아담한 산책로도 마련되어 가족 단위 캠핑객이 편안하게 머물기 좋다고 해요.', 'Convenience facilities such as separate male and female toilets, shower rooms, and sinks are kept clean, and a children''s playroom and small walking trail are also provided, making it ideal for family campers to stay comfortably.'),
    (31, 'summary', '경주 오아시스글램핑은 경주시 구정동 청량감 가득한 숲 속에 터를 잡았다.', 'Gyeongju Oasis Glamping is located in a refreshing forest in Gujeong-dong, Gyeongju.'),
    (31, 'intro', '경주 오아시스글램핑은 경주시 구정동 청량감 가득한 숲 속에 터를 잡았다. 마치 요새와 같은 느낌이다.', 'Gyeongju Oasis Glamping is located in a refreshing forest in Gujeong-dong, Gyeongju. It feels like a fortress.'),
    (31, 'story', '캠핑장에는 글램핑과 카라반이 마련되어 있다.
객실 내부에는 침대, 에어컨, 냉장고, 전자레인지, 테이블, 난방기구, 전기포트 등이 비치되어 있다.
캠핑장 근처에 토함산, 석굴암, 불국사, 보문관광단지 등 경주의 보석 같은 관광지가 많아 관광하기에도 좋다.', 'The camping site offers glamping and caravanning.
The room is equipped with a bed, air conditioner, refrigerator, microwave, table, heater, and electric kettle.
There are many gems of Gyeongju tourist attractions such as Tohamsan Mountain, Seokguram Grotto, Bulguksa Temple, and Bomun Tourist Complex near the campsite, making it a good place for sightseeing.'),
    (31, 'tip', '오아시스글램핑에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'Please first check the age, clothing, and equipment requirements for the activity you want to experience at Oasis Glamping. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (31, 'did_you_know', '캠핑장 근처에 토함산, 석굴암, 불국사, 보문관광단지 등 경주의 보석 같은 관광지가 많아 관광하기에도 좋다고 해요.', 'It is said to be good for sightseeing as there are many tourist attractions like Gyeongju''s gems, such as Tohamsan Mountain, Seokguram Grotto, Bulguksa Temple, and Bomun Tourist Complex, near the campsite.'),
    (32, 'summary', '경주 보문관광단지 내에 조성된 1,652,900㎡(50만 평) 규모의 인공호수이다.', 'It is a 1,652,900㎡ (500,000 pyeong) artificial lake created within the Bomun Tourist Complex in Gyeongju.'),
    (32, 'intro', '경주 보문관광단지 내에 조성된 1,652,900㎡(50만 평) 규모의 인공호수이다. 봄철 벚꽃구경 명소로 유명하며, 주변에 국제적 규모의 호텔, 리조트, 경주월드, 공원 등의 시설이 있어 많은 관광객이 방문하고 있다.', 'It is a 1,652,900㎡ (500,000 pyeong) artificial lake created within the Bomun Tourist Complex in Gyeongju. It is famous as a famous spot for viewing cherry blossoms in spring, and many tourists visit the area as it has facilities such as international hotels, resorts, Gyeongju World, and parks nearby.'),
    (32, 'story', '보문호수는 산책로가 잘 정비되어 있는데, 특히 보문호 주위의 버들나무 길을 따라 걷는 보문호반길이 유명하다.
탁 트인 호수를 바라보며 걸을 수 있는 약 8㎞의 구간이며, 한 바퀴 모두 둘러보는데 약 2시간이 소요된다.
산책로는 자전거, ATV등의 통행이 금지되기 때문에 안전하게 여유로운 산책을 즐길 수 있다.', 'Bomun Lake has well-maintained trails, and the Bomun Lakeside Trail, which follows the willow tree path around Bomun Lake, is especially famous.
It is a section of approximately 8 km that can be walked while looking at an open lake, and it takes about 2 hours to walk around the whole thing.
Bicycles and ATVs are prohibited on the trails, so you can enjoy a safe and leisurely walk.'),
    (32, 'tip', '보문호을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Bomun Lake, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (32, 'did_you_know', '경주 보문관광단지 내에 조성된 1,652,900㎡(50만 평) 규모의 인공호수이에요.', 'It is a 1,652,900㎡ (500,000 pyeong) artificial lake created within the Bomun Tourist Complex in Gyeongju.'),
    (33, 'summary', '1955년 무인등대로 설치되어 60여 년 동안 감포 앞바다를 비추었던 송대말등대를 문화공간으로 탈바꿈하였다.', 'Songdaemal Lighthouse, which was installed as an unmanned lighthouse in 1955 and illuminated the sea off Gampo for 60 years, was transformed into a cultural space.'),
    (33, 'intro', '1955년 무인등대로 설치되어 60여 년 동안 감포 앞바다를 비추었던 송대말등대를 문화공간으로 탈바꿈하였다. 이곳은 디지털 미디어 전시를 상영하는 공간으로 2025년 감포항 개항 100주년을 기념하기 위해 개관되었다.', 'Songdaemal Lighthouse, which was installed as an unmanned lighthouse in 1955 and illuminated the sea off Gampo for 60 years, was transformed into a cultural space. This is a space for screening digital media exhibitions and was opened to commemorate the 100th anniversary of the opening of Gampo Port in 2025.'),
    (33, 'story', '경주 앞바다와 감포항 등대를 주제로 해양문화의 역사를 현대적으로 해석한 미디어 아트를 선보이며 국내 유일 디지털 미디어 시상식인 2021년 ‘앤어워드 시상식’에서 그랑프리상을 수상한 최고의 디지털 콘텐츠로도 인정받았다.
전시공간은 5개 존과 13개 콘텐츠로 구성됐으며, 천년 광체라는 주제로 경주와 감포의 과거 1,000년과 현재, 미래 1,000년을 스토리텔링 방식으로 보여준다.
전시관 1층에서는 감포항과 송대말등대 빛의 역사, 감포항 주변의 주요 어종, 근대 감포 이야기, 감포항 개항 이후부터 현재까지의 역사를 소개하고 있다.', 'It was recognized as the best digital content, winning the Grand Prix Award at the 2021 Ann Awards Ceremony, the only digital media awards ceremony in Korea, by presenting media art that interprets the history of maritime culture in a modern way with the theme of the sea off Gyeongju and the Gampo Port Lighthouse.
The exhibition space is composed of 5 zones and 13 contents, and under the theme of 1,000 Years of Light, it shows the past 1,000 years, present, and future 1,000 years of Gyeongju and Gampo in a storytelling manner.
The first floor of the exhibition hall introduces the history of Gampo Port and the light of Songdaemal Lighthouse, major fish species around Gampo Port, the story of modern Gampo, and the history of Gampo Port from the opening of the port to the present.'),
    (33, 'tip', '송대말등대 빛 체험전시관을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Songdaemal Lighthouse Light Experience Exhibition Hall, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (33, 'did_you_know', '1955년 무인등대로 설치되어 60여 년 동안 감포 앞바다를 비추었던 송대말등대를 문화공간으로 탈바꿈했어요.', 'Songdaemal Lighthouse, which was installed as an unmanned lighthouse in 1955 and illuminated the sea off Gampo for 60 years, was transformed into a cultural space.'),
    (34, 'summary', '골굴사는 경주시의 함월산에 위치한 사찰로 선무도(禪武道)의 총본산으로 한국의 소림사라는 별명이 있다.', 'Golgulsa Temple is a temple located on Hamwolsan Mountain in Gyeongju, and is the head temple of Seonmudo (Zenmudo) and is nicknamed the Shaolin Temple of Korea.'),
    (34, 'intro', '골굴사는 경주시의 함월산에 위치한 사찰로 선무도(禪武道)의 총본산으로 한국의 소림사라는 별명이 있다. 약 1,500여 년 전 인도에서 온 광유 선인 일행이 경주 함월산에 정착하면서 골굴사와 기림사를 창건하였는데, 골굴사는 광유스님 일행이 인도를 본떠 석굴사원 형태로 조성한 국내에서 가장 오래된 석굴사원이다.', 'Golgulsa Temple is a temple located on Hamwolsan Mountain in Gyeongju, and is the head temple of Seonmudo (Zenmudo) and is nicknamed the Shaolin Temple of Korea. About 1,500 years ago, Gwangyu''s group of monks from India settled in Hamwolsan Mountain in Gyeongju and founded Golgulsa Temple and Girimsa Temple. Golgulsa Temple is the oldest cave temple in Korea, built in the form of a cave temple modeled after India by monk Gwangyu''s group.'),
    (34, 'story', '함월산 기슭의 골굴암에는 수십 미터 높이의 거대한 응회암에 12개의 석굴이 나있으며, 암벽 제일 높은 곳에는 돋을새김으로 새긴 마애불상이 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 골굴사(경주)은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Golgulam Grotto at the foot of Hamwolsan Mountain has 12 grottoes built into a huge tuff rock tens of meters high, and at the highest point of the rock wall is a carved rock-carved Buddha statue.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Golgulsa Temple (Gyeongju) leaves a different memory for each person who visits Gyeongju.'),
    (34, 'tip', '골굴사(경주)에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Golgulsa Temple (Gyeongju), rather than just quickly looking at the building, take a look at the arrangement of the pagoda and temple as well as the mountain landscape behind it. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (34, 'did_you_know', '약 1,500여 년 전 인도에서 온 광유 선인 일행이 경주 함월산에 정착하면서 골굴사와 기림사를 창건하였는데, 골굴사는 광유스님 일행이 인도를 본떠 석굴사원 형태로 조성한 국내에서 가장 오래된 석굴사원이에요.', 'About 1,500 years ago, Gwangyu''s group of monks from India settled in Hamwolsan Mountain in Gyeongju and founded Golgulsa Temple and Girimsa Temple. Golgulsa Temple is the oldest cave temple in Korea, built by monk Gwangyu''s group in the form of a cave temple modeled after India.'),
    (37, 'summary', '경주 대릉원은 경주시 노동동과 황남동에 있는 신라 시대의 고분군을 말하며 노동동 고분군, 노서리 고분군, 황남동 고분군, 황오동 고분군, 인왕동 고분군으로 구성되어 있다.', 'Gyeongju Daereungwon refers to a group of ancient tombs from the Silla period located in Nodong-dong and Hwangnam-dong, Gyeongju-si. It consists of Nodong-dong tombs, Noseo-ri tombs, Hwangnam-dong tombs, Hwango-dong tombs, and Inwang-dong tombs.'),
    (37, 'intro', '경주 대릉원은 경주시 노동동과 황남동에 있는 신라 시대의 고분군을 말하며 노동동 고분군, 노서리 고분군, 황남동 고분군, 황오동 고분군, 인왕동 고분군으로 구성되어 있다. 노동동 고분군은 고신라 시대 무덤들로, 봉황대, 식리총, 금령총 등이 포함되어 있다.', 'Gyeongju Daereungwon refers to a group of ancient tombs from the Silla period located in Nodong-dong and Hwangnam-dong, Gyeongju-si. It consists of Nodong-dong tombs, Noseo-ri tombs, Hwangnam-dong tombs, Hwango-dong tombs, and Inwang-dong tombs. The Nodong-dong Ancient Tombs are tombs from the Go Silla period and include Bonghwangdae, Sikri Tomb, and Geumnyeong Tomb.'),
    (37, 'story', '봉황대는 밑둘레 230m, 직경 82m, 높이 22m로 황남대총 다음으로 규모가 큰 무덤으로 덧널을 설치한 돌무지덧널무덤이다.
노서리 고분군은 넓은 평지에 크고 작은 고분 14기가 있다.
노동리의 봉황대 고분과 더불어 규모가 있고 쌍벽을 이루는 제130호 고분을 비롯해 1921년에 금관이 출토된 금관총, 1926년에 일본 방문 길에 스웨덴의 황태자이며 고고학자인 구스타프 6세 아돌프가 들러 발굴을 조사 참관한 서봉총이 있다.', 'Bonghwangdae is the second largest tomb after Hwangnamdaechong Tomb with a base circumference of 230m, a diameter of 82m, and a height of 22m. It is a stone mound tomb with an overlay installed.
The Noseo-ri tomb group consists of 14 large and small tombs on a large flat area.
In addition to the Bonghwangdae Tomb in Nodong-ri, there is Tomb No. 130, which is large in size and forms a double wall, as well as Geumgwanchong Tomb, where a gold crown was excavated in 1921, and Seobongchong Tomb, where Sweden''s crown prince and archaeologist Gustav VI Adolf stopped by during his visit to Japan in 1926 to investigate and observe the excavations.'),
    (37, 'tip', '늦은 오후에는 고분의 둥근 능선에 옆빛이 들어와 형태가 한층 또렷해져요. 대릉원 산책을 마친 뒤 가까운 첨성대로 이동하면 걷는 흐름을 끊지 않고 야경 코스까지 이어갈 수 있어요.', 'In the late afternoon, side light enters the round ridge of the ancient tomb, making its shape more vivid. After finishing the walk in Daereungwon, if you go to nearby Cheomseongdae, you can continue to the night view course without breaking the walking flow.'),
    (37, 'did_you_know', '봉황대는 밑둘레 230m, 직경 82m, 높이 22m로 황남대총 다음으로 규모가 큰 무덤으로 덧널을 설치한 돌무지덧널무덤이에요.', 'Bonghwangdae is the second largest tomb after Hwangnamdaechong Tomb with a base circumference of 230m, a diameter of 82m, and a height of 22m. It is a stone mound tomb with an overlay installed.'),
    (38, 'summary', '경주 옥산서원은 조선시대 성리학자인 회재 이언적을 기리기 위한 곳으로 이언적의 학문은 퇴계 이황에게 이어져 영남학파 성리설의 선구가 되었다.', 'Oksan Seowon in Gyeongju is a place to commemorate Hoejae Lee Eon-jeok, a Neo-Confucian scholar of the Joseon Dynasty. Lee Eon-jeok''s studies were passed down to Toegye Yi Hwang, who became the pioneer of Yeongnam School''s Neo-Confucianism.'),
    (38, 'intro', '경주 옥산서원은 조선시대 성리학자인 회재 이언적을 기리기 위한 곳으로 이언적의 학문은 퇴계 이황에게 이어져 영남학파 성리설의 선구가 되었다. 이러한 회재 이언적 선생을 기리기 위해 선조 5년(1572)에 경주부윤 이제민이 처음 세웠고 그다음 해에 임금에게 ‘옥산’이라는 이름을 받아 사액서원이 되었다.', 'Oksan Seowon in Gyeongju is a place to commemorate Hoejae Lee Eon-jeok, a Neo-Confucian scholar of the Joseon Dynasty. Lee Eon-jeok''s studies were passed down to Toegye Yi Hwang, who became the pioneer of Yeongnam School''s Neo-Confucianism. To commemorate Lee Eon-jeok, it was first built by Lee Je-min, Gyeongju Buyun, in the 5th year of King Seonjo''s reign (1572), and the following year, it was given the name ‘Oksan’ by the king and became Saekseowon.'),
    (38, 'story', '공부하는 공간 구인당이 앞에 있고 제사를 지내는 체인묘가 뒤에 위치한 전학후묘식의 배치 체계를 따르고 있다.
구인당은 맞배지붕 건물로 헌종 5년(1839)에 화재로 사라졌다가 다시 지어진 건물이다.
그 외에도 정문인 역락문, 2층 건물인 무변루, 학생들의 기숙사로 동재인 민구재, 서재인 암수재 등 여러 건물이 있다.', 'It follows the layout system of the Jeonhakhumyo style, with the Guindang, a study space, in the front and the chain tomb, where ancestral rites are performed, located in the back.
Guindang is a gable-roofed building that was rebuilt after being destroyed by fire in the 5th year of King Heonjong''s reign (1839).
In addition, there are several other buildings, including Yeokrakmun, which is the main gate, Mubyeonru, which is a two-story building, and Mingujae, which is the eastern building for students, and Amsujae, which is the western building.'),
    (38, 'tip', '옥산서원(경주)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Oksan Seowon (Gyeongju), check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (38, 'did_you_know', '이러한 회재 이언적 선생을 기리기 위해 선조 5년(1572)에 경주부윤 이제민이 처음 세웠고 그다음 해에 임금에게 ‘옥산’이라는 이름을 받아 사액서원이 되었다고 해요.', 'It is said that it was first built by Lee Je-min, Gyeongju Buyun, in the 5th year of King Seonjo''s reign (1572) to commemorate Hoejae Lee Eon-jeok, and the following year, it was given the name ''Oksan'' by the king and became Saekseowon.'),
    (39, 'summary', '경주시의 대표적인 가을 명소로 손꼽히는 곳이라고 할 수 있다.', 'It can be said to be one of the representative fall attractions in Gyeongju.'),
    (39, 'intro', '통일전 은행나무길은 경주시의 대표적인 가을 명소로 손꼽히는 곳이라고 할 수 있다. 신라의 삼국통일 정신과 화랑의 호국정신을 기리고 이를 이어받아 나라의 정신적 지주로 삼기 위하여 조성한 길이다.', 'Ginkgo Tree Road in Tongiljeon can be said to be one of Gyeongju City’s representative fall attractions. This road was created to commemorate Silla''s spirit of unification of the three kingdoms and Hwarang''s spirit of national defense, and to inherit this spirit and make it the spiritual pillar of the country.'),
    (39, 'story', '근방에 삼국통일의 정신을 계승하기 위하여 건립된 통일 전부터 시작되어 직선으로 광활하게 펼쳐진 도로 양옆으로 은행나무 가로수가 늘어서 있는 형태이다.
은행이 절정으로 물드는 10월 말부터 11월 초까지 가을의 정취를 느낄 수 있기 때문에 경주 지역 주민들뿐만 아니라 외지인들도 많이 방문하기도 한다.
또한 통일전으로 올라가 누각 위에서 통일전 은행나무길 전체의 풍광을 한눈에 담을 수 있다.', 'It was built before unification to inherit the spirit of the unification of the three kingdoms nearby, and is lined with ginkgo trees on both sides of a wide, straight road.
Since you can feel the autumn atmosphere from late October to early November when the banks are at their peak color, not only local residents of Gyeongju but also many people from outside the region visit.
You can also go up to Tongiljeon and take in the entire scenery of Ginkgo Tree Road in Tongiljeon from the top of the pavilion.'),
    (39, 'tip', '통일전 은행나무길에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'On the Ginkgo Tree Road in Tongiljeon, rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and pavilions and the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (39, 'did_you_know', '신라의 삼국통일 정신과 화랑의 호국정신을 기리고 이를 이어받아 나라의 정신적 지주로 삼기 위하여 조성한 길이에요.', 'This road was created to commemorate Silla''s spirit of unification of the three kingdoms and Hwarang''s spirit of national defense, and to inherit this spirit and make it the spiritual pillar of the country.'),
    (40, 'summary', '경주는 국내 최대의 관광도시로, 그 자체가 거대한 야외 박물관이라 할 만큼 곳곳에 문화재가 산재해 있다.', 'Gyeongju is the largest tourist city in Korea, and cultural assets are scattered throughout the city, so much so that it can be called a huge outdoor museum in itself.'),
    (40, 'intro', '경주는 국내 최대의 관광도시로, 그 자체가 거대한 야외 박물관이라 할 만큼 곳곳에 문화재가 산재해 있다. 걸어 다니는 모든 길이 유적지이고 보이는 모든 경치가 살아있는 역사이며, 만나는 모든 것이 문화재라고 해도 과언이 아닌 한국의 대표 역사 문화 도시다.', 'Gyeongju is the largest tourist city in Korea, and cultural assets are scattered throughout the city, so much so that it can be called a huge outdoor museum in itself. It is no exaggeration to say that every road you walk is a historic site, every view you see is living history, and everything you encounter is a cultural asset. It is Korea''s representative historical and cultural city.'),
    (40, 'story', '이러한 이유로 1994년 경주시 일대 시내, 보문지구, 불국지구 등이 관광특구로 지정되었다.
관광특구 내에는 문화재로 지정된 명소가 300여 개에 이르고, 그중 유네스코 세계유산에 등록되어 있는 것도 많다.
관광특구 내 주요 명소로는 불국사, 석굴암, 대릉원 등이 있으며, 경주세계문화 엑스포공원, 경주월드, 신라밀레니엄파크 등의 레저 시설 또한 갖추고 있다.', 'For this reason, the downtown area of Gyeongju-si, Bomun District, and Bulguk District were designated as special tourist zones in 1994.
Within the special tourist zone, there are over 300 famous sites designated as cultural assets, many of which are registered as UNESCO World Heritage Sites.
Major attractions in the special tourist zone include Bulguksa Temple, Seokguram Grotto, and Daereungwon, and it also has leisure facilities such as Gyeongju World Culture Expo Park, Gyeongju World, and Shilla Millennium Park.'),
    (40, 'tip', '경주시 관광특구을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Special Tourist Zone, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (40, 'did_you_know', '이러한 이유로 1994년 경주시 일대 시내, 보문지구, 불국지구 등이 관광특구로 지정되었다고 해요.', 'For this reason, the downtown area of Gyeongju-si, Bomun District, and Bulguk District were designated as special tourist zones in 1994.'),
    (42, 'summary', '도리마을 은행나무숲은 경북 경주시 서면에 자리 잡고 있다.', 'Dori Village Ginkgo Forest is located in Seomyeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (42, 'intro', '도리마을 은행나무숲은 경북 경주시 서면에 자리 잡고 있다. 묘목 판매를 목적으로 심은 수많은 은행나무가 숲을 이루게 됐다.', 'Dori Village Ginkgo Forest is located in Seomyeon, Gyeongju-si, Gyeongsangbuk-do. Numerous ginkgo trees planted for the purpose of selling seedlings have formed a forest.'),
    (42, 'story', '열 맞춰 빽빽하게 나무를 심은 덕에 자작나무처럼 위로만 쭉 뻗은 늘씬한 은행나무가 이국적인 정취를 뽐낸다.
사진작가들이 매해 이곳을 찾고, 웨딩 촬영 성지로도 불린다.
은행나무 물들 때면 마을 주민들이 먹거리 장터, 특산물 장터를 운영해 즐길 거리를 더하고 있다.', 'Thanks to the dense planting of trees in rows, the slender ginkgo trees that stretch upward like birch trees give off an exotic atmosphere.
Photographers visit this place every year, and it is also called a mecca for wedding photography.
When the ginkgo trees change color, village residents run food markets and specialty product markets to add to their enjoyment.'),
    (42, 'tip', '도리마을은행나무숲을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Dori Village Ginkgo Forest, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (42, 'did_you_know', '은행나무 물들 때면 마을 주민들이 먹거리 장터, 특산물 장터를 운영해 즐길 거리를 더하고 있어요.', 'When the ginkgo trees change color, village residents run food markets and specialty product markets to add to the fun.'),
    (43, 'summary', '1971년 경주관광종합개발계획으로 경주관광개발에 착수하여 1979년 4월 6일 보문관광단지가 개장되었다.', 'Gyeongju tourism development began in 1971 under the Gyeongju Tourism Comprehensive Development Plan, and Bomun Tourist Complex opened on April 6, 1979.'),
    (43, 'intro', '1971년 경주관광종합개발계획으로 경주관광개발에 착수하여 1979년 4월 6일 보문관광단지가 개장되었다. 대한민국 1호 관광단지로써 관광산업의 초석을 다져온 보문관광단지의 발자취를 기억하고 경상북도 관광산업의 새로운 백년대계를 대비하고자 조성된 공원이 관광역사공원이다.', 'Gyeongju tourism development began in 1971 under the Gyeongju Tourism Comprehensive Development Plan, and Bomun Tourist Complex opened on April 6, 1979. The Tourism History Park is a park created to remember the footsteps of Bomun Tourist Complex, which laid the foundation for the tourism industry as Korea''s first tourist complex, and to prepare for a new 100-year plan for the tourism industry in Gyeongsangbuk-do.'),
    (43, 'story', '관광역사공원은 무한한 관광 발전을 상징하고자 과거, 현재, 미래를 연결하는 뫼비우스의 띠를 형상화하였다.
관광역사공원은 보문호와 맞닿아 있다.
이 덕분에 공원 산책로를 따라 걸으며 보문호의 풍경을 감상할 수 있다.', 'The Tourism History Park symbolizes the infinite development of tourism and is shaped like a Möbius strip connecting the past, present, and future.
The Tourist and Historical Park is adjacent to Bomun Lake.
Thanks to this, you can enjoy the scenery of Bomun Lake while walking along the park trail.'),
    (43, 'tip', '관광역사공원은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk through the Tourist History Park in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (43, 'did_you_know', '1971년 경주관광종합개발계획으로 경주관광개발에 착수하여 1979년 4월 6일 보문관광단지가 개장되었다고 해요.', 'Gyeongju tourism development began in 1971 under the Gyeongju Tourism Comprehensive Development Plan, and Bomun Tourist Complex opened on April 6, 1979.'),
    (44, 'summary', '경주 보문관광단지 내에 위치한 복합문화공간으로, 고대 로마의 콜로세움을 모티브로 조성된 이국적인 건축물이 특징이다.', 'It is a complex cultural space located within the Bomun Tourist Complex in Gyeongju, and is characterized by an exotic architecture built with the motif of the Colosseum of ancient Rome.'),
    (44, 'intro', '보문콜로세움은 경주 보문관광단지 내에 위치한 복합문화공간으로, 고대 로마의 콜로세움을 모티브로 조성된 이국적인 건축물이 특징이다. 건물 내부에는 카페와 음식점, 전시시설 등이 입점해 있어 휴식과 관람을 함께 즐길 수 있다.', 'Bomun Colosseum is a complex cultural space located within the Bomun Tourist Complex in Gyeongju, and is characterized by an exotic architecture built with the motif of the Colosseum of ancient Rome. Inside the building, there are cafes, restaurants, and exhibition facilities, so you can enjoy resting and viewing at the same time.'),
    (44, 'story', '보문호를 배경으로 조성된 야외 정원과 테라스에서는 여유로운 분위기 속에서 식사와 차를 즐길 수 있으며, 이국적인 건축미와 조경이 어우러져 색다른 분위기를 선사한다.
또한 건물 내에 위치한 키덜트뮤지엄에서는 장난감과 영화, 음악을 주제로 한 다양한 전시를 만나볼 수 있다.
초기 영상기기와 축음기 등 근현대 수집품부터 영화 캐릭터 피규어, 아트토이, 정크아트 작품까지 폭넓은 콘텐츠가 전시되어 있어 남녀노소 흥미롭게 관람할 수 있다.', 'In the outdoor garden and terrace with Bomun Lake in the background, you can enjoy meals and tea in a leisurely atmosphere, and the exotic architectural beauty and landscaping combine to create a unique atmosphere.
Additionally, at the Kidult Museum located within the building, you can see various exhibitions themed around toys, movies, and music.
A wide range of contents are on display, from modern and contemporary collectibles such as early video equipment and gramophones to movie character figures, art toys, and junk art works, so people of all ages can enjoy the exhibition.'),
    (44, 'tip', '보문콜로세움은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Bomun Colosseum in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (44, 'did_you_know', '보문콜로세움은 경주 보문관광단지 내에 위치한 복합문화공간으로, 고대 로마의 콜로세움을 모티브로 조성된 이국적인 건축물이 특징이에요.', 'Bomun Colosseum is a complex cultural space located within the Bomun Tourist Complex in Gyeongju, and is characterized by an exotic building modeled after the Colosseum of ancient Rome.'),
    (45, 'summary', '경주 진현로 일대에 조성된 문화거리로, 불국사 상가시장과 토함산 자락의 마을 골목을 중심으로 형성되어 있다.', 'It is a cultural street built around Jinhyeon-ro, Gyeongju, centered around the Bulguksa commercial market and the village alleys at the foot of Tohamsan Mountain.'),
    (45, 'intro', '불리단길은 경주 진현로 일대에 조성된 문화거리로, 불국사 상가시장과 토함산 자락의 마을 골목을 중심으로 형성되어 있다. 과거 관광객들이 많이 찾던 지역이었으며, 최근에는 도시재생사업을 통해 카페와 음식점, 공방, 갤러리 등이 들어서며 새로운 문화공간으로 자리 잡고 있다.', 'Bullidan-gil is a cultural street built around Jinhyeon-ro, Gyeongju, centered around the Bulguksa commercial market and the village alleys at the foot of Tohamsan Mountain. It was an area frequented by many tourists in the past, and recently, through urban regeneration projects, cafes, restaurants, workshops, galleries, etc. have been built, making it a new cultural space.'),
    (45, 'story', '봄에는 겹벚꽃 명소로 알려져 있으며, 플리마켓과 전시, 체험 프로그램 등 다양한 문화행사가 열린다.
거리 곳곳에는 전통적인 분위기의 건물과 개성 있는 상점들이 어우러져 있으며, 인근 벽화마을에서는 다채로운 거리 예술도 감상할 수 있다.
불국사와 토함산을 찾는 여행객들이 함께 둘러보기 좋은 경주의 대표 문화거리이다.', 'It is known as a famous spot for double cherry blossoms in spring, and various cultural events such as flea markets, exhibitions, and experience programs are held here.
Traditional buildings and unique shops are scattered throughout the streets, and you can also enjoy colorful street art at the nearby Mural Village.
It is a representative cultural street in Gyeongju that travelers visiting Bulguksa Temple and Tohamsan Mountain can enjoy together.'),
    (45, 'tip', '불리단길을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Bulidan-gil, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (45, 'did_you_know', '불리단길은 경주 진현로 일대에 조성된 문화거리로, 불국사 상가시장과 토함산 자락의 마을 골목을 중심으로 형성되어 있어요.', 'Bullidan-gil is a cultural street built around Jinhyeon-ro, Gyeongju, and is centered around the Bulguksa commercial market and the village alleys at the foot of Tohamsan Mountain.'),
    (46, 'summary', '경주 보문호수 둘레에 조성된 수변공원으로, 산책과 휴식을 즐길 수 있는 공간이다.', 'This is a waterside park created around Bomun Lake in Gyeongju, and is a space where you can enjoy walking and relaxation.'),
    (46, 'intro', '물너울공원은 경주 보문호수 둘레에 조성된 수변공원으로, 산책과 휴식을 즐길 수 있는 공간이다. 공원 내에는 피크닉 테이블과 벤치 등 편의시설이 마련되어 있으며, 보문관광단지를 대표하는 물너울교가 자리하고 있다.', 'Mulneul Park is a waterside park built around Bomun Lake in Gyeongju, and is a space where you can enjoy walking and relaxation. Convenience facilities such as picnic tables and benches are provided within the park, and Mulneoul Bridge, which represents the Bomun Tourist Complex, is located.'),
    (46, 'story', '물너울교에서는 보문호의 푸른 수면과 주변 산세가 어우러진 풍경을 감상할 수 있으며, 경주 시가지와 형산강 일대의 경관도 한눈에 조망할 수 있다.
공원은 소나무 숲과 호숫가 산책로가 조화를 이루고 있어 사계절 내내 여유로운 시간을 보내기 좋으며, 야간에는 경관조명이 더해져 색다른 분위기를 선사한다.
특히 물너울교는 아름다운 야경으로 2016년 형산강 팔경에 선정되었다.', 'From Mulneoul Bridge, you can enjoy the scenery that combines the blue water of Bomun Lake and the surrounding mountains, and you can also see the scenery of the city of Gyeongju and the Hyeongsan River area at a glance.
The park is a harmonious combination of a pine forest and a lakeside trail, making it a great place to spend a leisurely time all year round. At night, landscape lighting is added to create a unique atmosphere.
In particular, Mulneul Bridge was selected as one of the Eight Scenic Views of the Hyeongsan River in 2016 for its beautiful night view.'),
    (46, 'tip', '물너울공원은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Mulneoul Park just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (46, 'did_you_know', '물너울공원은 경주 보문호수 둘레에 조성된 수변공원으로, 산책과 휴식을 즐길 수 있는 공간이에요.', 'Mulneul Park is a waterside park built around Bomun Lake in Gyeongju, and is a space where you can enjoy walking and relaxation.'),
    (47, 'summary', '경주문화관1918은 2022년 12월 개관한 복합문화공간으로, 약 100년 동안 경주의 관문 역할을 해온 옛 경주역을 문화예술 공간으로 재탄생시킨 곳이다.', 'Gyeongju Cultural Center 1918 is a complex cultural space that opened in December 2022, and is a place where the old Gyeongju Station, which served as the gateway to Gyeongju for about 100 years, has been reborn as a culture and arts space.'),
    (47, 'intro', '경주문화관1918은 2022년 12월 개관한 복합문화공간으로, 약 100년 동안 경주의 관문 역할을 해온 옛 경주역을 문화예술 공간으로 재탄생시킨 곳이다. 명칭은 1918년 개통한 경주역의 역사성을 계승하면서 시민들이 문화를 향유하는 플랫폼으로 거듭난다는 의미를 담아 공모를 통해 선정되었다.', 'Gyeongju Cultural Center 1918 is a complex cultural space that opened in December 2022, and is a place where the old Gyeongju Station, which served as the gateway to Gyeongju for about 100 years, has been reborn as a culture and arts space. The name was selected through a public contest with the intention of inheriting the historicity of Gyeongju Station, which opened in 1918, while being reborn as a platform for citizens to enjoy culture.'),
    (47, 'story', '시설 내에는 전시실과 지역 예술가를 위한 창작 스튜디오, 커뮤니티실 등이 마련되어 있으며, 전시와 공연, 문화예술 프로그램 등 다양한 활동이 이루어진다.
문화관 앞 광장에서는 공연과 플리마켓, 체험 행사 등이 열리며, 어린이를 위한 야외 놀이터도 조성되어 있어 시민과 관광객이 함께 즐길 수 있는 문화 공간으로 활용되고 있다.
오늘의 경주문화관 1918은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The facility has an exhibition room, a creative studio for local artists, and a community room, and various activities such as exhibitions, performances, and cultural arts programs take place.
Performances, flea markets, and experience events are held in the plaza in front of the cultural center, and an outdoor playground for children has also been created, making it a cultural space that citizens and tourists can enjoy together.
Today''s Gyeongju Cultural Center 1918 leaves a different memory for each person who visits Gyeongju.'),
    (47, 'tip', '경주문화관 1918을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Cultural Center 1918, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (47, 'did_you_know', '경주문화관1918은 2022년 12월 개관한 복합문화공간으로, 약 100년 동안 경주의 관문 역할을 해온 옛 경주역을 문화예술 공간으로 재탄생시킨 곳이에요.', 'Gyeongju Cultural Center 1918 is a complex cultural space that opened in December 2022, and is a place where the old Gyeongju Station, which served as the gateway to Gyeongju for about 100 years, has been reborn as a culture and arts space.'),
    (48, 'summary', '경주 보문관광단지를 대표하는 휴식 공간으로, 지름 13m 규모의 대형 물레방아가 설치되어 있다.', 'It is a relaxation space representing the Bomun Tourist Complex in Gyeongju, and is equipped with a large watermill with a diameter of 13m.'),
    (48, 'intro', '물레방아광장은 경주 보문관광단지를 대표하는 휴식 공간으로, 지름 13m 규모의 대형 물레방아가 설치되어 있다. 물레방아는 덕동호에서 흘러오는 물의 자연 수압으로 회전하며, 108개의 물받이는 백팔번뇌를 씻고 행복을 기원하는 의미를 담고 있다.', 'Watermill Square is a representative resting area of Bomun Tourist Complex in Gyeongju, and is equipped with a large watermill with a diameter of 13m. The watermill rotates with the natural hydraulic pressure of water flowing from Deokdong Lake, and the 108 water basins are meant to wash away one hundred and eight troubles and wish for happiness.'),
    (48, 'story', '주변에는 대나무숲과 인공폭포, 연못이 조성되어 있어 산책과 휴식을 즐기기 좋다.
봄에는 벚꽃이 만개해 많은 방문객이 찾으며, 야간에는 조명이 더해져 색다른 경관을 감상할 수 있다.
인근에는 보문호와 목월공원을 비롯해 경주엑스포대공원, 바니베어뮤지엄 등 다양한 관광지가 자리하고 있다.', 'There is a bamboo forest, an artificial waterfall, and a pond nearby, making it great for walking and relaxing.
In spring, the cherry blossoms are in full bloom, attracting many visitors, and at night, lights are added to provide a unique view.
There are various tourist attractions nearby, including Bomun Lake and Mokwol Park, Gyeongju Expo Park, and Bunny Bear Museum.'),
    (48, 'tip', '물레방아광장은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Watermill Square just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (48, 'did_you_know', '물레방아광장은 경주 보문관광단지를 대표하는 휴식 공간으로, 지름 13m 규모의 대형 물레방아가 설치되어 있어요.', 'Watermill Square is a representative resting area of Bomun Tourist Complex in Gyeongju, and is equipped with a large watermill with a diameter of 13m.'),
    (49, 'summary', '폐교를 리모델링한 곳으로 다양한 체험과 숙박을 함께 할 수 있는 농림부지원 교육체험 학습장이다.', 'It is a remodeled abandoned school and is an educational experience center supported by the Ministry of Agriculture and Forestry where you can enjoy a variety of experiences and accommodations.'),
    (49, 'intro', '두송녹색농촌체험마을은 폐교를 리모델링한 곳으로 다양한 체험과 숙박을 함께 할 수 있는 농림부지원 교육체험 학습장이다. 캠핑을 할 수 있는 야외 데크와 교실을 리모델링한 숙박시설, 60평 대형강당으로 구성되었으며 천연잔디로 조성된 150평 규모의 야외행사장은 각종 축구장, 농구장 등 운동시설이 준비되어 있다.', 'Dusong Green Rural Experience Village is a remodeled abandoned school and is an educational experience center supported by the Ministry of Agriculture and Forestry that offers various experiences and accommodations. It consists of an outdoor deck for camping, accommodations that are remodeled classrooms, and a large 60-pyeong auditorium. The 150-pyeong outdoor event hall, made of natural grass, is equipped with various sports facilities such as soccer fields and basketball courts.'),
    (49, 'story', '친구, 가족 단위 캠핑은 물론 학생, 모임, 직장 단체 수련회 등 단체 방문이 가능하다.
수영장과 야외 미끄럼틀, 숲 속 원두막, 바베큐장 시설이 갖추어져 있어 자연 속 휴식을 취할 수 있는 공간이다.
오늘의 두송녹색농촌체험마을은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Camping by friends and family is possible, as well as group visits such as students, gatherings, and work group retreats.
Equipped with a swimming pool, an outdoor slide, a cabin in the forest, and a barbecue area, it is a space where you can relax in nature.
Today''s Dusong Green Rural Experience Village leaves a different memory for each person who visits Gyeongju.'),
    (49, 'tip', '두송녹색농촌체험마을에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Dusong Green Rural Experience Village, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (49, 'did_you_know', '캠핑을 할 수 있는 야외 데크와 교실을 리모델링한 숙박시설, 60평 대형강당으로 구성되었으며 천연잔디로 조성된 150평 규모의 야외행사장은 각종 축구장, 농구장 등 운동시설이 준비되어 있어요.', 'It consists of an outdoor deck for camping, accommodations that are remodeled classrooms, and a large 60-pyeong auditorium. The 150-pyeong outdoor event hall, made of natural grass, is equipped with various sports facilities such as soccer fields and basketball courts.'),
    (50, 'summary', '경주 출신의 소설가 김동리와 시인 박목월의 문학적 업적을 기리기 위해 2006년에 건립된 문학관이다.', 'This literary museum was built in 2006 to commemorate the literary achievements of Gyeongju-born novelist Kim Dong-ri and poet Park Mok-wol.'),
    (50, 'intro', '동리목월문학관은 경주 출신의 소설가 김동리와 시인 박목월의 문학적 업적을 기리기 위해 2006년에 건립된 문학관이다. 한국 현대문학을 대표하는 두 문인의 삶과 작품 세계를 소개하며, 동리목월문학상 운영과 문예창작 교육, 문학 심포지엄, 시 낭송회, 백일장 등 다양한 문학 사업을 펼치고 있다.', 'Dongri-Mokwol Literature Museum is a literary museum built in 2006 to commemorate the literary achievements of Gyeongju-born novelist Kim Dong-ri and poet Park Mok-wol. It introduces the lives and works of two writers who represent modern Korean literature, and carries out various literary projects such as operating the Dongri Mokwol Literary Award, creative writing education, literary symposiums, poetry readings, and essay writing.'),
    (50, 'story', '전시관에는 동리문학관과 목월문학관이 조성되어 있으며, 두 문인의 서재를 재현해 집필 도구와 원고, 출판물 등 다양한 자료를 살펴볼 수 있다.
또한 작품을 바탕으로 제작한 영상과 육성 시 낭송을 통해 문학을 보다
쉽고 생생하게 접할 수 있다.', 'The exhibition hall houses the Dongni Literature Museum and the Mokwol Literature Museum, and the two writers'' studies have been recreated, allowing visitors to view various materials such as writing tools, manuscripts, and publications.
In addition, you can view literature through videos produced based on the work and recitations of poetry.
It can be accessed easily and vividly.'),
    (50, 'tip', '동리목월문학관에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At the Dongni Mokwol Literature Museum, choose the exhibition you are interested in and plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (50, 'did_you_know', '동리목월문학관은 경주 출신의 소설가 김동리와 시인 박목월의 문학적 업적을 기리기 위해 2006년에 건립된 문학관이에요.', 'Dongri-Mokwol Literature Museum is a literary museum built in 2006 to commemorate the literary achievements of Gyeongju-born novelist Kim Dong-ri and poet Park Mok-wol.'),
    (51, 'summary', '임실치즈학교는 폐교를 활용해 조성한 치즈 체험 시설로, 임실치즈를 직접 만들고 맛볼 수 있는 다양한 프로그램을 운영하고 있다.', 'Imsil Cheese School is a cheese experience facility created using a closed school, and runs a variety of programs where you can make and taste Imsil cheese yourself.'),
    (51, 'intro', '임실치즈학교는 폐교를 활용해 조성한 치즈 체험 시설로, 임실치즈를 직접 만들고 맛볼 수 있는 다양한 프로그램을 운영하고 있다. 대표 프로그램으로는 우유를 이용한 치즈 만들기와 치즈를 활용한 피자 만들기 체험이 있으며, 가족 단위 방문객부터 연인, 학생 단체까지 폭넓게 참여할 수 있다.', 'Imsil Cheese School is a cheese experience facility created using a closed school, and runs a variety of programs where you can make and taste Imsil cheese yourself. Representative programs include cheese-making using milk and pizza-making experiences using cheese, and a wide range of participants, from families to couples and student groups, can participate.'),
    (51, 'story', '체험 프로그램은 개인과 단체 과정으로 나누어 운영되며, 치즈 만들기와 피자 만들기 외에도 아이스크림 만들기, 쿠키 만들기, 비누 만들기, 한지공예 등 다양한 체험 활동을 즐길 수 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 임실치즈학교 경주체험장은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The experience program is divided into individual and group courses, and in addition to cheese making and pizza making, you can enjoy a variety of experiential activities such as ice cream making, cookie making, soap making, and Korean paper craft.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Imsil Cheese School Gyeongju Experience Center leaves a different memory for each person who visits Gyeongju.'),
    (51, 'tip', '임실치즈학교 경주체험장을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Imsil Cheese School Gyeongju Experience Center, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (51, 'did_you_know', '임실치즈학교는 폐교를 활용해 조성한 치즈 체험 시설로, 임실치즈를 직접 만들고 맛볼 수 있는 다양한 프로그램을 운영하고 있어요.', 'Imsil Cheese School is a cheese experience facility created using a closed school, and runs a variety of programs where you can make and taste Imsil cheese yourself.'),
    (52, 'summary', '대릉원 동쪽에 위치한 황오동·황남동·인왕동 일대의 신라 고분군으로, 4~6세기 신라 왕족과 귀족들의 집단 묘역이다.', 'It is a group of Silla tombs in the Hwango-dong, Hwangnam-dong, and Inwang-dong areas located to the east of Daereungwon. It is a mass grave site for Silla royalty and nobles from the 4th to 6th centuries.'),
    (52, 'intro', '쪽샘지구는 대릉원 동쪽에 위치한 황오동·황남동·인왕동 일대의 신라 고분군으로, 4~6세기 신라 왕족과 귀족들의 집단 묘역이다. 약 38만 4,000㎡ 규모의 유적으로, 신라 왕경의 역사와 문화를 보여주는 대표적인 발굴 현장으로 알려져 있다.', 'The Jjoksaem district is a group of Silla tombs in the area of Hwango-dong, Hwangnam-dong, and Inwang-dong located to the east of Daereungwon, and is a mass graveyard for Silla royal family members and nobles from the 4th to 6th centuries. It is a relic measuring approximately 384,000 m2 and is known as a representative excavation site showing the history and culture of the Silla capital.'),
    (52, 'story', '2007년부터 본격적인 발굴조사가 진행되었으며, 적석목곽분과 석곽묘, 옹관묘 등 150여 기의 무덤과 금귀걸이, 금동 장식, 말안장 등 3,000여 점의 유물이 출토되었다.
특히 5세기 무렵의 찰갑과 마갑이 온전한 형태로 발견되어 신라의 무기와 마구 문화를 연구하는 데 중요한 자료로 평가받고 있다.
현재도 발굴과 연구가 이어지고 있으며, 인근의 쪽샘유적발굴관에서는 발굴 과정과 출토 유물을 자세히 살펴볼 수 있다.', 'A full-scale excavation has been carried out since 2007, and about 150 tombs, including red stone wooden tombs, stone tombs, and jar coffin tombs, and about 3,000 artifacts, including gold earrings, gilt bronze decorations, and horse saddles, have been unearthed.
In particular, leather armor and barding from around the 5th century were discovered in their intact form, and are evaluated as important materials for studying the weapon and harness culture of Silla.
Excavations and research are still ongoing, and you can take a closer look at the excavation process and excavated artifacts at the nearby Jjoksaem Relics Excavation Hall.'),
    (52, 'tip', '쪽샘지구에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'In Jjoksaem District, decide on the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (52, 'did_you_know', '약 38만 4,000㎡ 규모의 유적으로, 신라 왕경의 역사와 문화를 보여주는 대표적인 발굴 현장으로 알려져 있어요.', 'It is a ruins measuring approximately 384,000㎡ and is known as a representative excavation site showing the history and culture of the Silla capital.'),
    (53, 'summary', '경주에 위치한 사륜바이크(ATV) 체험장으로, 다양한 코스를 갖추고 있어 색다른 레저 활동을 즐길 수 있는 곳이다.', 'This is an ATV experience center located in Gyeongju. It is a place where you can enjoy unique leisure activities as it has a variety of courses.'),
    (53, 'intro', '보불ATV체험장은 경주에 위치한 사륜바이크(ATV) 체험장으로, 다양한 코스를 갖추고 있어 색다른 레저 활동을 즐길 수 있는 곳이다. 이용자의 연령과 운전 경험을 고려해 적합한 차량을 배정하며, 체험 전 안전교육과 주행 연습을 진행한 뒤 코스를 이용할 수 있다.', 'Bobul ATV Experience Center is a quad bike (ATV) experience center located in Gyeongju. It is a place where you can enjoy unique leisure activities as it has a variety of courses. A suitable vehicle is assigned considering the user''s age and driving experience, and users can use the course after undergoing safety training and driving practice before the experience.'),
    (53, 'story', '코스는 언덕길과 숲길, 계곡 인근 구간 등으로 구성되어 있으며, 숙련도에 따라 다양한 난이도의 주행을 경험할 수 있다.
또한 체험 중 사진 촬영 서비스를 제공해 활동 모습을 기록할 수 있다.
경주의 문화유산 관광과 함께 즐길 수 있는 이색 체험 공간으로 많은 여행객이 찾고 있다.', 'The course consists of hill roads, forest roads, and sections near valleys, and you can experience driving of various levels of difficulty depending on your level of skill.
Additionally, we provide a photography service during the experience so you can record your activities.
Many travelers are looking for a unique experience space that can be enjoyed along with Gyeongju''s cultural heritage sightseeing.'),
    (53, 'tip', '보불ATV체험장은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to the Bobul ATV Experience Center in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (53, 'did_you_know', '경주의 문화유산 관광과 함께 즐길 수 있는 이색 체험 공간으로 많은 여행객이 찾고 있어요.', 'Many travelers are looking for a unique experience space that can be enjoyed along with Gyeongju’s cultural heritage sightseeing.'),
    (54, 'summary', '경주시 외동읍 괘릉리에 위치한 연못으로, 불국사 석가탑과 다보탑을 만든 석공 아사달과 아사녀의 애틋한 설화가 전해지는 곳이다.', 'This pond is located in Gwaereung-ri, Oedong-eup, Gyeongju-si, and is the place where the affectionate story of Asadal and Asanyeo, the masons who built the Seokgatap and Dabotap pagodas of Bulguksa Temple, is told.'),
    (54, 'intro', '영지는 경주시 외동읍 괘릉리에 위치한 연못으로, 불국사 석가탑과 다보탑을 만든 석공 아사달과 아사녀의 애틋한 설화가 전해지는 곳이다. 아사녀가 남편을 기다리며 탑의 그림자를 바라보았다는 이야기에서 유래한 장소로, 신라 시대의 전설과 역사를 함께 느낄 수 있다.', 'Yeongji is a pond located in Gwaereung-ri, Oedong-eup, Gyeongju-si, and is the place where the affectionate story of Asadal and Asanyeo, the masons who built the Seokgatap and Dabotap pagodas of Bulguksa Temple, is told. This place originated from the story that Asanyeo looked at the shadow of the pagoda while waiting for her husband, and you can feel the legend and history of the Silla period.'),
    (54, 'story', '연못 주변에는 영지석불좌상과 수변 산책로, 나무데크, 구름다리 등이 조성되어 있어 여유로운 산책을 즐기기에 좋다.
또한 인근에는 조각공원, 어린이 놀이터, 짚라인, 설화체험관 등이 마련되어 있으며, 봄이면 아름다운 벚꽃 풍경을 감상할 수 있어 많은 방문객이 찾는다.
불국사와 함께 둘러보기 좋은 경주의 역사·문화 명소이다.', 'Around the pond, there is a seated Buddha statue, a waterside promenade, a wooden deck, and an overpass, making it a great place to enjoy a leisurely walk.
In addition, there is a sculpture park, children''s playground, zip line, and a snowflake experience center nearby, and many visitors come to enjoy the beautiful cherry blossom scenery in spring.
It is a historical and cultural attraction in Gyeongju that is good to visit along with Bulguksa Temple.'),
    (54, 'tip', '영지은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk around Yeongji in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (54, 'did_you_know', '영지는 경주시 외동읍 괘릉리에 위치한 연못으로, 불국사 석가탑과 다보탑을 만든 석공 아사달과 아사녀의 애틋한 설화가 전해지는 곳이에요.', 'Yeongji is a pond located in Gwaereung-ri, Oedong-eup, Gyeongju-si, and is the place where the affectionate story of Asadal and Asanyeo, the masons who built the Seokgatap and Dabotap pagodas of Bulguksa Temple, is told.'),
    (55, 'summary', '경주시 외곽에 있는 글램핑장이다.', 'It is a glamping site located on the outskirts of Gyeongju.'),
    (55, 'intro', '두바퀴로 가는 자동차는 경주시 외곽에 있는 글램핑장이다. 한글, 큐브, VIP로 각기 다른 스타일의 카바나가 총 17개 있다.', 'The two-wheeled vehicle is a glamping site located on the outskirts of Gyeongju. There are a total of 17 cabanas of different styles: Korean, Cube, and VIP.'),
    (55, 'story', '내부는 에어컨과 난방시설과 함께 기본 편의 시설이 되어 있고, 특히 개별 찜질방이 설치되어 있다.
수영장은 온수로 실내수영장처럼 이용 가능하고 규모도 큰 편이다.
ATV, 3륜 전기 오토바이, 유아 범퍼카, 자전거 등도 무료로 이용할 수 있고, VR 게임 체험 시설, 노래방 등도 준비되어 있어, 캠핑장 내에서 즐길 거리가 풍부하다.', 'The interior is equipped with basic amenities including air conditioning and heating, and in particular, an individual sauna is installed.
The swimming pool is heated and can be used like an indoor swimming pool and is large in size.
You can use ATVs, three-wheeled electric motorcycles, bumper cars for children, and bicycles for free, and there are also VR game experience facilities and karaoke rooms, so there is plenty to enjoy at the campsite.'),
    (55, 'tip', '두바퀴로 가는 자동차에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water in a two-wheeled vehicle, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (55, 'did_you_know', '한글, 큐브, VIP로 각기 다른 스타일의 카바나가 총 17개 있어요.', 'There are a total of 17 cabanas of different styles: Korean, Cube, and VIP.'),
    (56, 'summary', '경상북도 경주시 양남면 하서리에 위치한 어항이다.', 'It is a fishing port located in Haseo-ri, Yangnam-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (56, 'intro', '하서항은 경상북도 경주시 양남면 하서리에 위치한 어항이다. 하서4리 진리마을에 있어 진리항 또는 율포진리항으로도 불린다.', 'Haseo Port is a fishing port located in Haseo-ri, Yangnam-myeon, Gyeongju-si, Gyeongsangbuk-do. Located in Haseo 4-ri Jinri Village, it is also called Jinri Port or Yulpo Jinri Port.'),
    (56, 'story', '항구 인근에는 몽돌과 모래가 섞인 하서해변이 있다.
하서항은 읍천항까지 이어지는 1.7㎞ 길이의 해안 산책로인 파도소리길의 시작점이다.
이 길을 따라 걸으면 천연기념물로 지정된 경주 양남 주상절리군과 부채꼴 주상절리를 관람할 수 있는 양남 주상절리 전망대가 위치한다.', 'Near the port, there is Haseo Beach with a mixture of pebbles and sand.
Haseo Port is the starting point of Padosori Road, a 1.7km long coastal promenade that leads to Eupcheon Port.
If you walk along this road, you will reach the Yangnam Columnar Joint Observatory, where you can view the Yangnam Columnar Joints and fan-shaped columnar joints in Gyeongju, which are designated as natural monuments.'),
    (56, 'tip', '하서항에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'Please first check the age, clothing, and equipment requirements for the activities you want to experience at Hexi Port. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (56, 'did_you_know', '이 길을 따라 걸으면 천연기념물로 지정된 경주 양남 주상절리군과 부채꼴 주상절리를 관람할 수 있는 양남 주상절리 전망대가 위치해요.', 'If you walk along this road, you will reach the Yangnam Columnar Joint Observatory, where you can see the Yangnam Columnar Joints and fan-shaped columnar joints in Gyeongju, which are designated as natural monuments.'),
    (57, 'summary', '경주 동남산 기슭에 자리한 경북천년숲정원은 본래 경상북도 산림환경연구원이었다.', 'Gyeongbuk Millennium Forest Garden, located at the foot of Dongnam Mountain in Gyeongju, was originally the Gyeongsangbuk-do Forest Environment Research Institute.'),
    (57, 'intro', '경주 동남산 기슭에 자리한 경북천년숲정원은 본래 경상북도 산림환경연구원이었다. 산림환경을 조사하고 천연기념물 후계목 증식·보존, 병해충 방제 등 산림 보호를 위한 연구를 수행하던 기관이었으나, 2023년 시민에게 숲공원으로 개방되었다.', 'Gyeongbuk Millennium Forest Garden, located at the foot of Dongnam Mountain in Gyeongju, was originally the Gyeongsangbuk-do Forest Environment Research Institute. It was an organization that investigated the forest environment and conducted research for forest protection, such as propagation and preservation of natural monument succession trees and pest control, but was opened to citizens as a forest park in 2023.'),
    (57, 'story', '지자체가 조성하고 관리하는 지방정원으로는 경북천년숲정원이 국내 다섯 번째이자, 경북에서는 첫 번째이다.
아스팔트 도로를 기준으로 서쪽은 경북 산림 환경연구원이 있고 동쪽으로 숲과 오솔길, 개울과 정원 등이 조성되어 있다.
메타세쿼이아 숲길을 따라 들어가면 제일 먼저 거울 숲을 만난다.', 'As a local garden created and managed by a local government, the Gyeongbuk Millennium Forest Garden is the fifth in Korea and the first in Gyeongbuk.
Based on the asphalt road, to the west is the Gyeongbuk Forest Environment Research Institute, and to the east are forests, paths, streams, and gardens.
When you follow the metasequoia forest path, the first thing you see is the mirror forest.'),
    (57, 'tip', '경북천년숲정원을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongbuk Millennium Forest Garden, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (57, 'did_you_know', '산림환경을 조사하고 천연기념물 후계목 증식·보존, 병해충 방제 등 산림 보호를 위한 연구를 수행하던 기관이었으나, 2023년 시민에게 숲공원으로 개방되었다고 해요.', 'It was an organization that investigated the forest environment and conducted research for forest protection, such as propagation and preservation of natural monument succession trees and pest control, but it was opened to citizens as a forest park in 2023.'),
    (58, 'summary', '경주시 탑동에 위치한 4기의 봉토무덤과 1기의 원형무덤이다.', 'There are four earthen mound tombs and one circular tomb located in Tap-dong, Gyeongju-si.'),
    (58, 'intro', '경주시 탑동에 위치한 4기의 봉토무덤과 1기의 원형무덤이다. 1969년 8월 27일 사적으로 지정되었으며, 내부구조는 알 수 없으나 무덤의 겉모습은 경주시내에 있는 다른 삼국시대 신라무덤과 같이 둥글게 흙을 쌓아 올린 원형 봉토무덤이다.', 'There are four earthen mound tombs and one circular tomb located in Tap-dong, Gyeongju-si. It was designated as a historic site on August 27, 1969, and the internal structure is unknown, but the exterior appearance of the tomb is a circular tomb with earth piled up like other Silla tombs from the Three Kingdoms period in Gyeongju.'),
    (58, 'story', '1호 무덤이 높이 10m로 가장 크며, 2호 무덤은 표주박형으로 봉분이 두 개인 2인용 무덤이다.
이러한 대형 원형 봉토무덤은 신라에서는 4세기 이후 등장하는 것으로 박혁거세 당시의 무덤 형식은 아니다.
『삼국사기』에는 신라 시조 박혁거세와 왕비 알영부인, 제2대 남해왕, 제3대 유리왕, 제5대 파사왕 등 신라 초기 4명의 박씨 임금과 왕비 1명의 무덤이라 나와 있다.', 'Tomb No. 1 is the largest at 10m in height, and Tomb No. 2 is a two-person tomb with two gourd-shaped burial mounds.
These large circular earthen mound tombs appeared in Silla after the 4th century and are not the type of tombs from the time of Park Hyeokgeose.
Samguksagi (History of the Three Kingdoms) states that it is the tomb of four kings of the Park clan and one queen from the early days of Silla, including the founder of Silla, Park Hyeokgeose, and his queen, Lady Alyeong, the 2nd King Namhae, the 3rd King Yuri, and the 5th King Pasa.'),
    (58, 'tip', '경주 오릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Oreung, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (58, 'did_you_know', '1969년 8월 27일 사적으로 지정되었으며, 내부구조는 알 수 없으나 무덤의 겉모습은 경주시내에 있는 다른 삼국시대 신라무덤과 같이 둥글게 흙을 쌓아 올린 원형 봉토무덤이에요.', 'It was designated as a historic site on August 27, 1969, and the internal structure is unknown, but the exterior of the tomb is a circular tomb with earth piled up like other Silla tombs from the Three Kingdoms period in Gyeongju.'),
    (59, 'summary', '신라의 동식물 문화를 현대적으로 재해석한 사계절 복합 체험 공간이에요.', 'It is a four-season complex experience space that reinterprets Silla’s flora and fauna culture in a modern way.'),
    (59, 'intro', '경주 동궁원은 보문관광단지 입구에서 식물원과 버드파크를 함께 만날 수 있는 공간이에요. 동궁과 월지에서 진귀한 꽃과 새를 길렀다는 기록을 바탕으로 신라의 정원을 현대적인 체험 시설로 되살렸습니다.', 'Gyeongju Donggungwon is a space where you can find a botanical garden and a bird park at the entrance of Bomun Tourist Complex. Based on records of rare flowers and birds being raised in Donggung Palace and Wolji Pond, the gardens of Silla have been revived as modern experience facilities.'),
    (59, 'story', '농업 시험포와 화훼 재배지였던 터는 식물 전시와 생태 체험을 즐기는 관광 공간으로 바뀌었어요. 유리 온실의 식물과 새 전시를 차례로 둘러보면 경주가 가진 역사 이야기와 자연 관찰의 재미를 한 자리에서 경험할 수 있습니다.', 'The site that used to be an agricultural experiment and flower farm has been transformed into a tourist space where you can enjoy plant exhibitions and ecological experiences. By looking through the glass greenhouse''s plant and bird exhibits one by one, you can experience the history of Gyeongju and the fun of observing nature all in one place.'),
    (59, 'tip', '실내 온실은 계절과 날씨의 영향을 덜 받아 비 오는 날에도 좋아요. 버드파크까지 함께 본다면 관람 시간이 길어지므로 입장 마감과 체험 운영 시간을 확인하고 편한 신발을 준비하세요.', 'Indoor greenhouses are less affected by seasons and weather, so they are great even on rainy days. If you also visit Bird Park, the viewing time will be longer, so check the admission deadline and experience operating hours and prepare comfortable shoes.'),
    (59, 'did_you_know', '동궁과 월지에서 꽃과 진귀한 새를 길렀다는 기록이 오늘날 동궁원의 이야기 바탕이 되었어요.', 'Records of flowers and rare birds being raised in Donggung Palace and Wolji Pond became the basis for the story of Donggungwon today.'),
    (60, 'summary', '경주월드는 어뮤즈먼트와 워터파크인 캘리포니아비치를 운영하고 있다.', 'Gyeongju World operates California Beach, an amusement and water park.'),
    (60, 'intro', '경주월드는 어뮤즈먼트와 워터파크인 캘리포니아비치를 운영하고 있다. 그 중 30여개의 놀이기구를 운영하고 있는 테마파크 경주월드 어뮤즈먼트는 스노우파크와 드라켄밸리 등 종합휴양시설을 갖춘 테마파크이다.', 'Gyeongju World operates California Beach, an amusement and water park. Among them, Gyeongju World Amusement, a theme park that operates about 30 rides, is a theme park with comprehensive recreational facilities such as a snow park and Draken Valley.'),
    (60, 'story', '타임라이더, 발키리, 크라크, 드래곤레이스 등 인생 어트랙션이 있으며, 다양한 공연과 행사도 진행 중이다.
또한 드라켄스낵, 스테이지 매점, 델리하우스 등 식사를 할 수 있는 매장이 있으며, 피크닉 그라운드에서는 직접 가져온 도시락을 먹을 수 있다.
오늘의 경주월드 어뮤즈먼트은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'There are life-changing attractions such as Time Rider, Valkyrie, Krak, and Dragon Race, and various performances and events are also underway.
There are also stores where you can eat, such as Draken Snacks, Stage Canteen, and Deli House, and you can eat your own packed lunch at the picnic ground.
Today''s Gyeongju World amusement leaves a different memory for each person who visits Gyeongju.'),
    (60, 'tip', '경주월드 어뮤즈먼트을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju World Amusement, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (60, 'did_you_know', '그 중 30여개의 놀이기구를 운영하고 있는 테마파크 경주월드 어뮤즈먼트는 스노우파크와 드라켄밸리 등 종합휴양시설을 갖춘 테마파크이에요.', 'Among them, Gyeongju World Amusement, a theme park that operates about 30 rides, is a theme park with comprehensive recreational facilities such as a snow park and Draken Valley.'),
    (61, 'summary', '소풍캠핑장은 경북 경주시 천북면 화산리에 자리한 폐교 리모델링 캠핑장이다.', 'Picnic Camping Site is a remodeled camping site for an abandoned school located in Hwasan-ri, Cheonbuk-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (61, 'intro', '소풍캠핑장은 경북 경주시 천북면 화산리에 자리한 폐교 리모델링 캠핑장이다. 캠핑장에는 넉넉한 크기의 오토캠핑 사이트 14면이 마련되어 있으며 사이트 간 간격도 여유로워 보다', 'Picnic Camping Site is a remodeled camping site for an abandoned school located in Hwasan-ri, Cheonbuk-myeon, Gyeongju-si, Gyeongsangbuk-do. The campsite has 14 generously sized auto camping sites, with ample space between sites.'),
    (61, 'story', '프라이빗 한 캠핑을 즐길 수 있다.
카라반과 개인 트레일러 동반 입장이 가능하며, 연박 이용객에게는 할인 혜택도 제공한다.
또한 천연 염색과 천연 화장품 만들기, 도예 체험 등 다양한 체험 프로그램이 준비되어 있어 가족 단위 방문객들에게 인기가 높다.', 'You can enjoy private camping.
Caravans and personal trailers are allowed to enter, and discounts are also provided for consecutive stay guests.
In addition, various experience programs such as natural dyeing, natural cosmetics making, and pottery experience are prepared, making it popular among family visitors.'),
    (61, 'tip', '소풍캠핑장(경주)은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'At the picnic camping site (Gyeongju), the site type and equipment provided may vary from site to site. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (61, 'did_you_know', '캠핑장에는 넉넉한 크기의 오토캠핑 사이트 14면이 마련되어 있으며 사이트 간 간격도 여유로워 보다', 'The campsite has 14 generously sized auto camping sites, with ample space between sites.'),
    (62, 'summary', '경상북도 경주시 산내면에 위치한 캠핑형 바비큐 음식점으로, 자연 속에서 특별한 식사를 즐길 수 있는 공간이다.', 'It is a camping-type barbecue restaurant located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do, and is a space where you can enjoy a special meal in nature.'),
    (62, 'intro', '산내956은 경상북도 경주시 산내면에 위치한 캠핑형 바비큐 음식점으로, 자연 속에서 특별한 식사를 즐길 수 있는 공간이다. 글램핑 형태의 텐트가 마련되어 있어 캠핑 분위기를 느끼며 편안하게 바비큐를 즐길 수 있으며, 별도의 장비를 준비하지 않아도 이용할 수 있는 것이 장점이다.', 'Sannae 956 is a camping-type barbecue restaurant located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do, and is a space where you can enjoy a special meal in nature. A glamping-type tent is provided so you can comfortably enjoy a barbecue while feeling the camping atmosphere. The advantage is that you can use it without having to prepare any separate equipment.'),
    (62, 'story', '매점에서는 육류를 비롯한 다양한 식재료와 먹거리를 판매하고 있어 원하는 재료를 직접 구입해 구워 먹는 방식으로 운영된다.
울창한 자연환경에 둘러싸여 여유로운 시간을 보내기 좋으며, 가족이나 친구, 연인과 함께 방문해 색다른 추억을 만들 수 있다.
인근에는 경주국립공원 등 관광지가 있어 경주 여행과 함께 즐기기에도 좋다.', 'The concession stand sells a variety of ingredients and food, including meat, so you can buy the ingredients you want and grill them yourself.
It is a great place to spend a leisurely time surrounded by a lush natural environment, and you can make unique memories by visiting with family, friends, or lovers.
Nearby are tourist attractions such as Gyeongju National Park, making it a great place to enjoy while traveling in Gyeongju.'),
    (62, 'tip', '산내956은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'At Sannae 956, the site type and provided equipment may vary for each seat. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (62, 'did_you_know', '산내956은 경상북도 경주시 산내면에 위치한 캠핑형 바비큐 음식점으로, 자연 속에서 특별한 식사를 즐길 수 있는 공간이에요.', 'Sannae 956 is a camping-type barbecue restaurant located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do, and is a space where you can enjoy a special meal in nature.'),
    (63, 'summary', '경상북도 경주시 감포읍에 위치한 카라반 숙소로, 오류고아라해변과 인접해 아름다운 동해 바다', 'A caravan accommodation located in Gampo-eup, Gyeongju-si, Gyeongsangbuk-do, adjacent to Oryu Goara Beach and the beautiful East Sea.'),
    (63, 'intro', '뷰델카라반펜션은 경상북도 경주시 감포읍에 위치한 카라반 숙소로, 오류고아라해변과 인접해 아름다운 동해 바다 풍경을 감상할 수 있는 곳이다.', 'Beaudel Caravan Pension is a caravan accommodation located in Gampo-eup, Gyeongju-si, Gyeongsangbuk-do, and is adjacent to Oryugoara Beach, where you can enjoy the beautiful East Sea seascape.'),
    (63, 'story', '고급스럽고 세련된 디자인의 카라반이 마련되어 있으며, 객실 내부에는 침대와 TV를 비롯해 취사 및 생활에 필요한 시설이 갖춰져 있어 편안한 휴식을 즐길 수 있다.
바다를 바라보며 머무를 수 있는 쾌적한 환경과 함께 감성적인 캠핑 분위기를 경험할 수 있는 것이 특징이다.
또한 다목적 루프탑 쉼터와 루프탑 야외 수영장, 카페, 야외 영화관 등 다양한 부대시설을 운영해 숙소 안에서도 다채로운 시간을 보낼 수 있다.', 'There is a caravan with a luxurious and sophisticated design, and the rooms are equipped with beds, TVs, and other necessary facilities for cooking and living, so you can enjoy a comfortable rest.
The characteristic feature is that you can experience an emotional camping atmosphere along with a comfortable environment where you can stay while looking at the sea.
In addition, various auxiliary facilities such as a multi-purpose rooftop rest area, rooftop outdoor swimming pool, cafe, and outdoor movie theater are operated so that you can enjoy a variety of times within the accommodation.'),
    (63, 'tip', '뷰델카라반펜션에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Budel Caravan Pension, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (63, 'did_you_know', '인근에는 감포항과 나정 고운 모래해변 등 관광 명소가 자리하고 있어 경주 동해안 여행과 함께 즐기기 좋다고 해요.', 'Nearby are tourist attractions such as Gampo Port and Najeong Fine Sand Beach, making it a great place to enjoy along with a trip to the east coast of Gyeongju.'),
    (64, 'summary', '경북 경주시 구황동에 위치한 황룡사 역사문화관은 황룡사지의 바로 옆에 건립된 전시관이다.', 'Hwangnyongsa History and Culture Museum, located in Guhwang-dong, Gyeongju-si, Gyeongsangbuk-do, is an exhibition hall built right next to Hwangnyongsa Temple Site.'),
    (64, 'intro', '경북 경주시 구황동에 위치한 황룡사 역사문화관은 황룡사지의 바로 옆에 건립된 전시관이다. 황룡사의 역사적 의미를 재조명하고 복원에 대한 염원을 담은 곳으로 황룡사지의 연구와 발굴조사 성과를 국민과 공유하기 위해 마련되었다.', 'Hwangnyongsa History and Culture Museum, located in Guhwang-dong, Gyeongju-si, Gyeongsangbuk-do, is an exhibition hall built right next to Hwangnyongsa Temple Site. It is a place that sheds new light on the historical significance of Hwangnyongsa Temple and contains wishes for its restoration. It was prepared to share the results of research and excavations at the Hwangnyongsa Temple site with the public.'),
    (64, 'story', '황룡사지에서 출토된 유물을 복제하고 유적을 재현 및 전시하여 신라시대 호국사찰의 장엄함을 실제로 느껴볼 수 있다.
내부에는 황룡사 건립부터 소실까지의 과정을 담은 3D 영상 시청각실, 발굴 조사 과정에서 출토된 유물을 전시한 신라 역사전시실 등으로 이루어져 졌다.
1층에는 황룡사 9층 목탑을 10분의 1 크기로 재현한 모형탑도 전시되어 있다.', 'By replicating relics excavated from Hwangnyongsa Temple site and reproducing and exhibiting ruins, you can actually experience the grandeur of a patriotic temple during the Silla Dynasty.
Inside, it consists of a 3D audio-visual room that shows the process from the construction of Hwangnyongsa Temple to its destruction, and a Silla history exhibition room that displays artifacts excavated during the excavation.
On the first floor, a model pagoda replicating the nine-story wooden pagoda of Hwangnyongsa Temple in one-tenth the size is also on display.'),
    (64, 'tip', '황룡사역사문화관은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Hwangnyongsa History and Culture Museum just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (64, 'did_you_know', '경북 경주시 구황동에 위치한 황룡사 역사문화관은 황룡사지의 바로 옆에 건립된 전시관이에요.', 'Hwangnyongsa History and Culture Museum, located in Guhwang-dong, Gyeongju-si, Gyeongsangbuk-do, is an exhibition hall built right next to Hwangnyongsa Temple Site.'),
    (65, 'summary', '경주시 황리단길 인근에 위치한 복합문화공간으로, 공연장, 북카페, 청년상점, 무료 짐보관함 등 다양한 시설을 갖추고 있다.', 'It is a complex cultural space located near Hwangridan-gil, Gyeongju-si, and is equipped with various facilities such as a performance hall, book cafe, youth store, and free luggage storage.'),
    (65, 'intro', '황리단길 생활문화센터는 경주시 황리단길 인근에 위치한 복합문화공간으로, 공연장, 북카페, 청년상점, 무료 짐보관함 등 다양한 시설을 갖추고 있다. 2021년에 개관하여 지역 주민과 관광객에게 문화와 소통의 장을 제공하며, 경주의 새로운 문화 허브로 자리 잡고 있다.', 'Hwangridan-gil Living Culture Center is a complex cultural space located near Hwangridan-gil, Gyeongju-si, and is equipped with various facilities such as a performance hall, book cafe, youth store, and free luggage storage. Opening in 2021, it provides a place for culture and communication for local residents and tourists, and is establishing itself as a new cultural hub in Gyeongju.'),
    (65, 'story', '이곳은 주변의 풍경과 어우러져 방문객에게 특별한 장면을 보여줍니다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 황리단길 생활문화센터은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'This place blends in with the surrounding landscape and presents a special scene to visitors.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Hwangridan-gil Living Culture Center leaves a different memory for each person who visits Gyeongju.'),
    (65, 'tip', '황리단길 생활문화센터을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Hwangridan-gil Life and Culture Center, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (65, 'did_you_know', '2021년에 개관하여 지역 주민과 관광객에게 문화와 소통의 장을 제공하며, 경주의 새로운 문화 허브로 자리 잡고 있어요.', 'Opening in 2021, it provides a place for culture and communication for local residents and tourists, and is establishing itself as a new cultural hub in Gyeongju.'),
    (66, 'summary', '에서는 향토사의 조사, 연구 및 사료의 수집과 발간, 지역 문화행사 및 공연 개최, 문화강좌 등 다양한 활동을 하고 있다.', 'It carries out a variety of activities, including research on local history, collection and publication of research and historical materials, holding local cultural events and performances, and cultural lectures.'),
    (66, 'intro', '경주문화원에서는 향토사의 조사, 연구 및 사료의 수집과 발간, 지역 문화행사 및 공연 개최, 문화강좌 등 다양한 활동을 하고 있다. 경주 지역 문화 창달과 전통문화를 전승, 보존하기 위한 운영을 하고 있다.', 'The Gyeongju Cultural Center engages in a variety of activities, including research on local history, collection and publication of research and historical materials, holding local cultural events and performances, and cultural lectures. It is operated to promote the culture of the Gyeongju region and to transmit and preserve traditional culture.'),
    (66, 'story', '문화원에는 조선시대 경주의 역사와 문화를 전시하는 향토사료관과 조선시대의 종각, 동경관, 교육장 등을 볼 수 있다.
또한 경상북도 기념물로 지정된 아름다운 은행나무가 경주문화원 후원에 위치하고 있어 가을에는 이를 보기 위해 많은 관광객들이 방문하고 있다.
오늘의 경주문화원은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'At the Cultural Center, you can see the local history museum that displays the history and culture of Gyeongju during the Joseon Dynasty, the bell pavilion of the Joseon Dynasty, the Donggyeong Pavilion, and the educational center.
In addition, the beautiful ginkgo tree, designated as a Gyeongsangbuk-do monument, is located in the back garden of the Gyeongju Cultural Center, and many tourists visit in the fall to see it.
Today''s Gyeongju Cultural Center leaves a different memory for each person who visits Gyeongju.'),
    (66, 'tip', '경주문화원을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Gyeongju Cultural Center, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (66, 'did_you_know', '또한 경상북도 기념물로 지정된 아름다운 은행나무가 경주문화원 후원에 위치하고 있어 가을에는 이를 보기 위해 많은 관광객들이 방문하고 있어요.', 'In addition, the beautiful ginkgo tree, designated as a Gyeongsangbuk-do monument, is located in the back garden of the Gyeongju Cultural Center, and many tourists visit in the fall to see it.'),
    (67, 'summary', '독락당은 회재 이언적(1491∼1553) 선생이 벼슬을 그만두고 고향에 돌아와 지은 집의 사랑채이다.', 'Dongnakdang is the sarangchae of the house built by Hoejae Lee Eon-jeok (1491-1553) after he returned to his hometown after quitting his government job.'),
    (67, 'intro', '독락당은 회재 이언적(1491∼1553) 선생이 벼슬을 그만두고 고향에 돌아와 지은 집의 사랑채이다. 조선 중종 11년(1516)에 건립된 이 독락당은 정면 4칸, 측면 2칸의 팔작집으로 온돌방(1칸× 2칸)과 대청(3칸× 2칸)으로 되어 있다.', 'Dongnakdang is the sarangchae of the house built by Hoejae Lee Eon-jeok (1491-1553) after he returned to his hometown after quitting his government job. Built in the 11th year of King Jungjong''s reign (1516) in the Joseon Dynasty, Doknakdang is a 4-kan (4-kan) front and 2-kan (two-kan) paljak-style house with an ondol room (1 kan x 2 kan) and a daecheong (3 kan x 2 kan).'),
    (67, 'story', '건물의 짜임새는 오량(五樑)에 두리기둥을 세우고 쇠서 하나를 둔 초익공(初翼工)의 공포(拱包)로 꾸몄다.
대청 천장은 서까래가 노출된 연등천장이고 종도리를 받친 대공(臺工)의 모양이 특이하다.
독락당 옆쪽 담장 살창을 달아 대청에서 살창을 통하여 앞 냇물을 바라보게 한 것은 특출한 공간구성이며, 독락당 뒤쪽의 계정(溪亭) 또한 자연에 융합하려는 공간성을 드러내 준다고 하겠다.', 'The structure of the building is decorated with a pillar at the top of the five pillars and the Gonggong (拱包) design of the Choikgong (初翼工) with a single iron stand.
The ceiling of the main hall is a lotus lantern ceiling with exposed rafters, and the shape of the daegong (臺工) supporting the bell dori is unique.
It is an exceptional spatial composition to install slats on the wall next to Dongnakdang so that the main hall can see the stream in front through the slats, and the stream at the back of Dongnakdang also reveals a spatiality that seeks to merge with nature.'),
    (67, 'tip', '경주 독락당을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Dokrakdang in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (67, 'did_you_know', '독락당은 회재 이언적(1491∼1553) 선생이 벼슬을 그만두고 고향에 돌아와 지은 집의 사랑채이에요.', 'Dongnakdang is the sarangchae of the house built by Hoejae Lee Eon-jeok (1491-1553) after he returned to his hometown after quitting his government job.'),
    (68, 'summary', '경북 경주시에 자리 잡고 있다.', 'It is located in Gyeongju-si, Gyeongbuk.'),
    (68, 'intro', '코라드 청정누리 공원 코라디움은 경북 경주시에 자리 잡고 있다. 코라디움은 방폐장과 방폐물 관리사업에 대해 올바른 정보와 지식을 얻을 수 있는 홍보 전시실이 조성되어 있으며, 실내에서 쉴 수 있는 휴식공간도 마련되어 있다.', 'Korad Clean Nuri Park Koradium is located in Gyeongju-si, Gyeongbuk. Korradium has a promotional exhibition room where you can get accurate information and knowledge about radioactive waste sites and waste management projects, and there is also a rest area where you can relax indoors.'),
    (68, 'story', '동해와 문무대왕릉을 한눈에 볼 수 있는 전망대도 조성되었다.
자연과 과학이 어우러진 테마파크는 방문객의 휴식 및 소규모 이벤트를 위한 레저문화 공간을 제공하고 온 가족이 즐길 수 있는 산책로와 체험 학습장으로 사용된다.
주차장에는 친환경 태양광 시설을 설치해 조명으로 활용되며 학습과 공연 등 지역주민들을 위한 야외무대도 마련되었다.', 'An observatory has also been built where you can see the East Sea and the Royal Tomb of King Munmu at a glance.
The theme park, which combines nature and science, provides a leisure and cultural space for visitors to relax and hold small events, and is used as a walking trail and experiential learning center for the whole family to enjoy.
An eco-friendly solar power facility was installed in the parking lot to be used for lighting, and an outdoor stage was also set up for local residents to participate in learning and performances.'),
    (68, 'tip', '코라드 청정누리 공원 코라디움은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Korad Clean Nuri Park Koradium just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (68, 'did_you_know', '코라디움은 방폐장과 방폐물 관리사업에 대해 올바른 정보와 지식을 얻을 수 있는 홍보 전시실이 조성되어 있으며, 실내에서 쉴 수 있는 휴식공간도 마련되어 있어요.', 'Korradium has a promotional exhibition room where you can get accurate information and knowledge about radioactive waste sites and waste management projects, and there is also a relaxation area where you can relax indoors.'),
    (69, 'summary', '경상북도 경주시 서면에 위치한 체험형 미디어 공간으로, 자연 환경과 첨단 기술을 결합한 다양한 미디어 콘텐츠와 체험 프로그램을 제공한다.', 'It is an experiential media space located in Seomyeon, Gyeongju-si, Gyeongsangbuk-do, and provides a variety of media contents and experience programs that combine the natural environment and cutting-edge technology.'),
    (69, 'intro', '정글미디어파크는 경상북도 경주시 서면에 위치한 체험형 미디어 공간으로, 자연 환경과 첨단 기술을 결합한 다양한 미디어 콘텐츠와 체험 프로그램을 제공한다. 정글미디어파크만의 공간과 분위기 속에서 경주의 또 다른 모습을 경험할 수 있습니다.', 'Jungle Media Park is an experiential media space located in Seomyeon, Gyeongju-si, Gyeongsangbuk-do, and provides a variety of media contents and experience programs that combine the natural environment and cutting-edge technology. You can experience a different side of Gyeongju in Jungle Media Park’s unique space and atmosphere.'),
    (69, 'story', '이곳은 주변의 풍경과 어우러져 방문객에게 특별한 장면을 보여줍니다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 정글미디어파크은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'This place blends in with the surrounding landscape and presents a special scene to visitors.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Jungle Media Park leaves a different memory for each person who visits Gyeongju.'),
    (69, 'tip', '정글미디어파크을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Jungle Media Park, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (69, 'did_you_know', '정글미디어파크는 경상북도 경주시 서면에 위치한 체험형 미디어 공간으로, 자연 환경과 첨단 기술을 결합한 다양한 미디어 콘텐츠와 체험 프로그램을 제공해요.', 'Jungle Media Park is an experiential media space located in Seomyeon, Gyeongju-si, Gyeongsangbuk-do, and provides a variety of media contents and experience programs that combine the natural environment and cutting-edge technology.'),
    (70, 'summary', '경주 솔거미술관은 한국화의 거장 소산 박대성 화백이 작품 830여 점을 기증하며 건립이 추진된 공립미술관이다.', 'Solgeo Art Museum in Gyeongju is a public art museum whose construction was promoted with the donation of 830 works by Sosan Park Dae-seong, a master of Korean painting.'),
    (70, 'intro', '경주 솔거미술관은 한국화의 거장 소산 박대성 화백이 작품 830여 점을 기증하며 건립이 추진된 공립미술관이다. 2015년 실크로드 경주 엑스포 개막과 함께 문을 열었으며, 승효상 건축가가 설계하여 ''사람과 공간, 자연의 경계가 허물어지는 공간''을 구현했다.', 'Solgeo Art Museum in Gyeongju is a public art museum whose construction was promoted with the donation of 830 works by Sosan Park Dae-seong, a master of Korean painting. It opened with the opening of the 2015 Silk Road Gyeongju Expo, and was designed by architect Seung Hyo-sang to create a ‘space where the boundaries between people, space, and nature are broken down.’'),
    (70, 'story', '관람객의 동선을 배려해 미로처럼 유기적으로 분리된 전시 공간은 박대성 화백의 상설전시실과 다채로운 기획전시실로 나뉜다.
특히 상설전시실에는 자연광이 쏟아지는 커다란 창이 있어 계절마다
변하는 밖의 풍경이 마치 하나의 작품처럼 느껴지는 것으로 유명하며, 작품에 대한 깊이 있는 이해를 돕기 위한 도슨트 프로그램도 운영하고 있다.', 'The exhibition space, which is organically separated like a maze in consideration of the visitor''s movement, is divided into a permanent exhibition room by artist Park Dae-sung and a colorful special exhibition room.
In particular, the permanent exhibition room has a large window that lets in natural light, so it changes every season.
It is famous for the changing exterior scenery that feels like a work of art, and it also operates a docent program to help you gain a deeper understanding of the work.'),
    (70, 'tip', '솔거미술관을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Solgeo Art Museum, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (70, 'did_you_know', '경주 솔거미술관은 한국화의 거장 소산 박대성 화백이 작품 830여 점을 기증하며 건립이 추진된 공립미술관이에요.', 'Solgeo Art Museum in Gyeongju is a public art museum whose construction was promoted with the donation of 830 works by Sosan Park Dae-seong, a master of Korean painting.'),
    (71, 'summary', '경주시 화랑마을은 우리의 고귀한 문화유산인 화랑의 정신과 문화를 재조명하고 확대 및 발전시켜 청소년 수련활동과 글로벌 체험관광, 휴양 문화의 새로운 패러다임을 열어가는 곳이다.', 'Gyeongju-si Hwarang Village is a place that reexamines, expands, and develops the spirit and culture of Hwarang, our precious cultural heritage, and opens a new paradigm for youth training activities, global experiential tourism, and recreational culture.'),
    (71, 'intro', '경주시 화랑마을은 우리의 고귀한 문화유산인 화랑의 정신과 문화를 재조명하고 확대 및 발전시켜 청소년 수련활동과 글로벌 체험관광, 휴양 문화의 새로운 패러다임을 열어가는 곳이다. 화랑마을은 청소년수련시설의 기능뿐 아니라 가족단위 관광객들이 콘텐츠를 즐길 수 있는 화랑전시관, 휴식과 힐링을 즐길 수 있는 어울마당, 어린이놀이터, 산책하기 좋은 코스 등 주변 부대시설을 갖추고 있으며, 야경이 아름다워 경주시의 새로운 랜드마크로 평가받는다.', 'Gyeongju-si Hwarang Village is a place that reexamines, expands, and develops the spirit and culture of Hwarang, our precious cultural heritage, and opens a new paradigm for youth training activities, global experiential tourism, and recreational culture. Hwarang Village not only functions as a youth training facility, but also has surrounding auxiliary facilities such as a Hwarang Exhibition Hall where family tourists can enjoy content, a playground where people can enjoy rest and healing, a children''s playground, and a good course for walking. It is evaluated as a new landmark in Gyeongju City due to its beautiful night view.'),
    (71, 'story', '또한, 화랑마을은 글로벌 체험형 교육, 문화 및 관광, 휴양 프로그램과 청소년 수련과 교류, 문화 활동 등 다양한 체험, 회의, 세미나 등 목적을 위한 시설 대관 사업을 하고 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 화랑마을은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'In addition, Hwarang Village is engaged in facility rental projects for various purposes such as global experiential education, culture and tourism, recreation programs, youth training and exchange, and cultural activities, meetings, and seminars.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Hwarang Village remains a different memory for each person who visits Gyeongju.'),
    (71, 'tip', '화랑마을은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Hwarang Village just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (71, 'did_you_know', '또한, 화랑마을은 글로벌 체험형 교육, 문화 및 관광, 휴양 프로그램과 청소년 수련과 교류, 문화 활동 등 다양한 체험, 회의, 세미나 등 목적을 위한 시설 대관 사업을 하고 있어요.', 'In addition, Hwarang Village is engaged in facility rental projects for various purposes such as global experiential education, culture and tourism, recreation programs, youth training and exchange, and cultural activities, as well as conferences and seminars.'),
    (72, 'summary', '1962년 제1회를 시작으로 올해 제53회를 맞이한다.', 'Starting with the first event in 1962, this year marks the 53rd event.'),
    (72, 'intro', '신라문화제는 1962년 제1회를 시작으로 올해 제53회를 맞이한다. 월정교를 배경으로 신라의 찬란한 역사를 재현하는 화백제전과 수많은 아티스트가 참여해 화려한 공연을 선보이는 거리예술축제, 실크로드페스타까지 다채로운 콘텐츠가 가득하다.', 'The Silla Cultural Festival started its first event in 1962 and celebrates its 53rd anniversary this year. It is filled with a variety of contents, including the Painter Festival, which recreates the glorious history of Silla against the backdrop of Woljeong Bridge, the Street Arts Festival, where numerous artists participate and present spectacular performances, and the Silk Road Festa.'),
    (72, 'story', '화랑힙합페스타는 고분을 배경으로 국내 최정상급 힙합 아티스트의 공연이 펼쳐져 경주에서만 볼 수 있는 이색적인 풍경을 선사한다.
즐거움을 더하는 낭만 야시장인 달빛난장은 경주 지역 상인이 직접 참여하여 경주의 맛을 자랑한다.
이처럼 천년고도 경주를 대표하는 축제인 신라문화제에서는 역사와 예술이 하나로 어우러지는 특별한 순간을 만나볼 수 있다.', 'Hwarang Hip Hop Festa presents a unique scene that can only be seen in Gyeongju, with performances by Korea''s top hip hop artists taking place against the backdrop of ancient tombs.
Moonlight Dwarf, a romantic night market that adds to the fun, boasts the taste of Gyeongju with local merchants directly participating.
In this way, at the Silla Cultural Festival, a festival representing the thousand-year old city of Gyeongju, you can experience a special moment where history and art come together.'),
    (72, 'tip', '신라문화제을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Silla Cultural Festival, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (72, 'did_you_know', '신라문화제는 1962년 제1회를 시작으로 올해 제53회를 맞이해요.', 'The Silla Cultural Festival started its first event in 1962 and is celebrating its 53rd anniversary this year.'),
    (73, 'summary', '경주 무열왕릉은 신라 제29대 태종(太宗) 무열왕(재위 654∼661, 김춘추)의 능이다.', 'King Muyeol''s tomb in Gyeongju is the tomb of King Muyeol (reign 654-661, Kim Chun-chu), the 29th king of Silla.'),
    (73, 'intro', '경주 무열왕릉은 신라 제29대 태종(太宗) 무열왕(재위 654∼661, 김춘추)의 능이다. 경주 북서쪽에 있는 선도산(仙桃山)에서 남쪽으로 뻗은 구릉의 말단부에 위치해 있다.', 'King Muyeol''s tomb in Gyeongju is the tomb of King Muyeol (reign 654-661, Kim Chun-chu), the 29th king of Silla. It is located at the end of a hill extending south from Seondo Mountain (仙桃山) in the northwest of Gyeongju.'),
    (73, 'story', '김춘추는 신라 중대(中代)의 첫 진골(眞骨) 출신 왕으로 당과 연합하여 백제를 병합하고 통일 대업의 기반을 닦았으나 통일을 완수하지 못하고 세상을 떠났다.
능은 밑둘레 114m, 높이 8.7m로 비교적 큰 편이며 능 아래쪽은 자연석을 쌓고 드문드문 큰 돌로 받쳤으나 지금은 흙 속에 묻혀 있다.
동쪽에 비석을 세웠던 돌거북 받침돌과 머릿돌이 남아있는데, 무열왕의 둘째 아들인 김인문(金仁問)이 쓴 ''태종무열대왕지비(太宗武烈大王之碑)''라는 글씨가 돋을새김 되어 있어 이곳이 무열왕의 능임을 알 수 있다.', 'Kim Chunchu was the first Jingol-born king of the Middle Dynasty of Silla. He united with Tang and annexed Baekje and laid the foundation for the great cause of unification, but he passed away without completing unification.
The tomb is relatively large, with a base circumference of 114m and a height of 8.7m. The lower part of the tomb was made of natural stones and supported with sparsely large stones, but is currently buried in the dirt.
The stone turtle pedestal and headstone that erected the monument remain on the east side, and the words ''Monument to King Taejong Muyeol'' written by King Muyeol''s second son, Kim In-moon, are embossed, indicating that this is King Muyeol''s tomb.'),
    (73, 'tip', '경주 무열왕릉·태종무열왕릉비에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At the Gyeongju King Muyeol Tomb and King Taejong Muyeol''s Tomb Monument, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (73, 'did_you_know', '경주 무열왕릉은 신라 제29대 태종(太宗) 무열왕(재위 654∼661, 김춘추)의 능이에요.', 'King Muyeol''s tomb in Gyeongju is the tomb of King Muyeol (reign 654-661, Kim Chun-chu), the 29th king of Silla.'),
    (74, 'summary', '역사 속 유물인 신라시대 황룡사 구층탑 양식의 중도탑을 현대 과학기술과 건축공법으로 재해석하여 지은 이색 건축물이다.', 'It is a unique building built by reinterpreting the nine-story pagoda of Hwangnyongsa Temple from the Silla Dynasty, a historical relic, using modern science and technology and construction methods.'),
    (74, 'intro', '역사 속 유물인 신라시대 황룡사 구층탑 양식의 중도탑을 현대 과학기술과 건축공법으로 재해석하여 지은 이색 건축물이다. 보문 단지의 새로운 랜드마크로 꼽힐 만큼 주목받고 있는 이 건물은 현재 개인과 기업 등을 대상으로 다양한 명상과 수행 프로그램을 운영하는 연수원으로 사용되고 있다.', 'It is a unique building built by reinterpreting the nine-story pagoda of Hwangnyongsa Temple from the Silla Dynasty, a historical relic, using modern science and technology and construction methods. This building, which is attracting enough attention to be considered a new landmark in the Bomun complex, is currently being used as a training center that operates various meditation and meditation programs for individuals and companies.'),
    (74, 'story', '때문에 사전 예약자에 한해 시설 이용이 가능한데 1시간 내외의 가벼운 생활명상을 체험하는 일일투어를 비롯해 1박 2일과 2박 3일 코스도 운영된다.
물론 내외부 일부 공간은 일반인들도 방문 가능하다.
숙소는 탑 내부에 자리한 온돌 타입과 중도타워를 바라볼 수 있는 다양한 타입의 연수동으로 나뉜다.', 'Therefore, only those who make advance reservations can use the facility. In addition to a daily tour where you can experience light meditation for about an hour, 2 days and 1 night and 3 days and 2 nights courses are also available.
Of course, some of the interior and exterior spaces can also be visited by the general public.
Accommodations are divided into an ondol type located inside the tower and various types of Yeonsu-dong overlooking the Jungdo Tower.'),
    (74, 'tip', '황룡원은 현장 방문만으로 참여하기 어려울 수 있어요. 원하는 프로그램과 해설 시간을 먼저 확인하고 사전 예약을 마친 뒤 방문해 보세요.', 'It may be difficult to participate in Hwangnyongwon just by visiting the site. Please check the desired program and commentary time first and make a reservation in advance before visiting.'),
    (74, 'did_you_know', '특히 경주 세계 문화엑스포 공원 내 장미공원에서 바라본 황룡원 전경이 무척 아름답다고 해요.', 'In particular, the view of Hwangnyongwon from the Rose Park in Gyeongju World Culture Expo Park is said to be very beautiful.'),
    (75, 'summary', '국가지질공원으로 지정된 양남 주상절리군을 한눈에 조망할 수 있는 전망대로 지난 2017년 10월 지어졌다.', 'It was built in October 2017 as an observatory that provides a panoramic view of the Yangnam columnar joints, which were designated as a national geopark.'),
    (75, 'intro', '국가지질공원으로 지정된 양남 주상절리군을 한눈에 조망할 수 있는 전망대로 지난 2017년 10월 지어졌다. 양남 주상절리는 양남면 읍천리의 해안을 따라 발달한 주상절리군이다.', 'It was built in October 2017 as an observatory that provides a panoramic view of the Yangnam columnar joints, which were designated as a national geopark. Yangnam Columnar Joints are a group of columnar joints developed along the coast of Eupcheon-ri, Yangnam-myeon.'),
    (75, 'story', '위로 솟은 주상절리뿐만 아니라 부채꼴 주상절리, 기울어진 주상절리, 누워있는 주상절리 등 다양한 형태의 주상절리를 관찰할 수 있다.
그중에서도 압권은 펴진 부채 모양과 같이 둥글게 펼쳐진 부채꼴 주상절리이다.
세계적으로도 유례를 찾기 어려운 아주 희귀한 형태로, 지난 2012년 9월 천연기념물로 지정되었다.', 'In addition to the columnar joints that rise upward, various types of columnar joints can be observed, including fan-shaped columnar joints, inclined columnar joints, and lying columnar joints.
Among them, the highlight is the fan-shaped columnar joints that are spread out in a circle like the shape of an unfolded fan.
It is a very rare form that is difficult to find anywhere in the world, and was designated as a natural monument in September 2012.'),
    (75, 'tip', '경주 양남 주상절리 전망대에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Yangnam Columnar Joint Observatory in Gyeongju, the perceived environment changes greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (75, 'did_you_know', '국가지질공원으로 지정된 양남 주상절리군을 한눈에 조망할 수 있는 전망대로 지난 2017년 10월 지어졌다고 해요.', 'It is said to have been built in October 2017 as an observatory that offers a panoramic view of the Yangnam columnar joints, which have been designated as a national geopark.'),
    (76, 'summary', '감은사는 동해안에 있는 통일신라시대의 사찰로 신라 문무왕이 삼국을 통일한 후 부처의 힘을 빌어 왜구의 침입을 막고자 세운 절이다.', 'Gameunsa Temple is a temple from the Unified Silla period on the east coast. It was built by King Munmu of Silla to prevent the invasion of Japanese pirates with the help of Buddha after unifying the three kingdoms.'),
    (76, 'intro', '감은사는 동해안에 있는 통일신라시대의 사찰로 신라 문무왕이 삼국을 통일한 후 부처의 힘을 빌어 왜구의 침입을 막고자 세운 절이다. 지어지기 전 문무왕이 죽자, 그 뜻을 이어받아 아들 신문왕이 682년 완성했다.', 'Gameunsa Temple is a temple from the Unified Silla period on the east coast. It was built by King Munmu of Silla to prevent the invasion of Japanese pirates with the help of Buddha after unifying the three kingdoms. When King Munmu died before it was built, his son King Sinmun took over his wishes and completed it in 682.'),
    (76, 'story', '문무왕은 죽기 전 내가 죽으면 바다의 용이 되어 나라를 지키고자 하니 화장하여 동해에 장사를 지낼 것을 유언했다.
문무왕을 장사한 곳이 대왕암이며, 신문왕이 이곳 사찰을 완성하고 부왕의 은혜에 감사한다는 의미로 이름을 감은사라 지었다고 한다.
지금은 3층 석탑 2기와 금당 및 강당 등 건물터만 남아있으며, 황룡사, 사천왕사와 함께 나라를 보호하는 호국사찰로 언제 절이 무너졌는지는 밝혀지지 않고 있다.', 'Before his death, King Munmu left a will saying that when I die, I will become a sea dragon and protect my country, so I will be cremated and buried in the East Sea.
The place where King Munmu was buried is Daewangam, and it is said that King Sinmun completed the temple here and named it Gameunsa Temple to express gratitude for his father''s favor.
Now, only the ruins of two three-story stone pagodas, a golden hall, and an auditorium remain. It is a patriotic temple that protects the country along with Hwangnyongsa Temple and Sacheonwangsa Temple, and it is not clear when the temple collapsed.'),
    (76, 'tip', '경주 감은사지을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gameunsa Temple Site in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (76, 'did_you_know', '지어지기 전 문무왕이 죽자, 그 뜻을 이어받아 아들 신문왕이 682년 완성했다고 해요.', 'It is said that when King Munmu died before it was built, his son King Sinmun took over his wishes and completed it in 682.'),
    (77, 'summary', '작가 최영욱의 작업은 언제나 하나의 근원적 질문에서 출발한다.', 'Artist Youngwook Choi''s work always starts from one fundamental question.'),
    (77, 'intro', '작가 최영욱의 작업은 언제나 하나의 근원적 질문에서 출발한다. “삶은 어떤 흔적을 남기며, 그 흔적은 어디로 흘러가는가.” 그는 이 질문을 ‘카르마(Karma)’라는 이름으로 20여 년 넘게 탐구해 왔다.', 'Artist Youngwook Choi''s work always starts from one fundamental question. “What traces does life leave behind, and where do those traces go?” He has been exploring this question for over 20 years under the name ‘Karma.’'),
    (77, 'story', '카르마는 단순한 시리즈의 제목이 아니라 그의 회화적 세계를 움직이는 중심 개념이며, 존재를 바라보는 태도이자 세계와 관계 맺는 방식을 규정하는 구조이다.
작가에게 달항아리의 선은 실제 균열의 재현이 아니라 자신의 이야기를 담아내는 드로잉이며, 선들이 만나고 헤어지고 다시 이어지는 모습 속에서 그는 인생의 순환을 읽어냈다.
그 과정에서 ‘카르마’라는 제목을 얻었고, 이는 특정한 종교적 해석에서 머무르기 보다는 열심히 살아낸 삶이 결국 긍정으로 되돌아온다는 믿음을 담은 이름이다.', 'Karma is not simply the title of a series, but the central concept that drives his pictorial world, an attitude toward existence, and a structure that defines the way to relate to the world.
For the artist, the lines of the moon jar are not a reproduction of an actual crack, but a drawing that tells his story, and he reads the cycle of life in the way the lines meet, break up, and connect again.
In the process, the title ‘Karma’ was obtained, which is a name that embodies the belief that a life lived hard will ultimately come back positive rather than staying within a specific religious interpretation.'),
    (77, 'tip', '쉼표：비우고, 머무르고, 채우는을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Comma: Empty, Stay, Fill, check out the latest operating information and travel directions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (77, 'did_you_know', '“삶은 어떤 흔적을 남기며, 그 흔적은 어디로 흘러가는가.” 그는 이 질문을 ‘카르마(Karma)’라는 이름으로 20여 년 넘게 탐구해 왔다고 해요.', '“What traces does life leave behind, and where do those traces go?” He says he has been exploring this question for over 20 years under the name ‘Karma.’'),
    (78, 'summary', '설악산국립공원, 한려해상국립공원처럼 산이나 바다', 'Mountains or seas like Seoraksan National Park and Hallyeohaesang National Park'),
    (78, 'intro', '경주국립공원은 설악산국립공원, 한려해상국립공원처럼 산이나 바다 등 자연경관이 아닌 세계적으로도 놀라운 문화유산으로 이루어진 국립공원이다.', 'Gyeongju National Park is a national park comprised of world-class cultural heritage, rather than natural scenery such as mountains or the sea, like Seoraksan National Park and Hallyeohaesang National Park.'),
    (78, 'story', '신라 천 년의 찬란한 문화를 꽃피운 경주는 우리 조상이 남긴 찬란한 민족문화의 발자취와 삼국통일의 웅장한 기상이 서려 있고 가는 곳마다
명승고적과 전설, 고유민속 등의 수많은 문화유산을 보존하고 있는 한국 관광의 대표적인 곳이다.
훌륭한 사적과 문화적, 역사적 유물이 놀라울 만큼 한 고장에 집중적으로 보존돼 있고 국보급 또는 세계적으로 가치 있는 고고품이 쏟아져 나왔으며, 또 찬란했던 불교문화와 그 예술을 확인할 수 있는 경주는 한마디로 도시 전체가 벽 없는 박물관이다.', 'Gyeongju, where the brilliant culture of Silla bloomed for a thousand years, is filled with traces of the brilliant national culture left behind by our ancestors and the magnificent spirit of the unification of the three kingdoms, and everywhere you go.
It is a representative place for Korean tourism that preserves numerous cultural heritages such as scenic sites, legends, and indigenous folklore.
In Gyeongju, where great historical sites, cultural and historical relics are surprisingly concentrated in one place, and antiques of national or world value are poured out, and where you can see the brilliant Buddhist culture and its art, the entire city is, in a word, a museum without walls.'),
    (78, 'tip', '경주국립공원에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'In Gyeongju National Park, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (78, 'did_you_know', '특히, 경주시가 관광특구로 지정된 후 민관이 함께 관광기반시설과 환경개선에 힘을 기울이고 있어 과거 어느 때보다도 훌륭한 관광 지역으로 변모하고 있으며, 해마다', 'In particular, after Gyeongju City was designated as a special tourist zone, the public and private sectors are working together to improve tourism infrastructure and the environment, transforming it into a better tourist area than ever before, year after year.'),
    (79, 'summary', '란 추령터널과 기림사를 잇는 함월산 아랫자락 편도 3.9㎞의 걷기 좋은 숲길이다.', 'It is a 3.9km one-way forest path at the foot of Hamwolsan Mountain that connects Churyeong Tunnel and Girimsa Temple.'),
    (79, 'intro', '경주 왕의 길이란 추령터널과 기림사를 잇는 함월산 아랫자락 편도 3.9㎞의 걷기 좋은 숲길이다. 추령터널 옆 진입로를 따라 2.5㎞의 시골길을 40~50분 정도 걸으면 왕의 길 초입인 모차골 입구에 닿는다.', 'Gyeongju King''s Road is a 3.9km one-way forest path at the foot of Hamwolsan Mountain that connects Churyeong Tunnel and Girimsa Temple. If you walk along the 2.5km country road for about 40 to 50 minutes along the access road next to the Chunyeong Tunnel, you will reach the entrance to Mochagol, the beginning of King''s Road.'),
    (79, 'story', '모차골은 마차가 다니던 곳이라 하여 ‘마차골’로 불리다가 모차골이 되었다.
여기서부터가 본격적인 ''왕의 길''이다.
신문왕이 마차를 타고 아버지 문무왕의 묘를 찾아가는 길이자 나라를 구원할 힘을 얻은 길이고 또 이보다', 'Mochagol was called ‘Machagol’ because it was a place where horse-drawn carriages used to travel, and then it became Mochagol.
From here, the ‘King’s Road’ begins in earnest.
This is the road where King Sinmun rode a carriage to the grave of his father, King Munmu, and the road where he gained the power to save the country.'),
    (79, 'tip', '경주 왕의 길에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'On Gyeongju King''s Road, rather than just quickly looking at the buildings, take a look at the arrangement of the towers and temples, as well as the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (79, 'did_you_know', '추령터널 옆 진입로를 따라 2.5㎞의 시골길을 40~50분 정도 걸으면 왕의 길 초입인 모차골 입구에 닿는다고 해요.', 'It is said that if you walk along the 2.5km country road for about 40 to 50 minutes along the access road next to the Churyeong Tunnel, you will reach the entrance to Mochagol, the beginning of King''s Road.'),
    (80, 'summary', '경주시에 위치한 플래시백 계림은 신라의 건국부터 통일 신라까지 아우르는 지역의 고유한 서사를 기술·공간·빛으로 재구성한 몰입형 미디어 아트 전시관이다.', 'Flashback Gyerim, located in Gyeongju-si, is an immersive media art exhibition hall that reconstructs the region''s unique narrative from the founding of Silla to the unification of Silla through technology, space, and light.'),
    (80, 'intro', '경주시에 위치한 플래시백 계림은 신라의 건국부터 통일 신라까지 아우르는 지역의 고유한 서사를 기술·공간·빛으로 재구성한 몰입형 미디어 아트 전시관이다. 경주 보문관광단지에 내에 자리잡고 있으며 국내 최대 규모인 1,700평, 최고 층고 11미터의 공간을 바탕으로 관람객이 신라의 신화·설화 속 세계를 직접 걸으며 공감각적 체험을 할 수 있도록 구성했다.', 'Flashback Gyerim, located in Gyeongju-si, is an immersive media art exhibition hall that reconstructs the region''s unique narrative from the founding of Silla to the unification of Silla through technology, space, and light. Located within the Bomun Tourist Complex in Gyeongju, it is the largest space in Korea with an area of ​​1,700 pyeong and a maximum floor height of 11 meters, and is designed to allow visitors to have a synesthetic experience while walking through the world of Silla myths and tales.'),
    (80, 'story', '초대형 프로젝션과 고해상도 미디어, 몰입형 사운드가 어우러진 전시는 13개 공간이 하나의 대서사로 연결되어 전통과 현대 기술이 어우러진 연출로 시간과 기억의 경계를 넘나드는 경험을 선사한다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 플래시백 계림은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The exhibition, which combines ultra-large projection, high-resolution media, and immersive sound, connects 13 spaces into one grand narrative, providing an experience that crosses the boundaries of time and memory through a combination of tradition and modern technology.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Flashback Gyerim leaves a different memory for each person who visits Gyeongju.'),
    (80, 'tip', '플래시백 계림에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At Flashback Gyerim, decide on the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (80, 'did_you_know', '경주 보문관광단지에 내에 자리잡고 있으며 국내 최대 규모인 1,700평, 최고 층고 11미터의 공간을 바탕으로 관람객이 신라의 신화·설화 속 세계를 직접 걸으며 공감각적 체험을 할 수 있도록 구성했다고 해요.', 'Located within the Bomun Tourist Complex in Gyeongju, it is said to be designed to allow visitors to have a synesthetic experience while walking through the world of Silla myths and tales, based on a space of 1,700 pyeong (1,700 pyeong) and a maximum floor height of 11 meters, which is the largest space in Korea.'),
    (81, 'summary', '전통 항아리를 활용해 막걸리를 빚는 양조장으로, 체리, 찰보리, 신라봉 등 지역 특산물을 활용한 다양한 막걸리를 선보이는 곳이다.', 'This is a brewery that makes makgeolli using traditional jars, and offers a variety of makgeolli using local specialties such as cherries, glutinous barley, and shillabong.'),
    (81, 'intro', '경주 깁 모어 막걸리는 전통 항아리를 활용해 막걸리를 빚는 양조장으로, 체리, 찰보리, 신라봉 등 지역 특산물을 활용한 다양한 막걸리를 선보이는 곳이다. ‘희로애락(喜怒哀樂)’의 감정을 담아 술을 빚는 것을 특징으로 하며, 전통주를 통해 지역의 이야기와 감성을 전한다.', 'Gyeongju Gibb More Makgeolli is a brewery that makes makgeolli using traditional jars, and offers a variety of makgeolli using local specialties such as cherries, glutinous barley, and shillabong. It is characterized by brewing alcohol with the emotions of ‘joy, sorrow and joy’, and conveys local stories and emotions through traditional liquor.'),
    (81, 'story', '이곳에서는 술 빚기 클래스와 함께 술지게미를 활용한 천연 비누 만들기 체험을 운영하고 있어 전통 발효 문화를 직접 경험할 수 있다.
또한 체험과 함께 막걸리와 천연 비누도 구매할 수 있다.
오늘의 경주 깁 모어 막걸리은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Here, along with a sake brewing class, a natural soap making experience using sake lees is offered, allowing visitors to experience traditional fermentation culture firsthand.
You can also purchase makgeolli and natural soap along with the experience.
Today''s Gyeongju Gibb More Makgeolli leaves a different memory for each person who visits Gyeongju.'),
    (81, 'tip', '경주 깁 모어 막걸리을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Gibb More Makgeolli, check the latest operating information and transportation directions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (81, 'did_you_know', '또한 체험과 함께 막걸리와 천연 비누도 구매할 수 있어요.', 'You can also purchase makgeolli and natural soap along with the experience.'),
    (82, 'summary', '경주시 양남면에 자리한 읍천항은 바다와 맞닿아 있는 작고 아담한 항구이다.', 'Eupcheon Port, located in Yangnam-myeon, Gyeongju-si, is a small and compact port facing the sea.'),
    (82, 'intro', '경주시 양남면에 자리한 읍천항은 바다와 맞닿아 있는 작고 아담한 항구이다. 방파제가 바다를 감싸 안은 듯한 모양을 하고 있으며, 규모는 크지 않지만 곳곳에 볼거리와 즐길 거리가 많다.', 'Eupcheon Port, located in Yangnam-myeon, Gyeongju-si, is a small and compact port facing the sea. The breakwater looks like it embraces the sea, and although it is not large in size, there are many things to see and enjoy here and there.'),
    (82, 'story', '주변에는 시원한 바닷바람을 만끽할 수 있는 출렁다리가 설치되어 있어 산책을 즐기기 좋고, 하트 모양으로 오목하게 들어간 해변과 읍천항의 등대를 배경으로 하여 사진을 찍기에도 좋다.
읍천항은 특히 주상절리 파도소리길을 걷기 위해 방문하는 경우가 많은데 화산 활동으로 형성된 주상절리 절벽을 마주하며 걸을 수 있는 이색 트레킹 코스이다.
가족 단위 여행객은 물론 친구, 연인과 함께 방문해 특별한 추억을 남기기 좋은 항구이다.', 'There is a suspension bridge nearby where you can enjoy the cool sea breeze, making it great for a walk. It is also great for taking pictures with the heart-shaped concave beach and the lighthouse of Eupcheon Port in the background.
Eupcheon Port is especially visited to walk along the columnar jointed waves sound path, which is a unique trekking course where you can walk while facing the columnar jointed cliffs formed by volcanic activity.
It is a great port to visit with families, friends, and lovers to make special memories.'),
    (82, 'tip', '읍천항에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Eupcheon Port, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (82, 'did_you_know', '가족 단위 여행객은 물론 친구, 연인과 함께 방문해 특별한 추억을 남기기 좋은 항구이에요.', 'It is a great port to visit with families, friends, and lovers to make special memories.'),
    (83, 'summary', '벚꽃 개화 시기에 맞춰 진행되는 축제로, 경주의 대표적인 봄 축제이다.', 'This festival is held to coincide with the blooming period of cherry blossoms and is a representative spring festival in Gyeongju.'),
    (83, 'intro', '벚꽃 개화 시기에 맞춰 진행되는 축제로, 경주의 대표적인 봄 축제이다. 벚꽃의 절경을 감상할 수 있을 뿐만 아니라 다양한 공연, 체험, 먹거리 등이 가득하다.', 'This festival is held to coincide with the blooming period of cherry blossoms and is a representative spring festival in Gyeongju. Not only can you enjoy the spectacular view of the cherry blossoms, but it is also full of various performances, experiences, and food.'),
    (83, 'story', '대릉원 돌담길 구간이 축제 기간 전면 교통통제되어 보다
안전한 보행 환경에서 축제를 즐길 수 있다.
경주 대릉원돌담길 축제만의 특별한 콘텐츠를 소개하자면, 마임, 댄스, 서커스 등 다양한 거리예술로 눈이 행복한 "벚꽃거리예술로", 매일 밤 벚꽃 터널을 화려하게 수놓는 "벚꽃라이트", QR 코드로 간편하게 주문하고 다회용기를 사용하는 "돌담길 레스토랑", 아이와 함께 동심의 세계로 떠나 함께 놀이를 즐겨볼 수 있는 "도로 위 놀이터" 등이 있다.', 'The Daereungwon Stonewall Road section is completely closed to traffic during the festival period.
You can enjoy the festival in a safe pedestrian environment.
To introduce special contents unique to the Gyeongju Daereungwon Doldamgil Festival, there are “Cherry Blossom Street Art Road” where you can enjoy a variety of street arts such as mime, dance, and circus, “Cherry Blossom Light” which colorfully decorates the cherry blossom tunnel every night, “Doldamgil Restaurant” where you can easily order with QR code and use reusable containers, and “Playground on the Road” where you can go to the world of innocence with your children and enjoy playing together.'),
    (83, 'tip', '경주 대릉원돌담길 축제을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Daereungwon Stone Wall Festival, check the latest operating information and travel directions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (83, 'did_you_know', '경주 대릉원돌담길 축제만의 특별한 콘텐츠를 소개하자면, 마임, 댄스, 서커스 등 다양한 거리예술로 눈이 행복한 "벚꽃거리예술로", 매일 밤 벚꽃 터널을 화려하게 수놓는 "벚꽃라이트", QR 코드로 간편하게 주문하고 다회용기를 사용하는 "돌담길 레스토랑", 아이와 함께 동심의 세계로 떠나 함께 놀이를 즐겨볼 수 있는 "도로 위 놀이터" 등이 있어요.', 'To introduce the special content unique to the Gyeongju Daereungwon Stone Wall Festival, there are the “Cherry Blossom Street Art Road” where you can enjoy a variety of street arts such as mime, dance, and circus, the “Cherry Blossom Light” which colorfully decorates the cherry blossom tunnel every night, the “Doldam Road Restaurant” where you can easily order with a QR code and use reusable containers, and the “Playground on the Road” where you can travel to the world of innocence with your children and enjoy playing together.'),
    (84, 'summary', '보문 단지 내 위치한 경주레저는 카트, 서바이벌, 사륜구동차를 한곳에서 즐길 수 있는 곳으로 24개월 이상부터 성인까지 누구나 액티비티 활동을 할 수 있는 장소이다.', 'Gyeongju Leisure, located in the Bomun Complex, is a place where you can enjoy karts, survival, and four-wheel drive vehicles in one place, and is a place where anyone from 24 months of age to adults can participate in activities.'),
    (84, 'intro', '보문 단지 내 위치한 경주레저는 카트, 서바이벌, 사륜구동차를 한곳에서 즐길 수 있는 곳으로 24개월 이상부터 성인까지 누구나 액티비티 활동을 할 수 있는 장소이다. 핸들 조작을 하고 싶어 하는 어린 자녀와 부모가 함께 탈 수 있는 2인승 카트와 스피드를 낼 수 있는 긴 카레이싱 코스가 있다.', 'Gyeongju Leisure, located in the Bomun Complex, is a place where you can enjoy karts, survival, and four-wheel drive vehicles in one place, and is a place where anyone from 24 months of age to adults can participate in activities. There is a two-seater kart that parents and young children who want to operate the steering wheel can ride together, and a long car racing course where they can show off their speed.'),
    (84, 'story', '시원한 자연을 배경으로 비포장도로를 달리는 스릴감 넘치는 산악바이크.
페이트탄을 이용한 사격, 6인 이상 참여 가능한 서바이벌 게임 등이 준비되어 가족단위는 물론 연인, 친구, 단체 등으로 경주에서의 액티비티를 원한다면 방문하기를 권한다.
모든 코스를 진행하기 전 안전 수칙과 교육, 안전모 착용은 필수이다.', 'A thrilling mountain bike ride on a dirt road with cool nature in the background.
There are activities such as shooting using fate bullets and survival games for 6 or more people, so it is recommended to visit if you want to enjoy activities in Gyeongju not only with your family, but also with couples, friends, and groups.
Before proceeding with any course, it is mandatory to follow safety rules, receive training, and wear a safety helmet.'),
    (84, 'tip', '경주레져에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'Please first check the age, clothing, and equipment requirements for the activity you want to experience at Gyeongju Leisure. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (84, 'did_you_know', '보문 단지 내 위치한 경주레저는 카트, 서바이벌, 사륜구동차를 한곳에서 즐길 수 있는 곳으로 24개월 이상부터 성인까지 누구나 액티비티 활동을 할 수 있는 장소이에요.', 'Gyeongju Leisure, located in the Bomun Complex, is a place where you can enjoy karts, survival, and four-wheel drive vehicles in one place, and is a place where anyone from 24 months of age to adults can participate in activities.'),
    (85, 'summary', '오아르(OAR)미술관은 ‘오늘 만나는 아름다움’이라는 뜻으로 경주 출신의 개인 컬렉터 김문호 관장이 2005년도부터 수집한 개인 소장품 약 600점을 가지고 설립한 사립 미술관이다.', 'OAR Art Museum, which means ‘beauty encountered today,’ is a private art museum established by director Moon-ho Kim, a private collector from Gyeongju, with about 600 pieces of personal collection collected since 2005.'),
    (85, 'intro', '오아르(OAR)미술관은 ‘오늘 만나는 아름다움’이라는 뜻으로 경주 출신의 개인 컬렉터 김문호 관장이 2005년도부터 수집한 개인 소장품 약 600점을 가지고 설립한 사립 미술관이다. 경주시 노서동 고분군 공원 부지에 자리한 오아르미술관은 지상 2층, 지하 1층, 연면적 1,594.06㎡ 규모의 신규 건축물로,신라 시대 왕과 왕비의 고분이 함께 있는 경주 대릉원 옆에 위치하고 있다.', 'OAR Art Museum, which means ‘beauty encountered today,’ is a private art museum established by director Moon-ho Kim, a private collector from Gyeongju, with about 600 pieces of personal collection collected since 2005. Oar Art Museum, located on the site of the ancient tomb park in Noseo-dong, Gyeongju, is a new building with two floors above ground and one floor underground and a total floor area of ​​1,594.06㎡. It is located next to Daereungwon, Gyeongju, where the tombs of the king and queen of the Silla Dynasty are located.'),
    (85, 'story', '한국의 전통 예술과 세계적인 현대 미술이 조화롭게 공존하는 예술적 아지트를 지향하고 있으며, 천년 고도 경주의 전통과 현대의 예술이 만나 아름다운 조화를 이루고 있다.
또한 다채로운 전시, 교육, 행사, 아카이브를 통해 누구나 쉽게 현대미술을 접하고 향유할 수 있는 경주의 새로운 예술적 랜드마크이다.
오늘의 오아르미술관은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'It aims to be an artistic hideout where Korean traditional art and world-class modern art coexist harmoniously, and the thousand-year-old tradition of Gyeongju, an ancient capital of Gyeongju, meets modern art to create a beautiful harmony.
It is also a new artistic landmark in Gyeongju where anyone can easily access and enjoy contemporary art through a variety of exhibitions, education, events, and archives.
Today''s Oar Art Museum leaves a different memory for each person who visits Gyeongju.'),
    (85, 'tip', '오아르미술관을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Oar Art Museum, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (85, 'did_you_know', '오아르(OAR)미술관은 ‘오늘 만나는 아름다움’이라는 뜻으로 경주 출신의 개인 컬렉터 김문호 관장이 2005년도부터 수집한 개인 소장품 약 600점을 가지고 설립한 사립 미술관이에요.', 'OAR Art Museum, which means ‘beauty encountered today,’ is a private art museum established by director Moon-ho Kim, a private collector from Gyeongju, with about 600 pieces of personal collection collected since 2005.'),
    (86, 'summary', '경주 오릉 근처에 있는 복합문화공간 플레이스 씨(Place C)는 많은 사람이 모여 예술을 즐기고 맛있는 음식을 먹으며 좋은 시간을 보낼 수 있도록 마련된 공간이다.', 'Place C, a complex cultural space near Oreung in Gyeongju, is a space where many people can gather to enjoy art, eat delicious food, and have a good time.'),
    (86, 'intro', '경주 오릉 근처에 있는 복합문화공간 플레이스 씨(Place C)는 많은 사람이 모여 예술을 즐기고 맛있는 음식을 먹으며 좋은 시간을 보낼 수 있도록 마련된 공간이다. 세계적인 작가들의 전시 등이 펼쳐지며, 야외 정원도 조성되어 있어 문화 활동과 치유의 시간을 가질 수 있는 곳이다.', 'Place C, a complex cultural space near Oreung in Gyeongju, is a space where many people can gather to enjoy art, eat delicious food, and have a good time. Exhibitions by world-class artists are held, and an outdoor garden has been created, making it a place where you can enjoy cultural activities and healing time.'),
    (86, 'story', '한옥에 현대적인 요소를 곁들인 건축물은 소박하면서도 고급스러운, 편안하면서도 지적인 감각을 제공한다.
카페에서는 높은 퀄리티를 자랑하는 하동의 프리미엄 차 라인과 플레이스 씨에서 자체적으로 개발한 다양한 티 베리에이션을 판매 중이다.
또한, 음식점에서는 지역 농가로부터 신선한 식재료를 당일 수급하여 음식 조리 및 먹거리를 제공하고 있다.', 'The Hanok-style architecture with modern elements provides a simple yet luxurious, comfortable yet intelligent feel.
The cafe sells Hadong''s premium tea line, which boasts high quality, as well as various tea variations developed in-house by Place C.
Additionally, the restaurant supplies fresh ingredients from local farms on the same day, prepares the food, and provides food.'),
    (86, 'tip', '플레이스 씨은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Place Sea in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (86, 'did_you_know', '세계적인 작가들의 전시 등이 펼쳐지며, 야외 정원도 조성되어 있어 문화 활동과 치유의 시간을 가질 수 있는 곳이에요.', 'There are exhibitions by world-class artists, and an outdoor garden has been created, making it a place where you can enjoy cultural activities and healing time.'),
    (87, 'summary', '생활 속의 안전사고에 대한 위험성을 학생 스스로 인지하여 예방하고 각 재난 상황에 맞는 대응 능력을 기르기 위해 건립된 체험교육 중심의 종합 안전체험관으로 학생의 발달단계에 맞는 체계적인 안전체험 교육 프로그램을 운영하고 있다.', 'It is a comprehensive safety experience center centered on experiential education that was built to help students recognize and prevent the risks of safety accidents in their daily lives and develop response skills appropriate for each disaster situation. It operates a systematic safety experience education program tailored to the student''s development stage.'),
    (87, 'intro', '경상북도교육청 경주안전체험관은 생활 속의 안전사고에 대한 위험성을 학생 스스로 인지하여 예방하고 각 재난 상황에 맞는 대응 능력을 기르기 위해 건립된 체험교육 중심의 종합 안전체험관으로 학생의 발달단계에 맞는 체계적인 안전체험 교육 프로그램을 운영하고 있다. 유치원생, 초·중·고등학생을 대상으로 안전 교육 7대 표준안을 바탕으로 한 생활안전체험, 재난안전체험, 교통안전체험, 응급처치 체험, 생명존중 체험 등 총 7개 체험관, 25개 체험실과 4D영상실로 구성되어 있다.', 'The Gyeongju Safety Experience Center, Gyeongsangbuk-do Office of Education, is a comprehensive safety experience center centered on experiential education built to help students recognize and prevent the risks of safety accidents in their daily lives and develop response skills appropriate for each disaster situation. It operates a systematic safety experience education program tailored to the student''s development stage. It consists of a total of 7 experience centers, 25 experience rooms, and a 4D video room, including life safety experience, disaster safety experience, traffic safety experience, first aid experience, and respect for life experience based on the 7 safety education standards for kindergarten students, elementary, middle, and high school students.'),
    (87, 'story', '체험은 홈페이지를 통해 사전 예약해야 하며 단체로 진행된다.
각 교육기관 주체 또는 개인일 경우에는 최소 10명 이상 체험 시 신청 가능하다.
오늘의 경상북도교육청 경주안전체험관은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The experience must be reserved in advance through the website and is conducted in groups.
Each educational institution or individual can apply for the experience with at least 10 people.
Today''s Gyeongju Safety Experience Center of the Gyeongsangbuk-do Office of Education leaves a different memory for each person who visits Gyeongju.'),
    (87, 'tip', '경상북도교육청 경주안전체험관은 현장 방문만으로 참여하기 어려울 수 있어요. 원하는 프로그램과 해설 시간을 먼저 확인하고 사전 예약을 마친 뒤 방문해 보세요.', 'It may be difficult to participate in the Gyeongju Safety Experience Center of the Gyeongsangbuk-do Office of Education just by visiting the site. Please check the desired program and commentary time first and make a reservation in advance before visiting.'),
    (87, 'did_you_know', '경상북도교육청 경주안전체험관은 생활 속의 안전사고에 대한 위험성을 학생 스스로 인지하여 예방하고 각 재난 상황에 맞는 대응 능력을 기르기 위해 건립된 체험교육 중심의 종합 안전체험관으로 학생의 발달단계에 맞는 체계적인 안전체험 교육 프로그램을 운영하고 있어요.', 'Gyeongju Safety Experience Center, Gyeongsangbuk-do Office of Education, is a comprehensive safety experience center centered on experiential education that was built to help students recognize and prevent the risks of safety accidents in their daily lives and develop response skills appropriate for each disaster situation. It operates a systematic safety experience education program tailored to the students'' development stage.'),
    (88, 'summary', '경주 형산강을 끼고 우뚝 솟은 암벽 금장대는 예부터 기러기도 쉬어가는 곳이라 하여 금장낙안(金藏落雁)으로 불렸다.', 'Geumjangdae, a towering rock wall along the Hyeongsan River in Gyeongju, has long been called Geumjangnagan (金藏落雁) because it is a resting place for wild geese.'),
    (88, 'intro', '경주 형산강을 끼고 우뚝 솟은 암벽 금장대는 예부터 기러기도 쉬어가는 곳이라 하여 금장낙안(金藏落雁)으로 불렸다. 김동리의 단편소설 『무녀도』의 배경이 되기도 했던 이곳엔 팔작지붕을 얹은 누각이 자리해 예스러운 정취를 즐기기 좋다.', 'Geumjangdae, a towering rock wall along the Hyeongsan River in Gyeongju, has long been called Geumjangnagan (金藏落雁) because it is a resting place for wild geese. This place, which served as the background for Kim Dong-ri''s short story “Munyeodo,” has a pavilion with a gable roof, making it a great place to enjoy an old-fashioned atmosphere.'),
    (88, 'story', '금장대 입구에 자리한 금장대 습지공원은 하천 내 자연적으로 형성된 습지에 교육 및 체험의 기능을 부여하여 이용객들에게 형산강의 동식물 및 생태를 관찰하고 탐구할 수 있는 공간을 제공하기 위해 조성되었다.
공원은 소셜 미디어를 통해 주목받기 시작했다.
초록빛 공원 풍경과 버려진 폐목선 한 척이 수채화처럼 어우러져 사진촬영 명소로 입소문이 났기 때문이다.', 'Geumjangdae Wetland Park, located at the entrance to Geumjangdae, was created to provide users with a space to observe and explore the flora, fauna and ecology of the Hyeongsan River by giving educational and experiential functions to the naturally formed wetlands within the river.
The park began to attract attention through social media.
This is because the green park scenery and an abandoned wooden boat blend together like a watercolor painting, making it a popular photo spot.'),
    (88, 'tip', '금장대 수변공원은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Geumjangdae Waterside Park in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (88, 'did_you_know', '금장대 입구에 자리한 금장대 습지공원은 하천 내 자연적으로 형성된 습지에 교육 및 체험의 기능을 부여하여 이용객들에게 형산강의 동식물 및 생태를 관찰하고 탐구할 수 있는 공간을 제공하기 위해 조성되었다고 해요.', 'Geumjangdae Wetland Park, located at the entrance to Geumjangdae, is said to have been created to provide users with a space to observe and explore the flora, fauna and ecology of the Hyeongsan River by giving educational and experiential functions to the naturally formed wetlands within the river.'),
    (89, 'summary', '경주 루지월드는 보문관광단지 내 약 7만 6840㎡ 부지에 조성되어 사계절 액티비티를 즐길 수 있는 곳이다.', 'Gyeongju Luge World is built on approximately 76,840㎡ of land within the Bomun Tourist Complex and is a place where you can enjoy activities in all four seasons.'),
    (89, 'intro', '경주 루지월드는 보문관광단지 내 약 7만 6840㎡ 부지에 조성되어 사계절 액티비티를 즐길 수 있는 곳이다. 루지는 별도의 동력 장치 없이 특수 제작된 카트를 타고 지면의 경사와 중력을 이용해 트랙을 달리는 썰매로, 누구나 쉽고 안전하게 즐길 수 있는 레저로 남녀노소 모두 다이내믹하게 즐길 수 있는 사계절 체험 스포츠이다.', 'Gyeongju Luge World is built on approximately 76,840㎡ of land within the Bomun Tourist Complex and is a place where you can enjoy activities in all four seasons. Luge is a sled that runs on a track using the slope of the ground and gravity on a specially designed cart without a separate power device. It is a leisure sport that anyone can enjoy easily and safely, and is an experiential sport in all seasons that can be enjoyed dynamically by people of all ages.'),
    (89, 'story', '코스는 1.6㎞의 화랑코스와 1.4㎞의 천마코스 총 2개의 코스로, 길고 경사가 있어 속도를 내며 라이딩하기 좋다.
코스를 완주하는 데 걸리는 시간은 대략 10여 분 정도이다.
경주 루지월드를 즐기는 또 하나의 방법은 리프트 탑승권만 구매해 전망대에 올라보는 것이다.', 'There are two courses, the 1.6km Hwarang Course and the 1.4km Cheonma Course. They are long and sloped, making them good for riding at speed.
It takes approximately 10 minutes to complete the course.
Another way to enjoy Gyeongju Luge World is to purchase a lift ticket and go up to the observatory.'),
    (89, 'tip', '경주루지월드에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Gyeongju Luge World. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (89, 'did_you_know', '경주 루지월드는 보문관광단지 내 약 7만 6840㎡ 부지에 조성되어 사계절 액티비티를 즐길 수 있는 곳이에요.', 'Gyeongju Luge World is built on approximately 76,840㎡ of land within the Bomun Tourist Complex and is a place where you can enjoy activities all year round.'),
    (90, 'summary', '천연기념물로 지정된 비단벌레를 형상화한 친환경 전기자동차다.', 'It is an eco-friendly electric vehicle shaped like a silkworm, which has been designated as a natural monument.'),
    (90, 'intro', '경주 비단벌레 전동차는 천연기념물로 지정된 비단벌레를 형상화한 친환경 전기자동차다. 비단벌레 전동차를 타고 문화해설을 들으며 첨성대를 비롯한 동부사적지대 일원을 투어한다.', 'The Gyeongju silkworm train is an eco-friendly electric vehicle shaped like a silkworm, which has been designated as a natural monument. Ride the silkworm electric train, listen to cultural commentary, and tour the Dongbu Historic Site, including Cheomseongdae.'),
    (90, 'story', '남녀노소 다양한 연령대가 이용하고 있으며 특히 아이들에게 인기 만점이다.
운행코스는 매표소에서 출발하여 계림과 향교, 최부자집, 교촌마을, 월정교, 월성, 꽃단지, 월성홍보관, 첨성대를 들러 출발지 도착하는 코스로 경주의 유명 관광지들을 한번에 둘러 볼 수 있다.
오늘의 경주 비단벌레 전동차은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'It is used by people of all ages and genders, and is especially popular with children.
The course starts from the ticket office and stops at Gyerim, Hyanggyo, Choi Rich House, Gyochon Village, Woljeonggyo Bridge, Wolseong, Kkot Complex, Wolseong Public Relations Center, and Cheomseongdae before arriving at the starting point, allowing you to see all of Gyeongju''s famous tourist attractions at once.
Today''s Gyeongju Silky Bug train leaves a different memory for each person who visits Gyeongju.'),
    (90, 'tip', '경주 비단벌레 전동차을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Gyeongju Beetle Train, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (90, 'did_you_know', '경주 비단벌레 전동차는 천연기념물로 지정된 비단벌레를 형상화한 친환경 전기자동차다고 해요.', 'The Gyeongju silkworm train is an eco-friendly electric vehicle shaped like a silkworm, which has been designated as a natural monument.'),
    (91, 'summary', '경주시 양남면에 위치하며 동해안을 따라 발달한 주상절리들의 발달규모 및 형태의 다양성을 인정받아 2012년 9월 25일 천연기념물로 지정되었다.', 'Located in Yangnam-myeon, Gyeongju-si, it was designated as a natural monument on September 25, 2012 in recognition of the scale and diversity of forms of the columnar joints developed along the east coast.'),
    (91, 'intro', '경주 양남 주상절리군은 경주시 양남면에 위치하며 동해안을 따라 발달한 주상절리들의 발달규모 및 형태의 다양성을 인정받아 2012년 9월 25일 천연기념물로 지정되었다. 주상절리는 주로 현무암과 같은 화산암에서 형성되는 육각기둥 모양의 돌기둥을 의미한다.', 'Gyeongju Yangnam Columnar Joint Group is located in Yangnam-myeon, Gyeongju-si, and was designated as a natural monument on September 25, 2012 in recognition of the scale and diversity of forms of columnar joints developed along the east coast. Columnar joints mainly refer to hexagonal pillar-shaped stone pillars formed from volcanic rocks such as basalt.'),
    (91, 'story', '이곳 경주 양남 주상절리군을 이루는 주상절리들은 짧은 해안 사이에 부채꼴 주상절리, 누워있는 주상절리, 기울어진 주상절리, 위로 솟은 주상절리 등 다양한 모양을 가지는 주상절리들이 모여 있다.
이 중에서도 특히 둥글게 펼쳐진 형태의 부채꼴 주상절리는 세계적으로 유례를 찾기 힘든 사례이며 이들의 형성과정에 대해서도 아직 밝혀진 바 없어 많은 지질학자들의 관심을 받고 있다.
오늘의 경주 양남 주상절리군은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The columnar joints that make up the columnar joints in Yangnam, Gyeongju, are gathered between the short coasts and have various shapes such as fan-shaped columnar joints, lying columnar joints, tilted columnar joints, and rising columnar joints.
Among these, the fan-shaped columnar joints in particular, which are spread out in a circle, are unprecedented examples in the world, and their formation process has not yet been revealed, so they are attracting the attention of many geologists.
Today''s Yangnam columnar joints in Gyeongju leave a different memory for each person who visits Gyeongju.'),
    (91, 'tip', '경주 양남 주상절리군에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'In the columnar joints in Yangnam, Gyeongju, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (91, 'did_you_know', '경주 양남 주상절리군은 경주시 양남면에 위치하며 동해안을 따라 발달한 주상절리들의 발달규모 및 형태의 다양성을 인정받아 2012년 9월 25일 천연기념물로 지정되었다고 해요.', 'Gyeongju Yangnam Columnar Joint Group is located in Yangnam-myeon, Gyeongju-si, and was designated as a natural monument on September 25, 2012 in recognition of the scale and diversity of forms of the columnar joints developed along the east coast.'),
    (92, 'summary', '인류 기계문명인 자동차를 초기부터 근대까지 실물을 관찰할 수 있는 박물관이다.', 'This is a museum where you can observe automobiles, part of human mechanical civilization, from the early days to the modern era.'),
    (92, 'intro', '경주세계자동차박물관은 인류 기계문명인 자동차를 초기부터 근대까지 실물을 관찰할 수 있는 박물관이다. 2017년 3월에 개관했으며 3층으로 이루어져 있다.', 'Gyeongju World Automobile Museum is a museum where you can observe automobiles, part of human mechanical civilization, from the early days to modern times. It opened in March 2017 and consists of three floors.'),
    (92, 'story', '다양한 주제의 기획, 상설 전시를 통하여 자동차의 역사, 문화적 변천 과정을 엿볼 수 있다.
게다가 전시관, 영상 역사관, 자동차 카페, 기념품 매장 등이 갖추어져 있다.
레이싱카에 쓰이는 버킷 시트에 앉아 핸들을 움직이면 차량 움직임과 노면 상황에 따라 진동이 느껴진다.', 'You can get a glimpse into the history of automobiles and the process of cultural change through planning and permanent exhibitions on various topics.
In addition, there is an exhibition hall, video history hall, car cafe, and souvenir shop.
When you sit in the bucket seat used in a racing car and move the steering wheel, you feel vibration depending on the vehicle movement and road conditions.'),
    (92, 'tip', '경주세계자동차박물관에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At the Gyeongju World Automobile Museum, choose the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (92, 'did_you_know', '2017년 3월에 개관했으며 3층으로 이루어져 있어요.', 'It opened in March 2017 and has three floors.'),
    (93, 'summary', '금관총 내부를 볼 수 있는 금관총 전시관 옆 신라고분정보센터가 2023년 7월부터 본격 운영에 돌입하였다.', 'The Silla Ancient Tombs Information Center next to the Geumgwanchong Exhibition Hall, where you can see the inside of the Geumgwanchong Tomb, began full-scale operation in July 2023.'),
    (93, 'intro', '금관총 내부를 볼 수 있는 금관총 전시관 옆 신라고분정보센터가 2023년 7월부터 본격 운영에 돌입하였다. 금관총 전시관과 관람 동선이 이어져 있어 같이 관람하기 좋으며, 과거의 신라와 지금의 경주가 어우러진 공간이다.', 'The Silla Ancient Tombs Information Center next to the Geumgwanchong Exhibition Hall, where you can see the inside of the Geumgwanchong Tomb, began full-scale operation in July 2023. The viewing route is connected to the Geumgwanchong Exhibition Hall, so it is good for viewing together. It is a space where the Silla of the past and Gyeongju of the present come together.'),
    (93, 'story', '고분정보센터의 전시공간은 길이 36m, 높이 4m 규모의 디지털 실감 영상관으로 신라고분에 대한 종합적인 정보 검색, 최신형 실감영상 시청 및 고분 문화체험, 전시유물을 관람할 수 있는 공간으로 조성되었으며, 고분에서 출토된 중요 유물들을 3D로 스캔한 자료를 활용해 복원한 실감형 영상을 비롯해 신라 고분 1천 년 이야기, 천마총 발굴 50주년을 기념하는 다큐멘터리, 경주 주요 고분의 항공 뷰 등 4개의 영상 콘텐츠가 상시 상영된다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 신라고분정보센터은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The exhibition space of the Ancient Tombs Information Center is a digital realistic video theater measuring 36m long and 4m high. It has been created as a space where you can search comprehensive information about Silla tombs, watch the latest realistic videos, experience tomb culture, and view exhibits. It includes realistic videos restored using 3D scanned data of important artifacts excavated from ancient tombs, the story of 1,000 years of Silla tombs, a documentary commemorating the 50th anniversary of the excavation of Cheonmachong Tombs, and major Gyeongju events. Four video contents, including an aerial view of the ancient tomb, are always shown.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Silla Ancient Tombs Information Center leaves a different memory for each person who visits Gyeongju.'),
    (93, 'tip', '신라고분정보센터에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At the Shilla Ancient Tombs Information Center, choose the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (93, 'did_you_know', '금관총 내부를 볼 수 있는 금관총 전시관 옆 신라고분정보센터가 2023년 7월부터 본격 운영에 돌입했어요.', 'The Silla Ancient Tomb Information Center next to the Geumgwanchong Exhibition Hall, where you can see the inside of Geumgwanchong Tomb, began full-scale operation in July 2023.'),
    (94, 'summary', '경상북도 경주시에 위치한 체험형 미디어 테마파크이다.', 'It is an experiential media theme park located in Gyeongju-si, Gyeongsangbuk-do.'),
    (94, 'intro', '코스믹 리조트는 경상북도 경주시에 위치한 체험형 미디어 테마파크이다. 우주와 휴양을 주제로 한 멀티센서리(시각, 청각, 촉각 등) 콘텐츠를 제공한다.', 'Cosmic Resort is an experiential media theme park located in Gyeongju-si, Gyeongsangbuk-do. It provides multi-sensor (visual, auditory, tactile, etc.) content themed around space and recreation.'),
    (94, 'story', '전시 존은 퍼즈 밸리(Fuzz Valley), 스타 로드(Star Road), 코스믹 홀(Cosmic Hall), 스페이스 맨(Space Man), 컨시어지 존(Concierge Zone), 댄스 라운지(Dance Lounge), 다크 웨이(Dark Way), 런드리 스플레쉬(Laundry Splash), 문라이트 풀(Moonlight Pool), 벌룬 샤워(Balloon Shower), 하이퍼 드라이브(Hyper Drive),…
방문객은 각 존에서 미디어아트, 인터랙티브 체험, 몰입형 공간 연출 등을 즐길 수 있다.
오늘의 코스믹 리조트은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The exhibition zones include Fuzz Valley, Star Road, Cosmic Hall, Space Man, Concierge Zone, Dance Lounge, Dark Way, Laundry Splash, Moonlight Pool, Balloon Shower, Hyper Drive,…
Visitors can enjoy media art, interactive experiences, and immersive space production in each zone.
Today''s Cosmic Resort leaves a different memory for each person who visits Gyeongju.'),
    (94, 'tip', '코스믹 리조트을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Cosmic Resort, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (94, 'did_you_know', '방문객은 각 존에서 미디어아트, 인터랙티브 체험, 몰입형 공간 연출 등을 즐길 수 있어요.', 'Visitors can enjoy media art, interactive experiences, and immersive space production in each zone.'),
    (95, 'summary', '세계적인 건축 거장 ‘쿠마 켄고’가 경주 대릉원과 주상절리에서 영감을 얻어 디자인한 건축물이다.', 'This is a building designed by world-renowned architect Kengo Kuma, inspired by Daereungwon and Columnar Joints in Gyeongju.'),
    (95, 'intro', '경주세계문화엑스포 기념관은 세계적인 건축 거장 ‘쿠마 켄고’가 경주 대릉원과 주상절리에서 영감을 얻어 디자인한 건축물이다. 한국, 중국 유명 작가들의 값진 작품을 만날 수 있으며, 예술적 즐거움을 공감하고 체험할 수 있는 복합 문화공간이다.', 'The Gyeongju World Culture Expo Memorial Hall is a building designed by world-famous architect Kengo Kuma, inspired by the Daereungwon Tomb and Columnar Joints in Gyeongju. It is a complex cultural space where you can see valuable works by famous Korean and Chinese artists, and empathize with and experience artistic pleasure.'),
    (95, 'story', '전시홀 로비는 장은피원(將恩被遠) 여물점균(與物霑均)을 세계 25개 주요 언어로 풀이하여 거울(Mirror)에 표현한 문자의 숲, 108개의 모니터를 통해 동·서양의 문화와 역사를 불교의 백팔번뇌로 표현한 백남준 작가의 작품 백팔번뇌, 역대 경주세계문화엑스포 기록을 아카이브존 및 아트월로 표현한 곳 문화팩토리 라운지로 구성되어 있다.
기념전시실에서는 세계 속의 신라인과 신라 속의 세계인을 기리는 작품이 있는 초월, 신라와 교류했던 주요 국가들의 랜드마크를 상징하는 문을 형상화하여 경주세계문화엑스포 문명의 교류를 표현한 세계의 문-엑스포 타임라인, 과거에서 현재로 전이되는 Liquid Floor 공간을 표현한 망라사방의 길 전시를 만날 수 있다.
또한, 기획전시실에서는 민화 속 다양한 상상 동물을 증강현실(AR) 등 디지털 기법으로 표현한 미디어아트 전시인 상상동물원을 볼 수 있다.', 'The exhibition hall lobby features a forest of characters expressed in the mirror by interpreting Jang Eunpiwon''s slime mold in 25 major languages around the world, Nam June Paik''s work Hundred Eight Tortures, which expresses the culture and history of the East and the West through the hundred eight sufferings of Buddhism through 108 monitors, and records of past Gyeongju World Culture Expos as an archive zone and art wall. It consists of the Culture Factory Lounge.
In the commemorative exhibition room, you can see the World Door-Expo Timeline, which depicts the exchange of civilizations at the Gyeongju World Culture Expo by embodying a gate symbolizing the landmarks of major countries that interacted with Silla, and the Moon of the World exhibition, which depicts the Liquid Floor space transitioning from the past to the present.
Additionally, in the special exhibition room, you can see the Imagination Zoo, a media art exhibition that expresses various imaginary animals from folk paintings using digital techniques such as augmented reality (AR).'),
    (95, 'tip', '경주세계문화엑스포 기념관을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Gyeongju World Culture Expo Memorial Hall, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (95, 'did_you_know', '전시홀 로비는 장은피원(將恩被遠) 여물점균(與物霑均)을 세계 25개 주요 언어로 풀이하여 거울(Mirror)에 표현한 문자의 숲, 108개의 모니터를 통해 동·서양의 문화와 역사를 불교의 백팔번뇌로 표현한 백남준 작가의 작품 백팔번뇌, 역대 경주세계문화엑스포 기록을 아카이브존 및 아트월로 표현한 곳 문화팩토리 라운지로 구성되어 있어요.', 'The exhibition hall lobby features a forest of characters expressed in the mirror by interpreting Jang Eunpiwon''s slime mold in 25 major languages around the world, Nam June Paik''s work Hundred Eight Tortures, which expresses the culture and history of the East and the West through the hundred eight sufferings of Buddhism through 108 monitors, and records of past Gyeongju World Culture Expos as an archive zone and art wall. It consists of the Culture Factory Lounge.'),
    (96, 'summary', '신라 시조인 김알지의 7대손 미추왕의 릉인 이곳은 경주 대릉원 내부에 존재하며 지름 59.1m, 높이 13.5m의 크기로 대릉원 고분군 중에서 4번째 규모에 해당하는 큰 규모의 능이다.', 'This is the tomb of King Michu, the 7th generation descendant of Kim Al-ji, the founder of Silla. It is located inside Daereungwon, Gyeongju. It is a large tomb with a diameter of 59.1m and a height of 13.5m, making it the fourth largest tomb among the Daereungwon tombs.'),
    (96, 'intro', '신라 시조인 김알지의 7대손 미추왕의 릉인 이곳은 경주 대릉원 내부에 존재하며 지름 59.1m, 높이 13.5m의 크기로 대릉원 고분군 중에서 4번째 규모에 해당하는 큰 규모의 능이다. 김씨 중 가장 처음 왕위에 올랐던 인물의 무덤이라는 것에 의의가 있다.', 'This is the tomb of King Michu, the 7th generation descendant of Kim Al-ji, the founder of Silla. It is located inside Daereungwon, Gyeongju. It is a large tomb with a diameter of 59.1m and a height of 13.5m, making it the fourth largest tomb among the Daereungwon tombs. It is significant in that it is the tomb of the first member of the Kim clan to ascend to the throne.'),
    (96, 'story', '내부는 인근 황남대총 및 천마총과 동일한 돌무지 덧널무덤 구조로 추정되는데, 이는 후대 눌지왕대 그의 업적을 기리기 위해 단순 덧널무덤이었던 것을 당대 묘제인 돌무지덧널무덤으로 수즙한 것으로 보고 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 미추왕릉은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The interior is presumed to have the same stone mound tomb structure as the nearby Hwangnamdae Tomb and Cheonmachong Tomb. It is believed that the simple mound tomb was converted into a stone mound tomb, a tomb ritual of the time, to commemorate his achievements during the reign of King Nulji.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Royal Tomb of King Michu remains a different memory for each person who visits Gyeongju.'),
    (96, 'tip', '미추왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Michu''s Tomb, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (96, 'did_you_know', '신라 시조인 김알지의 7대손 미추왕의 릉인 이곳은 경주 대릉원 내부에 존재하며 지름 59.1m, 높이 13.5m의 크기로 대릉원 고분군 중에서 4번째 규모에 해당하는 큰 규모의 능이에요.', 'This is the tomb of King Michu, the 7th generation descendant of Kim Al-ji, the founder of Silla. It is located inside Daereungwon, Gyeongju. It is a large tomb with a diameter of 59.1m and a height of 13.5m, making it the fourth largest among the Daereungwon tombs.'),
    (97, 'summary', '경주시 북군동에 있는 바니베어 뮤지엄은 실바니안 패밀리와 테디베어의 합작으로 만들어진 박물관으로 실바니안 한국지사에서 공식으로 인정한 곳이다.', 'The Bunny Bear Museum, located in Bukgun-dong, Gyeongju-si, is a museum created in collaboration between Sylvanian Family and Teddy Bear and is officially recognized by the Sylvanian Korean branch.'),
    (97, 'intro', '경주시 북군동에 있는 바니베어 뮤지엄은 실바니안 패밀리와 테디베어의 합작으로 만들어진 박물관으로 실바니안 한국지사에서 공식으로 인정한 곳이다. 테디베어를 이용하여 박혁거세의 탄생과 첨성대, 석굴암, 불국사 경주의 역사와 유적지를 알 수 있는 디오라마가 설치되어 있는 전시장과 전 세계 어린이들의 사랑을 받는 실바니안 패밀리 마을이 조성되어 있다.', 'The Bunny Bear Museum, located in Bukgun-dong, Gyeongju-si, is a museum created in collaboration between Sylvanian Family and Teddy Bear and is officially recognized by the Sylvanian Korean branch. There is an exhibition hall with a diorama using teddy bears to learn about the birth of Park Hyeokgeose and the history and historical sites of Cheomseongdae, Seokguram Grotto, and Bulguksa Temple in Gyeongju, as well as a Sylvanian Family Village loved by children all over the world.'),
    (97, 'story', '다람쥐, 토끼, 강아지, 코알라, 코끼리들의 병원, 유치원, 마켓, 발레, 학교 등등 아기자기하고 섬세한 실바니안 타운은 동물에 호기심을 가지는 어린이부터 어른까지 그 매력에 안 빠질 수가 없다.
아이들이 체험할 수 커다란 실바니안 하우스와 초콜릿 체험, 상상력을 자극하는 우주 테디베어, 공룡 전시까지 모든 어린이가 계절과 날씨에 구애받지 않고 즐길 수 있는 실내 공간이다.
오늘의 바니베어 뮤지엄은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Children and adults who are curious about animals cannot help but fall in love with the cute and delicate Sylvanian Town, which has a hospital for squirrels, rabbits, puppies, koalas, and elephants, a kindergarten, a market, a ballet, a school, etc.
It is an indoor space where all children can enjoy regardless of season or weather, including a large Sylvanian house and chocolate experience, a space teddy bear that stimulates the imagination, and a dinosaur exhibition.
Today''s Bunny Bear Museum leaves a different memory for each person who visits Gyeongju.'),
    (97, 'tip', '바니베어 뮤지엄을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Bunny Bear Museum, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (97, 'did_you_know', '테디베어를 이용하여 박혁거세의 탄생과 첨성대, 석굴암, 불국사 경주의 역사와 유적지를 알 수 있는 디오라마가 설치되어 있는 전시장과 전 세계 어린이들의 사랑을 받는 실바니안 패밀리 마을이 조성되어 있어요.', 'There is an exhibition hall with a diorama using teddy bears to learn about the birth of Park Hyeokgeose and the history and historical sites of Cheomseongdae, Seokguram Grotto, and Bulguksa Temple in Gyeongju, as well as a Sylvanian Family Village loved by children all over the world.'),
    (98, 'summary', '경상북도 경주시 신평동에 위치해 있는 몰입형 미디어아트 전시관이다.', 'It is an immersive media art exhibition hall located in Sinpyeong-dong, Gyeongju-si, Gyeongsangbuk-do.'),
    (98, 'intro', '정글미디어파크는 경상북도 경주시 신평동에 위치해 있는 몰입형 미디어아트 전시관이다. 모니터 프레임을 벗어나 상상 속으로만 느꼈던 공간을 직접 걸으며 체험하는 새롭고 독특한 경험을 선사한다.', 'Jungle Media Park is an immersive media art exhibition hall located in Sinpyeong-dong, Gyeongju-si, Gyeongsangbuk-do. It provides a new and unique experience of stepping out of the monitor frame and walking through a space that you only imagined.'),
    (98, 'story', '신비한 생명력이 넘쳐흐르는 재규어의 숲, 잃어버린 시간 속 여행을 통해 고대문명의 비밀을 알아낼 수 있는 신전, 화려한 수중 생물들의 세계가 펼쳐지는 심해, 다채로운 생명력으로 가득 찬 정글 등 즐길 거리가 다채롭다.
경주 IC에서 가깝고 인근에 보문관광단지와 첨성대가 있어 연계관광을 즐길 수도 있다.
오늘의 정글미디어파크은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'There are a variety of things to enjoy, including a forest of jaguars overflowing with mysterious vitality, a temple where you can discover the secrets of ancient civilizations through a journey through lost time, the deep sea where a world of colorful underwater creatures unfolds, and a jungle full of colorful vitality.
It is close to Gyeongju IC, and there are Bomun Tourist Complex and Cheomseongdae nearby, so you can enjoy linked tourism.
Today''s Jungle Media Park leaves a different memory for each person who visits Gyeongju.'),
    (98, 'tip', '정글미디어파크에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At Jungle Media Park, choose the exhibition you are interested in and plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (98, 'did_you_know', '경주 IC에서 가깝고 인근에 보문관광단지와 첨성대가 있어 연계관광을 즐길 수도 있어요.', 'It is close to Gyeongju IC, and there are Bomun Tourist Complex and Cheomseongdae nearby, so you can enjoy a linked tour.'),
    (99, 'summary', '경주에는 세 가지 진귀한 보물과 여덟 가지 기이한 현상을 뜻하는 ‘삼기팔괴’에 대한 이야기가 전해지고 있다.', 'In Gyeongju, there is a story about ‘Samgipalgoe’, which means three rare treasures and eight strange phenomena.'),
    (99, 'intro', '경주에는 세 가지 진귀한 보물과 여덟 가지 기이한 현상을 뜻하는 ‘삼기팔괴’에 대한 이야기가 전해지고 있다. 그 여덟 가지 기이한 현상 중 ‘금장낙안’은 서천과 북천이 만나는 예기청소 위 금장대에서 내려다보는 풍경에 취해 기러기도 쉬어갔다는 이야기이다.', 'In Gyeongju, there is a story about ‘Samgipalgoe’, which means three rare treasures and eight strange phenomena. Among the eight strange phenomena, ‘Geumjangnag-an’ is a story that even wild geese came to rest because they were intoxicated by the view from Geumjangdae above Yegicheongcho, where Seocheon and Bukcheon meet.'),
    (99, 'story', '그만큼 금장대는 빼어난 경치와 조망을 자랑한다.
금장대는 지난 2012년 중창하여 일반에 공개되었다.
누각에 야간경관조명이 설치되어 있고 누각에서 형산강과 경주 시가지의 야경이 한눈에 들어온다.', 'Geumjangdae boasts outstanding scenery and views.
Geumjangdae was rebuilt in 2012 and opened to the public.
Night scenery lighting is installed in the pavilion, and the night view of the Hyeongsan River and downtown Gyeongju can be seen at a glance from the pavilion.'),
    (99, 'tip', '금장대은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Geumjangdae just before the sun sets, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (99, 'did_you_know', '경주에는 세 가지 진귀한 보물과 여덟 가지 기이한 현상을 뜻하는 ‘삼기팔괴’에 대한 이야기가 전해지고 있어요.', 'In Gyeongju, there is a story about ‘Samgipalgoe’, which means three rare treasures and eight strange phenomena.'),
    (100, 'summary', '경주 핑크뮬리 군락지는 첨성대 일원에서 만날 수 있다.', 'Gyeongju pink muhly colonies can be found in the Cheomseongdae area.'),
    (100, 'intro', '경주 핑크뮬리 군락지는 첨성대 일원에서 만날 수 있다. 매년 가을이면 첨성대 꽃단지 일원이 핑크색으로 물이 든다.', 'Gyeongju pink muhly colonies can be found in the Cheomseongdae area. Every fall, the entire Cheomseongdae flower complex turns pink.'),
    (100, 'story', '경주시에서 관광콘텐츠 개발을 위해 2017년부터 핑크뮬리 군락을 조성하면서부터다.
문화유산과 핑크뮬리의 독특한 색감 덕분에 관광지 조경용으로 많은 인기를 끌고 있다.
만개한 핑크뮬리와 첨성대가 함께 나오는 멋진 풍경 사진을 남길 수 있다.', 'Gyeongju City has been establishing a colony of pink muhly since 2017 to develop tourism content.
Thanks to its cultural heritage and unique color, Pink Muhly has become very popular for landscaping in tourist destinations.
You can take great landscape photos with pink muhly in full bloom and Cheomseongdae Observatory.'),
    (100, 'tip', '경주 핑크뮬리(경주 핑크뮬리 군락지)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Pink Muhly (Gyeongju Pink Muhly Colony), check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (100, 'did_you_know', '경주시에서 관광콘텐츠 개발을 위해 2017년부터 핑크뮬리 군락을 조성하면서부터다고 해요.', 'It is said that Gyeongju City started creating a colony of pink muhly in 2017 to develop tourism content.'),
    (101, 'summary', '흥무대왕으로 추존되었던 김유신 장군의 묘 인근에 있어 이름이 흥무공원이다.', 'The name Heungmu Park is located near the tomb of General Kim Yu-sin, who was revered as King Heungmu.'),
    (101, 'intro', '흥무대왕으로 추존되었던 김유신 장군의 묘 인근에 있어 이름이 흥무공원이다. 김유신 장군묘 향하는 길이 흥무로였다.', 'The name Heungmu Park is located near the tomb of General Kim Yu-sin, who was revered as King Heungmu. The road to General Kim Yu-shin''s tomb was Heungmu-ro.'),
    (101, 'story', '공원은 크지 않지만 넓은 잔디밭과 곳곳에 나무가 만들어주는 그늘이 있어 경주시민들이 애용하는 휴식 공간이며 산책로도 잘 되어있어 힐링하기 좋은 장소이다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 흥무공원은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The park is not large, but it has a large lawn and shade provided by trees here and there, so it is a favorite resting place for Gyeongju citizens and has a good walking path, making it a good place for healing.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Heungmu Park remains a different memory for each person who visits Gyeongju.'),
    (101, 'tip', '흥무공원은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk through Heungmu Park in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (101, 'did_you_know', '공원은 크지 않지만 넓은 잔디밭과 곳곳에 나무가 만들어주는 그늘이 있어 경주시민들이 애용하는 휴식 공간이며 산책로도 잘 되어있어 힐링하기 좋은 장소이에요.', 'The park is not large, but it has a large lawn and shade provided by trees here and there, so it is a favorite resting place for Gyeongju citizens and has a good walking trail, making it a great place for healing.'),
    (102, 'summary', '동장천 청룡폭포는 동창천 계곡에 자리 잡은 인공폭포다.', 'Dongjangcheon Cheongryong Waterfall is an artificial waterfall located in Dongchangcheon Valley.'),
    (102, 'intro', '동장천 청룡폭포는 동창천 계곡에 자리 잡은 인공폭포다. 사방이 산으로 둘러싸여 있는 청정지역이다.', 'Dongjangcheon Cheongryong Waterfall is an artificial waterfall located in Dongchangcheon Valley. It is a clean area surrounded by mountains on all sides.'),
    (102, 'story', '여름철에는 하천 뒤 절벽 꼭대기에서 시원스레 물줄기가 쏟아져 내린다.
이곳은 캠퍼들이 많이 찾는 노지 캠핑의 성지다.
여름 성수기에는 자리 맡기가 하늘의 별따기 수준이다.', 'In the summer, a refreshing stream of water pours down from the top of the cliff behind the river.
This is a sacred place for open-air camping visited by many campers.
During the summer peak season, finding a seat is a breeze.'),
    (102, 'tip', '동창천 청룡폭포(청룡인공폭포)에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you are planning to play in the water at Dongchangcheon Cheongryong Waterfall (Cheongryong Artificial Waterfall), check the operation status and usage conditions first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (102, 'did_you_know', '안전한 물놀이를 위해 성수기에는 수상안전요원이 상주하고 있어요.', 'To ensure safe water play, water safety guards are on duty during peak season.'),
    (103, 'summary', '경북 경주시 안강읍 호국로에 위치한 저수지이다.', 'It is a reservoir located in Hoguk-ro, Angang-eup, Gyeongju-si, Gyeongbuk.'),
    (103, 'intro', '하곡지는 경북 경주시 안강읍 호국로에 위치한 저수지이다. 저수지 규모에 비해 평균 수심이 얕다.', 'Hagokji is a reservoir located in Hoguk-ro, Angang-eup, Gyeongju-si, Gyeongsangbuk-do. The average water depth is shallow compared to the size of the reservoir.'),
    (103, 'story', '하곡지에는 겹벚꽃나무가 있어 봄철에 방문하기 좋은 명소로 알려져 있다.
하곡지 근처에 특고압 전력선이 지나고 있어 감전위험으로 낚시가 불가하다.
주변 관광지로 옥산서원, 경주 독락당, 국립영천호국원 등이 있다.', 'There are double cherry blossom trees in Hagokji, so it is known as a good place to visit in spring.
Because an extra-high voltage power line passes near the river valley, fishing is not possible due to the risk of electric shock.
Nearby tourist attractions include Oksan Seowon, Dokrakdang in Gyeongju, and Yeongcheon National Patriotic Center.'),
    (103, 'tip', '하곡지은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk along Hagokji in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (103, 'did_you_know', '주변 관광지로 옥산서원, 경주 독락당, 국립영천호국원 등이 있어요.', 'Nearby tourist attractions include Oksan Seowon, Dokrakdang in Gyeongju, and Yeongcheon National Patriotic Center.'),
    (104, 'summary', '경주 다섯 곳의 해수욕장 가운데 가장 남쪽에 위치해 있다.', 'It is located in the southernmost of the five beaches in Gyeongju.'),
    (104, 'intro', '관성솔밭해변은 경주 다섯 곳의 해수욕장 가운데 가장 남쪽에 위치해 있다. 좌우로 수렴방파제와 지경방파제가 있어 파도가 높지 않고 맑고 푸른 청정해역으로 인기가 높으며 송림과 길게 펼쳐진 백사장이 어우러져 아름다운 풍광을 자랑한다.', 'Gwanseong Solbat Beach is located in the southernmost part of the five beaches in Gyeongju. There are convergence breakwaters and breakwaters on the left and right, so the waves are not high and it is popular as a clear, blue sea. It boasts a beautiful scenery with the pine grove and long white sand beach.'),
    (104, 'story', '해수부가 뛰어난 자연경관과 편의시설이 잘 갖추어진 곳 중 한적한 해수욕장으로 사람이 많이 분비지 않아 쾌적한 물놀이를 즐길 수 있는 곳이다.
인근 양남면 신대리에는 코오롱 골프장이 있어 해양레저와 함께 여가를 즐길 수 있으며 울산 방면 해안도로를 따라가는 드라이브 코스로도 이름이 높다.
주변 관광지로는 하서해안공원이 있다.', 'Among the beaches with outstanding natural scenery and well-equipped amenities, this is a quiet beach where there are not many people, so you can enjoy a pleasant swim.
Nearby, there is a Kolon golf course in Sindae-ri, Yangnam-myeon, where you can enjoy leisure activities along with marine leisure, and it is also famous as a driving course along the coastal road toward Ulsan.
Nearby tourist attractions include Haseo Coastal Park.'),
    (104, 'tip', '관성솔밭해변에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Gwanseong Pine Beach, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (104, 'did_you_know', '주변 관광지로는 하서해안공원이 있어요.', 'Nearby tourist attractions include Haseo Coastal Park.'),
    (105, 'summary', '경주 남산의 용장사 터에 있는 바위 면에 새겨진 불상이다.', 'This is a Buddha statue carved into a rock face at the site of Yongjangsa Temple on Namsan Mountain in Gyeongju.'),
    (105, 'intro', '경주 남산 용장사지 마애여래좌상은 경주 남산의 용장사 터에 있는 바위 면에 새겨진 불상이다. 용장사 터에는 이 불상과 함께 삼층석탑(보물 제186호)과 석조여래좌상(보물 제187호)이 남아있다.', 'The rock-carved seated Buddha at Yongjangsa Temple site in Namsan, Gyeongju is a Buddha statue carved into the face of a rock at the site of Yongjangsa Temple in Namsan, Gyeongju. Along with this Buddha statue, a three-story stone pagoda (Treasure No. 186) and a stone seated Buddha statue (Treasure No. 187) remain at the site of Yongjangsa Temple.'),
    (105, 'story', '불상의 머리에는 작은 소라 모양의 머리카락을 겹겹이 새겼고, 정수리의 뼈가 머리 위로 솟아 상투처럼 보이는 육계는 크고 펑퍼짐하게 표현하였다.
눈, 코, 입이 뚜렷하게 새겨진 얼굴에는 온화한 미소가 보인다.
옷 주름은 평행선을 빼곡하게 그려 넣어 표현하였다.', 'The head of the Buddha statue is carved with layers of small conch-shaped hair, and the bone on the top of the head, which looks like a topknot, is expressed large and puffy.
A gentle smile can be seen on the face with clearly carved eyes, nose, and mouth.
The wrinkles on the clothes were expressed by drawing dense parallel lines.'),
    (105, 'tip', '경주 남산 용장사지 마애여래좌상을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Rock-carved Buddha Statue at Yongjangsa Temple Site, Namsan, Gyeongju, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (105, 'did_you_know', '용장사 터에는 이 불상과 함께 삼층석탑(보물 제186호)과 석조여래좌상(보물 제187호)이 남아있어요.', 'Along with this Buddha statue, a three-story stone pagoda (Treasure No. 186) and a stone seated Buddha statue (Treasure No. 187) remain at the site of Yongjangsa Temple.'),
    (106, 'summary', '경주 건천으로 가면 피톤치드를 듬뿍 느끼고 체험할 수 있는 숲이 있다.', 'If you go to Geoncheon, Gyeongju, there is a forest where you can feel and experience plenty of phytoncide.'),
    (106, 'intro', '경주 건천으로 가면 피톤치드를 듬뿍 느끼고 체험할 수 있는 숲이 있다. 송선리 단석산 자락에 자리 잡은 건천편백나무숲이다.', 'If you go to Geoncheon, Gyeongju, there is a forest where you can feel and experience plenty of phytoncide. This is the Geoncheon Cypress Forest located at the foot of Danseoksan Mountain in Songseon-ri.'),
    (106, 'story', '이곳에는 시원스럽게 줄기를 뻗은 편백나무가 빽빽이 들어서 있다.
편백나무 사이에 설치된, 데크로 이루어진 산책로는 500m가량이다.
곳곳에 정자도 마련되어 있어 잠시 머무르기에도 좋다.', 'This place is densely lined with cypress trees with beautifully stretched out stems.
The walkway consisting of a deck installed between cypress trees is about 500 meters long.
There are also pavilions here and there, making it a good place to stay for a while.'),
    (106, 'tip', '건천편백나무숲은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk through the Geoncheon Cypress Forest in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (106, 'did_you_know', '편백나무 사이에 설치된, 데크로 이루어진 산책로는 500m가량이에요.', 'The decked walking path between cypress trees is about 500 meters long.'),
    (107, 'summary', '경북 경주에 위치한 금곡사(金谷寺)는 신라 진평왕 때의 대승불교 세속오계를 제정한 최초의 학승 원광법사가 13세에 출가하여 승려가 된 이후 30세인 585년경 삼기산에 창건하고 수도하였다.', 'Geumgoksa Temple (金谷寺), located in Gyeongju, Gyeongsangbuk-do, was founded and practiced on Mt. Samgi around 585, when Wonkwangbeopsa, the first scholar monk who established the five secular precepts of Mahayana Buddhism during the reign of King Jinpyeong of Silla, became a monk at the age of 13 and became a monk.'),
    (107, 'intro', '경북 경주에 위치한 금곡사(金谷寺)는 신라 진평왕 때의 대승불교 세속오계를 제정한 최초의 학승 원광법사가 13세에 출가하여 승려가 된 이후 30세인 585년경 삼기산에 창건하고 수도하였다. 이후 임진왜란 때 일본인으로 인하여, 절과 부도는 파괴되고 도굴되었으며, 1935년경 지금의 금곡사 주지 청운스님의 조모 고창(高敞) 오씨(吳氏) 순이가 절터 인근으로 나물을 채취하러 갔다가 목탁소리를 따라 지금의 금곡사 터를 발견하게 되었다고 전해진다.', 'Geumgoksa Temple (金谷寺), located in Gyeongju, Gyeongsangbuk-do, was founded and practiced on Mt. Samgi around 585, when Wonkwangbeopsa, the first scholar monk who established the five secular precepts of Mahayana Buddhism during the reign of King Jinpyeong of Silla, became a monk at the age of 13 and became a monk. Afterwards, the temple and stupa were destroyed and robbed by the Japanese during the Japanese invasions of Korea. Around 1935, Suni of the Oh clan, Gochang, the grandmother of Monk Cheongun, the current abbot of Geumgoksa Temple, went to collect herbs near the temple site and discovered the site of the current Geumgoksa Temple by following the sound of a moktak.'),
    (107, 'story', '2009년 부터 현재까지 지속적인 보수와 관리로 지금의 금곡사의 모습을 하게 되었다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 금곡사(경주)은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'From 2009 to the present, Geumgoksa Temple took on its current appearance through continuous repairs and management.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Geumgoksa Temple (Gyeongju) leaves a different memory for each person who visits Gyeongju.'),
    (107, 'tip', '금곡사(경주)에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Geumgoksa Temple (Gyeongju), rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and pavilions and the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (107, 'did_you_know', '경북 경주에 위치한 금곡사(金谷寺)는 신라 진평왕 때의 대승불교 세속오계를 제정한 최초의 학승 원광법사가 13세에 출가하여 승려가 된 이후 30세인 585년경 삼기산에 창건하고 수도했어요.', 'Geumgoksa Temple (金谷寺), located in Gyeongju, Gyeongsangbuk-do, was founded and practiced on Mt. Samgi around 585, when Wonkwangbeopsa, the first scholar monk who established the five secular precepts of Mahayana Buddhism during the reign of King Jinpyeong of Silla, became a monk at the age of 13 and became a monk.'),
    (108, 'summary', '용장사는 매월당 김시습이 『금오신화』를 쓰며 머물던 곳으로 잘 알려져 있으며, 현재 몇 군데의 석축(石築)이 남아있어 절터였음을 짐작하게 해 줄 뿐이다.', 'Yongjangsa Temple is well known as the place where Maewoldang Kim Si-seup stayed while writing 『Geumosinhwa』, and a few stone walls still remain, which only suggests that it was a temple site.'),
    (108, 'intro', '용장사는 매월당 김시습이 『금오신화』를 쓰며 머물던 곳으로 잘 알려져 있으며, 현재 몇 군데의 석축(石築)이 남아있어 절터였음을 짐작하게 해 줄 뿐이다. 절을 감싸고 뻗은 동쪽 바위 산맥의 높은 봉우리에 서 있는 이 탑은 2단의 기단(基壇) 위에 세워진 3층 석탑이다.', 'Yongjangsa Temple is well known as the place where Maewoldang Kim Si-seup stayed while writing 『Geumosinhwa』, and a few stone walls still remain, which only suggests that it was a temple site. This pagoda, which stands on the high peak of the eastern rocky mountain range that surrounds the temple, is a three-story stone pagoda built on a two-tiered stylobate.'),
    (108, 'story', '자연암석을 아래층 기단으로 삼고, 그 위로 바로 위층 기단이 올려져 있다.
즉, 자연암석이 아래층 기단일 수도 있고 그 아래 바위산 전체가 또한 아래층 기단일 수도 있는 셈이다.
위층 기단은 네 모서리와 중앙에 기둥조각을 새기고 2장의 판돌로 덮어 기단을 마감하였다.', 'Natural rock is used as the base for the lower floor, and the upper floor is raised directly above it.
In other words, the natural rock may be the base of the lower level, and the entire rocky mountain below it may also be the base of the lower level.
The stylobate of the upper floor was finished with carvings of pillars at the four corners and the center and covered with two sheets of stone.'),
    (108, 'tip', '경주 남산 용장사곡 삼층석탑을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Namsan Yongjangsagok Three-story Stone Pagoda in Gyeongju, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (108, 'did_you_know', '탑신(塔身)은 지붕돌과 몸돌을 별도의 석재로 조성했어요.', 'The body of the pagoda was made of separate stones for the roof and body stones.'),
    (109, 'summary', '경주 남산 바위의 작은 석굴 안에 새겨진 신라 초기의 마애불이에요.', 'This is a rock-carved Buddha from the early Silla Dynasty carved into a small grotto on the rock of Namsan Mountain in Gyeongju.'),
    (109, 'intro', '불곡 마애여래좌상은 남산 동쪽 골짜기의 바위를 깊게 파 만든 감실 안에 자리해요. 둥근 얼굴과 잔잔한 미소 때문에 ‘할매부처’라는 친근한 이름으로도 불리며, 남산에 남은 석불 가운데 이른 시기의 작품으로 평가됩니다.', 'The Bulgok rock-carved seated Buddha is located in a tabernacle deeply carved out of the rock in the eastern valley of Namsan Mountain. Because of its round face and calm smile, it is also affectionately called ‘Grandma Buddha’ and is considered to be an early work of stone Buddha statues remaining on Namsan Mountain.'),
    (109, 'story', '불상은 자연 바위를 지붕과 벽처럼 활용한 작은 석굴 안에 앉아 있어요. 화려한 장식보다 부드러운 표정과 단정한 자세가 먼저 눈에 들어오며, 신라인이 산과 바위를 신앙의 공간으로 받아들인 방식을 보여 줍니다.', 'The Buddha statue sits inside a small grotto that uses natural rocks as roof and walls. The gentle expression and neat posture are what first catches the eye rather than the flashy decorations, showing how the Silla people accepted mountains and rocks as spaces of faith.'),
    (109, 'tip', '대나무 숲을 지나는 짧은 산길이지만 비 온 뒤에는 바닥이 미끄러울 수 있어요. 불상 앞에서는 플래시와 접촉을 피하고, 오전의 부드러운 빛에 맞춰 조용히 감상해 보세요.', 'It''s a short mountain path through a bamboo forest, but the ground can be slippery after rain. Avoid contact with flashlights in front of the Buddha statue, and enjoy the view quietly in the soft morning light.'),
    (109, 'did_you_know', '둥글고 자애로운 인상 덕분에 오래전부터 ‘할매부처’라는 이름으로 사랑받아 왔어요.', 'Thanks to its round and benevolent appearance, it has long been loved by the name ‘Grandmother Buddha.’'),
    (110, 'summary', '한국수력원자력 본사 홍보관은 우리가 사용하고 있는 에너지를 보여준다.', 'The Korea Hydro & Nuclear Power headquarters promotional hall shows the energy we use.'),
    (110, 'intro', '한국수력원자력 본사 홍보관은 우리가 사용하고 있는 에너지를 보여준다. 홍보관은 전기에너지, 원자력 에너지, 신재생에너지 등 다양한 에너지들의 작동 원리를 전시했다.', 'The Korea Hydro & Nuclear Power headquarters promotional hall shows the energy we use. The public relations hall exhibited the operating principles of various energies such as electric energy, nuclear energy, and new and renewable energy.'),
    (110, 'story', '우리 삶 속에서 없으면 안 될 에너지들에 대해 알고 싶다면 한국수력원자력 본사 홍보관에 방문하는 것을 추천한다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 한수원 홍보관은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'If you want to know about the energies that cannot be dispensed with in our lives, we recommend visiting the Korea Hydro & Nuclear Power Headquarters Promotion Center.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Korea Hydro & Nuclear Power Promotion Center leaves a different memory for each person who visits Gyeongju.'),
    (110, 'tip', '한수원 홍보관을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Korea Hydro & Nuclear Power Promotion Center, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (110, 'did_you_know', '우리 삶 속에서 없으면 안 될 에너지들에 대해 알고 싶다면 한국수력원자력 본사 홍보관에 방문하는 것을 추천해요.', 'If you want to know about the energies that cannot be dispensed with in our lives, we recommend visiting the Korea Hydro & Nuclear Power Headquarters PR Center.'),
    (111, 'summary', '남산은 경주시의 남쪽에 솟은 산으로 신라인들의 신앙의 대상이 되어 왔다.', 'Namsan is a mountain rising to the south of Gyeongju-si and has been an object of worship for the Silla people.'),
    (111, 'intro', '남산은 경주시의 남쪽에 솟은 산으로 신라인들의 신앙의 대상이 되어 왔다. 금오봉(468m)과 고위봉(494m)의 두 봉우리에서 흘러내리는 40여 개의 계곡과 산줄기들로 이루어진 남산은 남북 8㎞, 동서 4㎞로 남북으로 길게 뻗어 내린 타원형이면서 약간 남쪽으로 치우쳐 정상을 이룬 직삼각형 모습을 취하고 있다.', 'Namsan is a mountain rising to the south of Gyeongju-si and has been an object of worship for the Silla people. Namsan, which consists of about 40 valleys and mountain ranges flowing down from the two peaks of Geumobong (468m) and Gowibong (494m), is 8km north-south and 4km east-west, and has an oval shape that extends from north to south, and is slightly tilted to the south to form a right triangle with a summit.'),
    (111, 'story', '100여 곳의 절터, 80여 구의 석불, 60여 기의 석탑이 산재해 있는 남산은 노천박물관이다.
남산에는 40여 개의 골짜기가 있으며 신라 태동의 성지 서남산, 미륵골·탑골·부처골 등의 수많은 돌 속에 묻힌 부처가 있는 동남산으로 구분된다.
남산 서쪽 기슭에 있는 나정은 신라의 첫 임금인 박혁거세의 탄생신화가 깃든 곳이며 양산재는 신라 건국 이전 서라벌에 있었던 6촌의 시조를 모신 사당이다.', 'Namsan Mountain, with over 100 temple sites, 80 stone Buddhas, and 60 stone pagodas, is an open-air museum.
Namsan has about 40 valleys and is divided into Seonamsan Mountain, the sacred site of the birth of Silla, and Dongnamsan Mountain, where Buddha is buried in numerous stones such as Mireukgol, Tapgol, and Buddhagol.
Najeong, located at the western foot of Namsan Mountain, is where the birth myth of Park Hyeokgeose, the first king of Silla, resides, and Yangsanjae is a shrine that enshrines the founders of the six villages in Seorabeol before the founding of Silla.'),
    (111, 'tip', '경주 남산은 산길이나 오르막 구간을 지나야 할 수 있어요. 미끄러지지 않는 신발과 물을 준비하고, 해가 지기 전에 돌아올 수 있도록 소요 시간을 넉넉히 잡으세요.', 'Namsan in Gyeongju may require passing through mountain paths or uphill sections. Bring non-slip shoes and water, and allow plenty of time to return before sunset.'),
    (111, 'did_you_know', '금오봉(468m)과 고위봉(494m)의 두 봉우리에서 흘러내리는 40여 개의 계곡과 산줄기들로 이루어진 남산은 남북 8㎞, 동서 4㎞로 남북으로 길게 뻗어 내린 타원형이면서 약간 남쪽으로 치우쳐 정상을 이룬 직삼각형 모습을 취하고 있어요.', 'Namsan, which consists of about 40 valleys and mountain ranges flowing down from the two peaks of Geumobong (468m) and Gowibong (494m), is 8km north-south and 4km east-west, and has an oval shape that extends from north to south, and is slightly tilted to the south to form a right triangle with a summit.'),
    (112, 'summary', '경주교촌한옥마을과 경주최부자댁 인근에 자리하고 있다.', 'It is located near Gyeongju Kyochon Hanok Village and Gyeongju Choi''s house.'),
    (112, 'intro', '경주향교는 경주교촌한옥마을과 경주최부자댁 인근에 자리하고 있다. 이 일대가 교촌, 교리, 교동이라 불리는 이유가 바로 이 향교 때문이다.', 'Gyeongju Hyanggyo is located near Gyeongju Gyochon Hanok Village and Gyeongju Choi’s house. The reason why this area is called Gyochon, Gyory, or Gyodong is because of this Hyanggyo.'),
    (112, 'story', '이 자리에 신라 최고의 중앙교육기관인 국학이 신문왕 2년(682)에 처음 세워졌다.
고려시대에는 성종 6년(987)에 지방교육기관인 학원을 설치하고 11년(992)에 시설을 정비하였다.
조선시대에는 향교로 이어져 성종 23년(1492)에 문묘와 성균관의 배치형식을 따라 다시 지었다.', 'At this location, Gukhak, the highest central educational institution in Silla, was first established in the second year of King Sinmun''s reign (682).
During the Goryeo Dynasty, an academy, a local educational institution, was established in the 6th year of King Seongjong''s reign (987) and the facilities were renovated in the 11th year of King Seongjong''s reign (992).
During the Joseon Dynasty, it was continued as a local school, and was rebuilt in the 23rd year of King Seongjong''s reign (1492), following the layout of Munmyo Shrine and Sungkyunkwan.'),
    (112, 'tip', '경주향교은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Gyeongju Hyanggyo in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (112, 'did_you_know', '이 자리에 신라 최고의 중앙교육기관인 국학이 신문왕 2년(682)에 처음 세워졌다고 해요.', 'It is said that Kukhak, the highest central educational institution in Silla, was first established on this site in the second year of King Sinmun''s reign (682).'),
    (113, 'summary', '경주터미널에서 형산강을 건너는 서천교를 지나 첫 교차로에서 우회전하면 만날 수 있다.', 'You can find it by passing Seocheon Bridge across the Hyeongsan River from Gyeongju Terminal and turning right at the first intersection.'),
    (113, 'intro', '흥무로 벚꽃길은 경주터미널에서 형산강을 건너는 서천교를 지나 첫 교차로에서 우회전하면 만날 수 있다. 이곳은 2007년 건설교통부에서 ‘한국의 아름다운 길 100선’ 가운데 하나로 선정했다.', 'Heungmu-ro Cherry Blossom Road can be found by passing Seocheon Bridge across the Hyeongsan River from Gyeongju Terminal and turning right at the first intersection. This place was selected as one of Korea’s 100 Beautiful Roads by the Ministry of Construction and Transportation in 2007.'),
    (113, 'story', '아름다운 길로 선정된 이유는 봄날에 흥무로를 찾는다면 자연스레 알게 될 것이다.
도로 양쪽에 선 아름드리 벚나무가 가지끼리 맞닿아 하늘을 가려 아름다운 벚꽃터널이 완성된다.
벚꽃 만발하는 봄이면 수많은 상춘객으로 도로가 주차장이 되니 자전거나 도보여행이 자동차 여행보다', 'If you visit Heungmu-ro on a spring day, you will naturally understand why it was selected as a beautiful road.
The beautiful cherry trees on both sides of the road have their branches touching and block the sky, creating a beautiful cherry blossom tunnel.
In spring, when the cherry blossoms are in full bloom, roads become parking lots due to the large number of visitors, so bicycle or walking trips are more popular than car trips.'),
    (113, 'tip', '흥무로 벚꽃길을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Heungmu-ro Cherry Blossom Road, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (113, 'did_you_know', '이곳은 2007년 건설교통부에서 ‘한국의 아름다운 길 100선’ 가운데 하나로 선정했다고 해요.', 'This place was selected as one of Korea''s 100 Beautiful Roads by the Ministry of Construction and Transportation in 2007.'),
    (114, 'summary', '(827.2m)은 경주에서 가장 높은 산으로 백제에 대한 신라의 국방의 요충지였다.', '(827.2m) is the highest mountain in Gyeongju and was a key point for Silla''s defense against Baekje.'),
    (114, 'intro', '단석산(827.2m)은 경주에서 가장 높은 산으로 백제에 대한 신라의 국방의 요충지였다. 진달래군락지로 봄철 산악애호가들의 사랑을 받고 있으며, 인근 조래봉과 더불어 등산코스로 각광을 받고 있다.', 'Danseoksan Mountain (827.2m) is the highest mountain in Gyeongju and was a key point for Silla''s defense against Baekje. It is loved by mountaineering enthusiasts in spring as it is home to a colony of azaleas, and is in the spotlight as a hiking course along with nearby Joraebong Peak.'),
    (114, 'story', '또한, 산 7~8부 능선 4개의 바위가 둘러싸인 천연굴이 있는데, 옛날에는 상인암 이라고 불렸다고 한다.
화랑들은 이 바위굴 속에 불상을 새기고, 그 위에 지붕을 덮어 석굴사원을 만들었다.
이 절을 신선사(神仙寺) 또는 단석사(斷石寺)라고 부른다.', 'In addition, there is a natural cave surrounded by four rocks on the 7th and 8th ridges of the mountain, and it is said that it was called Sanginam in the old days.
Hwarangs carved Buddha statues into these rock caves and covered them with roofs to create cave temples.
This temple is called Sinseonsa Temple or Danseoksa Temple.'),
    (114, 'tip', '단석산은 산길이나 오르막 구간을 지나야 할 수 있어요. 미끄러지지 않는 신발과 물을 준비하고, 해가 지기 전에 돌아올 수 있도록 소요 시간을 넉넉히 잡으세요.', 'Danseoksan Mountain may require passing through a mountain path or uphill section. Bring non-slip shoes and water, and allow plenty of time to return before sunset.'),
    (114, 'did_you_know', '단석산(827.2m)은 경주에서 가장 높은 산으로 백제에 대한 신라의 국방의 요충지였어요.', 'Danseoksan Mountain (827.2m) is the highest mountain in Gyeongju and was a key point for Silla''s defense against Baekje.'),
    (115, 'summary', '전촌항과 나정고운모래해변 사이에 자리 잡고 있는 작은 솔밭 해변이다.', 'It is a small pine beach located between Jeonchon Port and Najeong Fine Sand Beach.'),
    (115, 'intro', '전촌솔밭해변은 전촌항과 나정고운모래해변 사이에 자리 잡고 있는 작은 솔밭 해변이다. 길이 0.8㎞, 폭 30∼60ｍ의 백사장이 그리 넓지 않아 해수욕장으로 유명하지는 않지만 옆의 나정고운모래해변과 연결되어 긴 모래사장 펼쳐진 곳이다.', 'Jeonchon Pine Field Beach is a small pine field beach located between Jeonchon Port and Najeong Fine Sand Beach. The white sand beach, which is 0.8km long and 30-60m wide, is not very wide, so it is not famous as a beach, but it is connected to the nearby Najeong Fine Sand Beach and has a long sandy beach.'),
    (115, 'story', '음식점, 카페 샤워장 등 편의시설이 갖추어져 있고 조용한 해수욕을 즐기기 위한 관광객들이 찾는다.
반대편 전포항은 바다
낚시꾼들에게 인기 있는 곳이며 주변 식당에서는 그날 잡은 신선한 해산물 요리를 먹을 수 있다.', 'It is equipped with convenient facilities such as restaurants, cafes and showers, and is visited by tourists who want to enjoy quiet swimming in the sea.
Jeonpo Port on the other side is the sea
It is a popular spot for anglers, and you can eat fresh seafood caught that day at nearby restaurants.'),
    (115, 'tip', '전촌솔밭해변에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Jeonchon Solbat Beach, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (115, 'did_you_know', '길이 0.8㎞, 폭 30∼60ｍ의 백사장이 그리 넓지 않아 해수욕장으로 유명하지는 않지만 옆의 나정고운모래해변과 연결되어 긴 모래사장 펼쳐진 곳이에요.', 'The white sand beach, which is 0.8km long and 30-60m wide, is not that wide, so it is not famous as a beach, but it is connected to the Najeong Fine Sand Beach next door and has a long sandy beach.'),
    (116, 'summary', '불국사와 멀지 않은 곳에 아버지, 어머니 대의 역사를 담은 근대사 박물관 추억의 달동네가 있다.', 'Not far from Bulguksa Temple is Daldongne of Memories, a modern history museum that contains the history of one''s father and mother.'),
    (116, 'intro', '불국사와 멀지 않은 곳에 아버지, 어머니 대의 역사를 담은 근대사 박물관 추억의 달동네가 있다. 추억의 달동네에서는 1970~80년대의 생활상을 재현해 놓은 콘텐츠를 접할 수 있다.', 'Not far from Bulguksa Temple is Daldongne of Memories, a modern history museum that contains the history of one''s father and mother. In Daldongne of Memories, you can access content that recreates life in the 1970s and 1980s.'),
    (116, 'story', '지금은 쓰지 않는 낡은 라디오, 그것을 고치는 전파상, 골목 점방, 초등학교 아닌 국민학교 교실까지, 근래 반세기 우리네 생활상을 그대로 옮겨 두었다.
추억의 간식 달고나 체험, 추억의 교복체험 등 다양한 체험프로그램도 마련되어 있다.
오늘의 추억의 달동네은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'An old radio that is no longer in use, a radio shop that repairs it, an alley store, and even a classroom in a elementary school that is not an elementary school, we have copied our lifestyle for the past half century.
There are also various experience programs such as the nostalgic snack Dalgona experience and the nostalgic school uniform experience.
Today''s nostalgic Daldongne remains a different memory for each person who visits Gyeongju.'),
    (116, 'tip', '추억의 달동네에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At Daldongne of Memories, choose the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (116, 'did_you_know', '추억의 달동네에서는 1970~80년대의 생활상을 재현해 놓은 콘텐츠를 접할 수 있어요.', 'In Daldongne of Memories, you can access content that recreates life in the 1970s and 1980s.'),
    (117, 'summary', '이 무덤은 신라 제28대 진덕여왕을 모신 곳으로 알려져 있다.', 'This tomb is known as the place where Queen Jindeok, the 28th queen of Silla, is enshrined.'),
    (117, 'intro', '이 무덤은 신라 제28대 진덕여왕을 모신 곳으로 알려져 있다. 진덕여왕은 본명이 승만이며, 선덕여왕의 사촌동생이다.', 'This tomb is known as the place where Queen Jindeok, the 28th queen of Silla, is enshrined. Queen Jindeok''s real name is Seungman, and she is Queen Seondeok''s younger cousin.'),
    (117, 'story', '산라의 두 번째 여왕이면서 성골로서는 마지막 왕이다.
진덕여왕은 김춘추와 김유신의 도움으로 왕위에 올라 재위 기간에 관료와 군사 조직을 정비하고, 당나라의 제도와 문물을 적극적으로 받아들였다.
또한 김유신을 내세워 백제와의 잦은 전쟁에서 많은 승리를 거뒀다.', 'She is the second queen of Sanra and the last king of the Sacred Bones.
Queen Jindeok ascended to the throne with the help of Kim Chun-chu and Kim Yu-sin, and during her reign, she reorganized the bureaucracy and military organization and actively adopted the Tang Dynasty''s system and culture.
In addition, under the leadership of Kim Yu-shin, many victories were achieved in frequent wars with Baekje.'),
    (117, 'tip', '경주 진덕여왕릉에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At Queen Jindeok''s Tomb in Gyeongju, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (117, 'did_you_know', '이 무덤은 신라 제28대 진덕여왕을 모신 곳으로 알려져 있어요.', 'This tomb is known as the place where Queen Jindeok, the 28th queen of Silla, is enshrined.'),
    (118, 'summary', '운곡서원 옆에 있는 유연정은 조선 순조 11년(1811)에 안동 권씨 종중에서 고려태사 권행과 그의 후손인 죽림 권산해, 귀봉 권덕린을 추모하기 위해 세운 정자이다.', 'Yuyeonjeong, located next to Ungokseowon, is a pavilion built by the Andong Gwon clan in the 11th year of King Sunjo of the Joseon Dynasty (1811) to commemorate Goryeo Taesa Gwon Haeng and his descendants, Jukrim Kwon Sanhae and Gwibong Kwon Deokrin.'),
    (118, 'intro', '운곡서원 옆에 있는 유연정은 조선 순조 11년(1811)에 안동 권씨 종중에서 고려태사 권행과 그의 후손인 죽림 권산해, 귀봉 권덕린을 추모하기 위해 세운 정자이다. 이 정자는 도연명의 자연 애호 사상을 본받아 서원에서 동쪽으로 약 50m 떨어진 계곡의 용추대 위에 있는데, 주위의 자연경관과 멋진 조화를 이룬다.', 'Yuyeonjeong, located next to Ungokseowon, is a pavilion built by the Andong Gwon clan in the 11th year of King Sunjo of the Joseon Dynasty (1811) to commemorate Goryeo Taesa Gwon Haeng and his descendants, Jukrim Kwon Sanhae and Gwibong Kwon Deokrin. This pavilion is located on Yongchudae in a valley about 50m east of Seowon, following Tao Yuanming''s philosophy of protecting nature. It harmonizes wonderfully with the surrounding natural scenery.'),
    (118, 'story', '건물의 형태는 앞면 3칸, 옆면 2칸의 규모이고, 팔작지붕이다.
대청의 천장은 서까래가 보이지 않도록 井자 모양을 한 우물 반자로 꾸몄는데, 그 양쪽에 반원형 판재를 45도로 끼운 모습이 매우 독특하다.
용추계곡, 은행나무 등 주변 자연 경관과 조화를 이루며, 1800년대 초기의 건축 수법을 잘 보여준다.', 'The building is 3 rooms on the front and 2 rooms on the sides, and has a gable roof.
The ceiling of the main hall is decorated with a half-shaped well shaped like the letter 井 so that the rafters are not visible, and the appearance of semicircular boards inserted at 45 degrees on both sides is very unique.
It harmonizes with the surrounding natural landscape, including Yongchu Valley and ginkgo trees, and clearly displays the architectural techniques of the early 1800s.'),
    (118, 'tip', '경주유연정을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Yuyeonjeong, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (118, 'did_you_know', '운곡서원 옆에 있는 유연정은 조선 순조 11년(1811)에 안동 권씨 종중에서 고려태사 권행과 그의 후손인 죽림 권산해, 귀봉 권덕린을 추모하기 위해 세운 정자이에요.', 'Yeonyeonjeong, located next to Ungokseowon Confucian Academy, is a pavilion built by the Andong Gwon clan in the 11th year of King Sunjo''s reign (1811) to commemorate Goryeo Taesa Gwon Haeng and his descendants, Jukrim Gwon Sanhae and Gwibong Kwon Deokrin.'),
    (119, 'summary', '마우나오션 리조트 내에 있는 블루워터 스파는 영남 지역 최초의 고품격 스파시설이다.', 'Blue Water Spa, located within Mauna Ocean Resort, is the first high-quality spa facility in the Yeongnam region.'),
    (119, 'intro', '마우나오션 리조트 내에 있는 블루워터 스파는 영남 지역 최초의 고품격 스파시설이다. 온 가족이 함께 즐길 수 있는 실내 바데풀과 야외 수영장, 사우나 등이 있다.', 'Blue Water Spa, located within Mauna Ocean Resort, is the first high-quality spa facility in the Yeongnam region. There is an indoor bade pool, outdoor swimming pool, and sauna that the whole family can enjoy.'),
    (119, 'story', '실내와 실외 물놀이 시설을 모두 갖추고 있어 아이들과 함께 휴식과 여가를 즐기기 위해서 많이 방문한다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 마우나오션리조트 블루 워터은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'It has both indoor and outdoor water play facilities, so many people visit to enjoy rest and leisure with their children.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Mauna Ocean Resort Blue Water leaves a different memory for each person who visits Gyeongju.'),
    (119, 'tip', '마우나오션리조트 블루 워터에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Mauna Ocean Resort Blue Water, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (119, 'did_you_know', '마우나오션 리조트 내에 있는 블루워터 스파는 영남 지역 최초의 고품격 스파시설이에요.', 'Blue Water Spa, located within Mauna Ocean Resort, is the first high-quality spa facility in the Yeongnam region.'),
    (120, 'summary', '경주 남산은 유물·유적의 보고(寶庫)라고 할 수 있는데, 여기에 가면 삼국시대부터 통일신라 후기까지의 불상들을 모두 만나볼 수 있다.', 'Namsan in Gyeongju can be said to be a treasure trove of relics and relics. If you go here, you can see all the Buddhist statues from the Three Kingdoms period to the late Unified Silla period.'),
    (120, 'intro', '경주 남산은 유물·유적의 보고(寶庫)라고 할 수 있는데, 여기에 가면 삼국시대부터 통일신라 후기까지의 불상들을 모두 만나볼 수 있다. 그중에 하나인 높이 1.4m의 마애보살 반가상은 칠불암(七佛庵) 위에 곧바로 선 남쪽 바위에 새겨져 있다.', 'Namsan in Gyeongju can be said to be a treasure trove of relics and relics. If you go here, you can see all the Buddhist statues from the Three Kingdoms period to the late Unified Silla period. One of them, the 1.4m tall rock-carved Bodhisattva, is carved on the southern rock that stands straight above Chilbulam (Seven Buddha Temple).'),
    (120, 'story', '마치 구름 위에 앉아 있는 것처럼 보이는데 머리에 삼면보관(三面寶冠)을 쓰고 있어서 보살상임을 알 수 있다.
얼굴은 풍만하고, 지그시 감은 두 눈은 깊은 생각에 잠긴 모습으로 구름 위의 세계에서 중생을 살펴보고 있는 듯하다.
오른손에는 꽃을 잡고 있으며, 왼손은 가슴까지 들어 올려서 설법하는 모양을 표현하고 있다.', 'It looks as if it is sitting on a cloud, and it is wearing a three-faced crown on its head, making it clear that it is a Bodhisattva statue.
The face is voluptuous, and the two gently closed eyes look deep in thought, as if examining sentient beings from the world above the clouds.
He is holding a flower in his right hand, and his left hand is raised up to his chest to express the appearance of giving a sermon.'),
    (120, 'tip', '경주 남산 신선암 마애보살반가상에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Shinseonam Rock-carved Bodhisattva Statue on Namsan Mountain in Gyeongju, rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and pavilions and the mountain landscape behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (120, 'did_you_know', '머리 광배와 몸 광배를 갖춘 광배 (光背) 자체를 불상이 들어앉을 공간으로 이용했기 때문에 보살상이 더욱 두드러져 보이며, 통일신라시대 8세기 후반의 작품으로 보인다고 해요.', 'The Bodhisattva statue stands out even more because the mandorla itself, which consists of a head mandorla and a body mandorla, was used as a space for the Buddha statue to sit. It is said to be a work of art from the late 8th century during the Unified Silla period.'),
    (121, 'summary', '망월사는 경주시 배동에 자리한 대한불교원효종 소속 사찰이다.', 'Mangwolsa Temple is a temple affiliated with Wonhyojong of Korean Buddhism located in Bae-dong, Gyeongju-si.'),
    (121, 'intro', '망월사는 경주시 배동에 자리한 대한불교원효종 소속 사찰이다. 대한불교원효종의 중요한 사찰로 꼽힌다.', 'Mangwolsa Temple is a temple affiliated with Wonhyojong of Korean Buddhism located in Bae-dong, Gyeongju-si. It is considered an important temple of Wonhyojong of Korean Buddhism.'),
    (121, 'story', '대한불교원효종은 우리나라 18개 불교 종단 가운데 하나로 신라의 원효스님을 종조로 하여 1963년 경주에서 해인스님이 대한불교원효종 포교원을 창종하고 해인스님이 초대 종정이 되었다.
그 뒤 1967년 8월 망월사가 본원이 되었으며, 1977년 12월 대한불교원효종이 되었다.
현재 총무원은 서울 안양암에 있고, 주요 경전은 원효종성전인데 1967년 망월사에서 발간되었다.', 'Wonhyojong of Korean Buddhism is one of the 18 Buddhist orders in Korea. With Monk Wonhyo of Silla as its founder, Monk Haein founded the Wonhyojong Missionary Center of Korean Buddhism in Gyeongju in 1963, and Monk Haein became the first monk.
Afterwards, Mangwolsa Temple became the head temple in August 1967, and it became the Wonhyojong Order of Korean Buddhism in December 1977.
Currently, the general affairs office is located in Anyangam, Seoul, and the main scripture is Wonhyojongseongjeon, which was published by Mangwolsa Temple in 1967.'),
    (121, 'tip', '망월사(경주)에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Mangwolsa Temple (Gyeongju), rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and pavilions and the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (121, 'did_you_know', '대한불교원효종은 우리나라 18개 불교 종단 가운데 하나로 신라의 원효스님을 종조로 하여 1963년 경주에서 해인스님이 대한불교원효종 포교원을 창종하고 해인스님이 초대 종정이 되었다고 해요.', 'Wonhyojong of Korean Buddhism is one of the 18 Buddhist orders in Korea. With Monk Wonhyo of Silla as its founder, Monk Haein founded the Wonhyojong Missionary Center of Korean Buddhism in Gyeongju in 1963, and Monk Haein became the first monk.'),
    (122, 'summary', '경상북도 경주시에 위치한 대한불교조계종 제11교구 본사 불국사의 말사이다.', 'It is a subsidiary temple of Bulguksa Temple, the headquarters of the 11th Diocese of the Jogye Order of Korean Buddhism, located in Gyeongju, Gyeongsangbuk-do.'),
    (122, 'intro', '분황사는 경상북도 경주시에 위치한 대한불교조계종 제11교구 본사 불국사의 말사이다. 선덕여왕 3년인 634년에 창건된 사찰로, 원효대사와 자장법사가 머물렀던 역사 깊은 절이다.', 'Bunhwangsa Temple is a branch temple of Bulguksa Temple, the headquarters of the 11th Diocese of the Jogye Order of Korean Buddhism, located in Gyeongju, Gyeongsangbuk-do. This temple was founded in 634, the third year of Queen Seondeok, and is a temple with a long history where Master Wonhyo and Beopsa Jajang stayed.'),
    (122, 'story', '절 안에는 국보로 지정된 모전석탑이 있으며, 이는 통일신라 이전에 세워진 대표적인 전탑 양식이다.
모전석탑은 본래 5층 이상이었으나 현재는 3층만 남아 있으며, 고려시대에도 보수가 이루어졌음을 사리장치에서 확인할 수 있다.
탑 1층에는 감실과 수문장상이 조각되어 있으며, 석사자상도 함께 배치되어 있다.', 'Inside the temple, there is a stone pagoda designated as a national treasure, which is a representative pagoda style built before the Unified Silla Dynasty.
The original stone pagoda had more than five stories, but now only three stories remain, and it can be seen from the reliquary that repairs were made even during the Goryeo Dynasty.
On the first floor of the tower, a tabernacle and a statue of the gatekeeper are carved, and a statue of a master master is also placed there.'),
    (122, 'tip', '분황사에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Bunhwangsa Temple, rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and temples, as well as the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (122, 'did_you_know', '분황사는 경상북도 경주시에 위치한 대한불교조계종 제11교구 본사 불국사의 말사이에요.', 'Bunhwangsa Temple is a branch of Bulguksa Temple, the headquarters of the 11th Diocese of the Jogye Order of Korean Buddhism, located in Gyeongju, Gyeongsangbuk-do.'),
    (123, 'summary', '경상북도 산림환경연구소는 신라 천 년의 시간을 흐르는 경주 남산 자락에 자리하고 있다.', 'The Gyeongsangbuk-do Forest Environment Research Institute is located at the foot of Namsan Mountain in Gyeongju, a place that dates back 1,000 years during the Silla Dynasty.'),
    (123, 'intro', '경상북도 산림환경연구소는 신라 천 년의 시간을 흐르는 경주 남산 자락에 자리하고 있다. 기후변화에 대응한 산림환경조사, 산림병해충의 친환경 방제, 우량수목 등 식물 유전자원 보존 및 증식, 천연기념물 후계목의 증식과 보존, 병해충을 방제 등 산림보호를 위한 연구 기관이며, 지방 정원, 숲 체험원 조성으로 생태휴양공간을 마련하고 산림의 효율적인 경영과 보호를 위한 임도 및 사방사업을 수행하는 산림 전문 연구기관이다.', 'The Gyeongsangbuk-do Forest Environment Research Institute is located at the foot of Namsan Mountain in Gyeongju, a place that dates back 1,000 years during the Silla Dynasty. It is a research institute for forest protection, including forest environmental surveys in response to climate change, eco-friendly control of forest diseases and pests, preservation and propagation of plant genetic resources such as superior trees, proliferation and preservation of natural monument successor trees, and pest control.'),
    (123, 'story', '숲공원으로 지자체가 조성하고 관리하는 국가 정원으로는 국내 5번째이고, 경북에서는 첫 번째 숲 정원이다.
경북천년숲정원은 다양한 테마로 조성된 정원과 오솔길.
메타세콰이어 숲길, 거울숲, 외나무다리 등 이 있으며, 각 구역별 계절별 꽃을 피우는 나무와 야생화들이 식재되어 있어 각기 다른 공간적 특징을 지니며 계절에 따른 변화도 즐길 수 있다.', 'As a forest park, it is the fifth national garden created and managed by a local government in Korea, and the first forest garden in Gyeongbuk.
Gyeongbuk Millennium Forest Garden is a garden and path created with various themes.
There is a metasequoia forest path, a mirror forest, and a single tree bridge, and each area is planted with trees and wildflowers that bloom according to the season, so each area has different spatial characteristics and allows you to enjoy seasonal changes.'),
    (123, 'tip', '경상북도 산림환경연구원에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At the Gyeongsangbuk-do Forest Environment Research Institute, rather than just quickly looking at the buildings, take a look at the arrangement of the towers and pavilions and the mountain landscape behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (123, 'did_you_know', '기후변화에 대응한 산림환경조사, 산림병해충의 친환경 방제, 우량수목 등 식물 유전자원 보존 및 증식, 천연기념물 후계목의 증식과 보존, 병해충을 방제 등 산림보호를 위한 연구 기관이며, 지방 정원, 숲 체험원 조성으로 생태휴양공간을 마련하고 산림의 효율적인 경영과 보호를 위한 임도 및 사방사업을 수행하는 산림 전문 연구기관이에요.', 'It is a research institute for forest protection, including forest environmental surveys in response to climate change, eco-friendly control of forest diseases and pests, conservation and propagation of plant genetic resources such as superior trees, proliferation and preservation of successor trees to natural monuments, and pest control. It is a forestry research institute that prepares ecological recreation spaces by creating local gardens and forest experience centers and carries out forestry and erosion control projects for efficient management and protection of forests.'),
    (124, 'summary', '읍천항에서 하서항까지 1.7㎞ 구간을 일컫는다.', 'It refers to the 1.7km section from Eupcheon Port to Haseo Port.'),
    (124, 'intro', '파도소리길은 읍천항에서 하서항까지 1.7㎞ 구간을 일컫는다. 데크 로드, 정자, 벤치, 구름다리 등 해안 길이 잘 정비되어 있다.', 'Padosori Road refers to a 1.7km section from Eupcheon Port to Haseo Port. The coastal path is well maintained, including deck roads, pavilions, benches, and overpasses.'),
    (124, 'story', '이곳은 경주 양남 주상절리를 구경하며 걸을 수 있다.
경주 양남 주상절리는 2012년 군부대가 철수하면서 세상에 나왔다.
통상적으로 주상절리는 주로 화산암 지대에서 발견할 수 있는 위로 솟은 모양의 육각형 돌기둥을 뜻한다.', 'Here, you can walk while looking at the columnar joints in Yangnam, Gyeongju.
The columnar joints in Yangnam, Gyeongju, came into existence in 2012 when military units withdrew.
Columnar joints generally refer to hexagonal stone pillars that rise upward and can be found mainly in volcanic rock areas.'),
    (124, 'tip', '파도소리길을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Padosori Road, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (124, 'did_you_know', '경주 양남 주상절리는 2012년 군부대가 철수하면서 세상에 나왔다고 해요.', 'It is said that the columnar joints in Yangnam, Gyeongju, came into being when the military units withdrew in 2012.'),
    (125, 'summary', '나아 해변은 경북 경주시 양남면에 자리 잡고 있다.', 'Naa Beach is located in Yangnam-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (125, 'intro', '나아 해변은 경북 경주시 양남면에 자리 잡고 있다. 해변은 몽돌과 모래가 섞여있다.', 'Naa Beach is located in Yangnam-myeon, Gyeongju-si, Gyeongsangbuk-do. The beach is a mixture of pebbles and sand.'),
    (125, 'story', '낚시를 즐기는 사람이 많다.
특히 소나무 숲에는 무료로 텐트를 설치할 수 있어 많은 사람이 캠핑을 즐긴다.
취사는 금지이지만 차크닉과 차박을 즐기기 위해 많은 이들이 찾는다.', 'There are many people who enjoy fishing.
In particular, many people enjoy camping because tents can be set up for free in the pine forest.
Cooking is prohibited, but many people visit to enjoy chaknik and chabak.'),
    (125, 'tip', '나아해변에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Naa Beach, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (125, 'did_you_know', '주변에 나산들 공원, 경주 문무대왕릉이 있어요.', 'Nearby are Nasandeul Park and the Tomb of King Munmu in Gyeongju.'),
    (126, 'summary', '통일전은 삼국 통일의 정신을 계승하고, 다가올 남북통일을 기원하는 국민의 전당이다.', 'Unification Hall is a people''s hall that inherits the spirit of the unification of the three countries and prays for the coming unification of North and South Korea.'),
    (126, 'intro', '통일전은 삼국 통일의 정신을 계승하고, 다가올 남북통일을 기원하는 국민의 전당이다. 경내에는 태종무열왕, 문무대왕, 김유신 장군의 영정이 모셔져 있으며, 통일을 위한 격전을 생생히 보여주는 기록화가 긴 회랑을 따라 전시되어 있다.', 'Unification Hall is a people''s hall that inherits the spirit of the unification of the three countries and prays for the coming unification of North and South Korea. The grounds house the portraits of King Taejong Muyeol, King Munmu, and General Kim Yu-sin, and documentary paintings vividly showing the fierce battle for unification are displayed along the long corridor.'),
    (126, 'story', '통일전은 호국영령의 뜻을 기리기 위해 건립된 만큼, 초·중등학생들의 이념 교육장으로 활용되고 있으며, 수학여행의 필수 코스로 자리 잡고 있다.
삼국 통일 당시의 전투 장면이 여러 액자에 그려져 있는 것이 인상적이며, 남산 답사 중 잠시 호국영령에게 참배하고, 넓은 잔디밭에서 쉬어가는 것도 좋다.
오늘의 통일전(경주)은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'As Tongiljeon was built to commemorate the spirit of the patriotic spirit, it is used as an ideological education center for elementary and middle school students, and is established as an essential course for school trips.
It is impressive to see battle scenes from the time of the unification of the three kingdoms depicted in various frames, and while exploring Namsan Mountain, it is also a good idea to briefly pay homage to the patriotic spirit and take a rest on the large lawn.
Today''s Unification Exhibition (Gyeongju) leaves a different memory for each person who visits Gyeongju.'),
    (126, 'tip', '통일전(경주)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Tongiljeon (Gyeongju), check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (126, 'did_you_know', '통일전은 호국영령의 뜻을 기리기 위해 건립된 만큼, 초·중등학생들의 이념 교육장으로 활용되고 있으며, 수학여행의 필수 코스로 자리 잡고 있어요.', 'As Tongiljeon was built to honor the spirit of the patriotic spirit, it is used as an ideological education center for elementary and middle school students, and is established as a required course for school trips.'),
    (127, 'summary', '경주 최씨의 종가로 신라시대 요석궁이 있던 자리라고 전하는 곳에 위치하고 있다.', 'It is the head home of the Gyeongju Choi clan and is located at the site where Yoseokgung Palace was located during the Silla Dynasty.'),
    (127, 'intro', '경주 최씨의 종가로 신라시대 요석궁이 있던 자리라고 전하는 곳에 위치하고 있다. 9대째 대대로 살고 있으며, 1700년경 이 가옥을 지었다고 하지만 확실한 시기는 알 수 없다.', 'It is the head home of the Gyeongju Choi clan and is located at the site where Yoseokgung Palace was located during the Silla Dynasty. Nine generations have been living in this house, and it is said that this house was built around 1700, but the exact date is unknown.'),
    (127, 'story', '건물 구성은 사랑채, 안채, 대문채 등으로 이루어져 있는데, 그중 대문채에는 작은방과 큰 곳간을 마련하였다.
사랑채는 안마당 맞은편에 있었으나 별당과 함께 1970년 11월 화재로 지금은 터만 남아있다.
사랑채터 뒤쪽에 있는 안채는 트인 ㅁ자형이나 실제로는 몸채가 ㄷ자형 평면을 가지고 있고, ㄱ자형 사랑채와 一자형 중문채가 어울려 있었다.', 'The building consists of a sarangchae (sarangchae), anchae (main house), and a main house, and the main house has a small room and a large storeroom.
The sarangchae was located across from the courtyard, but along with the outbuildings, a fire occurred in November 1970, and now only the site remains.
The main building behind the Sarangchaeter was open, ㅁ-shaped, but in reality, the main building had a U-shaped floor plan, and the L-shaped Sarangchae and the I-shaped Jungmunchae were combined.'),
    (127, 'tip', '경주 최부자댁을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Choi''s residence, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (127, 'did_you_know', '9대째 대대로 살고 있으며, 1700년경 이 가옥을 지었다고 하지만 확실한 시기는 알 수 없다고 해요.', 'Nine generations have been living here, and it is said that this house was built around 1700, but the exact date is not known.'),
    (128, 'summary', '명활산을 둘러싸고 있는 신라시대 산성으로 경주 주변의 남산신성, 서형산성, 북형산성과 함게 수도 방어시설로 큰 몫을 한 곳이다.', 'It is a fortress from the Silla Dynasty surrounding Myeonghwalsan Mountain that played a major role as a capital defense facility along with Namsanshinseong Fortress, Seohyeongsanseong Fortress, and Bukhyeongsanseong Fortress around Gyeongju.'),
    (128, 'intro', '경주 명활성은 명활산을 둘러싸고 있는 신라시대 산성으로 경주 주변의 남산신성, 서형산성, 북형산성과 함게 수도 방어시설로 큰 몫을 한 곳이다. 성의 둘레는 약 6㎞로 토성과 함께 석성이 함께 있는데, 석성은 다듬지 않은 자연석을 사용한 신라 초기의 축성 방식을 보이고 있다.', 'Gyeongju Myeonghwalsanseong is a fortress from the Silla Dynasty surrounding Myeonghwalsan Mountain. It played a major role as a capital defense facility along with Namsanseongseong, Seohyeongsanseong, and Bukhyeongsanseong fortress around Gyeongju. The circumference of the castle is about 6km, and there is a stone castle along with an earthen castle, which shows the construction method of the early Silla Dynasty using uncut natural stones.'),
    (128, 'story', '『삼국사기』에 의하면 실성왕 4년(405)에 왜병이 명활성을 공격해 왔으나 격퇴시켰다는 기록이 있는 것으로 보아 그 이전에 만들어졌음을 알 수 있다.
또한, 눌지왕 15년(431)에는 왜구가 이 성을 포위하고 공격하였는데, 이는 이 성이 신라의 수도인 금성을 지키는데 중요한 곳임을 말해준다.
자비왕 18년(475)부터 소지왕 10년(488)까지는 이곳을 궁성으로 사용하였다.', 'According to 『History of the Three Kingdoms』, there is a record that a Japanese army attacked Myeonghaeng in the 4th year of King Silseong''s reign (405), but they were repelled, so it can be seen that it was built before that.
Additionally, in the 15th year of King Nulji''s reign (431), Japanese pirates surrounded and attacked this castle, which shows that this castle was important in protecting Geumseong, the capital of Silla.
This place was used as a palace from the 18th year of King Jabi (475) to the 10th year of King Soji (488).'),
    (128, 'tip', '경주 명활성을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Myeonghwal, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (128, 'did_you_know', '『삼국사기』에 의하면 실성왕 4년(405)에 왜병이 명활성을 공격해 왔으나 격퇴시켰다는 기록이 있는 것으로 보아 그 이전에 만들어졌음을 알 수 있어요.', 'According to 『History of the Three Kingdoms』, there is a record that in the 4th year of King Silseong''s reign (405), a Japanese army attacked Myeonghyeong but were repelled, which suggests that it was built before that.'),
    (129, 'summary', '토함산 이웃에 자리한 조항산 정상에는 경주 풍력발전단지가 위치해 있다.', 'The Gyeongju Wind Power Complex is located at the top of Johangsan Mountain, located next to Tohamsan Mountain.'),
    (129, 'intro', '토함산 이웃에 자리한 조항산 정상에는 경주 풍력발전단지가 위치해 있다. 이 상업용 풍력발전단지는 친환경 청정에너지 생산을 목적으로 하며, 현재 총 7기의 풍력발전기가 가동 중이다.', 'The Gyeongju Wind Power Complex is located at the top of Johangsan Mountain, located next to Tohamsan Mountain. This commercial wind power farm aims to produce eco-friendly clean energy, and a total of 7 wind power generators are currently in operation.'),
    (129, 'story', '연간 1만여 가구가 사용할 수 있는 전력을 생산하고 있다.
산 능선을 따라 늘어선 거대한 풍력발전기들이 인상적인 이곳은 바람의 언덕이라 불리며, 사계절 내내 일반에 개방되어 있다.
발전소 전경이 한눈에 펼쳐지는 전망대 경풍루를 비롯해 바람길 산책로, 피크닉 테이블 존 등 방문객을 위한 공간도 마련되어 있다.', 'It produces electricity that can be used by over 10,000 households annually.
This impressive place, with its huge wind turbines lined up along the mountain ridge, is called Windy Hill and is open to the public all year round.
There are also spaces for visitors, including the observatory Gyeongpungru, which offers a panoramic view of the power plant, a wind path trail, and a picnic table zone.'),
    (129, 'tip', '경주 풍력발전(바람의언덕)은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at the Gyeongju Wind Power Plant (Windy Hill) just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (129, 'did_you_know', '특히 해 질 무렵 노을이 아름답기로 유명하며, 일몰 후 밤하늘에 수 놓인 별빛까지 감상할 수 있어 많은 이들이 찾는 경주의 새로운 힐링 명소로 주목받고 있어요.', 'It is especially famous for its beautiful sunset, and you can even enjoy the starlight in the night sky after sunset, attracting attention as a new healing spot in Gyeongju that many people visit.'),
    (130, 'summary', '문무왕이 삼국통일을 완성하고 병기와 투구를 묻었다고 전하는 산이 있다.', 'There is a mountain where it is said that King Munmu completed the unification of the three kingdoms and buried his weapons and helmet.'),
    (130, 'intro', '문무왕이 삼국통일을 완성하고 병기와 투구를 묻었다고 전하는 산이 있다. 함월산과 토함산을 이웃으로 두고 있는 동대봉산, 무장봉이라 부르는 산이다.', 'There is a mountain where it is said that King Munmu completed the unification of the three kingdoms and buried his weapons and helmet. It is a mountain called Dongdaebongsan Mountain and Mujangbong Mountain, with Hamwolsan Mountain and Tohamsan Mountain as its neighbors.'),
    (130, 'story', '보문관광단지에서 자동차로 15분가량 가면 무장산 등반로 초입인 암곡마을에 닿는다.
미나리가 유명한 농촌 마을인 이곳은 가을철이면 등산객들로 인산인해를 이룬다.
무장산 정상부의 넓은 초원에 조성된 억새군락을 보기 위한 인파다.', 'If you drive about 15 minutes from Bomun Tourist Complex, you will reach Amgok Village, the beginning of the Mujangsan Mountain climbing trail.
This farming village is famous for water parsley, and is crowded with hikers in the fall season.
Crowds come to see the silver grass colony created in the wide grassland at the top of Mujangsan Mountain.'),
    (130, 'tip', '무장산은 산길이나 오르막 구간을 지나야 할 수 있어요. 미끄러지지 않는 신발과 물을 준비하고, 해가 지기 전에 돌아올 수 있도록 소요 시간을 넉넉히 잡으세요.', 'To reach Mujangsan Mountain, you may have to pass through a mountain path or uphill section. Bring non-slip shoes and water, and allow plenty of time to return before sunset.'),
    (130, 'did_you_know', '보문관광단지에서 자동차로 15분가량 가면 무장산 등반로 초입인 암곡마을에 닿는다고 해요.', 'It is said that if you drive for about 15 minutes from Bomun Tourist Complex, you will reach Amgok Village, the beginning of the Mujangsan Mountain climbing trail.'),
    (131, 'summary', '경상북도 경주시 배동에 자리 잡고 있다.', 'It is located in Bae-dong, Gyeongju-si, Gyeongsangbuk-do.'),
    (131, 'intro', '삼불사는 경상북도 경주시 배동에 자리 잡고 있다. 사찰에는 대웅전, 산신각, 보물 경주 배동 석조 여래 삼존입상이 있다.', 'Sambulsa Temple is located in Bae-dong, Gyeongju-si, Gyeongsangbuk-do. The temple includes Daeungjeon, Sansingak, and the Baedong Stone Buddha Triad of Treasure Gyeongju.'),
    (131, 'story', '경주 배동 석조 여래 삼존입상은 삼국시대에 만든 것으로 추정되며, 경주 남산 기슭에 흩어져 있던 석상과 석재들을 1923년 삼불사가 있는 자리에 모아 세웠다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 삼불사은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The Baedong Stone Standing Buddha Triad in Baedong, Gyeongju is believed to have been made during the Three Kingdoms Period, and was erected in 1923 at the site of Sambulsa Temple from stone statues and stones scattered at the foot of Namsan Mountain in Gyeongju.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Sambulsa remains a different memory for each person who visits Gyeongju.'),
    (131, 'tip', '삼불사에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Sambulsa Temple, rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and temples, as well as the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (131, 'did_you_know', '경주 배동 석조 여래 삼존입상은 삼국시대에 만든 것으로 추정되며, 경주 남산 기슭에 흩어져 있던 석상과 석재들을 1923년 삼불사가 있는 자리에 모아 세웠다고 해요.', 'The Baedong Stone Standing Buddha Triad in Bae-dong, Gyeongju is believed to have been made during the Three Kingdoms Period, and is said to have been erected in 1923 by gathering stone statues and stones scattered at the foot of Namsan Mountain in Gyeongju at the site of Sambulsa Temple.'),
    (132, 'summary', '황성공원 예술의 전당 뒤편에 위치한 경주 빛누리정원은 경주 야경 명소로 인기 있는 곳이다.', 'Gyeongju Bitnuri Garden, located behind the Arts Center in Hwangseong Park, is a popular Gyeongju night view spot.'),
    (132, 'intro', '황성공원 예술의 전당 뒤편에 위치한 경주 빛누리정원은 경주 야경 명소로 인기 있는 곳이다. 낮에는 아름다운 자연 속에서 산책을 즐기며 밤에는 산책로를 따라서 설치된 음향 시설에서 대중가요, 국악, 가곡, 클래식 등 다양한 음악이 흘러나와 음악을 들으며 야경을 감상할 수 있다.', 'Gyeongju Bitnuri Garden, located behind the Arts Center in Hwangseong Park, is a popular Gyeongju night view spot. During the day, you can enjoy a walk in beautiful nature, and at night, you can enjoy the night view while listening to various music, including popular songs, Korean traditional music, songs, and classical music, from the sound system installed along the trail.'),
    (132, 'story', '빛누리정원 뒤편에는 신라시대 건축 방법을 고증해 재현한 상우정 누각과 연못이 있다.
또한 곳곳에 의자가 배치되어 있어 마음에 드는 풍경을 보면서 쉬어가기 좋은 곳이다.
오늘의 빛누리정원은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Behind Bitnuri Garden, there is Sangwoojeong pavilion and pond, which are recreated through historical research of the construction methods of the Silla Dynasty.
Additionally, there are chairs placed here and there, making it a great place to take a break while looking at the scenery you like.
Today’s Bitnuri Garden remains a different memory for each person who visits Gyeongju.'),
    (132, 'tip', '빛누리정원은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Bitnuri Garden just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (132, 'did_you_know', '또한 곳곳에 의자가 배치되어 있어 마음에 드는 풍경을 보면서 쉬어가기 좋은 곳이에요.', 'Additionally, there are chairs placed here and there, making it a great place to take a break while looking at the scenery you like.'),
    (133, 'summary', '자전거의 스릴과 재미를 즐길 수 있는 국내 최대 규모의 공원형 자전거 관광 명소로서, 어린이도 즐길 수 있는 초급 코스에서부터 전문가를 위한 고급 코스까지 다양한 펌프트랙 코스를 갖춘 시설이다.', 'It is Korea''s largest park-type bicycle tourist attraction where you can enjoy the thrill and fun of cycling. It is a facility with a variety of pump track courses, from beginner courses that even children can enjoy to advanced courses for experts.'),
    (133, 'intro', '경주시 자전거공원은 자전거의 스릴과 재미를 즐길 수 있는 국내 최대 규모의 공원형 자전거 관광 명소로서, 어린이도 즐길 수 있는 초급 코스에서부터 전문가를 위한 고급 코스까지 다양한 펌프트랙 코스를 갖춘 시설이다. 안전 서약서를 작성하고 안전장비를 착용한 8세 이상 자전거 탑승자가 이용가능하며, 우천 시 이외에는 연중무휴 무료로 이용 가능하다.', 'Gyeongju City Bicycle Park is Korea''s largest park-type bicycle tourist attraction where you can enjoy the thrill and fun of bicycles. It is a facility with a variety of pump track courses, from beginner courses that even children can enjoy to advanced courses for experts. Bicycle riders over 8 years old who fill out a safety pledge and wear safety equipment can use it, and it is available free of charge 24 hours a day, 365 days a year except in rainy weather.'),
    (133, 'story', '또한 현장에서 자전거와 안전장비도 무료로 대여해 준다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 경주시 자전거공원은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Bicycles and safety equipment are also available for free on site.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Gyeongju City bicycle park leaves a different memory for each person who visits Gyeongju.'),
    (133, 'tip', '경주시 자전거공원은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk through Gyeongju City Bicycle Park in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (133, 'did_you_know', '또한 현장에서 자전거와 안전장비도 무료로 대여해 준다고 해요.', 'They also provide free rental of bicycles and safety equipment on site.'),
    (134, 'summary', '지도에 잘 나오지 않는 경주의 숨은 바다', 'The hidden sea of Gyeongju that does not appear on maps'),
    (134, 'intro', '지도에 잘 나오지 않는 경주의 숨은 바다 명소 지경리 해변은 주상절리 전망대에서 약 10분 동안 자동차로 이동하면 도착할 수 있다.', 'Jigyeong-ri Beach, a hidden sea attraction in Gyeongju that is not often shown on maps, can be reached by driving about 10 minutes from the Columnar Joint Observatory.'),
    (134, 'story', '지경 방파제에서 약 400m 정도 해안을 따라 걸어가면 기암괴석 군단을 만날 수 있고 둥근 자갈로 이루어진 지경리 해변과 푸르고 투명한 바다가 펼쳐진다.
조금 더 안쪽으로 들어가면 바다뷰의 멋진 풍경을 가진 해식동굴도 있어 동굴 안에서 바다를 배경으로 멋진 사진을 남겨볼 수 있다.
방문 시 지도에서 지경마을회관 또는 지경방파제를 검색해 찾아가는 걸 추천한다.', 'If you walk along the coast for about 400m from the Jigyeong breakwater, you can see a group of strangely shaped rocks, and the Jigyeong-ri beach, made of round pebbles, and the blue and transparent sea unfold.
If you go a little further inside, there is a sea cave with a wonderful view of the sea, so you can take great photos inside the cave with the sea in the background.
When visiting, we recommend searching for Jigyeong Village Hall or Jigyeong Breakwater on the map.'),
    (134, 'tip', '지경리해변(경주)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Jigyeong-ri Beach (Gyeongju), check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (134, 'did_you_know', '명소 지경리 해변은 주상절리 전망대에서 약 10분 동안 자동차로 이동하면 도착할 수 있어요.', 'The famous Jigyeong-ri Beach can be reached by driving about 10 minutes from the Columnar Joint Observatory.'),
    (135, 'summary', '경주보문단지 힐튼경주 부지 내에 위치한 우양미술관은 1991년 5월 18일에 개관하였다.', 'Wooyang Art Museum, located on the site of Hilton Gyeongju in Gyeongju Bomun Complex, opened on May 18, 1991.'),
    (135, 'intro', '경주보문단지 힐튼경주 부지 내에 위치한 우양미술관은 1991년 5월 18일에 개관하였다. 국내 최초 사립 현대미술관으로 1,800여 평 부지에 지하 1층, 지상 2층 건물로 전시실과 수장고, 교육공간, 야외조각공원, 기타 편의시설 등으로 구성되어 있다.', 'Wooyang Art Museum, located on the site of Hilton Gyeongju in Gyeongju Bomun Complex, opened on May 18, 1991. It is Korea''s first private modern art museum and is located on a site of approximately 1,800 pyeong, with one underground floor and two above-ground floors. It consists of an exhibition hall, a storage room, an educational space, an outdoor sculpture park, and other convenient facilities.'),
    (135, 'story', '우양미술관은 동시대 미술의 흐름을 제시하는 국내외 주요 작가들의 전시를 기획하며, 해외 작가(교류)전, 우양작가시리즈, 신소장품전 등 매년 두 세 차례 다채로운 전시를 선보이고 있다.
또한 현대미술의 중요한 역할을 해 온 국내외 작가인 박서보, 이우환, 김창열, 백남준, 이브 클랭, 길버트와 조지, 프랭크 스텔라, 안젤름 키퍼, 막달레나 아바카노비츠 등 회화와 조각, 설치, 영상, 사진 등 현대미술의 다양한 가능성을 보여주는 작품들을 폭넓게 소장해 왔다.
앞으로도 경주의 자랑스러운 문화유산과 눈부신 자연 속에 휴식과 현대미술이 하나의 풍경을 이루는 아름다운 하모니를 계속해서 만들어나갈 것이다.', 'Wooyang Art Museum plans exhibitions of major domestic and foreign artists that present trends in contemporary art, and presents a variety of exhibitions two to three times a year, including overseas artist (exchange) exhibitions, Wooyang Artist Series, and new collection exhibitions.
In addition, it has a wide collection of works that demonstrate the various possibilities of modern art, including paintings, sculptures, installations, videos, and photographs, including paintings, sculptures, installations, videos, and photographs, including domestic and foreign artists who have played an important role in modern art, such as Park Seo-bo, Lee U-hwan, Kim Tschang-yeol, Nam June Paik, Yves Klein, Gilbert and George, Frank Stella, Anselm Kiefer, and Magdalena Abakanowicz.
In the future, we will continue to create a beautiful harmony where relaxation and modern art form one landscape amid Gyeongju''s proud cultural heritage and dazzling nature.'),
    (135, 'tip', '우양미술관에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At the Wooyang Art Museum, choose the exhibition you are interested in and plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (135, 'did_you_know', '경주보문단지 힐튼경주 부지 내에 위치한 우양미술관은 1991년 5월 18일에 개관했어요.', 'Wooyang Art Museum, located on the site of Hilton Gyeongju in Gyeongju Bomun Complex, opened on May 18, 1991.'),
    (136, 'summary', '토함산 자연휴양림은 불국사와 석굴암을 품고 있는 토함산의 동쪽 기슭에 위치해 있으며 경주시 시설관리공단에서 운영하는 휴양시설이다.', 'Tohamsan Natural Recreation Forest is located at the eastern foot of Tohamsan Mountain, which contains Bulguksa Temple and Seokguram Grotto, and is a recreational facility operated by the Gyeongju City Facilities Management Corporation.'),
    (136, 'intro', '토함산 자연휴양림은 불국사와 석굴암을 품고 있는 토함산의 동쪽 기슭에 위치해 있으며 경주시 시설관리공단에서 운영하는 휴양시설이다. 산림에 숲 속의 집, 화랑관, 야영장, 체육시설(풋살장, 족구장, 농구장)을 비롯한 숲길(등산로), 산림욕장 등이 조성되어 있다.', 'Tohamsan Natural Recreation Forest is located at the eastern foot of Tohamsan Mountain, which contains Bulguksa Temple and Seokguram Grotto, and is a recreational facility operated by the Gyeongju City Facilities Management Corporation. In the forest, a house in the forest, an art gallery, a campsite, sports facilities (futsal court, foot volleyball court, basketball court), forest paths (hiking trails), and a forest bathing area have been created.'),
    (136, 'story', '다양한 침엽수와 활엽수가 자생하고 있으며 다람쥐, 딱따구리 등 각종 야생동물과 식물들이 생태계를 이루고 있어 자연체험 학습장과 휴양지로 즐겨 찾을 수 있으며 동쪽으로는 감포 해수욕장, 양남 주상절리, 양북 문무대왕릉, 서쪽으로는 불국사, 석굴암, 보문단지를 연결하는 중심에 위치하고 있어 역사문화체험과 휴양을 동시에 즐길 수 있는 숙박시설로 더욱 각광받고 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 토함산자연휴양림은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'A variety of conifers and broad-leaved trees grow naturally, and various wild animals and plants, such as squirrels and woodpeckers, form an ecosystem, making it a popular place for nature experience learning and recreation. It is located in the center connecting Gampo Beach, Yangnam columnar joints, and King Munmu''s Tomb in Yangbuk to the east, and Bulguksa Temple, Seokguram Grotto, and Bomun Complex to the west, making it more popular as an accommodation facility where you can enjoy historical and cultural experiences and recreation at the same time.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Tohamsan Natural Recreation Forest leaves a different memory for each person who visits Gyeongju.'),
    (136, 'tip', '토함산자연휴양림은 산길이나 오르막 구간을 지나야 할 수 있어요. 미끄러지지 않는 신발과 물을 준비하고, 해가 지기 전에 돌아올 수 있도록 소요 시간을 넉넉히 잡으세요.', 'Tohamsan Natural Recreation Forest may require passing through mountain paths or uphill sections. Bring non-slip shoes and water, and allow plenty of time to return before sunset.'),
    (136, 'did_you_know', '산림에 숲 속의 집, 화랑관, 야영장, 체육시설(풋살장, 족구장, 농구장)을 비롯한 숲길(등산로), 산림욕장 등이 조성되어 있어요.', 'The forest has a house in the forest, a gallery, a campsite, sports facilities (futsal court, foot volleyball court, basketball court), a forest path (hiking trail), and a forest bathing area.'),
    (137, 'summary', '경주 보문 단지는 경주 시가지에서 동쪽으로 약 10여㎞ 정도 떨어진 명활산 옛 성터에 보문호를 중심으로 조성되었다.', 'Gyeongju Bomun Complex was built around Bomun Lake on the site of an old castle on Myeonghwalsan Mountain, about 10km east of downtown Gyeongju.'),
    (137, 'intro', '경주 보문 단지는 경주 시가지에서 동쪽으로 약 10여㎞ 정도 떨어진 명활산 옛 성터에 보문호를 중심으로 조성되었다. 보문관광단지는 전 지역이 온천지구 및 관광특구로 지정되어 있고 도로, 전기, 통신, 상하수도 등 기반 시설이 완비되어 있으며 컨벤션시티로의 육성, 보문관광단지와 연계한 감포 관광단지의 개발을 추진하고 있는 등 국제적 수준의 종합관광 휴양 단지로 자리를 잡아가고 있다.', 'Gyeongju Bomun Complex was built around Bomun Lake on the site of an old castle on Myeonghwalsan Mountain, about 10km east of downtown Gyeongju. The entire area of ​​Bomun Tourist Complex has been designated as a hot spring district and special tourist zone, and is fully equipped with infrastructure such as roads, electricity, communications, water and sewerage, etc., and is establishing itself as an international level comprehensive tourism and resort complex by promoting it as a convention city and promoting the development of Gampo Tourist Complex in connection with Bomun Tourist Complex.'),
    (137, 'story', '총 8,000,036㎡(242만 평)의 대지에 국제적 규모의 최고급 호텔, 가족단위의 콘도미니엄, 골프장, 각종 수상시설, 산책로, 보문호와 고사분수 등 수많은 위락시설을 갖춘 경주의 사랑방이라고 일컫는 종합관광 휴양지이다.
경주지역에는 특히 벚나무가 많다.
어느 특정 지역에만 많은 것이 아니라 도시 전체가 벚꽃 천지인 것이 다른 지역과 다르다.', 'It is a comprehensive tourist resort called the Sarangbang of Gyeongju, with numerous entertainment facilities such as an international top-class hotel, family condominiums, a golf course, various water facilities, walking trails, Bomun Lake, and Gosa Fountain on a total of 8,000,036㎡ (2.42 million pyeong) of land.
There are especially many cherry trees in the Gyeongju area.
It is different from other areas in that the entire city is full of cherry blossoms, not just in one specific area.'),
    (137, 'tip', '경주 보문관광단지은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Bomun Tourist Complex in Gyeongju in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (137, 'did_you_know', '경주 보문 단지는 경주 시가지에서 동쪽으로 약 10여㎞ 정도 떨어진 명활산 옛 성터에 보문호를 중심으로 조성되었다고 해요.', 'Gyeongju Bomun Complex is said to have been built around Bomun Lake on the site of an old castle on Myeonghwalsan Mountain, about 10km east of downtown Gyeongju.'),
    (138, 'summary', '황리단길은 경주에서 가장 젊은 길로 황남동과 이태원의 경리단길을 합쳐진 단어로 ‘황남동의 경리단길’이라는 뜻을 가지고 있다.', 'Hwangridan-gil is the youngest road in Gyeongju and is a combination of Hwangnam-dong and Itaewon’s Gyeongnidan-gil, meaning ‘Hwangnam-dong’s Gyeongnidan-gil.’'),
    (138, 'intro', '황리단길은 경주에서 가장 젊은 길로 황남동과 이태원의 경리단길을 합쳐진 단어로 ‘황남동의 경리단길’이라는 뜻을 가지고 있다. 내남사거리에서 시작해 황남초등학교 사거리까지의 도로를 기준으로 양쪽의 황남동, 사정동 일대의 지역을 일컫는다.', 'Hwangridan-gil is the youngest road in Gyeongju and is a combination of Hwangnam-dong and Itaewon’s Gyeongnidan-gil, meaning ‘Hwangnam-dong’s Gyeongnidan-gil.’ It refers to the area around Hwangnam-dong and Sajeong-dong on both sides of the road starting from Naenam Intersection to Hwangnam Elementary School Intersection.'),
    (138, 'story', '1960~70년대의 낡은 건물 등이 그대로 보존되어 있어 옛 정취를 고스란히 느낄 수 있는 거리이다.
몇 해 전부터 젊은이들이 모여들기 시작해 분위기 좋은 카페, 아기자기한 소품, 기념품 가게, 개성 있는 식당들이 들어섰다.
초기에는 도로변을 중심으로 상점들이 들어섰는데 황리단길 외연이 확장되면서 골목골목마다', 'It is a street where you can fully feel the old atmosphere as old buildings from the 1960s and 1970s have been preserved as is.
A few years ago, young people began to gather here, and cafes with a nice atmosphere, cute props, souvenir shops, and unique restaurants opened.
In the beginning, shops were built mainly along the roadside, but as the outer edge of Hwangridan-gil expanded, every alley was filled with shops.'),
    (138, 'tip', '경주 황리단길에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'On Hwangridan-gil, Gyeongju, walk around the burial mounds and compare their sizes and spacing rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (138, 'did_you_know', '1960~70년대의 낡은 건물 등이 그대로 보존되어 있어 옛 정취를 고스란히 느낄 수 있는 거리이에요.', 'It is a street where you can fully feel the atmosphere of the past as old buildings from the 1960s and 1970s have been preserved as is.'),
    (139, 'summary', '조선 중기의 무신 정무공 최진립(1568∼1636)이 살았던 곳으로 가옥의 사랑채에 해당한다.', 'This is the place where Choi Jin-rip (1568-1636), a military official in the mid-Joseon Dynasty, lived, and is equivalent to the sarangchae of the house.'),
    (139, 'intro', '조선 중기의 무신 정무공 최진립(1568∼1636)이 살았던 곳으로 가옥의 사랑채에 해당한다. 최진립 장군은 임진왜란이 발발하자 의병을 이끌었고, 정유재란 때 권율 장군을 도와 공을 세웠다.', 'This is the place where Choi Jin-rip (1568-1636), a military official in the mid-Joseon Dynasty, lived, and is equivalent to the sarangchae of the house. General Choi Jin-rip led the volunteer army when the Japanese Invasion of Korea broke out, and made a contribution by helping General Kwon Yul during the Jeong Yu Jaeran.'),
    (139, 'story', '충의당은 처음에는 당호를 흠흠당이라 했는데 1760년경 건물을 수리한 후 충의당으로 이름을 바꿨다.
건물은 앞면 4칸, 옆면 2칸으로 홑처마 팔작지붕을 하고 있으며 뒤편에는 정침과 고방채가 있고 오른쪽에 제향공간이 있어 조선시대 상류주택의 전형적인 배치방법을 지니고 있다.
그가 지냈던 충의당은 경주 최부자집의 시작이라 볼 수 있으며, 현재 일부는 고택체험이 가능한 한옥스테이 객실과 다실로 운영된다.', 'At first, Chunguidang was called Heumheumdang, but after the building was repaired around 1760, the name was changed to Chunguidang.
The building has 4 rooms on the front and 2 rooms on the sides, and has a hip-and-gable roof with single-layer eaves. There is the main living quarters and a storage wing at the back, and an ancestral rite space on the right, which is a typical arrangement of upper-class houses during the Joseon Dynasty.
Chunguidang, where he stayed, can be seen as the beginning of the Choi family estate in Gyeongju, and some of it is currently operated as a hanok stay room and tea room where you can experience old houses.'),
    (139, 'tip', '충의당을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Chunguidang, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (139, 'did_you_know', '조선 중기의 무신 정무공 최진립(1568∼1636)이 살았던 곳으로 가옥의 사랑채에 해당해요.', 'This is the place where Choi Jin-rip (1568-1636), a military official during the mid-Joseon Dynasty, lived, and it is the sarangchae of the house.'),
    (140, 'summary', '서남산의 최고봉인 고위산(高位山) 정상 부근에 자리한 천룡사는 신라시대 때 천녀(天女)와 용녀(龍女)라는 두 딸을 가진 부모가 딸들을 위해 창건하였다고 전한다.', 'It is said that Cheonryongsa Temple, located near the summit of Gowisan Mountain, the highest peak of Seonamsan Mountain, was founded by parents with two daughters, Cheonnyeo and Yongnyeo, during the Silla Dynasty for their daughters.'),
    (140, 'intro', '서남산의 최고봉인 고위산(高位山) 정상 부근에 자리한 천룡사는 신라시대 때 천녀(天女)와 용녀(龍女)라는 두 딸을 가진 부모가 딸들을 위해 창건하였다고 전한다. 천룡사는 지리적으로 큰 역할을 하는 사찰이었다.', 'It is said that Cheonryongsa Temple, located near the summit of Gowisan Mountain, the highest peak of Seonamsan Mountain, was founded by parents with two daughters, Cheonnyeo and Yongnyeo, during the Silla Dynasty for their daughters. Cheonryongsa Temple was a temple that played a major geographical role.'),
    (140, 'story', '그것은 이 절이 계림(鷄林) 땅을 흐르는 한 줄기의 객수(客水)와 한 줄기의 역수(逆水)의 근원지에 있으면서 객수와 역수의 조화를 유지시키는 위치에 있고 그 일을 수행한다는 것이다.
이러한 지리를 아는 당(唐)의 사자(使者) 악붕귀(樂鵬龜)는 “이 절을 파괴하면 나라가 망한다.”라고 했다.
신라 말기에 와서 어느 사이엔가 절이 폐사가가 되고 과연 나라도 망하고 말았다.', 'That is, this temple is located at the source of a stream of guest water and a stream of reverse water flowing through the land of Gyerim, and is in a position to maintain harmony between the guest water and the reverse water and performs the work.
Akbungwi, a messenger of the Tang Dynasty who knew this geography, said, “If this temple is destroyed, the country will fall.”
At the end of the Silla Dynasty, the temple fell into disrepair and the country collapsed.'),
    (140, 'tip', '천룡사(경주)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Cheonnyongsa Temple (Gyeongju), check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (140, 'did_you_know', '천룡사에서 열렸던 석가 만일도량에 관해서는 고려 때 최승로가 지은 글이 남아 있는데, 10,000일이면 거의 30년에 해당하는 셈인데, 이렇게 오랜 기간 동안 끊임없이 법회가 열렸던 것이에요.', 'There is a text written by Choi Seung-ro during the Goryeo Dynasty regarding the Sakyamun Doryang held at Cheonryongsa Temple, which states that 10,000 days is equivalent to almost 30 years, and Buddhist services were held continuously for such a long period of time.'),
    (141, 'summary', '과거 양산재로 불렸던 육부전은 신라 건국 이전 서라벌에 있었던 6부 촌장의 위패를 봉안하고 제사를 지내는 사당이다.', 'Yukjeon, previously called Yangsanjae, is a shrine where memorial tablets of the six village chiefs of Seorabeol, which existed in Seorabeol before the founding of Silla, are enshrined and ancestral rites are held.'),
    (141, 'intro', '과거 양산재로 불렸던 육부전은 신라 건국 이전 서라벌에 있었던 6부 촌장의 위패를 봉안하고 제사를 지내는 사당이다. 기원전 57년 알천양산촌, 돌산고허촌, 취산진지촌, 무산대수촌, 금산가리촌, 명활산고야촌의 6부 촌장들이 알천 언덕에 모여 알에서 탄생한 박혁거세를 신라의 첫 임금으로 추대하였다.', 'Yukjeon, previously called Yangsanjae, is a shrine where memorial tablets of the six village chiefs of Seorabeol, which existed in Seorabeol before the founding of Silla, are enshrined and ancestral rites are held. In 57 BC, the six village chiefs of Alcheon Yangsan Village, Dolsan Gohe Village, Chwisan Jinji Village, Musan Dae Village, Geumsan Gari Village, and Myeonghwal Mountain Goya Village gathered on Alcheon Hill and elected Park Hyeokgeose, who was born from an egg, as the first king of Silla.'),
    (141, 'story', '이후 신라 3대 왕인 유리왕이 이들의 건국 공로를 기리기 위해 양산촌은 이 씨, 고허촌은 최 씨, 진지촌은 정씨, 대수촌은 손 씨, 가리촌은 배 씨, 고야촌은 설 씨로 각각의 성을 내려 이들이 각 성씨의 시조가 되었다고 전한다.
육부전은 외삼문인 대덕문을 지나 동편에 윤적당, 서편에 익익재가 배치되어 있고 이어 내삼문인 홍익문이 자리한다.
홍익문 안에는 주건물인 입덕묘가 세워져 있는데, 이 공간은 제례가 있는 날을 제외하고는 일반에 개방하지 않는다.', 'Afterwards, in order to commemorate their contribution to founding the nation, King Yuri, the third king of Silla, gave them individual surnames: Yangsanchon to the Lee clan, Goheochon to the Choi clan, Jinjichon to the Jeong clan, Daesuchon to the Son clan, Garichon to the Bae clan, and Goyachon to the Seol clan. It is said that these people became the progenitors of each clan.
Yukjeon passes through Daedeokmun, the outer three gates, and is located on the east side with Yunjeokdang and Ikikjae on the west, followed by the inner three gates, Hongikmun.
Inside Hongikmun, the main building, Ipdeokmyo, is built, but this space is not open to the public except on days when ancestral rites are held.'),
    (141, 'tip', '육부전을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Yukjeon, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (141, 'did_you_know', '기원전 57년 알천양산촌, 돌산고허촌, 취산진지촌, 무산대수촌, 금산가리촌, 명활산고야촌의 6부 촌장들이 알천 언덕에 모여 알에서 탄생한 박혁거세를 신라의 첫 임금으로 추대했어요.', 'In 57 BC, six village chiefs from Alcheon Yangsan Village, Dolsan Gohe Village, Chwisan Jinji Village, Musan Dae Village, Geumsan Gari Village, and Myeonghwal Mountain Goya Village gathered on Alcheon Hill and elected Park Hyeokgeose, who was born from an egg, as the first king of Silla.'),
    (142, 'summary', '한국골프의 대중화를 선도하는 국내 최고의 대중골프장이다.', 'It is the best public golf course in Korea, leading the popularization of Korean golf.'),
    (142, 'intro', '경주컨트리클럽은 한국골프의 대중화를 선도하는 국내 최고의 대중골프장이다. 천년고도의 경주 보문관광단지에 위치하며 보문 호반을 중심으로 구성되어 자연경관이 수려하고 보문호수 및 보문관광단지 전경을 한눈에 볼 수 있다.', 'Gyeongju Country Club is the best public golf course in Korea, leading the popularization of Korean golf. It is located in the thousand-year-old Bomun Tourist Complex in Gyeongju, and is centered around Bomun Lake, with beautiful natural scenery and a panoramic view of Bomun Lake and Bomun Tourist Complex.'),
    (142, 'story', '밤에 즐기는 환상적인 Light 경기는 경주컨트리클럽의 자랑으로, 전홀 라이트시설을 완비하여 새벽 및 야간에도 골프를 부담없이 즐길 수 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 경주컨트리클럽은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The fantastic light play at night is the pride of Gyeongju Country Club, and all holes are equipped with lighting facilities, so you can enjoy golf even in the early morning or at night.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Gyeongju Country Club leaves a different memory for each person who visits Gyeongju.'),
    (142, 'tip', '경주컨트리클럽은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Gyeongju Country Club just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (142, 'did_you_know', '밤에 즐기는 환상적인 Light 경기는 경주컨트리클럽의 자랑으로, 전홀 라이트시설을 완비하여 새벽 및 야간에도 골프를 부담없이 즐길 수 있어요.', 'The fantastic light play at night is the pride of Gyeongju Country Club, and all holes are equipped with lighting facilities, so you can enjoy golf without any worries even in the early morning or at night.'),
    (143, 'summary', '조선 중종 때의 문신 손중돈을 향사하고 높은 학덕을 기리기 위해 1695년(숙종 21) 건립했다.', 'It was built in 1695 (the 21st year of King Sukjong’s reign) to commemorate Son Jung-don, a civil servant during the reign of King Jungjong of the Joseon Dynasty, and to commemorate his high academic virtue.'),
    (143, 'intro', '조선 중종 때의 문신 손중돈을 향사하고 높은 학덕을 기리기 위해 1695년(숙종 21) 건립했다. 포항시와 경주시에 걸쳐 있는 형제산 중 제산 자락에 자리 잡았다.', 'It was built in 1695 (the 21st year of King Sukjong’s reign) to commemorate Son Jung-don, a civil servant during the reign of King Jungjong of the Joseon Dynasty, and to commemorate his high academic virtue. It is located at the foot of Jesan Mountain, one of the Hyeongje Mountains spanning Pohang and Gyeongju.'),
    (143, 'story', '묘우를 중심으로 강당, 동재, 서재, 신도비각, 관리사 등의 건물이 있으며 1996년 1월 20일 경상북도 기념물로 지정됐다.
손중돈의 자는 대발[大發], 시호는 경절[景節]이다.
이시애의 난을 평정한 손소의 아들로, 김종직의 문하에서 수학하였다.', 'Centered around the grave, there are buildings such as an auditorium, an east hall, a study hall, a memorial hall, and a management temple. It was designated as a Gyeongsangbuk-do monument on January 20, 1996.
Son Jung-don''s pen name was Daebal [大發] and his posthumous name was Gyeongjeol [景節].
He was the son of Son So, who suppressed Lee Si-ae''s rebellion, and studied under Kim Jong-jik.'),
    (143, 'tip', '동강서원을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Donggangseowon, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (143, 'did_you_know', '조선 중종 때의 문신 손중돈을 향사하고 높은 학덕을 기리기 위해 1695년(숙종 21) 건립했다고 해요.', 'It is said to have been built in 1695 (the 21st year of King Sukjong’s reign) to commemorate Son Jung-don, a civil servant during the reign of King Jungjong of the Joseon Dynasty, and to commemorate his high academic virtue.'),
    (144, 'summary', '조선 중기의 무신 정무공 최진립을 제사 지내기 위한 곳으로 숙종 25년(1699)에 경주부윤 이형상이 지방 선비들과 함께 세웠다.', 'It was built by Gyeongju Buyun Lee Hyeong-sang along with local scholars in the 25th year of King Sukjong''s reign (1699) to commemorate Choi Jin-rip, a military official from the mid-Joseon Dynasty.'),
    (144, 'intro', '조선 중기의 무신 정무공 최진립을 제사 지내기 위한 곳으로 숙종 25년(1699)에 경주부윤 이형상이 지방 선비들과 함께 세웠다. 숙종 37년(1711)에 임금으로부터 [숭렬사우]라는 편액을 내려받았으며 후에 서원으로 승격됐다.', 'It was built by Gyeongju Buyun Lee Hyeong-sang along with local scholars in the 25th year of King Sukjong''s reign (1699) to commemorate Choi Jin-rip, a military official from the mid-Joseon Dynasty. In the 37th year of King Sukjong''s reign (1711), he received the title [Sungryeolsau] from the king and was later promoted to a seowon.'),
    (144, 'story', '고종 7년(1870) 서원철폐령으로 철거됐다가 1924년 다시 건립됐다.
용산서원에서 서남쪽으로 조금 떨어진 곳에는 신도비각이 있다.
최진립은 지금의 경주시 현곡면에서 태어났다.', 'It was demolished in the 7th year of King Gojong''s reign (1870) due to the abolition of Confucian academies, and rebuilt in 1924.
There is a secret shrine located a little southwest of Yongsan Seowon.
Choi Jin-rip was born in what is now Hyeongok-myeon, Gyeongju-si.'),
    (144, 'tip', '용산서원(경주)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Yongsan Seowon (Gyeongju), check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (144, 'did_you_know', '조선 중기의 무신 정무공 최진립을 제사 지내기 위한 곳으로 숙종 25년(1699)에 경주부윤 이형상이 지방 선비들과 함께 세웠다고 해요.', 'It is said to have been built by Gyeongju Buyun Lee Hyeong-sang along with local scholars in the 25th year of King Sukjong''s reign (1699) as a place to commemorate Choi Jin-rip, a military official from the mid-Joseon Dynasty.'),
    (145, 'summary', '1986년 신라시대의 공예기술을 보존하고 개발하기 위해 토함산 기슭에 조성한 마을로 전통 민예품을 재현하고 민속공예를 계승·발전하기 위해 흩어져 있던 경주 지역 장인들을 한 곳에 모은 촌락 형태의 민속품협업단지이다.', 'This village was created at the foot of Tohamsan Mountain in 1986 to preserve and develop the craftsmanship of the Silla Dynasty. It is a village-type folk crafts cooperative complex that brings together artisans from the Gyeongju region who were scattered around Gyeongju in one place to reproduce traditional folk crafts and inherit and develop folk crafts.'),
    (145, 'intro', '경주민속공예촌은 1986년 신라시대의 공예기술을 보존하고 개발하기 위해 토함산 기슭에 조성한 마을로 전통 민예품을 재현하고 민속공예를 계승·발전하기 위해 흩어져 있던 경주 지역 장인들을 한 곳에 모은 촌락 형태의 민속품협업단지이다. 옛 모습을 지닌 전통 골기와집과 초가 45동으로 이루어진 이곳은 전통가구와 토우를 비롯하여 신라금관, 불상, 칠보 등의 금속공예품, 청자, 백자, 토기 등 도자기공예품 및 목가구, 목불상 등 목공예품과 죽세공예품, 보석공예품 등을 옛날 그대로 재현하고 있다.', 'Gyeongju Folk Craft Village is a village created at the foot of Tohamsan Mountain in 1986 to preserve and develop craft techniques from the Silla Dynasty. It is a village-type folk crafts cooperative complex that brings together artisans from the Gyeongju region who were scattered in the Gyeongju region to reproduce traditional folk crafts and inherit and develop folk crafts. This place, which consists of 45 old-style traditional tile-roofed houses and thatched houses, reproduces traditional furniture and clay, metal crafts such as Silla gold crowns, Buddha statues, and cloisonné, ceramic crafts such as celadon, white porcelain, and earthenware, and wood crafts such as wooden furniture and wooden Buddha statues, bamboo crafts, and jewelry crafts, as they were in the past.'),
    (145, 'story', '재래식 생산과정과 장인들의 솜씨를 관광객이 직접 관람할 수 있도록 개방하고 생산품을 전시·판매하는 현대식 종합전시장도 있다.
공예촌에는 신라역사과학관이 있어 석굴암 석굴의 신비를 밝히는 석굴 모형도와 해부도 및 경주 첨성대를 통하여 관측한 천문도, 서라벌의 옛 모습을 재현하는 왕경도(王京圖)를 제작·전시하고 석굴암 석굴 모형도를 제작하여 석굴의 과학성을 설명하였다.
보문단지와 불국사를 연계하는 관광코스로 한옥과 어우러진 마을의 풍경이 아름다워 관광객들이 즐겨 찾는 곳이다.', 'There is also a modern comprehensive exhibition hall that is open to tourists so that they can directly observe the traditional production process and the skills of craftsmen, and displays and sells the products.
There is a Silla History and Science Museum in the Craft Village, which produces and displays model maps and anatomical maps that reveal the mysteries of Seokguram Grottoes, an astronomical map observed through Cheomseongdae in Gyeongju, and a royal view map that reproduces the old appearance of Seorabeol. A model map of Seokguram Grottoes was also produced to explain the scientific nature of the caves.
This is a tourist course that connects Bomun Complex and Bulguksa Temple, and is a popular destination for tourists due to the beautiful scenery of the village combined with Hanok.'),
    (145, 'tip', '경주민속공예촌에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Gyeongju Folk Craft Village, rather than just quickly looking at the buildings, take a look at the arrangement of the towers and pavilions and the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (145, 'did_you_know', '경주민속공예촌은 1986년 신라시대의 공예기술을 보존하고 개발하기 위해 토함산 기슭에 조성한 마을로 전통 민예품을 재현하고 민속공예를 계승·발전하기 위해 흩어져 있던 경주 지역 장인들을 한 곳에 모은 촌락 형태의 민속품협업단지이에요.', 'Gyeongju Folk Craft Village is a village created at the foot of Tohamsan Mountain in 1986 to preserve and develop craft techniques from the Silla Dynasty. It is a village-type folk crafts cooperative complex that brings together artisans from the Gyeongju area who were scattered around Gyeongju in one place to reproduce traditional folk crafts and inherit and develop folk crafts.'),
    (146, 'summary', '불교정신을 바탕으로 학술과 인격을 연마하는 동국대학교에서 운영하는 박물관이다.', 'It is a museum operated by Dongguk University that cultivates academics and character based on the spirit of Buddhism.'),
    (146, 'intro', '동국대학교 와이즈 캠퍼스 박물관은 불교정신을 바탕으로 학술과 인격을 연마하는 동국대학교에서 운영하는 박물관이다. 경상북도 경주시 석장동에 자리하고 있는 박물관으로 불교 유물의 수집·정리·전시와 더불어 유적의 발굴조사와 연구를 목적으로 1983년 개관하였다.', 'Dongguk University Wise Campus Museum is a museum operated by Dongguk University that cultivates academics and character based on the spirit of Buddhism. This museum is located in Seokjang-dong, Gyeongju-si, Gyeongsangbuk-do, and was opened in 1983 for the purpose of collecting, organizing, and exhibiting Buddhist relics, as well as excavating and researching relics.'),
    (146, 'story', '개관 당시에는 도서관 건물의 3층과 4층을 사용하였고 동국대학교 박물관 경주 분관으로 출발하였다.
이후 1985년 4월에 전시실을 도서관 2층으로 확장·이전하고 1994년 사무실 및 부속시설을 전시실 옆으로 확장하여 현재에 이르고 있다.
박물관은 전시실, 수장고, 연구실, 사무실로 구성되어 있다.', 'At the time of opening, it used the 3rd and 4th floors of the library building and started as the Gyeongju branch of Dongguk University Museum.
Afterwards, in April 1985, the exhibition room was expanded and relocated to the second floor of the library, and in 1994, the office and auxiliary facilities were expanded next to the exhibition room, which is where it is today.
The museum consists of an exhibition room, storage, laboratory, and office.'),
    (146, 'tip', '동국대학교 와이즈 캠퍼스 박물관에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At the Dongguk University Wise Campus Museum, choose the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (146, 'did_you_know', '경상북도 경주시 석장동에 자리하고 있는 박물관으로 불교 유물의 수집·정리·전시와 더불어 유적의 발굴조사와 연구를 목적으로 1983년 개관했어요.', 'This museum is located in Seokjang-dong, Gyeongju-si, Gyeongsangbuk-do, and was opened in 1983 for the purpose of collecting, organizing, and exhibiting Buddhist relics, as well as excavating and researching ruins.'),
    (147, 'summary', '넓은 백사장의 잔잔한 모래와 동해의 청정해역 바다를 자랑하는 나정고운모래해변은 여유 있는 주변 공간과 인근의 갖은 편의시설이 있고 동해의 바닷물을 이용하여 온천을 즐길 수 있는 해수탕이 있어 새로운 체험을 할 수 있다.', 'Najeong Fine Sand Beach, which boasts the calm sand of a wide white sand beach and the clean waters of the East Sea, has ample surrounding space, various convenient facilities nearby, and a seawater bath where you can enjoy hot springs using the seawater of the East Sea, allowing you to experience a new experience.'),
    (147, 'intro', '넓은 백사장의 잔잔한 모래와 동해의 청정해역 바다를 자랑하는 나정고운모래해변은 여유 있는 주변 공간과 인근의 갖은 편의시설이 있고 동해의 바닷물을 이용하여 온천을 즐길 수 있는 해수탕이 있어 새로운 체험을 할 수 있다. 해수탕 옆은 주차 공간과 송림이 개방되어 있으며, 모터보트, 바나나보트 등 수상 레저를 즐길 수 있어 가족과 친구와 함께 여름 피서지로 방문하기에도 좋다.', 'Najeong Fine Sand Beach, which boasts the calm sand of a wide white sand beach and the clean waters of the East Sea, has ample surrounding space, various convenient facilities nearby, and a seawater bath where you can enjoy hot springs using the seawater of the East Sea, allowing you to experience a new experience. There is an open parking space and pine grove next to the sea bath, and you can enjoy water leisure activities such as motor boats and banana boats, making it a great place to visit in the summer with family and friends.'),
    (147, 'story', '해변을 따라 산책로도 잘 조성되어 있어 바다를 보며 걷기에도 좋다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 나정고운모래해변은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'There is a well-maintained walking path along the beach, so it is great for walking while looking at the sea.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Najeong Fine Sand Beach remains a different memory for each person visiting Gyeongju.'),
    (147, 'tip', '나정고운모래해변에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Najeong Fine Sand Beach, the perceived environment changes greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (147, 'did_you_know', '해변을 따라 산책로도 잘 조성되어 있어 바다를 보며 걷기에도 좋다고 해요.', 'There is a well-maintained walking path along the beach, so it is said to be great for walking while looking at the sea.'),
    (148, 'summary', '칠불암 내에 있는 바위 면에 새겨진 7구의 불상들을 지칭한다.', 'It refers to the seven Buddha statues carved into the rock face within Chilbulam Hermitage.'),
    (148, 'intro', '경주 남산 칠불암 마애불상군은 칠불암 내에 있는 바위 면에 새겨진 7구의 불상들을 지칭한다. 동쪽을 향한 넓은 바위 면에 삼존상이 있고, 삼존상 바로 앞의 네모난 돌기둥에는 면마다', 'The group of rock-carved Buddha statues at Chilbulam in Namsan, Gyeongju refers to the seven Buddha statues carved on the rock face within Chilbulam. There is a triad on the wide rock face facing east, and on each side of the square stone pillar right in front of the triad.'),
    (148, 'story', '불좌상이 새겨져 있다.
본존과 두 보살로 된 삼존상, 돌기둥의 네 면에 새겨진 사방불을 합쳐 모두 7구의 불상들이 새겨져 있으므로 암자의 이름을 칠불암이라 부른다.
이곳에 원래 있던 사찰 이름은 밝혀지지 않았다.', 'A seated Buddha statue is engraved on it.
The hermitage is called Chilbulam because there are a total of seven Buddha statues engraved on it, including the main Buddha, the triad of two Bodhisattvas, and the four directions of Buddha carved on the four sides of the stone pillar.
The name of the temple that originally existed here has not been revealed.'),
    (148, 'tip', '경주 남산 칠불암 마애불상군을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Namsan Chilbulam Rock-carved Buddha Statues in Gyeongju, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (148, 'did_you_know', '이 주변에서 「약사경」과 「금강경」을 새긴 석경의 파편들이 발견되어 복과 장수, 건강과 행운을 기원하는 민간의 약사 신앙과 관련된 사찰로 보인다고 해요.', 'Fragments of a stone sutra engraved with the “Yaksha Sutra” and “Diamond Sutra” were discovered around here, and it appears to be a temple related to the folk belief in the Yaksha, which prays for good fortune, longevity, health, and good luck.'),
    (149, 'summary', '세계적인 문화유산인 경주 보문단지의 대표적인 숙박시설이다.', 'It is a representative lodging facility in the Bomun Complex in Gyeongju, a world-class cultural heritage site.'),
    (149, 'intro', '한화리조트 경주는 세계적인 문화유산인 경주 보문단지의 대표적인 숙박시설이다. 객실은 에톤과 담톤으로 구성되어 있으며, 수영장, 온천사우나, 연회장, 세미나실 등 다양한 부대시설을 갖추고 있다.', 'Hanwha Resort Gyeongju is a representative accommodation facility in Gyeongju Bomun Complex, a world-class cultural heritage. The rooms are composed of Eton and Damton, and are equipped with various auxiliary facilities such as a swimming pool, hot spring sauna, banquet hall, and seminar room.'),
    (149, 'story', '객실은 깨끗함과 안락함을 자랑하며, 현대적인 감각에 발맞춰 모던하고 심플하게 꾸며져 있다.
넉넉한 여유를 느낄 수 있는 객실에는 다양한 최신 설비를 갖추고 있으며, 고객을 한 번 더 생각하는 서비스를 통해 편안하게 머무를 수 있도록 모든 편의를 제공하고 있다.
오늘의 한화리조트 경주은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The guest rooms boast cleanliness and comfort, and are decorated in a modern and simple manner in keeping with modern sensibilities.
The spacious rooms are equipped with a variety of state-of-the-art facilities, and provide all the conveniences to ensure a comfortable stay through customer-oriented services.
Today''s Hanwha Resort Gyeongju leaves a different memory for each person who visits Gyeongju.'),
    (149, 'tip', '한화리조트 경주을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Hanwha Resort Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (149, 'did_you_know', '넉넉한 여유를 느낄 수 있는 객실에는 다양한 최신 설비를 갖추고 있으며, 고객을 한 번 더 생각하는 서비스를 통해 편안하게 머무를 수 있도록 모든 편의를 제공하고 있어요.', 'The spacious rooms are equipped with a variety of state-of-the-art facilities, and we provide every convenience to ensure a comfortable stay through customer-oriented services.'),
    (150, 'summary', '동해바다와 동대산 500m 대자연 속에 위치하고 있는 골프장이다.', 'This golf course is located in the great outdoors, 500m above the East Sea and Dongdaesan Mountain.'),
    (150, 'intro', '동해바다와 동대산 500m 대자연 속에 위치하고 있는 골프장이다. 코스 설계의 필드 컨설턴트 김명길 소장, 조항 설계 및 시공을 담당한 Nickels Golf Group의 Douglas Nickels, 조경설계의 서안 조경 정영선 조장, 서울대 유병림교수, 클럽하우스설계의 두우건축 조용식 소장 그리고 코오롱그룹이 시공하였다.', 'This golf course is located in the great outdoors, 500m above the East Sea and Dongdaesan Mountain. Field consultant Director Myeong-gil Kim of course design, Douglas Nickels of Nickels Golf Group in charge of provision design and construction, Seoan Landscape Manager Young-seon Jeong of landscape design, Professor Byeong-rim Yoo of Seoul National University, Director Cho Yong-sik of Douwoo Architecture and Kolon Group of clubhouse design.'),
    (150, 'story', '미국 LPGA투어 경기인 ‘코오롱-하나은행 챔피언십’와 2023년 새롭게 출범한 위믹스 챔피언십을 2025년, 마우나오션에서 성공적으로 개최하였다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 마우나오션 컨트리클럽은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The US LPGA Tour event ‘Kolon-Hana Bank Championship’ and the newly launched Wemix Championship in 2023 were successfully held at Mauna Ocean in 2025.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Mauna Ocean Country Club leaves a different memory for each person who visits Gyeongju.'),
    (150, 'tip', '마우나오션 컨트리클럽에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Mauna Ocean Country Club, the experienced environment changes greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (150, 'did_you_know', '동해바다와 동대산 500m 대자연 속에 위치하고 있는 골프장이에요.', 'It is a golf course located in the great outdoors, 500m above the East Sea and Dongdaesan Mountain.'),
    (151, 'summary', '경주 옥산 세심마을은 회재 이언적 선생이 성리학 연구에 전념하던 곳으로, 훌륭한 문화유산과 아름다운 자연경관, 그리고 넉넉한 인심을 자랑하는 마을이다.', 'Sesim Village in Oksan, Gyeongju is the place where Professor Lee Eon-jeok devoted himself to the study of Neo-Confucianism, and is a village that boasts excellent cultural heritage, beautiful natural scenery, and generous people.'),
    (151, 'intro', '경주 옥산 세심마을은 회재 이언적 선생이 성리학 연구에 전념하던 곳으로, 훌륭한 문화유산과 아름다운 자연경관, 그리고 넉넉한 인심을 자랑하는 마을이다. 유네스코 세계문화유산으로 지정된 옥산서원과 KBS가 선정한 독락당, 정혜사지 13층 석탑 등이 있으며, 국가 지정 보물만 200여 점을 보유하고 가장 한국적인 마을이다.', 'Sesim Village in Oksan, Gyeongju is the place where Professor Lee Eon-jeok devoted himself to the study of Neo-Confucianism, and is a village that boasts excellent cultural heritage, beautiful natural scenery, and generous people. It is home to Oksan Seowon, designated as a UNESCO World Heritage Site, Dokrakdang, selected by KBS, and the 13-story stone pagoda of Jeonghyesa Temple, and is the most Korean-style village with over 200 nationally designated treasures.'),
    (151, 'story', '마을의 주변 경관은 한 폭의 잔잔한 동양화를 연상시킬 만큼 아름답다.
옥산 세심마을이 가진 테마로는 팜스테이 마을, 전통 테마 마을, 농촌 휴양 마을, 팜스쿨 마을, 식교육 전문 농장, 루랄-20까지 6개의 테마로 이루어져 있다.
체험 프로그램으로는 전통놀이 체험(활쏘기, 제기 만들어 차기, 고리 던지기), 식 체험(칼국수 만들어 먹기, 떡메치기, 전 부쳐 먹기, 두부 만들기), 문화 체험(과거 보기, 김장하기), 생태체험(손수건 풀잎 염색하기), 수확 체험(감자, 고구마)이 있다.', 'The surrounding scenery of the village is so beautiful that it is reminiscent of a calm oriental painting.
Oksan Sesim Village has six themes: Farm Stay Village, Traditional Theme Village, Rural Recreation Village, Farm School Village, Food Education Farm, and Rural-20.
Experience programs include traditional play experiences (archery, making kicks, ring throwing), food experiences (making and eating kalguksu, mixing rice cakes, pancakes, making tofu), cultural experiences (seeing the past, making kimchi), ecological experiences (dying handkerchief blades), and harvesting experiences (potatoes, sweet potatoes).'),
    (151, 'tip', '옥산 세심마을을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Oksan Sesimmaeul, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (151, 'did_you_know', '유네스코 세계문화유산으로 지정된 옥산서원과 KBS가 선정한 독락당, 정혜사지 13층 석탑 등이 있으며, 국가 지정 보물만 200여 점을 보유하고 가장 한국적인 마을이에요.', 'It is home to Oksan Seowon, designated as a UNESCO World Heritage Site, Dokrakdang, selected by KBS, and the 13-story stone pagoda of Jeonghyesa Temple, and is the most Korean-style village with over 200 nationally designated treasures.'),
    (152, 'summary', '경주시 양남면 나산리 큰 마을에 있는 나산서원은 조선 전기의 문신 백촌 김문기를 배향하는 곳으로 일명 나산사라고도 한다.', 'Nasanseowon, located in the large village of Nasan-ri, Yangnam-myeon, Gyeongju-si, is a place where Baekchon Kim Mun-gi, a civil servant from the early Joseon Dynasty, is buried and is also called Nasansa Temple.'),
    (152, 'intro', '경주시 양남면 나산리 큰 마을에 있는 나산서원은 조선 전기의 문신 백촌 김문기를 배향하는 곳으로 일명 나산사라고도 한다. 김문기 선생과 나산리 입향조 김제학 선생의 후손들이 매년 향례를 올리는 이 서원은 경주 최남단에 위치하며 해안 지역에서는 유일하게 설립된 서원이다.', 'Nasanseowon, located in the large village of Nasan-ri, Yangnam-myeon, Gyeongju-si, is a place where Baekchon Kim Mun-gi, a civil servant from the early Joseon Dynasty, is buried and is also called Nasansa Temple. This seowon, where the descendants of Kim Mun-gi and Nasan-ri''s successor Kim Je-hak hold a memorial service every year, is located in the southernmost part of Gyeongju and is the only one established in the coastal area.'),
    (152, 'story', '나산리 입구 마을회관에서 서원까지 걷다
보면 안동 장씨 양반마을의 정취를 느낄 수 있다.
나산서원은 대지 800평에 묘우 1동 3칸, 강당 1동 4칸, 동재 1동 3칸, 서재 1동 3칸, 전사청 1동 3칸, 외삼문 1동, 내삼문 2동, 관리사 등을 갖춘 전형적인 조선시대 서원 건축양식을 따르고 있다.', 'Walk from the village hall at the entrance to Nasan-ri to Seowon
If you look at it, you can feel the atmosphere of the Andong Jang noble village.
Nasanseowon follows the typical Joseon Dynasty Seowon architectural style, with 1 building and 3 rooms of land, 4 rooms of lecture hall, 3 rooms of Dongjae building, 3 rooms of study building, 3 rooms of Jeonsammun building, 1 building of Oesammun, 2 buildings of Naesammun, and Gwanisa Temple on 800 pyeong of land.'),
    (152, 'tip', '나산서원에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Nasanseowon, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (152, 'did_you_know', '나산서원은 대지 800평에 묘우 1동 3칸, 강당 1동 4칸, 동재 1동 3칸, 서재 1동 3칸, 전사청 1동 3칸, 외삼문 1동, 내삼문 2동, 관리사 등을 갖춘 전형적인 조선시대 서원 건축양식을 따르고 있어요.', 'Nasan Seowon follows the typical Joseon Dynasty Seowon architectural style with 1 building and 3 spaces of land, 4 rooms of lecture hall, 3 rooms of Dongjae building, 3 rooms of study building, 3 rooms of Jeonsammun building, 1 building of Oesammun, 2 buildings of Naesammun, and Gwanisa Temple on 800 pyeong of land.'),
    (153, 'summary', '1786년(정조 10)에 지방 유림의 공의로 서유(徐愈)의 학문과 덕행을 추모하기 위해 귀산서사(龜山書社)를 창건하여 위패를 모셨다.', 'In 1786 (the 10th year of King Jeongjo''s reign), as a public act of local Confucianism, Guisan Seosa (龜山書社) was founded to commemorate the learning and virtue of Seo Yu (徐愈), and a memorial tablet was placed there.'),
    (153, 'intro', '1786년(정조 10)에 지방 유림의 공의로 서유(徐愈)의 학문과 덕행을 추모하기 위해 귀산서사(龜山書社)를 창건하여 위패를 모셨다. 1839년(헌종 5)에 ‘구산’이라고 사액 되어 사액서원으로 승격되었으며, 1848년에 서일원(徐一元)을 추가로 배향하였다.', 'In 1786 (the 10th year of King Jeongjo''s reign), as a public act of local Confucianism, Guisan Seosa (龜山書社) was founded to commemorate the learning and virtue of Seo Yu (徐愈), and a memorial tablet was placed there. In 1839 (the 5th year of King Heonjong’s reign), it was named ‘Gusan’ and promoted to Saekseowon, and in 1848, Seoilwon (徐一元) was additionally enshrined.'),
    (153, 'story', '선현 배향과 지방 교육의 일익을 담당하여 오던 중, 흥선대원군의 서원철폐령으로 1868년(고종 5)에 훼철되었다.
그 뒤 1983년 지방 유림에 의해 복원되어 현재에 이르고 있다.
매년 2월 상정(上丁)과 8월 상정에 향사를 지내고 있다.', 'While it played a part in the ancestral rites and local education, it was abolished in 1868 (the 5th year of King Gojong''s reign) due to Heungseon Daewongun''s order to abolish Confucian academies.
Afterwards, it was restored by a local Confucian forest in 1983 and remains as it is today.
A memorial service is held every year on Sangjeong in February and Sangjeong in August.'),
    (153, 'tip', '귀산서원을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Guisan Seowon, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (153, 'did_you_know', '1786년(정조 10)에 지방 유림의 공의로 서유(徐愈)의 학문과 덕행을 추모하기 위해 귀산서사(龜山書社)를 창건하여 위패를 모셨다고 해요.', 'It is said that in 1786 (the 10th year of King Jeongjo''s reign), Guisan Seosa (龜山書社) was founded to commemorate the learning and virtue of Seo Yu (徐愈), as a public act of local Confucianism, and a memorial tablet was placed there.'),
    (154, 'summary', '경주월드 내에 있는 스노우파크는 겨울 시즌에만 운영되는 눈썰매장이다.', 'The Snow Park within Gyeongju World is a sledding hill that operates only during the winter season.'),
    (154, 'intro', '경주월드 내에 있는 스노우파크는 겨울 시즌에만 운영되는 눈썰매장이다. 1994년 말에 처음 개장한 뒤 매년 시설을 확장하여 전용 리프트와 썰매 리프트까지 갖추었다.', 'The Snow Park within Gyeongju World is a sledding hill that operates only during the winter season. After first opening in late 1994, the facility was expanded every year to include a dedicated lift and sled lift.'),
    (154, 'story', '익스트림 라인 바나헤임은 남부권 최대 길이인 250m의 압도적인 규모를 자랑한다.
성인 썰매장인 어드벤처 라인 요툰헤임은 튜브 썰매와 플라스틱 썰매를 마음껏 즐길 수 있는 곳이며, 어린이 썰매장인 드림 라인 알프헤임은 아이들이 안전하게 눈썰매를 탈 수 있는 곳이다.
또한, 새하얀 눈으로 뒤덮인 눈마을 플리트비체에서 눈싸움도 즐기며 시간을 보낼 수 있다.', 'Extreme Line Vanaheim boasts an overwhelming scale of 250m, the longest in the southern region.
Adventure Line Jotunheim, a sledding range for adults, is a place where you can enjoy tube and plastic sleds to your heart''s content, and Dream Line Alfheim, a children''s sledding range, is a place where children can safely snow sled.
You can also spend time having a snowball fight in the snow village of Plitvice covered in pure white snow.'),
    (154, 'tip', '경주월드 스노우파크에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Gyeongju World Snow Park. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (154, 'did_you_know', '1994년 말에 처음 개장한 뒤 매년 시설을 확장하여 전용 리프트와 썰매 리프트까지 갖추었다고 해요.', 'Since it first opened in late 1994, the facility has been expanded every year to include a dedicated lift and sled lift.'),
    (155, 'summary', '경주월드에 있는 이국적인 풍경을 가진 물놀이 시설로 여름 시즌에만 운영한다.', 'This water amusement facility with exotic scenery is located in Gyeongju World and operates only during the summer season.'),
    (155, 'intro', '경주월드에 있는 이국적인 풍경을 가진 물놀이 시설로 여름 시즌에만 운영한다. 320m의 유수풀과 파도풀, 초대형 튜브슬라이드, 정글짐, 미끄럼틀, 스플래시어드벤쳐, 수심 35cm의 어린이 물놀이장, 바닥분수 등 다양한 물놀이 어트랙션을 보유하고 있다.', 'This water amusement facility with exotic scenery is located in Gyeongju World and operates only during the summer season. It has a variety of water play attractions, including a 320m lazy river and wave pool, a large tube slide, jungle gym, slide, splash adventure, a children''s water park with a water depth of 35cm, and a floor fountain.'),
    (155, 'story', '또한 물놀이 도중 휴식을 취할 수 있는 천연 온천스파와 지압 마사지를 함께 즐길 수 있는 팜스프링도 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 경주월드 캘리포니아비치은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'There is also a natural hot spring spa where you can relax while playing in the water, and a palm spring where you can enjoy an acupressure massage.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Gyeongju World California Beach leaves a different memory for each person who visits Gyeongju.'),
    (155, 'tip', '경주월드 캘리포니아비치에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Gyeongju World California Beach, the experienced environment changes greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (155, 'did_you_know', '320m의 유수풀과 파도풀, 초대형 튜브슬라이드, 정글짐, 미끄럼틀, 스플래시어드벤쳐, 수심 35cm의 어린이 물놀이장, 바닥분수 등 다양한 물놀이 어트랙션을 보유하고 있어요.', 'It has a variety of water play attractions, including a 320m lazy river and wave pool, a large tube slide, jungle gym, slide, splash adventure, a children''s water park with a water depth of 35cm, and a floor fountain.'),
    (156, 'summary', '작은 암자에 석조약사여래입상과 창건 설화가 함께 전해지는 곳이에요.', 'It is a small hermitage where a stone standing Buddha statue and a founding story are told.'),
    (156, 'intro', '연지암은 경주 괘릉 안쪽의 조용한 마을 언덕에 자리한 작은 암자예요. 일제강점기 말 김연지화 보살이 창건했다고 전해지며, 대웅전에 모신 석조약사여래입상이 이곳의 중심을 이룹니다.', 'Yeonjiam Hermitage is a small hermitage located on a hill in a quiet village inside Gwareung Royal Tomb in Gyeongju. It is said to have been founded by Bodhisattva Kim Yeon-jihwa at the end of the Japanese colonial period, and the stone standing Yaksha Nyorai statue enshrined in the main hall forms the center of this place.'),
    (156, 'story', '규모는 크지 않지만 대웅전과 요사채가 단정하게 놓여 있어 소박한 수행 공간의 분위기가 또렷해요. 석불을 찾아 봉안했다는 이야기도 전해져, 지역 주민의 기도와 돌봄 속에서 이어져 온 암자의 시간을 보여 줍니다.', 'Although it is not large in size, the main hall and Yosachae are neatly placed, creating a clear atmosphere of a simple training space. There is also a story that a stone Buddha was found and enshrined, showing the hermitage''s time spent under the prayers and care of local residents.'),
    (156, 'tip', '주민 생활 공간과 가까운 작은 암자이므로 조용히 방문하고 법회 시간을 피하는 것이 좋아요. 경내 촬영 전에는 안내를 확인하고, 괘릉과 함께 둘러보면 이동 동선을 효율적으로 짤 수 있습니다.', 'Since it is a small hermitage close to the residents'' living space, it is best to visit quietly and avoid Buddhist service times. Check the guidance before taking pictures of the temple grounds, and if you tour along with Gwaereung, you can plan your travel route efficiently.'),
    (156, 'did_you_know', '연지암의 이름은 창건자로 전해지는 김연지화 보살의 이름과 연결해 이야기돼요.', 'The name of Yeonjiam is said to be connected to the name of Bodhisattva Kim Yeonjihwa, who is said to be the founder.'),
    (157, 'summary', '경주시 배동의 거대한 자연 바위벽에 새긴 앉아 있는 모습의 석가여래불로 높이는 6m이다.', 'It is a seated Shakyamuni Buddha carved into a huge natural rock wall in Baedong, Gyeongju, and is 6m tall.'),
    (157, 'intro', '경주시 배동의 거대한 자연 바위벽에 새긴 앉아 있는 모습의 석가여래불로 높이는 6m이다. 남산의 좌불 중에서 가장 큰 것으로, 통일신라시대 후기에 유행하던 양식의 마애불로 추정된다.', 'It is a seated Shakyamuni Buddha carved into a huge natural rock wall in Baedong, Gyeongju, and is 6m tall. It is the largest of the sitting Buddhas in Namsan, and is presumed to be a rock-carved Buddha in the style popular in the late Unified Silla period.'),
    (157, 'story', '바위 자체가 약간 뒤로 기울어져 있어 조각된 불상이 먼 하늘을 올려다보는 것처럼 보인다.
몸을 약간 뒤로 젖히고 있으며, 반쯤 뜬 눈은 속세의 중생을 굽어살펴 보는 것 같다.
머리에서 어깨까지는 입체감 있게 깊게 새겨서 돋보이게 했으나 몸체는 아주 얕게 새겼다.', 'The rock itself is slightly tilted backwards, making the carved Buddha statue appear to be looking up into the distant sky.
The body is slightly tilted back, and the half-open eyes seem to be looking down at the living beings of this world.
From the head to the shoulders, it was carved deeply and three-dimensionally to make it stand out, but the body was carved very shallowly.'),
    (157, 'tip', '삼릉계곡마애석가여래좌상을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Samneung Valley Rock-carved Seated Shakyamuni Buddha, please check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (157, 'did_you_know', '이곳에 있는 다른 불상들의 세련되고 단정한 얼굴과는 달리, 이 불상은 약간 투박한 느낌을 준다고 해요.', 'Unlike the refined and neat faces of the other Buddha statues here, this Buddha statue has a slightly rugged feel.'),
    (158, 'summary', '경주향교 인근 인왕동 고분군에 있는 내물왕릉은 신라 제17대 내물왕(재위 356~402)의 무덤으로 401년에 조성되었다.', 'The Royal Tomb of King Naemul, located in the ancient tombs in Inwang-dong near Gyeongju Hyanggyo, was created in 401 as the tomb of King Naemul, the 17th king of Silla (reigned 356-402).'),
    (158, 'intro', '경주향교 인근 인왕동 고분군에 있는 내물왕릉은 신라 제17대 내물왕(재위 356~402)의 무덤으로 401년에 조성되었다. 밑지름 22m, 높이 5.3m의 봉토분으로 밑면 주변에는 자연석의 한 모서리가 노출되어 있는데, 이는 무열왕릉처럼 그 안에 별도의 호석이 설치된 것으로 추측된다.', 'The Royal Tomb of King Naemul, located in the ancient tombs in Inwang-dong near Gyeongju Hyanggyo, was created in 401 as the tomb of King Naemul, the 17th king of Silla (reigned 356-402). It is an earthen mound with a base diameter of 22m and a height of 5.3m. A corner of the natural stone is exposed around the base. It is presumed that a separate stone was installed inside it, like in the tomb of King Muyeol.'),
    (158, 'story', '에는 내물왕의 장지에 관한 기록이 없으나, 에 첨성대 남서쪽에 있다고 기록되었으며 현 위치와 일치한다.
1969년 8월 27일 사적으로 지정되었다.
내물왕은 김 씨 왕으로는 두 번째로 왕위에 올랐으며 이후 김씨 성에 의한 독점적 왕위 계승을 이루었다.', 'There is no record of the burial site of King Naemul, but it is recorded as being southwest of Cheomseongdae and matches the current location.
It was designated as a historic site on August 27, 1969.
King Naemul was the second king of the Kim clan to ascend to the throne, and thereafter achieved exclusive succession to the throne by the Kim clan surname.'),
    (158, 'tip', '경주 내물왕릉에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At King Naemul''s Tomb in Gyeongju, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (158, 'did_you_know', '경주향교 인근 인왕동 고분군에 있는 내물왕릉은 신라 제17대 내물왕(재위 356~402)의 무덤으로 401년에 조성되었다고 해요.', 'The Royal Tomb of King Naemul, located in the ancient tombs in Inwang-dong near Gyeongju Hyanggyo, is said to have been created in 401 as the tomb of King Naemul, the 17th king of Silla (reigned 356-402).'),
    (159, 'summary', '경주시 강동면 청수골에 있는 운곡서원은 안동권씨 시조인 고려 공신 태사 권행과 조선시대 참판 권산해, 군수 권덕린을 추모하기 위하여 건립한 조선시대 서원이다.', 'Ungok Seowon, located in Cheongsu-gol, Gangdong-myeon, Gyeongju-si, is a Joseon Dynasty Seowon built to commemorate the founder of the Andong Kwon clan, Goryeo meritorious Taesa Kwon Haeng, the Joseon Dynasty champion Kwon Sanhae, and the county governor Kwon Deok-rin.'),
    (159, 'intro', '경주시 강동면 청수골에 있는 운곡서원은 안동권씨 시조인 고려 공신 태사 권행과 조선시대 참판 권산해, 군수 권덕린을 추모하기 위하여 건립한 조선시대 서원이다. 서원은 훌륭한 유학자의 위패를 모시고 제사를 지내며 지방민의 교육과 교화를 위해 설립된 고려, 조선시대의 사립 지방 교육기관을 말한다.', 'Ungok Seowon, located in Cheongsu-gol, Gangdong-myeon, Gyeongju-si, is a Joseon Dynasty Seowon built to commemorate the founder of the Andong Kwon clan, Goryeo meritorious Taesa Kwon Haeng, the Joseon Dynasty champion Kwon Sanhae, and the county governor Kwon Deok-rin. Seowon refers to a private local educational institution during the Goryeo and Joseon Dynasties that was established to honor the memorial tablets of great Confucian scholars, hold ancestral rites, and educate and enlighten local residents.'),
    (159, 'story', '1868년 서원철폐령으로 훼철되었다가 이후에 휴허지에 단을 설치하고 재사와 전사청을 지어 제향하고, 1976년 신라 밀곡사 터로 추정되는 이곳에 복원하였다.
묘우인 경덕사와 강당인 정의당, 동재와 서재 및 외삼문으로 이루어져 있으며, 매년 음력 3월 초정일에 향사를 지낸다.
운곡서원에서 약 50m 떨어진 동쪽 계곡의 용추대 위에는 정자 유연정이 있다.', 'It was demolished in 1868 due to the abolition of Confucian academies, but later an altar was installed on the abandoned site, a Jaesa and Jeonsacheong were built to hold a ancestral rite, and in 1976, it was restored at this presumed site of Milgoksa Temple of the Silla Dynasty.
It consists of Gyeongdeoksa Temple, a tomb, Jeongeuidang, an auditorium, Dongjae, Study, and Oesammun, and a memorial service is held every year on the first day of the third month of the lunar calendar.
There is a pavilion, Yuyeonjeong, on Yongchudae in the eastern valley, about 50 meters away from Ungok Seowon.'),
    (159, 'tip', '운곡서원을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Ungokseowon Confucian Academy, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (159, 'did_you_know', '경주시 강동면 청수골에 있는 운곡서원은 안동권씨 시조인 고려 공신 태사 권행과 조선시대 참판 권산해, 군수 권덕린을 추모하기 위하여 건립한 조선시대 서원이에요.', 'Ungok Seowon, located in Cheongsu-gol, Gangdong-myeon, Gyeongju-si, is a Joseon Dynasty Seowon built to commemorate the founder of the Andong Kwon clan, Goryeo meritorious Taesa Kwon Haeng, Joseon Dynasty champion Kwon Sanhae, and county governor Kwon Deok-rin.'),
    (160, 'summary', '신라 제52대 효공왕(재위 897∼912)의 무덤으로 높이 5m, 지름 21.2m이며 둥글게 흙을 쌓아 올린 원형 봉토 무덤이다.', 'This is the tomb of King Hyogong, the 52nd king of Silla (r. 897-912), and is a circular earthen mound tomb with a height of 5 m and a diameter of 21.2 m.'),
    (160, 'intro', '신라 제52대 효공왕(재위 897∼912)의 무덤으로 높이 5m, 지름 21.2m이며 둥글게 흙을 쌓아 올린 원형 봉토 무덤이다. 무덤 밑부분에는 무덤을 보호하기 위해 쌓았던 돌이 몇 개 남아 있으며, 이는 무열왕릉과 같은 성격인 둘레돌의 일부로 추측된다.', 'This is the tomb of King Hyogong, the 52nd king of Silla (r. 897-912), and is a circular earthen mound tomb with a height of 5 m and a diameter of 21.2 m. At the bottom of the tomb, there remain a few stones that were piled up to protect the tomb, which are presumed to be part of the surrounding stone that is similar to the tomb of King Muyeol.'),
    (160, 'story', '그밖에는 아무런 표식물이 없는 매우 단순한 형태의 무덤이다.
에 의하면 912년 왕이 죽자 이름을 효공이라 하고 사자사라는 절 북쪽에 장사 지냈다고 하고, 에는 왕이 죽자, 사자사 북쪽에 화장해 그 유골을 구지제의 동산 옆에 묻었다
하여 기록에 차이가 있으나 현재의 위치가 사자사터로 전하는 지점의 북쪽에 해당하므로 크게 어긋나지 않는다.', 'Other than that, it is a very simple tomb with no markings.
According to the legend, when the king died in 912, his name was Hyogong and he was buried to the north of a temple called Sajasa Temple. When the king died, he was cremated to the north of Sajasa Temple and his ashes were buried next to the garden of Gujije.
Therefore, there are differences in the records, but the current location is north of the point said to be Sajasa Temple site, so there is not a significant discrepancy.'),
    (160, 'tip', '경주 효공왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Hyogong''s Tomb in Gyeongju, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (160, 'did_you_know', '신라 제52대 효공왕(재위 897∼912)의 무덤으로 높이 5m, 지름 21.2m이며 둥글게 흙을 쌓아 올린 원형 봉토 무덤이에요.', 'This is the tomb of King Hyogong, the 52nd king of Silla (reigned 897-912), and is a circular earthen mound tomb with a height of 5 m and a diameter of 21.2 m.'),
    (161, 'summary', '동서는 안압지로부터 교동까지 남북은 반월성 남쪽의 남천에서 고분공원 앞 첨성로에 이르는 광대한 지역이다.', 'It is a vast area, from Anapji Pond to Gyo-dong in the east and west, and from Namcheon south of Banwolseong Fortress to Cheomseong-ro in front of Ancient Tombs Park in the north and south.'),
    (161, 'intro', '동서는 안압지로부터 교동까지 남북은 반월성 남쪽의 남천에서 고분공원 앞 첨성로에 이르는 광대한 지역이다. 이 지역은 신라 왕도의 중심부였기 때문에 반월성, 안압지, 첨성대, 계림 등 중요한 유적이 많을 뿐만 아니라 내물왕을 위시한 수십 기에 달하는 신라시대의 고분이 밀집되어 있는 곳이다.', 'It is a vast area, from Anapji Pond to Gyo-dong in the east and west, and from Namcheon south of Banwolseong Fortress to Cheomseong-ro in front of Ancient Tombs Park in the north and south. Because this area was the center of the royal capital of Silla, there are many important ruins such as Banwolseong Fortress, Anapji Pond, Cheomseongdae, and Gyerim, as well as dozens of ancient tombs from the Silla period, including those of King Naemul.'),
    (161, 'story', '이 일대의 면적은 668,121㎡(202,46평)이다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 경주 동부 사적지대은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The area of this area is 668,121㎡ (202,46 pyeong).
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s historical site in the eastern part of Gyeongju leaves a different memory for each person who visits Gyeongju.'),
    (161, 'tip', '경주 동부 사적지대에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At the historical site in eastern Gyeongju, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (161, 'did_you_know', '이 일대의 면적은 668,121㎡(202,46평)이에요.', 'The area of this area is 668,121㎡ (202,46 pyeong).'),
    (162, 'summary', '장항리사지는 경주시 문무대왕면 장항리에 위치한 토함산 동쪽에 있는 절터로, 절의 이름을 정확히 알 수 없어 마을의 이름인 장항리를 따서 장항리사지라고 부른다.', 'Janghang-ri Temple Site is a temple site on the east side of Tohamsan Mountain, located in Janghang-ri, Munmu Daewang-myeon, Gyeongju-si. As the exact name of the temple is unknown, it is called Janghang-ri Temple Site after the name of the village, Janghang-ri.'),
    (162, 'intro', '장항리사지는 경주시 문무대왕면 장항리에 위치한 토함산 동쪽에 있는 절터로, 절의 이름을 정확히 알 수 없어 마을의 이름인 장항리를 따서 장항리사지라고 부른다. 금당 터를 중심으로 동탑과 서탑이 있었으나, 도굴범에 의해 붕괴한 것을 1932년에 복원이 가능한 서탑만을 새로이 복원해 놓은 것이다.', 'Janghang-ri Temple Site is a temple site on the east side of Tohamsan Mountain, located in Janghang-ri, Munmu Daewang-myeon, Gyeongju-si. As the exact name of the temple is unknown, it is called Janghang-ri Temple Site after the name of the village, Janghang-ri. There were an east pagoda and a west pagoda centered on the Geumdang site, but only the west pagoda, which could be restored, was restored in 1932 after it collapsed due to grave robbers.'),
    (162, 'story', '높이 9m의 5층석탑으로 신라시대 석탑 양식의 전형적인 특징을 보여주는 큰 규모의 석탑으로 이중 기단을 가졌고, 상륜부에는 노반만 남아 있으며 하층 기단은 비교적 넓게 만들어져 안정감이 있다.
1층 몸돌 4면에 도깨비 형태의 쇠고리가 장식된 2짝의 문을 조각하고, 각 면에 한 쌍의 인왕상을 정교하게 새긴 희귀한 수법을 보여 주고 있다.
조각 수법으로 보아 8세기의 작품으로 평가된다.', 'It is a 9m high, 5-story stone pagoda that shows the typical characteristics of the stone pagoda style of the Silla Dynasty. It has a double stylobate. Only the roadbed remains in the upper part, and the lower stylobate is relatively wide, giving it a sense of stability.
On the four sides of the body stone of the first floor, two pairs of doors decorated with goblin-shaped iron rings are carved, and a pair of Nio statues are elaborately carved on each side, showing a rare technique.
Judging from the carving technique, it is assessed to be a work of the 8th century.'),
    (162, 'tip', '경주 장항리 서 오층석탑을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the West Five-story Stone Pagoda in Janghang-ri, Gyeongju, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (162, 'did_you_know', '금당 터를 중심으로 동탑과 서탑이 있었으나, 도굴범에 의해 붕괴한 것을 1932년에 복원이 가능한 서탑만을 새로이 복원해 놓은 것이에요.', 'There were an east pagoda and a west pagoda centered on the Geumdang site, but only the west pagoda, which could be restored, was restored in 1932 after it collapsed due to grave robbers.'),
    (163, 'summary', '경주 낭산의 정상에 있는 신라 제27대 선덕여왕릉(재위 632∼647)은 646년경에 조성되었다.', 'The tomb of Queen Seondeok, the 27th queen of Silla (reign 632-647), located at the top of Nangsan Mountain in Gyeongju, was built around 646.'),
    (163, 'intro', '경주 낭산의 정상에 있는 신라 제27대 선덕여왕릉(재위 632∼647)은 646년경에 조성되었다. 높이 6.8m, 지름 23.6m의 원형 봉토분이며, 자연석을 이용해 봉분 아래에 2단 보호석을 쌓은 것 외에는 별다른 장식이 없다.', 'The tomb of Queen Seondeok, the 27th queen of Silla (reign 632-647), located at the top of Nangsan Mountain in Gyeongju, was built around 646. It is a circular mound with a height of 6.8m and a diameter of 23.6m, and has no other decorations other than a two-tiered protective stone piled under the mound using natural stones.'),
    (163, 'story', '선덕여왕은 아들이 없던 진평왕의 딸로 태어나 성골이라는 특수한 신라 왕족 의식에 의해 신라 최초의 여왕이 되었다.
재위 16년간 첨성대와 분황사, 특히 신라 최대의 황룡사 9층 목탑을 세웠으며, 훗날 태종 무열왕이 되는 김춘추와 명장 김유신과 함께 신라 삼국통일의 기초를 닦았다.
에 의하면 선덕여왕이 죽을 날을 예언하며 부처의 나라인 도리천에 묻어 달라고 했다고 한다.', 'Queen Seondeok was born as the daughter of King Jinpyeong, who had no sons, and became the first queen of Silla through a special Silla royal ritual called the Seonggol.
During his 16 years of reign, he built Cheomseongdae and Bunhwangsa Temple, and especially the nine-story wooden pagoda of Hwangnyongsa Temple, the largest in Silla, and laid the foundation for the unification of the three kingdoms of Silla with Kim Chun-chu, who later became King Taejong Muyeol, and the famous general Kim Yu-shin.
According to the legend, Queen Seondeok predicted the day she would die and asked to be buried in Doricheon, the kingdom of Buddha.'),
    (163, 'tip', '경주 선덕여왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Queen Seondeok''s Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (163, 'did_you_know', '경주 낭산의 정상에 있는 신라 제27대 선덕여왕릉(재위 632∼647)은 646년경에 조성되었다고 해요.', 'The tomb of Queen Seondeok, the 27th queen of Silla (reign 632-647), located at the top of Nangsan Mountain in Gyeongju, is said to have been built around 646.'),
    (164, 'summary', '청소년의 활동과 상담, 교육을 지원하는 경주의 열린 공공 문화 공간이에요.', 'It is an open public cultural space in Gyeongju that supports youth activities, counseling, and education.'),
    (164, 'intro', '경주시청소년수련관은 1995년 문을 연 뒤 청소년의 참여 활동과 상담, 교육을 지원해 온 시설이에요. 일반 관광 명소라기보다 지역 청소년과 가족이 프로그램을 통해 이용하는 생활 문화 공간에 가깝습니다.', 'Gyeongju City Hall Youth Training Center is a facility that has supported youth participation activities, counseling, and education since opening in 1995. Rather than a general tourist attraction, it is closer to a living and cultural space used by local youth and families through programs.'),
    (164, 'story', '수련관에서는 동아리와 체험 활동, 상담과 진로 지원 등 다양한 프로그램이 운영돼요. 건물 자체를 관람하기보다 사전에 참여 가능한 프로그램과 대상 연령을 확인할 때 이 공간의 역할을 제대로 경험할 수 있습니다.', 'The training center offers a variety of programs, including clubs, experiential activities, counseling, and career support. Rather than viewing the building itself, you can truly experience the role of this space by checking in advance the programs you can participate in and the target age group.'),
    (164, 'tip', '자유 관람 시설이 아니므로 방문 전에 공식 일정에서 모집 대상과 신청 방법을 확인하세요. 프로그램 시작보다 여유 있게 도착해 접수와 안전 안내를 마치는 것이 좋아요.', 'As this is not an open-access facility, please check the official schedule to see who is recruiting and how to apply before visiting. It is a good idea to arrive early and complete registration and safety information before the program starts.'),
    (164, 'did_you_know', '1995년 개관한 뒤 청소년 활동뿐 아니라 상담과 자립 지원까지 폭넓게 맡아 왔어요.', 'Since opening in 1995, it has been in charge of a wide range of activities, including counseling and independence support for youth.'),
    (165, 'summary', '경주 근교 금척리 평지에 있는 신라의 무덤들로, 크고 작은 30 여기의 무덤이 모여 있다.', 'There are 30 large and small tombs from the Silla Dynasty located on the plains of Geumcheok-ri near Gyeongju.'),
    (165, 'intro', '경주 근교 금척리 평지에 있는 신라의 무덤들로, 크고 작은 30 여기의 무덤이 모여 있다. 이곳은 신라의 시조 박혁거세가 하늘에서 받은 금으로 만든 자(금자)를 숨기기 위해서 40여 개의 가짜무덤을 만들었다는 전설이 내려오는 곳으로 지금도 이 무덤들 속에 묻혀 있을 것이라 전한다.', 'There are 30 large and small tombs from the Silla Dynasty located on the plains of Geumcheok-ri near Gyeongju. This is where the legend goes that Park Hyeokgeose, the founder of Silla, created about 40 fake tombs to hide the gold he received from heaven. It is said that he is still buried in these tombs.'),
    (165, 'story', '본격적인 조사는 이루어지지 않았지만 1952년에 파괴된 무덤 2기를 조사하였다.
무덤 내부는 직사각형의 구덩이를 파고 덧널(곽)을 설치한 신라 특유의 돌무지덧널무덤(적석목곽분)이다.
유물은 금귀고리와 굽은 옥 등이 수습되었다.', 'Although a full-scale investigation was not conducted, two tombs destroyed in 1952 were investigated.
The inside of the tomb is a unique stone mound tomb (Jeokseokmokkwak tomb) of Silla, in which a rectangular pit was dug and a shroud was installed.
Artifacts recovered included gold earrings and curved jade.'),
    (165, 'tip', '경주 금척리 고분군을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Geumcheok-ri Ancient Tombs in Gyeongju, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (165, 'did_you_know', '경주 근교 금척리 평지에 있는 신라의 무덤들로, 크고 작은 30 여기의 무덤이 모여 있어요.', 'These are the Silla tombs located on the plains of Geumcheok-ri near Gyeongju. There are 30 large and small tombs gathered here.'),
    (166, 'summary', '1977년 택지 조성공사 도중에 우연히 발견된 가마터로 국립경주박물관에서는 발굴조사하여 9기의 도자기와 기와를 굽던 가마터를 발굴하였다.', 'The site of a kiln was accidentally discovered during housing development construction in 1977, and the Gyeongju National Museum conducted an excavation and discovered the site of 9 kilns where pottery and tiles were fired.'),
    (166, 'intro', '경주 동방동 와요지는 1977년 택지 조성공사 도중에 우연히 발견된 가마터로 국립경주박물관에서는 발굴조사하여 9기의 도자기와 기와를 굽던 가마터를 발굴하였다. 그중 1기를 조사한 결과 가마의 전체 길이는 10.5m, 넓이 1.72m인 구릉 경사면을 이용하여 만든 굴가마(등요)로 밝혀졌다.', 'Wayoji, Dongbang-dong, Gyeongju, is a kiln site that was accidentally discovered during housing development construction in 1977. The Gyeongju National Museum conducted an excavation and discovered the site of 9 kilns where pottery and tiles were fired. As a result of examining one of them, it was revealed that it was a cave kiln made using a hilly slope with a total length of 10.5m and a width of 1.72m.'),
    (166, 'story', '도자기를 굽던 곳의 천장 부분 벽 일부가 남아있으며, 도자기를 빚던 곳과 굽던 방 사이에는 높은 벽이 있다.
출토된 기왓조각은 고려시대에 성행한 새 깃털 모양 무늬와 연꽃무늬의 장식 기와, 그리고 조선시대에 제작된 기와류가 대부분을 차지하고 있었다.
가마바닥에서 출토된 건륭이 새겨진 암막새는 가마터가 없어질 당시의 것으로 생각되며, 가마터의 제작시기를 고려시대부터 조선시대 후기까지로 추정하게 한다.', 'A portion of the ceiling wall of the pottery-making area remains, and there is a high wall between the pottery-making area and the firing room.
Most of the excavated tile pieces were decorative tiles with bird feather patterns and lotus patterns that were popular during the Goryeo Dynasty, as well as tiles made during the Joseon Dynasty.
The blockhouse with Qianlong engraved on it excavated from the bottom of the kiln is thought to be from when the kiln site was lost, and the construction period of the kiln site is estimated to be from the Goryeo Dynasty to the late Joseon Dynasty.'),
    (166, 'tip', '경주 동방동 와요지을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Wayoji in Dongbang-dong, Gyeongju, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (166, 'did_you_know', '경주 동방동 와요지는 1977년 택지 조성공사 도중에 우연히 발견된 가마터로 국립경주박물관에서는 발굴조사하여 9기의 도자기와 기와를 굽던 가마터를 발굴했어요.', 'Wayoji, Dongbang-dong, Gyeongju, is a kiln site that was accidentally discovered during housing development construction in 1977. The Gyeongju National Museum conducted an excavation and discovered the site of 9 kilns where pottery and tiles were fired.'),
    (167, 'summary', '『삼국유사』에 기록된 인용사의 터로 추정되는 신라 사찰 유적이에요.', 'It is the ruins of a Silla temple that is believed to be the site of Injingsa Temple, recorded in Samguk Yusa.'),
    (167, 'intro', '인왕동 사지는 태종 무열왕의 둘째 아들 김인문을 위해 세운 인용사의 터로 추정돼요. 남아 있는 유구는 많지 않지만, 왕실 인물의 안녕과 극락왕생을 빌었던 신라 불교의 한 장면을 전합니다.', 'The site in Inwang-dong is believed to be the site of Yongyeonsa Temple, built for Kim In-moon, the second son of King Taejong Muyeol. Although there are not many relics remaining, they convey a scene from Silla Buddhism in which people prayed for the well-being of royal figures and their return to paradise.'),
    (167, 'story', '김인문이 당나라에 머물던 시기 신라 사람들은 그의 무사 귀환을 바라며 관음도량을 열었다고 해요. 그가 귀국길에 세상을 떠난 뒤에는 극락왕생을 비는 미타도량으로 바뀌었다는 기록이 남아, 당시 신앙과 국제 관계를 함께 생각하게 합니다.', 'It is said that during the time Kim In-moon stayed in the Tang Dynasty, the people of Silla opened the Gwaneumdoryang in hopes of his safe return. After he passed away on his way home, there is a record that he changed his name to Mitadoryang praying for his return to paradise, making us think about both faith and international relations at the time.'),
    (167, 'tip', '건물보다 터와 기록을 통해 이해하는 유적이라 현장 안내판을 먼저 읽는 것이 좋아요. 인근 월성과 동궁과 월지를 함께 둘러보면 신라 왕경 안에서 이 사찰이 놓였던 위치를 짐작하기 쉽습니다.', 'It is a ruin that is understood through the site and records rather than the buildings, so it is best to read the site information board first. If you tour nearby Wolseong, Donggung Palace, and Wolji together, it is easy to guess where this temple was located within the Silla royal capital.'),
    (167, 'did_you_know', '인용사는 승려나 왕이 아닌 김인문 개인의 안녕을 위해 세운 이른 사례로 알려져 있어요.', 'Inyongsa Temple is known as an early example of a temple built for the well-being of Kim In-moon, not a monk or a king.'),
    (168, 'summary', '신라 31대 신문왕(재위 681~692)의 무덤이다.', 'This is the tomb of King Sinmun, the 31st king of Silla (reigned 681-692).'),
    (168, 'intro', '신라 31대 신문왕(재위 681~692)의 무덤이다. 신문왕은 문무왕의 아들로 부왕의 뜻을 이어받아 옛 백제와 고구려 백성을 융합하는데 힘썼다.', 'This is the tomb of King Sinmun, the 31st king of Silla (reigned 681-692). King Sinmun, the son of King Munmu, inherited his father''s wishes and worked to unite the people of old Baekje and Goguryeo.'),
    (168, 'story', '국립교육기관인 국학을 설립하고, 귀족들의 기반이 되면 녹읍을 폐지하고 관료전을 지급하였다.
지방을 통치하기 위해 전국을 아홉 개의 주로 나누고 중요한 거점 다섯 곳에 소경을 설치하였다.
신문왕이 죽은 후에는 낭산 동쪽에서 장사를 지냈다고 한다.', 'Kukhak, a national educational institution, was established, and once the nobility was established, nok-eup (nok-eup) was abolished and bureaucrats were provided.
In order to govern the region, the country was divided into nine provinces and small governors were installed at five important bases.
It is said that after King Sinmun died, he was buried east of Nangsan Mountain.'),
    (168, 'tip', '경주 신문왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Royal Tomb, please check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (168, 'did_you_know', '신라 31대 신문왕(재위 681~692)의 무덤이에요.', 'This is the tomb of King Sinmun, the 31st king of Silla (reigned 681-692).'),
    (169, 'summary', '신라 55대 왕인 경애왕(재위 924~927)의 무덤이다.', 'This is the tomb of King Gyeongae (reign 924-927), the 55th king of Silla.'),
    (169, 'intro', '신라 55대 왕인 경애왕(재위 924~927)의 무덤이다. 경애왕은 신덕왕의 둘째 아들이자 경명왕의 동생으로, 경명왕의 뒤를 이어 왕위에 올랐다.', 'This is the tomb of King Gyeongae (reign 924-927), the 55th king of Silla. King Gyeongae was the second son of King Shindeok and the younger brother of King Gyeongmyeong, and ascended the throne after King Gyeongmyeong.'),
    (169, 'story', '왕건이 후백제를 정벌할 때 군사를 보내어 고려를 도왔다.
927년에 포석정에서 제사를 지낸 후 연회를 베풀던 중 그곳을 기습한 후백제의 견훤에게 사로잡혀 스스로 목숨을 끊었다.
무덤은 삼릉계곡 입구의 소나무 숲 안에 있다.', 'When Wang Geon conquered Later Baekje, he sent troops to help Goryeo.
In 927, while holding a banquet after holding a memorial service at Poseokjeong, he was captured by Gyeon Hwon of Later Baekje who attacked the place and committed suicide.
The tomb is located in a pine forest at the entrance to Samneung Valley.'),
    (169, 'tip', '경주 경애왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Gyeongae''s Royal Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (169, 'did_you_know', '신라 55대 왕인 경애왕(재위 924~927)의 무덤이에요.', 'This is the tomb of King Gyeongae (reign 924-927), the 55th king of Silla.'),
    (170, 'summary', '경주 남산 이 일대는 통일신라시대에 신인사라는 절이 있었던 곳이다.', 'This area of ​​Namsan, Gyeongju, is where a temple called Ininsa Temple was located during the Unified Silla period.'),
    (170, 'intro', '경주 남산 이 일대는 통일신라시대에 신인사라는 절이 있었던 곳이다. 남쪽의 큰 바위에는 목조건물의 흔적이 남아 있으며, 석탑 조각들이 흩어져 있는 것으로 보아 남쪽면의 불상을 주존으로 하여 남향 사찰을 경영했었음을 알 수 있다.', 'This area of Namsan, Gyeongju, is where a temple called Ininsa Temple was located during the Unified Silla period. Traces of a wooden building remain on the large rock to the south, and fragments of stone pagodas are scattered around, indicating that the temple was operated as a south-facing temple with the Buddha statue on the southern side as the main temple.'),
    (170, 'story', '9m나 되는 사각형의 커다란 바위에 여러 불상을 회화적으로 묘사하였다.
남쪽 바위면에는 삼존과 독립된 보살상이 배치되어 있고, 동쪽 바위면에도 불상과 보살, 승려, 그리고 비천상을 표현해 놓았다.
불상, 보살상 등은 모두 연꽃무늬를 조각한 대좌와 몸 전체에서 나오는 빛을 형상화 한 광배를 갖추었으며 자세와 표정이 각기 다르다.', 'Several Buddha statues are pictorially depicted on a large 9m square rock.
On the southern rock face, the Triad and independent Bodhisattva statues are placed, and on the eastern rock face, Buddha statues, Bodhisattvas, monks, and non-celestial statues are depicted.
The Buddha and Bodhisattva statues all have pedestals carved with lotus patterns and halos that symbolize light coming from the entire body, and their postures and expressions are different.'),
    (170, 'tip', '경주 남산 탑곡 마애불상군을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Namsan Tapgok Rock-carved Buddha Group, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (170, 'did_you_know', '조각 양식은 많이 도식화되었으나 화려한 조각을 회화적으로 배치하여 보여주는 것은 우리나라에서 특이한 것이에요.', 'Although many sculpture styles have been schematized, displaying colorful sculptures arranged in a pictorial manner is unique in Korea.'),
    (171, 'summary', '신라 제45대 신무왕(재위 839)의 무덤이다.', 'This is the tomb of King Shinmu, the 45th king of Silla (reigned 839).'),
    (171, 'intro', '신라 제45대 신무왕(재위 839)의 무덤이다. 본명은 김우징이고, 희강왕의 사촌동생이다.', 'This is the tomb of King Shinmu, the 45th king of Silla (reigned 839). His real name is Kim Woo-jing, and he is King Heegang’s younger cousin.'),
    (171, 'story', '흥덕왕 사후에 왕위 쟁탈전에서 아버지를 도왔으나 패하여 청해진으로 도망하였다가 장보고의 군사를 빌려 민애왕을 내쫓고 왕위에 올랐다.
그러나 왕위에 오른 지 3개월 만에 병으로 세상을 떠났다.
제형상 서북쪽에서 장사를 지냈다고 한다.', 'After the death of King Heungdeok, he helped his father in the battle for the throne, but was defeated and fled to Cheonghaejin. Then, with the help of Jang Bogo''s troops, he overthrew King Minae and ascended to the throne.
However, he died of illness three months after ascending to the throne.
It is said that the burial took place in the northwest.'),
    (171, 'tip', '경주 신무왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Sinmu’s Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (171, 'did_you_know', '신라 제45대 신무왕(재위 839)의 무덤이에요.', 'This is the tomb of King Sinmu, the 45th king of Silla (reigned 839).'),
    (172, 'summary', '경주 남산의 서쪽 기슭에 동서로 3개의 왕릉이 나란히 있어 붙여졌다.', 'It was named so because there are three royal tombs located side by side from east to west at the western foot of Namsan Mountain in Gyeongju.'),
    (172, 'intro', '경주 배동 삼릉은 경주 남산의 서쪽 기슭에 동서로 3개의 왕릉이 나란히 있어 붙여졌다. 밑으로부터 신라 8대 아달라왕, 53대 신덕왕, 54대 경명왕 등 박씨 3왕의 무덤이라 전하고 있다.', 'Baedong Samneung, Gyeongju, was named so because there are three royal tombs located side by side from east to west at the western foot of Namsan Mountain in Gyeongju. It is said that from the bottom, it is the tomb of three kings of the Park clan, including King Adala, the 8th king of Silla, King Shindeok, the 53rd king, and King Gyeongmyeong, the 54th king.'),
    (172, 'story', '무덤은 모두 원형으로 흙을 쌓아 올린 형태를 하고 있다.
신덕왕릉이라 전해오는 가운데의 무덤은 1953년과 1963년에 도굴당하여, 내부를 조사한 결과 굴식돌방무덤(횡혈식석실묘) 임을 확인하였다.
무덤에는 돌방 벽면에 병풍을 돌려세워 놓은 것처럼 동·서 양벽의 일부에 색이 칠해져 있는데, 이것은 본격적인 벽화는 아니지만 벽화가 그려지지 않은 경주의 신라 무덤에서는 처음 발견되는 것으로 주목되는 자료이다.', 'All tombs are circular in shape with dirt piled up.
The tomb in the middle, which is said to be the tomb of King Sindeok, was robbed in 1953 and 1963, and after examining the interior, it was confirmed that it was a cave-type stone chamber tomb (horizontal stone chamber tomb).
In the tomb, parts of both the east and west walls are painted in color, as if a folding screen was turned on the wall of a stone room. Although these are not full-scale murals, they are noteworthy as they are found for the first time in a Silla tomb in Gyeongju where no murals were painted.'),
    (172, 'tip', '경주 배동 삼릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Baedong Samneung, Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (172, 'did_you_know', '밑으로부터 신라 8대 아달라왕, 53대 신덕왕, 54대 경명왕 등 박씨 3왕의 무덤이라 전하고 있어요.', 'It is said that from the bottom, it is the tomb of three kings of the Park clan, including King Adala, the 8th king of Silla, King Shindeok, the 53rd king, and King Gyeongmyeong, the 54th king.'),
    (173, 'summary', '이 능은 신라 제32대 효소왕(재위 692~702) 무덤이다.', 'This tomb is the tomb of King Hyoso, the 32nd king of Silla (reigned 692-702).'),
    (173, 'intro', '이 능은 신라 제32대 효소왕(재위 692~702) 무덤이다. 신문왕(재위 681~692)의 맏아들로서 6세의 어린 나이에 즉위하였으며, 어머니인 신목태후가 8년간 섭정하였다.', 'This tomb is the tomb of King Hyoso, the 32nd king of Silla (reigned 692-702). As the eldest son of King Sinmun (reigned 681-692), he ascended to the throne at the young age of six, and his mother, Empress Dowager Shinmok, served as regent for eight years.'),
    (173, 'story', '효소왕의 재위 기간에 관제를 정비하고 의료 교육기관인 의학을 설립하였다.
고구려의 옛 땅을 되찾기 위해 성을 많이 쌓았고, 왕도에 물품의 유통을 쉽게 하기 위해 시장을 열었다.
효소왕이 죽은 후 망덕사 동쪽에서 장사를 지냈다고 한다.', 'During the reign of King Hyo-so, the government system was reorganized and the medical education institute, Medicine, was established.
To regain Goguryeo''s old land, many castles were built, and markets were opened to facilitate the distribution of goods in the royal capital.
It is said that after King Hyoso died, he was buried east of Mangdeoksa Temple.'),
    (173, 'tip', '경주 효소왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju King Hyoso Royal Tomb, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (173, 'did_you_know', '이 능은 신라 제32대 효소왕(재위 692~702) 무덤이에요.', 'This tomb is the tomb of King Hyoso, the 32nd king of Silla (reigned 692-702).'),
    (174, 'summary', '경주 북천가에 있는 신라 제41대 헌덕왕(재위 809~826)의 무덤이다.', 'This is the tomb of King Heondeok, the 41st king of Silla (reigned 809-826), located in Bukcheonga, Gyeongju.'),
    (174, 'intro', '경주 북천가에 있는 신라 제41대 헌덕왕(재위 809~826)의 무덤이다. 헌덕왕의 본명은 김언승이며, 조카인 애장왕을 죽이고 왕이 되었다.', 'This is the tomb of King Heondeok, the 41st king of Silla (reigned 809-826), located in Bukcheonga, Gyeongju. King Heondeok''s real name was Kim Eon-seung, and he became king after killing his nephew, King Aejang.'),
    (174, 'story', '재위기간 동안에 농사를 권장하고 당나라와 친밀한 관계를 유지했으나, 김헌창의 난과 김범문의 난이 일어나는 등 국내정세가 혼란스러웠다.
『삼국사기』에 의하면 826년에 왕이 죽자 천림사의 북쪽에 장사 지냈다고 한다.
천림사의 위치는 정확히 알 수 없으나 이 왕릉의 남쪽에 절터가 있어 이곳을 천림사 터로 본다.', 'During his reign, he encouraged farming and maintained a close relationship with the Tang Dynasty, but the domestic situation was chaotic, including the rebellion of Kim Heon-chang and the rebellion of Kim Beom-mun.
According to Samguksagi (History of the Three Kingdoms), when the king died in 826, he was buried north of Cheonlimsa Temple.
The exact location of Cheonlimsa Temple is not known, but there is a temple site to the south of this royal tomb, so this is believed to be the site of Cheonlimsa Temple.'),
    (174, 'tip', '경주 헌덕왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Heondeok''s Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (174, 'did_you_know', '경주 북천가에 있는 신라 제41대 헌덕왕(재위 809~826)의 무덤이에요.', 'This is the tomb of King Heondeok, the 41st king of Silla (reigned 809-826), located in Bukcheonga, Gyeongju.'),
    (175, 'summary', '이 능은 신라 제49대 헌강왕(재위 875~886)의 무덤이다.', 'This tomb is the tomb of King Heongang, the 49th king of Silla (reigned 875-886).'),
    (175, 'intro', '이 능은 신라 제49대 헌강왕(재위 875~886)의 무덤이다. 경문왕의 맏아들로서 왕위를 이었다.', 'This tomb is the tomb of King Heongang, the 49th king of Silla (reigned 875-886). He ascended the throne as the eldest son of King Gyeongmun.'),
    (175, 'story', '헌강왕은 왕은 불교와 국학에 큰 관심을 가지고 문치를 지향하였다.
풍년이 들어 태평성대를 이루었는데, 거리마다
노랫소리가 끊이지 않았고 일본왕이 황금을 바칠 정도였다고 한다.', 'King Heongang was very interested in Buddhism and national studies and pursued civil affairs.
There was a good harvest and peace was achieved, and every street
It is said that the singing continued and the King of Japan even offered gold.'),
    (175, 'tip', '경주 헌강왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Heongang’s Royal Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (175, 'did_you_know', '이 능은 신라 제49대 헌강왕(재위 875~886)의 무덤이에요.', 'This tomb is the tomb of King Heongang, the 49th king of Silla (reigned 875-886).'),
    (176, 'summary', '이 능은 신라 제50대 정강왕(재위 886~887)의 무덤이다.', 'This tomb is the tomb of King Jeonggang, the 50th king of Silla (reigned 886-887).'),
    (176, 'intro', '이 능은 신라 제50대 정강왕(재위 886~887)의 무덤이다. 정강왕은 경문왕의 둘째 아들이며, 헌강왕의 동생이다.', 'This tomb is the tomb of King Jeonggang, the 50th king of Silla (reigned 886-887). King Jeonggang is the second son of King Gyeongmun and the younger brother of King Heongang.'),
    (176, 'story', '황룡사에 백고좌를 설치하여 왕이 친히 강연을 들었다.
정강왕은 병이 깊어지자 누이동생인 만(진성여왕)이 왕위를 잇게 하라는 말을 남기고 세상을 떠났다.
재위 기간은 만 1년에 불과하다.', 'A white throne room was set up at Hwangnyongsa Temple and the king personally listened to the lectures.
As King Jeonggang''s illness worsened, he passed away, leaving behind the words that his sister Man (Queen Jinseong) should succeed to the throne.
The reign lasted only one year.'),
    (176, 'tip', '경주 정강왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Royal Tomb of King Jeonggang, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (176, 'did_you_know', '이 능은 신라 제50대 정강왕(재위 886~887)의 무덤이에요.', 'This tomb is the tomb of King Jeonggang, the 50th king of Silla (reigned 886-887).'),
    (177, 'summary', '불국사의 석가탑과 다보탑처럼 형식을 달리하는 쌍탑이 동·서로 건립된 특이한 예의 두 탑이다.', 'Like the Seokgatap and Dabotap pagodas of Bulguksa Temple, these two pagodas are unusual in that they are twin pagodas of different forms built to the east and west.'),
    (177, 'intro', '불국사의 석가탑과 다보탑처럼 형식을 달리하는 쌍탑이 동·서로 건립된 특이한 예의 두 탑이다. 동탑은 돌을 벽돌 모양으로 다듬어서 쌓아 올린 모전석탑의 양식을 취하고 있고, 서탑은 전형적인 3층석탑의 양식이다.', 'Like the Seokgatap and Dabotap pagodas of Bulguksa Temple, these two pagodas are unusual in that they are twin pagodas of different forms built to the east and west. The east pagoda is in the style of a stone pagoda made by trimming stones into brick shapes, and the west pagoda is a typical three-story stone pagoda.'),
    (177, 'story', '동탑은 탑의 토대가 되는 바닥돌이 넓게 2중으로 깔려있고, 그 위에 잘 다듬은 돌 여덟 개를 한 단처럼 짜 맞추어 기단부(基壇部)를 이루고 있다.
탑신부(塔身部)의 몸돌과 지붕돌은 각각 돌 하나로 만들었다.
지붕돌은 밑면의 받침과 낙수면이 모전석탑처럼 똑같이 각각 5단으로 층을 이루고 있다.', 'The East Pagoda has a double layer of floor stones, which serve as the foundation of the pagoda, and eight well-cut stones are placed on top of it to form a stylobate.
The body stone and roof stone of the pagoda body were each made from a single stone.
The base of the roof stone and the falling surface are each 5-tiered, just like the parent stone pagoda.'),
    (177, 'tip', '경주 남산동 동·서 삼층석탑을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the East and West Three-story Stone Pagodas in Namsan-dong, Gyeongju, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (177, 'did_you_know', '불국사의 석가탑과 다보탑처럼 형식을 달리하는 쌍탑이 동·서로 건립된 특이한 예의 두 탑이에요.', 'Like the Seokgatap and Dabotap pagodas of Bulguksa Temple, these two pagodas are unusual in that they are twin pagodas of different shapes built to the east and west.'),
    (178, 'summary', '무열왕릉 뒤편 구릉에 나란히 자리한 네 기의 대형 신라 고분이에요.', 'These are four large Silla tombs located side by side on the hill behind King Muyeol’s tomb.'),
    (178, 'intro', '서악동 고분군은 태종 무열왕릉 뒤편의 완만한 구릉에 자리한 네 기의 큰 무덤이에요. 둥근 봉분과 일부 드러난 둘레돌에서 대릉원 일대 고분과 다른 통일신라 왕릉의 구조를 살펴볼 수 있습니다.', 'The Seoak-dong Ancient Tombs are four large tombs located on a gentle hill behind the tomb of King Taejong Muyeol. You can see the structure of the royal tombs of the Unified Silla Dynasty, which is different from the tombs in the Daereungwon area, through the round mound and partially exposed surrounding stones.'),
    (178, 'story', '무덤의 주인은 명확히 밝혀지지 않았지만 규모와 위치로 보아 신라 왕실과 밀접한 인물들의 묘역으로 여겨져요. 자연스러운 능선을 따라 이어지는 봉분은 서악 일대가 오랫동안 중요한 장송 공간이었음을 보여 줍니다.', 'The owner of the tomb is not clearly known, but considering its size and location, it is believed to be the tomb of people closely related to the Silla royal family. The burial mounds along the natural ridge show that the Seoak area has been an important funeral space for a long time.'),
    (178, 'tip', '무열왕릉을 먼저 보고 뒤편 구릉으로 이동하면 고분군의 배치를 이해하기 쉬워요. 봉분에 오르지 말고 정해진 길에서 크기와 간격을 비교해 보세요. 늦은 오후에는 능선의 입체감이 잘 드러납니다.', 'It is easy to understand the layout of the ancient tombs if you look at King Muyeol''s tomb first and then move to the hill behind it. Instead of climbing the mound, compare the size and spacing along the designated path. In the late afternoon, the three-dimensional effect of the ridge is clearly revealed.'),
    (178, 'did_you_know', '봉분 둘레에는 깬돌을 사용한 흔적이 남아 있어 대릉원 고분들과 다른 조성 방식을 살펴볼 수 있어요.', 'There are traces of the use of broken stones around the mound, allowing you to see the construction method that is different from the Daereungwon tombs.'),
    (179, 'summary', '신라 제6대 지마왕(재위 112~134)의 무덤이다.', 'This is the tomb of King Jima, the 6th king of Silla (reigned 112-134).'),
    (179, 'intro', '신라 제6대 지마왕(재위 112~134)의 무덤이다. 지마왕은 신라 5대 파사왕의 아들로 태어나 23년간 재위하면서 가야, 왜구, 말갈의 침입을 막았다.', 'This is the tomb of King Jima, the 6th king of Silla (reigned 112-134). King Jima was born as the son of King Pasa, the 5th king of Silla, and reigned for 23 years, preventing invasions by Gaya, Japanese pirates, and Malgal.'),
    (179, 'story', '지마왕의 재위 기간에는 신라는 백제와 우호적 관계를 유지했으나 가야와는 낙동강 하류를 둘러싸고 패권을 다투었다.
왜인들이 동쪽 변경을 침범하였으나 교섭하여 강화를 맺었고, 북쪽에서 말갈이 쳐들어오자 백제의 도움을 받아 물리쳤다.
무덤은 포석정에 남쪽으로 200m 떨어진 남산 서쪽 자락에 위치해 있다.', 'During King Jima''s reign, Silla maintained friendly relations with Baekje, but Gaya and Gaya fought for hegemony over the lower reaches of the Nakdong River.
The Japanese invaded the eastern border, but negotiated and made peace, and when Malgal invaded from the north, they were defeated with the help of Baekje.
The tomb is located at the western foot of Namsan Mountain, 200 meters south of Poseokjeong.'),
    (179, 'tip', '경주 지마왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Jima’s Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (179, 'did_you_know', '신라 제6대 지마왕(재위 112~134)의 무덤이에요.', 'This is the tomb of King Jima, the 6th king of Silla (reign 112-134).'),
    (180, 'summary', '이곳은 예로부터 능시탑 또는 연화탑으로 불렸던 능지탑이 있던 자리이다.', 'This is the site of Neungjitap, which has been called Neungsitap or Yeonhwatap since ancient times.'),
    (180, 'intro', '이곳은 예로부터 능시탑 또는 연화탑으로 불렸던 능지탑이 있던 자리이다. 무너진 채 버려져 있던 탑을 신라삼산조사단이 1969년부터 수차례 조사하여 1979년에 지금의 모습으로 정비하였다.', 'This is the site of Neungjitap, which has been called Neungsitap or Yeonhwatap since ancient times. The collapsed and abandoned pagoda was investigated several times by the Silla Samsan Investigation Team starting in 1969, and was restored to its current appearance in 1979.'),
    (180, 'story', '능지탑은 원래 기단의 네 면에 십이지신상을 세워 넣고 연꽃 모양의 무늬를 새긴 돌을 쌓아 탑신을 만든 5층탑으로 추정된다.
또한 발굴 중에 소조불상의 파편과 많은 양의 기와 조각들이 출토된 점으로 보아 탑의 네 면에 감실을 만들어 불상을 모셨던 것으로 보인다.
탑의 기단부는 돌을 다듬어 쌓고 윗면은 흙을 덮어 잔디를 심었다.', 'Neungji Pagoda is believed to have originally been a five-story pagoda with statues of the zodiac gods erected on four sides of the stylobate and stones with lotus-shaped patterns carved into the pagoda''s body.
In addition, judging from the fact that fragments of Buddha statues and a large amount of tile fragments were unearthed during the excavation, it appears that tabernacles were built on four sides of the pagoda to enshrine Buddha statues.
The base of the tower was made of hewn stones, and the top was covered with soil and planted with grass.'),
    (180, 'tip', '경주 능지탑지을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Neungjitapji, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (180, 'did_you_know', '무너진 채 버려져 있던 탑을 신라삼산조사단이 1969년부터 수차례 조사하여 1979년에 지금의 모습으로 정비했어요.', 'The collapsed and abandoned pagoda was investigated several times by the Silla Samsan Investigation Team starting in 1969, and was rebuilt to its current appearance in 1979.'),
    (181, 'summary', '경주에서 불국사 방향으로 가는 길의 동남쪽 구릉 소나무숲 속에 자리하고 있는 신라 제33대 성덕왕(재위 701~737)의 무덤이다.', 'This is the tomb of King Seongdeok, the 33rd king of Silla (reigned 701-737), located in a pine forest on a hill southeast of the road from Gyeongju to Bulguksa Temple.'),
    (181, 'intro', '경주에서 불국사 방향으로 가는 길의 동남쪽 구릉 소나무숲 속에 자리하고 있는 신라 제33대 성덕왕(재위 701~737)의 무덤이다. 성덕왕은 신문왕의 아들로 본명은 융기이다.', 'This is the tomb of King Seongdeok, the 33rd king of Silla (reigned 701-737), located in a pine forest on a hill southeast of the road from Gyeongju to Bulguksa Temple. King Seongdeok was the son of King Sinmun and his real name was Yunggi.'),
    (181, 'story', '당과 적극적인 교류를 하였으며 정치적으로 가장 안정된 신라의 전성기를 이끌어 나갔다.
『삼국사기』에 의하면 737년에 왕이 죽자 이거사(移車寺) 남쪽에 장사 지냈다고 하는데, 현재 왕릉 북쪽에 이거사로 추정되는 절터가 있다.
왕릉의 밑둘레는 46m, 높이는 5m이다.', 'He actively interacted with Tang and led the heyday of Silla, which was the most politically stable.
According to the Samguk Sagi (History of the Three Kingdoms), when the king died in 737, he was buried south of Igeosa Temple. Currently, there is a temple site believed to be Igeosa Temple to the north of the royal tomb.
The base circumference of the royal tomb is 46m and the height is 5m.'),
    (181, 'tip', '경주 성덕왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Seongdeok''s Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (181, 'did_you_know', '경주에서 불국사 방향으로 가는 길의 동남쪽 구릉 소나무숲 속에 자리하고 있는 신라 제33대 성덕왕(재위 701~737)의 무덤이에요.', 'This is the tomb of King Seongdeok, the 33rd king of Silla (reigned 701-737), located in a pine forest on a hill southeast of the road from Gyeongju to Bulguksa Temple.'),
    (182, 'summary', '경주 남산 서쪽에 있는 포석정은 왕이 술을 들면서 즐길 수 있도록 마련된 별궁의 하나였으나, 현재 정자는 없고 풍류를 즐기던 물길만이 남아있다.', 'Poseokjeong, located on the west side of Namsan Mountain in Gyeongju, was one of the villas built for the king to enjoy drinking alcohol, but now there is no pavilion and only a waterway where people could enjoy the arts remains.'),
    (182, 'intro', '경주 남산 서쪽에 있는 포석정은 왕이 술을 들면서 즐길 수 있도록 마련된 별궁의 하나였으나, 현재 정자는 없고 풍류를 즐기던 물길만이 남아있다. 조성연대는 신라 제49대 헌강왕(875~886) 때로 본다.', 'Poseokjeong, located on the west side of Namsan Mountain in Gyeongju, was one of the villas built for the king to enjoy drinking alcohol, but now there is no pavilion and only a waterway where people could enjoy the arts remains. The Joseon Dynasty is believed to be from the time of King Heongang, the 49th king of Silla (875-886).'),
    (182, 'story', '규모는 폭이 약 35㎝, 깊이 평균 26㎝, 전체 길이가 약 10m이다.
포석정은 중국 고대 강가에서 초혼제를 지내고 악귀를 쫓는 행사의 하나인 유상곡수연에서 유래하였다.
353년 중국의 왕희지가 쓴 난정서문에 보면 맑은 시냇물을 아홉 구비로 돌아 흐르게 하여 흐르는 물속에 술잔을 띄우고 시를 짓게 하되 술잔이 아홉 구비를 다', 'It is approximately 35 cm wide, 26 cm deep on average, and approximately 10 m long.
Poseokjeong originated from the Yusanggok Suyeon, a ceremony to hold a first marriage ceremony at a riverside in ancient China and ward off evil spirits.
According to the Preface to Nanjeong written by Wang Xizhi of China in 353, he made a clear stream flow in nine directions, floated drinking glasses in the flowing water, and composed poems.'),
    (182, 'tip', '경주 포석정지을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Poseokjeongji, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (182, 'did_you_know', '조성연대는 신라 제49대 헌강왕(875~886) 때로 본다고 해요.', 'It is said that the Joseon Dynasty dates back to the time of King Heongang, the 49th king of Silla (875-886).'),
    (183, 'summary', '경주시 북쪽 소금강산 중턱에 자리한 백률사는 신라 법흥왕 14년(527) 불교 공인을 위해 순교한 이차돈을 기리기 위한 절이자, 신라의 불교 성지이다.', 'Baengnyulsa Temple, located on the slope of Geumgangsan Mountain in the north of Gyeongju, is a temple dedicated to Lee Cha-don, who was martyred for public Buddhism in the 14th year of King Beopheung of Silla (527), and is a sacred place for Buddhism in Silla.'),
    (183, 'intro', '경주시 북쪽 소금강산 중턱에 자리한 백률사는 신라 법흥왕 14년(527) 불교 공인을 위해 순교한 이차돈을 기리기 위한 절이자, 신라의 불교 성지이다. 와 헌덕왕 때 작성된 에 따르면 이차돈은 법흥왕의 명을 받들어 불교를 공인하고 사찰을 짓기 위해 순교했는데, 참수형을 받고 이차돈의 목을 베니 흰색 피가 솟아 나오고 꽃비가 내리는 등 기이한 일이 일어났다.', 'Baengnyulsa Temple, located on the slope of Geumgangsan Mountain in the north of Gyeongju, is a temple dedicated to Lee Cha-don, who was martyred for public Buddhism in the 14th year of King Beopheung of Silla (527), and is a sacred place for Buddhism in Silla. According to , written during the reign of King Heondeok, Lee Cha-don was martyred in obedience to King Beopheung''s orders to recognize Buddhism and build a temple. After being beheaded, Lee Cha-don''s head was cut, and strange things happened, such as white blood gushing out and flower rain falling.'),
    (183, 'story', '불교 공인을 반대하던 신하들도 이것을 보고 마음을 돌렸다고 하며 이차돈의 아내가 그의 명복을 빌기 위해 이차돈의 목이 베려 날아가 떨어진 자리에 자추사를 지었다고 전한다.
백률사는 이 기록에 나오는 자추사일 것으로 추정된다.
백률사 건물은 임진왜란 때 불타 후에 다시 지었으며, 기단부는 일부 신라시대 양식을 지니고 있다.', 'It is said that even the subjects who opposed the official recognition of Buddhism changed their minds after seeing this, and it is said that Lee Cha-don''s wife built Jachusa Temple on the spot where Lee Cha-don''s head was cut off and fell to pray for his soul.
Baekryulsa is presumed to be the Jachusa temple mentioned in this record.
The Baengnyulsa building was rebuilt after it burned down during the Japanese invasions of Korea, and the stylobate retains some of the Silla period style.'),
    (183, 'tip', '백률사(경주)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Baengnyulsa Temple (Gyeongju), check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (183, 'did_you_know', '경주시 북쪽 소금강산 중턱에 자리한 백률사는 신라 법흥왕 14년(527) 불교 공인을 위해 순교한 이차돈을 기리기 위한 절이자, 신라의 불교 성지이에요.', 'Baekryulsa Temple, located on the slope of Geumgangsan Mountain in the north of Gyeongju, is a temple dedicated to Lee Cha-don, who was martyred for public Buddhism in the 14th year of King Beopheung of Silla (527), and is a sacred place for Buddhism in Silla.'),
    (184, 'summary', '신라 왕궁의 별궁과 연회 공간이었던 월지를 복원한 대표적인 야경 명소예요.', 'It is a representative night view attraction that has restored Wolji Pond, which was the annex and banquet space of the Silla royal palace.'),
    (184, 'intro', '동궁과 월지는 신라 왕궁의 별궁과 연못이 있던 자리예요. 문무왕 때 조성된 뒤 왕자가 머물고 나라의 경사나 귀한 손님을 위한 연회가 열렸으며, 발굴된 토기 조각의 명문을 근거로 오늘의 이름을 되찾았습니다.', 'Donggung Palace and Wolji Pond are where the annexes and ponds of the Silla royal palace were located. After it was built during the reign of King Munmu, the prince stayed and banquets were held for the nation''s auspicious guests and distinguished guests. It was given its current name based on the inscriptions on the excavated pottery fragments.'),
    (184, 'story', '연못은 어느 지점에서도 전체 모습이 한눈에 드러나지 않도록 굴곡지게 설계됐어요. 세 개의 섬과 굽이치는 물가, 복원 전각이 시선을 계속 바꾸게 하며 신라인이 궁원에 담은 풍경 감각을 보여 줍니다. 1970년대 발굴에서는 건물터와 생활 유물이 대량으로 확인되어 왕궁 생활을 복원하는 중요한 단서가 됐습니다.', 'The pond was designed to be curved so that the entire shape is not visible at a glance from any point. The three islands, the winding waterfront, and the restored pavilion keep changing the view, showing the sense of scenery that Silla people brought to the palace. Excavations in the 1970s revealed a large number of building sites and living artifacts, which served as important clues to restoring life in the royal palace.'),
    (184, 'tip', '해 지기 30분쯤 전에 입장하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 주말 저녁은 혼잡하므로 평일을 권하며, 연못 반영은 바람이 잔잔한 날 동쪽 산책로에서 선명하게 담깁니다.', 'If you enter about 30 minutes before sunset, you can see the daytime scenery and the moment the lights turn on. Weekdays are recommended as it is crowded on weekend evenings. The reflection of the pond can be clearly captured from the eastern promenade on a calm day.'),
    (184, 'did_you_know', '‘월지’라는 이름은 발굴된 토기 조각에 새겨진 글자 덕분에 확인됐어요. 기러기와 오리가 날아들어 훗날 ‘안압지’라고도 불렸답니다.', 'The name ‘Wolji’ was confirmed thanks to the letters engraved on the excavated pottery pieces. Geese and ducks flew in, and it was later called ‘Anapji.’'),
    (185, 'summary', '신라시대의 보리사터로 추정되는 곳에 남아 있는 전체 높이 4.36m, 불상 높이 2.44m의 석불좌상으로 현재 경주 남산에 있는 신라시대의 석불 가운데 가장 완벽하게 보존되어 있다.', 'It is a seated stone Buddha statue with an overall height of 4.36m and a Buddha statue height of 2.44m that remains at what is believed to be the site of Bodhi Temple from the Silla Dynasty. It is the most perfectly preserved stone Buddha from the Silla Dynasty currently located in Namsan, Gyeongju.'),
    (185, 'intro', '신라시대의 보리사터로 추정되는 곳에 남아 있는 전체 높이 4.36m, 불상 높이 2.44m의 석불좌상으로 현재 경주 남산에 있는 신라시대의 석불 가운데 가장 완벽하게 보존되어 있다. 작은 소라 모양의 머리칼을 한 머리에는 상투 모양의 머리(육계)가 높게 솟아 있으며, 둥근 얼굴에서는 은은하게 내면적인 웃음이 번지고 있다.', 'It is a seated stone Buddha statue with an overall height of 4.36m and a Buddha statue height of 2.44m that remains at what is believed to be the site of Bodhi Temple from the Silla Dynasty. It is the most perfectly preserved stone Buddha from the Silla Dynasty currently located in Namsan, Gyeongju. The head, which is shaped like a small conch, has a high topknot-shaped head (yukgye), and a subtle inner smile spreads across its round face.'),
    (185, 'story', '양 어깨를 감싸고 있는 옷은 힘없이 축 늘어진 느낌이며, 군데군데 평행한 옷주름을 새겨 넣었다.
손모양은 오른손을 무릎 위에 올려 손끝이 아래로 향하고 왼손은 배부분에 대고 있는 항마촉지인(降魔觸地印)인데 다소 연약해 보인다.
불상과는 별도로 마련해 놓은 광배(光背)는 매우 장식적인데, 광배 안에는 작은 부처와 보상화·덩쿨무늬가 화려하게 새겨져 있다.', 'The clothes covering both shoulders felt limp and droopy, and there were parallel wrinkles here and there.
The shape of the hand is that of placing the right hand on the knee, with the fingertips pointing down and the left hand resting on the abdomen, and it looks somewhat fragile.
The mandorla prepared separately from the Buddha statue is very decorative, with small Buddhas, bodhisattva flowers, and vine patterns engraved inside the mandorla.'),
    (185, 'tip', '경주 남산 미륵곡 석조여래좌상을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Stone Seated Buddha in Mireukgok, Namsan, Gyeongju, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (185, 'did_you_know', '신라시대의 보리사터로 추정되는 곳에 남아 있는 전체 높이 4.36m, 불상 높이 2.44m의 석불좌상으로 현재 경주 남산에 있는 신라시대의 석불 가운데 가장 완벽하게 보존되어 있어요.', 'It is a seated stone Buddha statue with a total height of 4.36m and a Buddha statue height of 2.44m that remains at the site of Bodhi Temple, believed to be from the Silla period. It is the most perfectly preserved stone Buddha statue from the Silla period currently in Namsan, Gyeongju.'),
    (186, 'summary', '경주 손 씨 큰 종가로 이 마을에서 시조가 된 양민공 손소(1433∼1484)가 조선 성종 15년(1484)에 지은 집이다.', 'This is a house built in the 15th year of King Seongjong''s reign (1484) in the Joseon Dynasty by Yang Min-gong Son So (1433-1484), who was the head of the Gyeongju Son clan and became the founder of this village.'),
    (186, 'intro', '경주 양동마을 송첨종택은 경주 손 씨 큰 종가로 이 마을에서 시조가 된 양민공 손소(1433∼1484)가 조선 성종 15년(1484)에 지은 집이다. 양민공의 아들 손중돈 선생과 외손인 이언적(1491∼1553) 선생이 태어난 곳이기도 하다.', 'Songcheomjongtaek in Yangdong Village, Gyeongju is a house built by Yang Min-gong Son So (1433-1484), the head family of the Gyeongju Son clan and the founder of this village, in the 15th year of King Seongjong''s reign (1484) in the Joseon Dynasty. It is also the birthplace of Yang Min-gong''s son, Son Jung-don, and his maternal grandson, Lee Eon-jeok (1491-1553).'),
    (186, 'story', '一자형 대문채 안에 ㅁ자형 안채가 있고 사랑채 뒤쪽 높은 곳에 신문(神門)과 사당이 있다.
안채는 지붕 옆면이 여덟 팔(八) 자 모양인 팔작지붕이고 사랑채는 지붕 옆면이 사람 인(人) 자 모양인 맞배지붕이다.
사랑방과 침방이 대청을 사이에 두고 ㄱ자형으로 놓여 있는 사랑채 뒤편 정원에는 수백 년 묵은 향나무가 있다.', 'There is a ㅁ-shaped main house inside the 一-shaped main gate, and there is a shrine and a shrine located high behind the sarangchae.
The main house has a gable roof with the sides of the roof shaped like the letters 八, and the sarangchae has a gable roof with the sides of the roof shaped like the character 人.
In the garden behind the sarangchae, where the sarangbang and bedroom are arranged in an L shape with the main hall in between, there is a juniper tree that is hundreds of years old.'),
    (186, 'tip', '경주 양동마을 송첨종택은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Songcheom Jongtaek in Yangdong Village, Gyeongju in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (186, 'did_you_know', '경주 양동마을 송첨종택은 경주 손 씨 큰 종가로 이 마을에서 시조가 된 양민공 손소(1433∼1484)가 조선 성종 15년(1484)에 지은 집이에요.', 'Songcheom Jongtaek in Yangdong Village, Gyeongju is a house built by Yang Min-gong Son So (1433-1484), the head family of the Gyeongju Son clan and the founder of this village, in the 15th year of King Seongjong''s reign (1484) in the Joseon Dynasty.'),
    (187, 'summary', '경주 평야를 가로지르는 서천과 북천, 두 하천이 만나는 금장대 북쪽 바위벽에 그려진 것이다.', 'It was painted on the rock wall north of Geumjangdae, where two rivers, Seocheon and Bukcheon, across the Gyeongju Plain meet.'),
    (187, 'intro', '경주석장동암각화는 경주 평야를 가로지르는 서천과 북천, 두 하천이 만나는 금장대 북쪽 바위벽에 그려진 것이다. 선사시대의 것으로 추측되는 이 그림은 강물에서 약 15m 높이의 수직 절벽 윗부분에 가로 약 2m, 세로 약 9m 되는 범위에 새겨졌으며, 추상적이고 기하학적으로 표현되어 있다.', 'The Gyeongju Seokjangdong petroglyphs were painted on the northern rock wall of Geumjangdae, where two rivers, Seocheon and Bukcheon, across the Gyeongju Plain meet. This painting, which is presumed to be from prehistoric times, was carved in an area of ​​about 2m wide and 9m tall on the top of a vertical cliff about 15m high above the river, and is expressed in an abstract and geometrical way.'),
    (187, 'story', '모두 27점이 확인됐는데, 기하문 8점, 검과 창의 요소를 갖춘 그림 11점, 발자국 4점, 여성기 3점, 배 1점, 그외 동물 모습과 해석이 어려운 그림 등이 있다.
서로 조금씩 형태를 달리하고 있지만 기본은 방패 모양과 도토리 모양, 꽃 모양으로 나눌 수 있는데, 이 가운데 도토리 모양과 꽃 모양의 그림은 다른 지역의 바위 그림에서는 볼 수 없는 이 지역만의 독특한 특색이다.
특히 검과 결합된 여성기의 그림 등은 칠포리의 영향을 많이 받은 것으로 추정된다.', 'A total of 27 pieces were identified, including 8 geometric patterns, 11 paintings with sword and spear elements, 4 footprints, 3 female genitalia, 1 pear, and other animal figures and paintings that are difficult to interpret.
The shapes are slightly different, but the basics can be divided into shield shapes, acorn shapes, and flower shapes. Among these, the acorn-shaped and flower-shaped paintings are a unique feature unique to this region that cannot be seen in rock paintings from other regions.
In particular, it is presumed that the paintings of the female genitalia combined with the sword were greatly influenced by Chilpori.'),
    (187, 'tip', '경주석장동암각화을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Seokjangdong Petroglyphs, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (187, 'did_you_know', '선사시대의 것으로 추측되는 이 그림은 강물에서 약 15m 높이의 수직 절벽 윗부분에 가로 약 2m, 세로 약 9m 되는 범위에 새겨졌으며, 추상적이고 기하학적으로 표현되어 있어요.', 'This painting, which is presumed to be from prehistoric times, was carved in an area of about 2m wide and 9m tall on the top of a vertical cliff about 15m high above the river, and is expressed in an abstract and geometric way.'),
    (188, 'summary', '경상북도 경주시 외동읍에 자리 잡은 콘도형 리조트이다.', 'It is a condominium-type resort located in Oedong-eup, Gyeongju-si, Gyeongsangbuk-do.'),
    (188, 'intro', '성호리조트는 경상북도 경주시 외동읍에 자리 잡은 콘도형 리조트이다. 140여 개의 객실과 기업 모임이나 세미나, 예식홀로 이용 가능한 소형과 대형 연회장이 있다.', 'Seongho Resort is a condominium-type resort located in Oedong-eup, Gyeongju-si, Gyeongsangbuk-do. There are about 140 rooms and small and large banquet halls that can be used for corporate meetings, seminars, and wedding halls.'),
    (188, 'story', '객실은 패밀리룸, 슈페리어룸, 엠버서더 스위트, 디럭스 스위트, 로열 스위트 등을 갖추었고 부대시설로는 연회장을 비롯해 야외 수영장, 승마장, 휘트니스 클럽, 레스토랑, 편의점, 카페, 사우나, 노래연습장, 바비큐장 등이 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 성호리조트은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Rooms include family rooms, superior rooms, ambassador suites, deluxe suites, and royal suites, and auxiliary facilities include a banquet hall, an outdoor swimming pool, horseback riding, a fitness club, a restaurant, a convenience store, a cafe, a sauna, a karaoke room, and a barbecue area.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Seongho Resort leaves a different memory for each person who visits Gyeongju.'),
    (188, 'tip', '성호리조트에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Seongho Resort, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (188, 'did_you_know', '140여 개의 객실과 기업 모임이나 세미나, 예식홀로 이용 가능한 소형과 대형 연회장이 있어요.', 'There are about 140 rooms and small and large banquet halls that can be used for corporate meetings, seminars, and wedding halls.'),
    (189, 'summary', '경주시 산내면에 있는 카라반 겸 펜션이다.', 'It is a caravan and pension located in Sannae-myeon, Gyeongju-si.'),
    (189, 'intro', '사나래카라반펜션 산내점은 경주시 산내면에 있는 카라반 겸 펜션이다. 카라반은 모두 6개가 있고 미국 정통 스타일과 한국식 두 가지 타입 중에 고를 수 있다.', 'Sanarae Caravan Pension Sannae Branch is a caravan and pension located in Sannae-myeon, Gyeongju-si. There are six caravans in total, and you can choose between two types: American or Korean style.'),
    (189, 'story', '계곡은 물론 별도의 야외수영장이 있어 여름에 아이들과 물놀이하기 좋다.
주소지는 경주시 산내면으로, 경주 관광은 물론이고 거리적으로 가까운 청도 운문산, 운문사 관광도 편리하다.
봄에는 벚꽃이 계곡을 따라 만개하고, 가을에는 단풍이 절경이다.', 'There is a separate outdoor swimming pool in the valley, so it is great for playing in the water with children in the summer.
The address is Sannae-myeon, Gyeongju-si, and it is convenient not only for sightseeing in Gyeongju, but also for sightseeing in Unmunsan Mountain and Unmunsa Temple in Cheongdo, which are located close by.
In spring, cherry blossoms are in full bloom along the valley, and in fall, the autumn leaves are a spectacular sight.'),
    (189, 'tip', '사나래카라반펜션 산내점에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Sanarae Caravan Pension Sannae branch, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (189, 'did_you_know', '봄에는 벚꽃이 계곡을 따라 만개하고, 가을에는 단풍이 절경이에요.', 'In spring, cherry blossoms are in full bloom along the valley, and in fall, the autumn leaves are spectacular.'),
    (190, 'summary', '오글오글 글램핑은 경북 경주시 산내면에 자리 잡고 있다.', 'Ogeul Ogeul Glamping is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (190, 'intro', '오글오글 글램핑은 경북 경주시 산내면에 자리 잡고 있다. 경주시청을 기점으로 33㎞가량 떨어졌다.', 'Ogeul Ogeul Glamping is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 33km away from Gyeongju City Hall.'),
    (190, 'story', '자동차에 몸을 싣고 용담로, 건포산업로, 단석로를 차례로 달리면 닿는다.
도착까지 소요되는 시간은 40분 안팎이다.
이곳은 해발 250m 산 중턱에 터를 잡았다.', 'You can get there by getting in a car and driving along Yongdam-ro, Geonpo Industrial-ro, and Danseok-ro in order.
It takes about 40 minutes to arrive.
This place was built on a hillside 250 meters above sea level.'),
    (190, 'tip', '오글오글오토캠핑장은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'At Ogeul Ogeul Auto Camping Site, the site type and equipment provided may vary from site to site. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (190, 'did_you_know', '경주시청을 기점으로 33㎞가량 떨어졌다고 해요.', 'It is said to be about 33km away from Gyeongju City Hall.'),
    (191, 'summary', '청석들 오토캠핑은 경상북도 경주시 산내면에 위치한 캠핑장으로 자리 잡고 있다.', 'Cheongseokdeul Auto Camping is a camping site located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (191, 'intro', '청석들 오토캠핑은 경상북도 경주시 산내면에 위치한 캠핑장으로 자리 잡고 있다. 경주 시청을 기점으로 약 40㎞가량 떨어진 곳으로 맑은 계곡과 울창한 숲이 공존하는 공간이다.', 'Cheongseokdeul Auto Camping is a camping site located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 40km away from Gyeongju City Hall and is a space where clear valleys and dense forests coexist.'),
    (191, 'story', '계곡 물놀이와 숲 속 체험을 함께 할 수 있어 휴가철이면 찾는 이들이 많다.
캠핑장은 자동차 야영장 27면을 갖추고 있는데 이 가운데 25면은 파쇄석, 나머지는 데크로 이뤄졌다.
개인 트레일러와 카라반도 입장이 가능하다.', 'Many people visit during the vacation season because they can enjoy swimming in the valley and experiencing the forest together.
The campsite has 27 car campsites, 25 of which are made of crushed stone and the rest are decks.
Personal trailers and caravans are also permitted.'),
    (191, 'tip', '청석들오토캠핑에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Cheongseokdeul Auto Camping, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (191, 'did_you_know', '경주 시청을 기점으로 약 40㎞가량 떨어진 곳으로 맑은 계곡과 울창한 숲이 공존하는 공간이에요.', 'It is about 40km away from Gyeongju City Hall and is a space where clear valleys and dense forests coexist.'),
    (192, 'summary', '강동리조트는 경상북도 경주에 위치한 골프장, 콘도미니엄, 워터파크 등을 운영하는 사계절 종합 휴양리조트이다.', 'Gangdong Resort is a four-season comprehensive vacation resort located in Gyeongju, Gyeongsangbuk-do that operates a golf course, condominiums, and a water park.'),
    (192, 'intro', '강동리조트는 경상북도 경주에 위치한 골프장, 콘도미니엄, 워터파크 등을 운영하는 사계절 종합 휴양리조트이다. 강동리조트 프라이빗콘도의 콘셉트는 언덕 위의 성［城］이다.', 'Gangdong Resort is a four-season comprehensive vacation resort located in Gyeongju, Gyeongsangbuk-do that operates a golf course, condominiums, and a water park. The concept of Gangdong Resort Private Condominium is a castle on a hill.'),
    (192, 'story', '다채로운 자연의 일부가 되도록 우아함은 물론, 현대적인 공간미학까지 고려했다.
누구에게도 방해받지 않고 평온한 휴식을 꿈꾸는 공간이 될 수 있도록 고민하고 또 노력했다.
강동리조트는 이스트섬의 모아이 석상과 석굴암의 조각, 이스탄불 톱카프 궁전, 프랑스의 상보로 성 등 원형질 석재를 주재료로 선정했다.', 'We considered not only elegance but also modern spatial aesthetics to become part of the colorful nature.
We thought and worked hard to create a space where we could dream of peaceful rest without being disturbed by anyone.
Gangdong Resort selected protoplasmic stones as its main materials, such as the Moai statues of East Island, the sculptures of Seokguram Grotto, Topkapi Palace in Istanbul, and Sangboro Castle in France.'),
    (192, 'tip', '강동리조트 프라이빗콘도에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you are planning to play in the water at Gangdong Resort Private Condo, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (192, 'did_you_know', '전체 외형의 웅장함은 시간이 지날수록 전통이 깊어지고 명예로움이 빛나는 느낌을 받는다고 해요.', 'The grandeur of the overall appearance is said to give a feeling of deepening tradition and shining honor as time passes.'),
    (193, 'summary', '경주 대릉원 안에 위치한 천마총은 5세기 말에서 6세기 초에 축조된 것으로 추정되는 통일 이전 신라의 고분이다.', 'Cheonmachong, located inside Daereungwon in Gyeongju, is a tomb from the pre-unification Silla Dynasty that is believed to have been built in the late 5th or early 6th century.'),
    (193, 'intro', '경주 대릉원 안에 위치한 천마총은 5세기 말에서 6세기 초에 축조된 것으로 추정되는 통일 이전 신라의 고분이다. 1973년에 발굴되었으며, 신라 특유의 돌무지덧널무덤 형태를 하고 있다.', 'Cheonmachong, located inside Daereungwon in Gyeongju, is a tomb from the pre-unification Silla Dynasty that is believed to have been built in the late 5th or early 6th century. It was excavated in 1973 and is in the form of a stone mound tomb, unique to Silla.'),
    (193, 'story', '무덤은 높이 12.7m, 지름 50m 규모로 봉토 안에는 냇가의 돌로 쌓은 적석층이 있으며 적석층 내부에는 길이 6.5m, 너비 4.2m, 높이 2.1m의 나무로 만든 방이 있고 그 중앙에 목관을 두어 시신을 안치했다.
천마총은 대릉원 고분군 가운데 유일하게 일반에 공개된 고분으로 인근의 황남대총을 발굴하기 전에 시범적으로 조사되었다.
당시 기술로는 황남대총처럼 거대한 규모의 무덤을 바로 발굴하기 어려웠기 때문이다.', 'The tomb is 12.7m high and 50m in diameter. Inside the tomb is a layer of stones made from stones from a stream. Inside the layer of stones there is a room made of wood with a length of 6.5m, a width of 4.2m, and a height of 2.1m, and a wooden coffin is placed in the center to place the body.
Cheonmachong is the only tomb among the Daereungwon tombs that is open to the public, and was investigated on a pilot basis before excavating the nearby Hwangnamdaechong.
This is because it was difficult to immediately excavate a tomb as large as Hwangnamdaechong with the technology of the time.'),
    (193, 'tip', '천마총(대릉원)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Cheonmachong (Daereungwon), check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (193, 'did_you_know', '1973년에 발굴되었으며, 신라 특유의 돌무지덧널무덤 형태를 하고 있어요.', 'It was excavated in 1973 and is in the form of a stone mound tomb, unique to Silla.'),
    (194, 'summary', '2025년 개항 100주년을 맞이하는 경주 최대의 항구이다.', 'It is the largest port in Gyeongju, celebrating the 100th anniversary of its opening in 2025.'),
    (194, 'intro', '감포항은 2025년 개항 100주년을 맞이하는 경주 최대의 항구이다. 항구 주변에는 항상 고깃배들이 드나들고, 활어 위판장에서는 매일 신선한 생선이 경매로 오간다.', 'Gampo Port is the largest port in Gyeongju, celebrating its 100th anniversary in 2025. Fishing boats always come and go around the port, and fresh fish are auctioned every day at the live fish market.'),
    (194, 'story', '감포항 방파제가 있는 곳에 조성된 감포 해상공원의 경우 2018년 조성된 곳으로 해안데크, 바람개비 동산, 감포항 조형물 등을 갖추고 있다.
또한 감포항 방파제에는 감은사지 3층 석탑을 음각화한 아름다운 등대가 우뚝 솟아있고, 바다낚시 포인트로 유명해 낚시를 즐기기에 좋은 곳이다.
주변 관광지로는 전촌 용굴, 오류고아라 해변, 전촌항 등이 있어 함께 둘러볼 수 있다.', 'In the case of Gampo Marine Park, which was created in 2018 where the Gampo Port breakwater is located, it features a coastal deck, pinwheel hill, and Gampo Port sculptures.
In addition, a beautiful lighthouse with an engraving of the three-story stone pagoda of Gameunsaji Temple stands tall on the breakwater of Gampo Port, and it is famous as a sea fishing spot, making it a good place to enjoy fishing.
Nearby tourist attractions include Jeonchon Yonggul, Oryu Goara Beach, and Jeonchon Port, which can be explored together.'),
    (194, 'tip', '감포항에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Gampo Port, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (194, 'did_you_know', '감포항은 2025년 개항 100주년을 맞이하는 경주 최대의 항구이에요.', 'Gampo Port is the largest port in Gyeongju, celebrating its 100th anniversary in 2025.'),
    (195, 'summary', '남녀노소 즐길 수 있는 눈썰매와 빙어잡기 체험, 정글카누체험 등 다양한 놀거리가 가득한 테마파크이다.', 'It is a theme park full of various activities that people of all ages can enjoy, such as snow sledding, smelt catching experience, and jungle canoeing experience.'),
    (195, 'intro', '남녀노소 즐길 수 있는 눈썰매와 빙어잡기 체험, 정글카누체험 등 다양한 놀거리가 가득한 테마파크이다. 아이들과 함께 토끼 마을에서 건초를 주기도 하고 물 위에서 카누를 타며 떠다니는 오리를 보는 것도 겨울철 가족나들이에 으뜸이다.', 'It is a theme park full of various activities that people of all ages can enjoy, such as snow sledding, smelt catching experience, and jungle canoeing experience. Feeding hay at Rabbit Village with your children, riding a canoe on the water, and watching ducks floating around are great family outings in the winter.'),
    (195, 'story', '테마파크의 곳곳이 겨울왕국에 온 듯이 빙벽이 많이 보이는데 곳곳이 포토존이다.
야영장과 숙박시설 또한 구비되어 있으며, 모닥불에서 구워먹는 밤과 고구마 체험도 아이들이 좋아한다.
입장료와 체험비는 별도이며 애완동물은 동반이 불가하다.', 'There are many ice walls everywhere in the theme park, as if you were in a winter wonderland, and there are photo zones everywhere.
Camping sites and lodging facilities are also available, and children also enjoy roasting chestnuts and sweet potatoes over a bonfire.
Admission and experience fees are separate, and pets are not allowed.'),
    (195, 'tip', '국민힐링파크은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'National Healing Park''s site type and provided equipment may vary from location to location. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (195, 'did_you_know', '입장료와 체험비는 별도이며 애완동물은 동반이 불가하다고 해요.', 'Admission and experience fees are separate, and pets are not allowed.'),
    (196, 'summary', '신라 21대 소지왕이 서기 488년 정월 보름날 행차에 나설 때다.', 'It was when King Soji, the 21st king of Silla, went on a royal journey on the full moon day of the first month of 488 AD.'),
    (196, 'intro', '신라 21대 소지왕이 서기 488년 정월 보름날 행차에 나설 때다. 까마귀와 쥐가 와서 울더니 쥐가 말했다.', 'It was when King Soji, the 21st king of Silla, went on a royal journey on the full moon day of the first month of 488 AD. The crow and the mouse came and cried, and the mouse said.'),
    (196, 'story', '“이 까마귀 가는 곳을 살피십시오” 왕은 장수를 시켜 따라가게 했다.
동남산 양피촌 못 가에 이르러 장수는 그만 까마귀를 놓쳐 버렸다.
이때 갑자기 못 가운데서 풀 옷을 입은 한 노인이 봉투를 들고 나타났다.', '“Watch where this crow goes.” The king ordered his general to follow him.
When the general reached the pond of Sheep Village on Dongnam Mountain, he lost sight of the crow.
At this time, an old man dressed in grass suddenly appeared from the middle of the pond, holding an envelope.'),
    (196, 'tip', '경주 서출지을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Seochulji, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (196, 'did_you_know', '신라 21대 소지왕이 서기 488년 정월 보름날 행차에 나설 때다고 해요.', 'It is said that King Soji, the 21st king of Silla, went on a royal journey on the full moon day of the first month of 488 AD.'),
    (197, 'summary', '1998년 세계 최초로 문화예술을 주제로 한 문화박람회 ''경주세계엑스포''가 열린 곳이다.', 'In 1998, the world''s first cultural expo with the theme of culture and arts, ''Gyeongju World Expo'', was held here.'),
    (197, 'intro', '경주엑스포대공원은 1998년 세계 최초로 문화예술을 주제로 한 문화박람회 ''경주세계엑스포''가 열린 곳이다. 이후 20여 년간 10차례에 걸쳐 경주세계엑스포의 개최 장소로 한국인의 문화 자긍심을 높이고 인류 문화 발전에 이바지하였다.', 'Gyeongju Expo Grand Park is where the world''s first culture and arts-themed cultural expo, ''Gyeongju World Expo'', was held in 1998. Since then, it has been the venue for the Gyeongju World Expo 10 times over the past 20 years, raising Koreans'' cultural pride and contributing to the development of human culture.'),
    (197, 'story', '현재는 다양한 전시·영상·공연·체험 문화콘텐츠를 바탕으로 연인과 친구, 가족이 함께 찾고 즐기는 경주의 명소이다.
주요 시설로는 경주타워, 경주솔거미술관, 비움명상길, 루미나이트 등이 있다.
이 외에도 타임리스 미디어아트, 자연사 박물관, 경주세계문화엑스포기념관 등 다양한 시설이 갖추어져 있다.', 'Currently, it is a famous place in Gyeongju that lovers, friends, and families can visit and enjoy together based on various exhibitions, videos, performances, and experiential cultural contents.
Major facilities include Gyeongju Tower, Gyeongju Solgeo Art Museum, Bium Meditation Trail, and Luminite.
In addition, there are various facilities such as Timeless Media Art, Natural History Museum, and Gyeongju World Culture Expo Memorial Hall.'),
    (197, 'tip', '경주엑스포대공원에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At Gyeongju Expo Grand Park, choose the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (197, 'did_you_know', '경주엑스포대공원은 1998년 세계 최초로 문화예술을 주제로 한 문화박람회 ''경주세계엑스포''가 열린 곳이에요.', 'Gyeongju Expo Grand Park is where the world''s first culture and arts-themed cultural expo, ''Gyeongju World Expo'', was held in 1998.'),
    (198, 'summary', '보문정은 CNN에서 ‘한국의 비경’으로 소개된 적이 있을 정도로 아름다운 풍광을 자랑한다.', 'Bomunjeong boasts such beautiful scenery that it was once introduced as ‘Korea’s secret place’ on CNN.'),
    (198, 'intro', '보문정은 CNN에서 ‘한국의 비경’으로 소개된 적이 있을 정도로 아름다운 풍광을 자랑한다. 팔각 정자와 2개의 연못 주위로 벚나무, 단풍나무 등이 식재되어 어느 계절 하나 빼놓지 않고 풍경을 감상해야 할 곳이다.', 'Bomunjeong boasts such beautiful scenery that it was once introduced as ‘Korea’s secret place’ on CNN. Cherry trees and maple trees are planted around the octagonal pavilion and two ponds, making it a place to enjoy the scenery in any season.'),
    (198, 'story', '봄이면 보문정 주변을 수놓는 새하얀 벚꽃들로 빼어난 경치를 선사한다.
특히, 수양버드나무처럼 꽃가지가 축 늘어진 수양벚꽃을 볼 수 있어 인기가 좋다.
여름이면 보문정 앞 연못에 수련이 그득 피어나 절경을 더한다.', 'In spring, the pure white cherry blossoms that decorate the area around Bomunjeong provide a spectacular view.
In particular, it is popular because you can see weeping cherry blossoms with drooping flower branches like weeping willows.
In the summer, water lilies are in full bloom in the pond in front of Bomunjeong, adding to the spectacular scenery.'),
    (198, 'tip', '보문정(경주)에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Bomunjeong (Gyeongju), rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and pavilions and the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (198, 'did_you_know', '어느 계절이건 아름다운 덕에 이곳은 사진작가들이 사랑하는 장소로도 손꼽힌다고 해요.', 'Because it is beautiful no matter what season it is, this place is said to be a favorite spot for photographers.'),
    (199, 'summary', '신라시대 수도인 왕경지구의 하천 범람을 막기 위해 경주 명활산성에서 분황사까지 5리, 즉 2㎞에 걸쳐 ‘오리수’라는 숲을 조성했다.', 'To prevent river flooding in the Wanggyeong district, the capital of the Silla Dynasty, a forest called ‘Orisu’ was created over 5 ri, or 2 km, from Myeonghwalsanseong Fortress in Gyeongju to Bunhwangsa Temple.'),
    (199, 'intro', '신라시대 수도인 왕경지구의 하천 범람을 막기 위해 경주 명활산성에서 분황사까지 5리, 즉 2㎞에 걸쳐 ‘오리수’라는 숲을 조성했다. 보문관광단지 입구에 자리한 신라 왕경 숲이 바로 그 오리수를 재현해 조성한 숲이다.', 'To prevent river flooding in the Wanggyeong district, the capital of the Silla Dynasty, a forest called ‘Orisu’ was created over 5 ri, or 2 km, from Myeonghwalsanseong Fortress in Gyeongju to Bunhwangsa Temple. Silla Wanggyeong Forest, located at the entrance to Bomun Tourist Complex, is a forest created by replicating the duck tree.'),
    (199, 'story', '신라 왕경 숲은 신라시대 치수사업의 역사를 간직하고 있다.
1,500년 전 서라벌의 왕들이 거닐던 숲으로 꾸며진 신라 왕경 숲은 지난 2007년 세계 문화엑스포 개최와 함께 일반에 공개됐다.
구황교 쪽에 1차로 조성된 왕경숲이 있고, 숲머리음식촌 쪽에도 2차로 숲이 있다.', 'Silla Wanggyeong Forest preserves the history of flood control projects during the Silla Dynasty.
Silla Wanggyeong Forest, decorated as a forest where the kings of Seorabeol roamed 1,500 years ago, was opened to the public in 2007 with the hosting of the World Culture Expo.
There is a primary Wanggyeong Forest on the Guhwang Bridge side, and a secondary forest on the Forest Meori Food Village side.'),
    (199, 'tip', '신라왕경숲은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk through Silla Wanggyeong Forest in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (199, 'did_you_know', '신라시대 수도인 왕경지구의 하천 범람을 막기 위해 경주 명활산성에서 분황사까지 5리, 즉 2㎞에 걸쳐 ‘오리수’라는 숲을 조성했다고 해요.', 'It is said that a forest called ‘Orisu’ was created over 5 ri, or 2 km, from Myeonghwalsanseong Fortress in Gyeongju to Bunhwangsa Temple to prevent river flooding in the Wanggyeong district, the capital of the Silla Dynasty.'),
    (200, 'summary', '경주 시가지 중심부에 신라 이후의 천년 경주를 상징하는 주요 유적인 경주읍성이 자리해 있다.', 'In the center of Gyeongju city, Gyeongju Eupseong Fortress is located, a major relic symbolizing the thousand years of Gyeongju since the Silla Dynasty.'),
    (200, 'intro', '경주 시가지 중심부에 신라 이후의 천년 경주를 상징하는 주요 유적인 경주읍성이 자리해 있다. 신라 시대에는 월성이 중심이었다면 고려 이후에는 경주 읍성으로 중심이 옮겨졌다.', 'In the center of Gyeongju city, Gyeongju Eupseong Fortress is located, a major relic symbolizing the thousand years of Gyeongju since the Silla Dynasty. During the Silla period, Wolseong was the center, but after Goryeo, the center was moved to Gyeongju Eupseong.'),
    (200, 'story', '고려와 조선에 이어지기까지 행정, 생활, 군사기능이 모여 있던 경주의 심장부였다.
고려 시대에 처음 축조된 이래, 조선 시대에 여러 번 고쳐지었다는 기록이 있으며 현재 복원된 모습은 조선 영조 21년(1745)에 중수한 모습이다.
영조 때 중수한 경주읍성은 성곽 둘레가 2.3㎞에 달했고, 동서남북에 성내로 통하는 사대문이 자리했다고 전한다.', 'It was the heart of Gyeongju, where administrative, living, and military functions were gathered until the Goryeo and Joseon Dynasties.
Since it was first built during the Goryeo Dynasty, there are records showing that it was renovated several times during the Joseon Dynasty, and its current restored appearance was renovated in the 21st year of King Yeongjo''s reign (1745).
It is said that Gyeongju-eupseong Fortress, which was rebuilt during the reign of King Yeongjo, had a perimeter of 2.3km, and that there were four main gates leading into the fortress to the north, south, east, and west.'),
    (200, 'tip', '경주읍성을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Eupseong Fortress, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (200, 'did_you_know', '고려 시대에 처음 축조된 이래, 조선 시대에 여러 번 고쳐지었다는 기록이 있으며 현재 복원된 모습은 조선 영조 21년(1745)에 중수한 모습이에요.', 'Since it was first built during the Goryeo Dynasty, there are records showing that it was renovated several times during the Joseon Dynasty, and its current restored appearance was renovated in the 21st year of King Yeongjo''s reign (1745).'),
    (201, 'summary', '캠프 아이엔지는 경북 경주시 강동면에 자리 잡고 있다.', 'Camp ING is located in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (201, 'intro', '캠프 아이엔지는 경북 경주시 강동면에 자리 잡고 있다. 경주시청을 기점으로 13㎞가량 떨어졌다.', 'Camp ING is located in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 13km away from Gyeongju City Hall.'),
    (201, 'story', '자동차에 몸을 싣고 양정로와 산업로를 차례로 달리면 닿는다.
도착까지 걸리는 시간은 20분 안팎이다.
이곳은 숲 속에 위치한 폐교를 감성적인 캠핑장으로 탈바꿈한 공간이다.', 'You can get there by getting in a car and driving along Yangjeong-ro and Industrial Road in turn.
It takes about 20 minutes to arrive.
This is a space where an abandoned school located in the forest has been transformed into an emotional camping site.'),
    (201, 'tip', '캠프 아이엔지(ING)에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Camp ING. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (201, 'did_you_know', '경주시청을 기점으로 13㎞가량 떨어졌다고 해요.', 'It is said to be about 13km away from Gyeongju City Hall.'),
    (202, 'summary', '경주 보문관광단지 내 조성된 대중골프장이다.', 'It is a public golf course built within the Bomun Tourist Complex in Gyeongju.'),
    (202, 'intro', '보문골프클럽은 경주 보문관광단지 내 조성된 대중골프장이다. 체육시설의 설치, 이용에 관한 법령에 의거 골프 대중화와 국민 건강 증진 및 여가선용에 이바지하기 위해 조성되었다.', 'Bomun Golf Club is a public golf course built within the Bomun Tourist Complex in Gyeongju. It was created to contribute to the popularization of golf, improvement of national health, and leisure use in accordance with the Act on the Installation and Use of Sports Facilities.'),
    (202, 'story', '다이나믹하고 골퍼들의 도전의욕을 일으키는 자연 그대로를 살린 코스로 설계를 하였다.
클럽하우스와 대식당, 그늘집, 락커룸, 프로샵 등의 편의시설을 갖추고 있다.
오늘의 보문골프클럽은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'It was designed as a course that takes advantage of the natural environment that is dynamic and arouses golfers'' desire to challenge themselves.
It is equipped with convenient facilities such as a clubhouse, large cafeteria, shade house, locker room, and pro shop.
Today''s Bomun Golf Club leaves a different memory for each person who visits Gyeongju.'),
    (202, 'tip', '보문골프클럽에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Bomun Golf Club. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (202, 'did_you_know', '보문골프클럽은 경주 보문관광단지 내 조성된 대중골프장이에요.', 'Bomun Golf Club is a public golf course built within the Bomun Tourist Complex in Gyeongju.'),
    (203, 'summary', '경주 초우 오토캠핑장은 경상북도 경주시내 인근에 자리하고 있다.', 'Gyeongju Chow Auto Camping Site is located near downtown Gyeongju, Gyeongsangbuk-do.'),
    (203, 'intro', '경주 초우 오토캠핑장은 경상북도 경주시내 인근에 자리하고 있다. 경부고속도로에서 경주 IC로 나와 경주박물관 사거리를 거쳐 울산 방면 국도 7호선을 타고 진행하다', 'Gyeongju Chow Auto Camping Site is located near downtown Gyeongju, Gyeongsangbuk-do. From the Gyeongbu Expressway, exit at the Gyeongju IC, pass the Gyeongju Museum intersection and take National Route 7 toward Ulsan.'),
    (203, 'story', '보면 ‘천선사’ 입석이 보인다.
거기서 우회전하여 농로(둑길)로 진입하면 큰 기와집이 보인다.
이곳이 어성초 농장을 겸한 캠핑장이다.', 'If you look, you can see the standing stone of ‘Cheonseonsa Temple.’
If you turn right there and enter the farm road (causeway), you will see a large tile-roofed house.
This is a camping site that also serves as a Houttuynia cordata farm.'),
    (203, 'tip', '경주초우오토캠핑장에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First, check the age, clothing, and equipment requirements for the activity you want to experience at Gyeongju Chow Auto Camping Site. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (203, 'did_you_know', '사이트는 A, B, C 구역으로 나뉘며 오토캠핑 사이트 41개가 마련되어 있어요.', 'The site is divided into zones A, B, and C and has 41 auto camping sites.'),
    (204, 'summary', '펜션600은 경북 경주시 동방동에 자리 잡았다.', 'Pension 600 is located in Dongbang-dong, Gyeongju-si, Gyeongsangbuk-do.'),
    (204, 'intro', '펜션600은 경북 경주시 동방동에 자리 잡았다. 경주시청을 기점으로 6㎞ 정도 자동차로 운전하면 15분 안팎에 도착한다.', 'Pension 600 is located in Dongbang-dong, Gyeongju-si, Gyeongsangbuk-do. If you drive 6km from Gyeongju City Hall, you will arrive there in about 15 minutes.'),
    (204, 'story', '이곳 캠핑장은 숲으로 둘러싸여 있어 자연 그대로를 체감할 수 있다.
더불어 카페, 세미나실, 수영장, 노래방, 족구장, 당구장 등 알찬 부대시설이 있어 캠핑 외에도 즐길 거리가 많다.
캠핑장에는 카라반 7대가 있다.', 'This campsite is surrounded by a forest, so you can experience nature as it is.
In addition, there are many auxiliary facilities such as a cafe, seminar room, swimming pool, karaoke room, foot volleyball court, and billiards room, so there are many things to enjoy other than camping.
There are 7 caravans at the campsite.'),
    (204, 'tip', '펜션600 캠핑장에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Pension 600 Camping Site. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (204, 'did_you_know', '펜션600은 경북 경주시 동방동에 자리 잡았다고 해요.', 'Pension 600 is said to be located in Dongbang-dong, Gyeongju-si, Gyeongbuk.'),
    (205, 'summary', '경북 경주시 양남면 신대리에 자리 잡았다.', 'It is located in Sindae-ri, Yangnam-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (205, 'intro', '라라캠핑장은 경북 경주시 양남면 신대리에 자리 잡았다. 경주시청을 기점으로 40㎞가량 떨어졌다.', 'Lara Camping Site is located in Sindae-ri, Yangnam-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 40km away from Gyeongju City Hall.'),
    (205, 'story', '자동차를 타고 신대로와 서왕길을 번갈아 달리면 닿는다.
도착까지 걸리는 시간은 60분 안팎이다.
캠핑장은 산속 숲에 위치한 덕분에 더없이 자연친화적인 느낌이다.', 'You can reach it by driving alternately between Sindae-ro and Seowang-gil.
It takes about 60 minutes to arrive.
Because the campsite is located in a mountain forest, it has an extremely nature-friendly feel.'),
    (205, 'tip', '라라캠핑장에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Lara Camping Site, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (205, 'did_you_know', '경주시청을 기점으로 40㎞가량 떨어졌다고 해요.', 'It is said to be about 40km away from Gyeongju City Hall.'),
    (206, 'summary', '경북 경주시에 위치한 빵집이다.', 'It is a bakery located in Gyeongju-si, Gyeongbuk.'),
    (206, 'intro', '이상복명과 경주빵 숲머리점는 경북 경주시에 위치한 빵집이다. 이상복 명과의 빵은 보존료, 인공감미료를 사용하지 않고 천연 재료만을 사용하여 많은 사람들이 찾는 빵이다.', 'Lee Sangbokmyeong and Gyeongju Bread Forest Meori Branch are bakeries located in Gyeongju, Gyeongbuk. Lee Sang-bok Myeong-Gwa''s bread is a bread that many people look for because it uses only natural ingredients without using preservatives or artificial sweeteners.'),
    (206, 'story', '오랜 기간 팥을 삶고 빵을 빚은 장인의 기술과 천연재료만을 사용하는 장인의 정신으로 맛은 기본, 건강까지 고려하여 만든 이상복의 빵은 경주의 대표 먹거리이다.
대표 메뉴는 이상복 경주빵으로 창시자의 기술에 대를 이어 전통의 맛을 그대로 담아낸 빵이다.
얇고 고소한 밀가루 외피에 은은하게 달콤한 국내산 팥앙금의 환상조화를 맛볼 수 있다.', 'Lee Sang-bok''s bread, made with both taste and health in mind, is a representative food of Gyeongju.
The representative menu item is Lee Sang-bok Gyeongju Bread, a bread that preserves the traditional taste by passing on the founder''s techniques for generations.
You can taste the fantastic harmony of the thin, savory flour crust and the slightly sweet domestic red bean paste.'),
    (206, 'tip', '이상복명과 경주빵 숲머리점은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Lee Sangbokmyeong and Gyeongju Bread Forest Meori branch in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (206, 'did_you_know', '이외에도 계피빵, 찰보리빵, 녹차빵 등 다양한 빵을 판매해요.', 'In addition, they sell a variety of breads such as cinnamon bread, glutinous barley bread, and green tea bread.'),
    (207, 'summary', '문희공 이세기 선생을 주벽으로 하고, 문효공 이천 선생, 송와공 이종윤을 배향하는 서원이다.', 'It is a seowon with Moon Hee-gong Lee Se-gi as its main wall, Mun Hyo-gong Lee Cheon, and Song Wa-gong Lee Jong-yoon are enshrined.'),
    (207, 'intro', '단구서원은 문희공 이세기 선생을 주벽으로 하고, 문효공 이천 선생, 송와공 이종윤을 배향하는 서원이다. 원래 송와공을 제향 하는 모현서당이 철종 13년(1862)에 건립되었는데, 고종 5년(1868)에 훼철되어 1983년에 단구서원을 창건하였다.', 'Dangu Seowon is a seowon with Moon Hee-gong Lee Se-gi as its main wall and Mun Hyo-gong Lee Cheon and Song Wa-gong Lee Jong-yoon are enshrined. Originally, Mohyeon Seodang, dedicated to Songwagong, was built in the 13th year of King Cheoljong''s reign (1862), but it was demolished in the 5th year of King Gojong''s reign (1868), and Dangu Seowon was founded in 1983.'),
    (207, 'story', '이세기는 고려 충렬왕 때 명신으로 문장에 능하였으며, 밀직부사, 예문관대제학, 동지춘추관사, 검교정승 등을 역임하였다.
이천은 이세기의 장자이며, 고려 충렬왕 25년(1299)에 국자시 장원하였고, 충혜왕 4년(1343)에 첨의평리상의 동지공거를 겸하였다.
충목왕 즉위에 원나라 사신으로 다녀와서 판밀직사사 겸 서연관이 되고, 곧 정당문학에 올랐다.', 'During the reign of King Chungnyeol of Goryeo, Lee Segi was a famous scholar and was skilled in writing, and served as Miljikbusa, Yemungwandaehak, Dongjichunchugwansa, and Geomgyojeongseung.
Icheon is the eldest son of the Isegi Dynasty. He was appointed Gukjasi Manor in the 25th year of King Chungryeol''s reign (1299) of Goryeo, and also served as Dongjigonggeo of Cheomuipyeongrisang in the 4th year of King Chunghye''s reign (1343).
He went to the throne of King Chungmok as an envoy to the Yuan Dynasty, became Panmiljiksa and Seoyeongwan, and soon rose to the rank of Jeongdangmunhak.'),
    (207, 'tip', '단구서원을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Dangu Seowon, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (207, 'did_you_know', '원래 송와공을 제향 하는 모현서당이 철종 13년(1862)에 건립되었는데, 고종 5년(1868)에 훼철되어 1983년에 단구서원을 창건했어요.', 'Originally, Mohyeon Seodang, dedicated to Songwagong, was built in the 13th year of King Cheoljong''s reign (1862), but it was demolished in the 5th year of King Gojong''s reign (1868), and Dangu Seowon was founded in 1983.'),
    (208, 'summary', '경주 낭산［狼山］의 기슭에 자리하고 있는 절터로 사천왕사와 마주하고 있다.', 'This temple site is located at the foot of Nangsan Mountain in Gyeongju and faces Sacheonwangsa Temple.'),
    (208, 'intro', '경주 낭산［狼山］의 기슭에 자리하고 있는 절터로 사천왕사와 마주하고 있다. 처음 지어진 때는 정확하지 않으나 신라 문무왕 또는 신문왕 때로 전한다.', 'This temple site is located at the foot of Nangsan Mountain in Gyeongju and faces Sacheonwangsa Temple. It is not clear when it was first built, but it is said to have been during the time of King Munmu or King Sinmun of Silla.'),
    (208, 'story', '현재 절터에는 동·서 목탑터와 그 북쪽으로 금당터와 강당터, 남쪽으로 중문터, 그리고 이를 둘러싼 회랑터가 남아 있어 통일신라시대 전형의 쌍탑 가람배치를 볼 수 있다.
이밖에 중문터 남쪽에 계단터가 잘 남아 있고 그 서쪽으로는 당간지주(보물)가 그대로 남아 있다.
이 절은 황룡사, 사천왕사, 황복사와 함께 경주의 중요한 사찰이었던 곳으로 그 의미가 크다.', 'Currently, at the temple site, the eastern and western wooden pagoda sites, the Geumdang site and the lecture hall site to the north, the Jungmun site to the south, and the corridor site surrounding it remain, showing the twin pagoda layout typical of the Unified Silla period.
In addition, the staircase remains well to the south of the Jungmun site, and the dangganjiju (treasure) remains intact to the west.
This temple has great significance as it was an important temple in Gyeongju along with Hwangnyongsa Temple, Sacheonwangsa Temple, and Hwangboksa Temple.'),
    (208, 'tip', '경주 망덕사지에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At Mangdeoksa Temple Site in Gyeongju, rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and pavilions and the mountains behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (208, 'did_you_know', '이 절은 황룡사, 사천왕사, 황복사와 함께 경주의 중요한 사찰이었던 곳으로 그 의미가 크다고 해요.', 'This temple is said to be of great significance as it was an important temple in Gyeongju along with Hwangnyongsa Temple, Sacheonwangsa Temple, and Hwangboksa Temple.'),
    (209, 'summary', '하이코 (HICO)는 한국 대표 관광단지인 경주 보문관광단지 내에 위치한 전시컨벤션센터로 HICO는 경주화백컨벤션센터(Hwabaek International Convention Center)의 영문명칭이며, 센터명칭은 신라시대 합좌제도인 ‘화백［和白］’에서 그 모티브를 가져왔다.', 'HICO is an exhibition and convention center located in Gyeongju Bomun Tourist Complex, Korea''s representative tourist complex. HICO is the English name of Gyeongju Hwabaek International Convention Center, and the name of the center takes its motif from ‘Hwabaek [和白］’, a sitting system in the Silla Dynasty.'),
    (209, 'intro', '하이코 (HICO)는 한국 대표 관광단지인 경주 보문관광단지 내에 위치한 전시컨벤션센터로 HICO는 경주화백컨벤션센터(Hwabaek International Convention Center)의 영문명칭이며, 센터명칭은 신라시대 합좌제도인 ‘화백［和白］’에서 그 모티브를 가져왔다. 화백은 만장일치에 의한 의결을 원칙으로 하는 합의체회의기구이다.', 'HICO is an exhibition and convention center located in Gyeongju Bomun Tourist Complex, Korea''s representative tourist complex. HICO is the English name of Gyeongju Hwabaek International Convention Center, and the name of the center takes its motif from ‘Hwabaek [和白］’, a sitting system in the Silla Dynasty. Hwabaek is a collegial body based on the principle of unanimous decision.'),
    (209, 'story', '한국 대표 관광단지인 보문관광단지 중심부에 위치하고 있어서 각종 행사와 숙박 및 관광을 한 장소에서 할 수 있는 큰 장점이 있다.
최첨단 회의 및 전시시설과 각종 편의시설은 다양한 행사를 성공적으로 개최할 수 있어서 주최자와 참가자를 위한 최상의 컨벤션 센터이다.
오늘의 경주화백컨벤션센터은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'It is located in the center of Bomun Tourist Complex, Korea''s representative tourist complex, so it has the great advantage of being able to hold various events, accommodations, and sightseeing in one place.
State-of-the-art conference and exhibition facilities and various convenience facilities can successfully host a variety of events, making it the best convention center for organizers and participants.
Today''s Gyeongju Hwabaek Convention Center leaves a different memory for each person who visits Gyeongju.'),
    (209, 'tip', '경주화백컨벤션센터을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Hwabaek Convention Center, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (209, 'did_you_know', '최첨단 회의 및 전시시설과 각종 편의시설은 다양한 행사를 성공적으로 개최할 수 있어서 주최자와 참가자를 위한 최상의 컨벤션 센터이에요.', 'State-of-the-art conference and exhibition facilities and various convenience facilities can successfully host a variety of events, making it the best convention center for organizers and participants.'),
    (210, 'summary', '골굴암의 높은 암벽에 있는 자연굴을 이용하여 만든 12개의 석굴 중 가장 윗부분에 있는 마애여래좌상이다.', 'This is the rock-carved seated Buddha statue at the top of the 12 stone caves created using natural caves on the high rock wall of Golgulam Grotto.'),
    (210, 'intro', '골굴암의 높은 암벽에 있는 자연굴을 이용하여 만든 12개의 석굴 중 가장 윗부분에 있는 마애여래좌상이다. 조선시대 겸재 정선이 그린 ‘골굴석굴’에는 목조전실이 묘사되었으나 지금은 바위에 흔적만 남아있다.', 'This is the rock-carved seated Buddha statue at the top of the 12 stone caves created using natural caves on the high rock wall of Golgulam Grotto. In the ‘Golgul Grottoes’ painted by Gyeomjae Jeong Seon during the Joseon Dynasty, a wooden anteroom was depicted, but now only traces remain on the rocks.'),
    (210, 'story', '민머리 위에는 상투 모양의 머리(육계)가 높이 솟아있고, 윤곽이 뚜렷한 얼굴은 가늘어진 눈, 작은 입, 좁고 긴 코 등의 표현에서 이전보다
형식화가 진전된 모습을 살펴볼 수 있다.
입체감이 두드러진 얼굴에 비해 평면적인 신체는 어깨가 거의 수평을 이루면서 넓게 표현되었는데, 목과 가슴 윗부분은 손상되었다.', 'The topknot-shaped head (yukgye) rises high above the bald head, and the clearly defined face is more expressive than before, with narrowed eyes, a small mouth, and a narrow, long nose.
You can see the progress in formalization.
Compared to the three-dimensional face, the flat body was expressed wide with the shoulders almost horizontal, but the neck and upper chest were damaged.'),
    (210, 'tip', '경주 골굴암 마애여래좌상에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At the Golguram Rock-carved Buddha Statue in Gyeongju, rather than just quickly looking at the building, take a look at the arrangement of the tower and pavilion as well as the mountain landscape behind it. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (210, 'did_you_know', '골굴암의 높은 암벽에 있는 자연굴을 이용하여 만든 12개의 석굴 중 가장 윗부분에 있는 마애여래좌상이에요.', 'This is the rock-carved seated Buddha statue at the top of the 12 stone caves created using natural caves on the high rock wall of Golgulam Grotto.'),
    (211, 'summary', '신라 제35대 왕인 경덕왕이 돌아가신 아버지 성덕대왕을 위하여 만들기 시작하여 그 아들인 혜공왕에 의해 771년에 완성되었다.', 'King Gyeongdeok, the 35th king of Silla, began making it for his late father, King Seongdeok, and it was completed in 771 by his son, King Hyegong.'),
    (211, 'intro', '성덕대왕신종은 신라 제35대 왕인 경덕왕이 돌아가신 아버지 성덕대왕을 위하여 만들기 시작하여 그 아들인 혜공왕에 의해 771년에 완성되었다. 종의 꼭대기에는 용뉴와 음통이, 몸에는 위로부터 보상당초무늬를 새긴 문양띠, 그 아래는 4개의 유곽, 4구의 비천상, 2곳의 당좌, 맨 아래에는 보상당초와 연꽃 문양띠가 양각되어 있다.', 'The King Seongdeok Divine Bell began to be made by King Gyeongdeok, the 35th king of Silla, for his late father, King Seongdeok, and was completed in 771 by his son, King Hyegong. At the top of the bell is a dragon nyu and an eumtong, and on the body, a pattern band with a Bosang arabesque pattern is engraved from the top. Below it, there are four Yugak, four Bicheonsang statues, two dangjwa, and at the bottom, a Bosang arabesque and a lotus flower pattern band are embossed.'),
    (211, 'story', '전체적으로 우아한 형태와 화려한 장식,아름답고 여운이 긴 종소리 등 우리나라의 종 가운데에서 가장 뛰어난 걸작이다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 성덕대왕신종은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'It is the most outstanding masterpiece among Korean bells, with its overall elegant shape, splendid decoration, and beautiful, long-lasting bell sound.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s King Seongdeok Divine Bell remains a different memory for each person who visits Gyeongju.'),
    (211, 'tip', '성덕대왕신종을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Seongdeok the Great Divine Bell, please check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (211, 'did_you_know', '성덕대왕신종은 신라 제35대 왕인 경덕왕이 돌아가신 아버지 성덕대왕을 위하여 만들기 시작하여 그 아들인 혜공왕에 의해 771년에 완성되었다고 해요.', 'It is said that King Gyeongdeok, the 35th king of Silla, began making the Divine Bell for his late father, King Seongdeok, and was completed by his son, King Hyegong, in 771.'),
    (212, 'summary', '신라의 김유신 장군 집에 있던 우물이다.', 'This is a well that was located in the house of General Kim Yu-shin of Silla.'),
    (212, 'intro', '경주 재매정은 신라의 김유신 장군 집에 있던 우물이다. 화강암을 벽돌처럼 쌓아 올려 만들었는데, 이 일대가 장군의 집이 있었던 자리로 추정된다.', 'Jaemaejeong in Gyeongju is a well that was located in the house of General Kim Yu-sin of Silla. It was made of granite stacked like bricks, and this area is presumed to be the site of the general''s house.'),
    (212, 'story', '김유신 장군이 오랜 기간을 전쟁터에서 보내고 돌아오다가 다시 전쟁터로 떠날 때, 자신의 집 앞을 지나면서 가족들을 보지도 않고 우물물을 떠 오게 하여 말위에서 마시고는, “우리 집 물맛은 옛날 그대로구나”하고 떠났다는 이야기가 전해지고 있다.
1993년 발굴조사에서 재매정을 중심으로 사방 70m 지역을 발굴하였다.
우물의 깊이는 5.7m이며, 가장 넓은 부분은 1.8m이고, 바닥의 지름이 1.2m로 벽돌같이 다듬은 돌로 만들었다.', 'There is a story that when General Kim Yu-shin returned from a long period of time in the battlefield and was leaving for the battlefield again, he passed by his house without seeing his family, brought water from a well, drank it on his horse, and left, saying, “The water from my house tastes just like it did before.”
In an excavation survey in 1993, an area measuring 70 meters in all directions was excavated centered on Jaemaejeong Pavilion.
The depth of the well is 5.7m, the widest part is 1.8m, the diameter of the bottom is 1.2m, and it is made of stone cut like a brick.'),
    (212, 'tip', '경주 재매정을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Jaemaejeong, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (212, 'did_you_know', '김유신 장군이 오랜 기간을 전쟁터에서 보내고 돌아오다가 다시 전쟁터로 떠날 때, 자신의 집 앞을 지나면서 가족들을 보지도 않고 우물물을 떠 오게 하여 말위에서 마시고는, “우리 집 물맛은 옛날 그대로구나”하고 떠났다는 이야기가 전해지고 있어요.', 'There is a story that when General Kim Yu-shin returned from a long period of time in the battlefield and was leaving for the battlefield again, he passed by his house without even seeing his family. He brought water from a well and drank it on a horse, and then left, saying, “The water from my house tastes just like it did before.”'),
    (213, 'summary', '경상북도 경주시 외동읍 괘능리에 있는 석불좌상이다.', 'This is a seated stone Buddha statue located in Gwaeneung-ri, Oedong-eup, Gyeongju-si, Gyeongsangbuk-do.'),
    (213, 'intro', '영지석불좌상 경상북도 경주시 외동읍 괘능리에 있는 석불좌상이다. 대좌와 몸 뒷부분에 조각된 광배가 있는 불상으로 광배 일부와 머리 부분은 심하게 닳아서 형태를 알아보기 어렵다.', 'This is a seated stone Buddha statue located in Gwaeneung-ri, Oedong-eup, Gyeongju-si, Gyeongsangbuk-do. This is a Buddha statue with a pedestal and a mandorla carved on the back of the body. Part of the mandorla and the head are so worn that their shape is difficult to recognize.'),
    (213, 'story', '건장한 신체와 허리, 부피감 있는 무릎 표현 등에서 통일신라 양식을 잘 나타내고 있다.
오른손은 손끝이 땅을 향하게 하며, 왼손은 왼쪽 무릎 위에 놓고 손바닥이 밖을 향하게 하였다.
팔각형의 섬세하고 고운 연꽃대좌와 불신과 같이 하나의 돌에 새겨진 광배에는 번잡한 불꽃무늬 안에 작은 부처가 화려하게 새겨져 있어 당시의 모습을 잘 보여준다.', 'The sturdy body, waist, and voluminous knees clearly represent the Unified Silla style.
The right hand is placed with the fingertips pointing toward the ground, and the left hand is placed on the left knee with the palm facing outward.
The delicate and beautiful octagonal lotus pedestal and the mandorla carved from a single stone like the Buddha statue have a small Buddha engraved in a busy flame pattern, showing the appearance of the time well.'),
    (213, 'tip', '영지석불좌상에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At the Yeongji Stone Seated Buddha Statue, rather than just quickly looking at the building, take a look at the arrangement of the pagoda and temple as well as the mountain landscape behind it. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (213, 'did_you_know', '몸을 던져 죽은 후 아사달이 그녀를 위하여 만들었다는 이야기가 전해지지만 정확하게는 알 수 없다고 해요.', 'There is a story that Asadal made it for her after she died by throwing herself, but the exact details are not known.'),
    (214, 'summary', '경주의 직천서원은 조선 후기의 학자 수암 정사진(1567∼1616)을 배향하는 서원이다.', 'Jikcheonseowon in Gyeongju is a seowon dedicated to Suam Jeong Sa-jin (1567-1616), a scholar of the late Joseon Dynasty.'),
    (214, 'intro', '경주의 직천서원은 조선 후기의 학자 수암 정사진(1567∼1616)을 배향하는 서원이다. 정사진은 경북 영천 출신으로 본관은 영일, 자는 군섭이다.', 'Jikcheonseowon in Gyeongju is a seowon dedicated to Suam Jeong Sa-jin (1567-1616), a scholar of the late Joseon Dynasty. Jeong Sa-jin is from Yeongcheon, Gyeongsangbuk-do. His hometown is Yeongil and his pen name is Gunseop.'),
    (214, 'story', '여헌 장현광의 문하에서 수학하였으며, 임진왜란 때 의병을 일으켜 활약하였다.
1606년(선조 39) 왕자의 사부로 천거되고 1611년(광해군 3) 세마, 시직을 제수받았으나 모두 사양하고 학문에만 전념하였다.
직천서원은 1711년(숙종 37)에 영천의 직천에 건립하였다가 1868년(고종 5) 대원군의 서원철폐로 훼철된 것을 1979년 후손들이 경주시 안강읍 대동리에 중건하였다.', 'He studied under Yeoheon Jang Hyeon-gwang, and was active in the volunteer army during the Japanese invasions of Korea.
In 1606 (the 39th year of King Seonjo''s reign), he was recommended as the prince''s master, and in 1611 (the 3rd year of King Gwanghaegun''s reign), he was offered the positions of Sema and Shi, but he declined them all and focused only on his studies.
Jikcheon Seowon was built in 1711 (the 37th year of King Sukjong''s reign) in Jikcheon, Yeongcheon. It was demolished in 1868 (5th year of King Gojong''s reign) when Daewongun abolished the academy. In 1979, his descendants rebuilt it in Daedong-ri, Angang-eup, Gyeongju-si.'),
    (214, 'tip', '직천서원을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Jikcheonseowon Confucian Academy, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (214, 'did_you_know', '경주의 직천서원은 조선 후기의 학자 수암 정사진(1567∼1616)을 배향하는 서원이에요.', 'Jikcheonseowon in Gyeongju is a seowon dedicated to Suam Jeong Sa-jin (1567-1616), a scholar of the late Joseon Dynasty.'),
    (215, 'summary', '경주 장산서원은 1780년(정조 4)에 지방 유림의 공의로 이전인의 학문과 덕행을 추모하기 위해 경상도 영천군 임고면 수성리에 창건하여 위패를 모셨다.', 'Gyeongju Jangsan Seowon was founded in 1780 (the 4th year of King Jeongjo''s reign) in Suseong-ri, Imgo-myeon, Yeongcheon-gun, Gyeongsang-do to commemorate the learning and virtue of Jeon Jeon-in, as a courtesy to local Confucian scholars, and enshrined a memorial tablet.'),
    (215, 'intro', '경주 장산서원은 1780년(정조 4)에 지방 유림의 공의로 이전인의 학문과 덕행을 추모하기 위해 경상도 영천군 임고면 수성리에 창건하여 위패를 모셨다. 이전인은 조선 중기의 성리학자 회재 이언적의 서자로 태어났으며 효성이 지극하여 부친 이언적이 정미사화에 연루되어 강계로 유배될 때 동행하여 시중을 들었고 이언적의 학문과 행적을 세상에 널리 알리는 데 힘을 다하였다.', 'Gyeongju Jangsan Seowon was founded in 1780 (the 4th year of King Jeongjo''s reign) in Suseong-ri, Imgo-myeon, Yeongcheon-gun, Gyeongsang-do to commemorate the learning and virtue of Jeon Jeon-in, as a courtesy to local Confucian scholars, and enshrined a memorial tablet. Lee Jeon-in was born as the illegitimate son of Hoejae Lee Eon-jeok, a Neo-Confucian scholar in the mid-Joseon Dynasty, and was extremely filial. He accompanied and served his father, Lee Eon-jeok, when he was exiled to Ganggye for involvement in the Jeongmisahwa, and did his best to publicize Lee Eon-jeok''s studies and achievements to the world.'),
    (215, 'story', '장산서원은 선현배향과 지방교육의 일익을 담당해 오던 중 1868년(고종 5) 대원군의 서원철폐로 훼철되었다.
후손들에 의해 2006년 11월에 경주시 안강읍 옥산리에 복원되었다.
2008년 4월 11일 장산서원 복원 건립기념식이 거행되었다.', 'Jangsan Seowon, which played a role in the ancestral rites and local education, was demolished in 1868 (the 5th year of King Gojong''s reign) when Daewongun abolished the academy.
It was restored by descendants in Oksan-ri, Angang-eup, Gyeongju-si in November 2006.
On April 11, 2008, a ceremony to commemorate the restoration and establishment of Jangsan Seowon was held.'),
    (215, 'tip', '장산서원을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Jangsan Seowon, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (215, 'did_you_know', '경주 장산서원은 1780년(정조 4)에 지방 유림의 공의로 이전인의 학문과 덕행을 추모하기 위해 경상도 영천군 임고면 수성리에 창건하여 위패를 모셨다고 해요.', 'Gyeongju Jangsan Seowon was founded in 1780 (the 4th year of King Jeongjo''s reign) in Suseong-ri, Imgo-myeon, Yeongcheon-gun, Gyeongsang-do to commemorate the learning and virtue of Jeon Jeon-in, as a courtesy to local Confucian scholars.'),
    (216, 'summary', '석빙고는 얼음을 넣어두던 창고로, 이 석빙고는 경주 반월성 안의 북쪽 성루 위에 남북으로 길게 자리하고 있다.', 'Seokbinggo is a warehouse used to store ice. This seokbinggo is located long from north to south on the northern fortress of Banwolseong Fortress in Gyeongju.'),
    (216, 'intro', '석빙고는 얼음을 넣어두던 창고로, 이 석빙고는 경주 반월성 안의 북쪽 성루 위에 남북으로 길게 자리하고 있다. 남쪽에 마련된 출입구를 들어가면 계단을 통하여 밑으로 내려가게 되어 있다.', 'Seokbinggo is a warehouse used to store ice. This seokbinggo is located long from north to south on the northern fortress of Banwolseong Fortress in Gyeongju. If you enter the entrance on the south side, you will go down the stairs.'),
    (216, 'story', '안으로 들어갈수록 바닥은 경사를 지어 물이 흘러 배수가 될 수 있게 만들었다.
지붕은 반원형이며 3곳에 환기통을 마련하여 바깥공기와 통하게 하였다.
석비와 입구 이맛돌에 의하면, 조선 영조 14년(1738) 당시 조명겸이 나무로 된 빙고를 돌로 축조하였다는 것과, 4년 뒤에 서쪽에서 지금의 위치로 옮겼다는 내용이 상세히 기록되어 있어 이때의 것으로 추정된다.', 'As you go inside, the floor slopes so that water can flow and drain.
The roof is semicircular and has three vents to allow access to the outside air.
According to the stone monument and the entrance stone, it is presumed to be from this time as it is recorded in detail that Myeong-gyeom Myeong-gyeom built a wooden bingo out of stone in the 14th year of King Yeongjo''s reign (1738) of the Joseon Dynasty, and that he moved it from the west to its current location four years later.'),
    (216, 'tip', '경주 석빙고은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Gyeongju Seokbinggo just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (216, 'did_you_know', '석비와 입구 이맛돌에 의하면, 조선 영조 14년(1738) 당시 조명겸이 나무로 된 빙고를 돌로 축조하였다는 것과, 4년 뒤에 서쪽에서 지금의 위치로 옮겼다는 내용이 상세히 기록되어 있어 이때의 것으로 추정돼요.', 'According to the stone monument and the entrance stone, it is presumed to be from that time as it is recorded in detail that Myeong-gyeom Myeong-gyeom built a wooden bingo out of stone in the 14th year of King Yeongjo''s reign (1738) of the Joseon Dynasty, and that he moved it from the west to its current location four years later.'),
    (217, 'summary', '신라 23대 왕인 법흥왕(재위 514∼540)의 무덤이다.', 'This is the tomb of King Beopheung (reign 514-540), the 23rd king of Silla.'),
    (217, 'intro', '신라 23대 왕인 법흥왕(재위 514∼540)의 무덤이다. 법흥왕은 신라를 중앙집권적 고대국가 체제로 완성시킨 왕이다.', 'This is the tomb of King Beopheung (reign 514-540), the 23rd king of Silla. King Beopheung is the king who completed Silla into a centralized ancient state system.'),
    (217, 'story', '왕권강화를 위해 상대등과 병부를 설치하였고, 520년 율령을 반포하였다.
532년 금관가야와 합병하여 낙동강유역에 처음 진출하였다.
신라 처음으로 건원［建元］이라는 독자적인 연호를 사용하였으며, 중국 양［梁］나라에 사신을 파견하였다.', 'To strengthen royal authority, Sangdae-deung and Military Affairs were established, and the Yulryeong was promulgated in 520.
In 532, it merged with Geumgwan Gaya and entered the Nakdong River basin for the first time.
Silla used its own unique era name, Geonwon [建元], for the first time, and envoys were dispatched to the Liang Dynasty of China.'),
    (217, 'tip', '경주 법흥왕릉에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At the Royal Tomb of King Beopheung in Gyeongju, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (217, 'did_you_know', '신라 23대 왕인 법흥왕(재위 514∼540)의 무덤이에요.', 'This is the tomb of King Beopheung (reign 514-540), the 23rd king of Silla.'),
    (218, 'summary', '경주 남산 기슭에 흩어져 있던 것을 1923년 지금의 자리에 모아 세웠다.', 'It was gathered together and erected at its current location in 1923, which had been scattered at the foot of Namsan Mountain in Gyeongju.'),
    (218, 'intro', '경주 남산 기슭에 흩어져 있던 것을 1923년 지금의 자리에 모아 세웠다. 이 석불들은 기본양식이 똑같아 처음부터 삼존불［三尊佛］로 모셔졌던 것으로 보인다.', 'It was gathered together and erected at its current location in 1923, which had been scattered at the foot of Namsan Mountain in Gyeongju. Since these stone Buddhas have the same basic style, they appear to have been enshrined as the Three Buddhas from the beginning.'),
    (218, 'story', '중앙의 본존불은 머리에 상투 모양의 머리(육계)가 있는데, 특이하게도 이중으로 되어 있으며, 표면이 매끄럽게 표현되었다.
어린아이 표정의 네모난 얼굴은 풍만하며, 둥근 눈썹, 아래로 뜬 눈, 다문 입, 깊이 파인 보조개, 살찐 뺨 등을 통하여 온화하고 자비로운 불성［佛性］을 표현하고 있다.
목이 표현되지 않은 원통형의 체구에 손을 큼직하게 조각하였는데, 왼손은 내리고 오른손은 올리고 있다.', 'The main Buddha in the center has a topknot-shaped head (yukgye), which is unique in that it is double-layered and has a smooth surface.
The square face with the expression of a child is voluptuous, and the gentle and merciful nature of Buddha is expressed through round eyebrows, downturned eyes, closed mouth, deep dimples, and plump cheeks.
The hand is large and carved on a cylindrical body with no neck. The left hand is lowered and the right hand is raised.'),
    (218, 'tip', '경주 배동 석조여래삼존입상에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At the Stone Standing Buddha Triad in Bae-dong, Gyeongju, rather than just quickly looking at the building, take a look at the arrangement of the tower and pavilion and the mountain landscape behind it. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (218, 'did_you_know', '경주 남산 기슭에 흩어져 있던 것을 1923년 지금의 자리에 모아 세웠다고 해요.', 'It is said that the items scattered at the foot of Namsan in Gyeongju were gathered together and erected at the current location in 1923.'),
    (219, 'summary', '경주 벽도산의 서쪽을 향한 바위에 삼존불［三尊佛］을 조각한 마애불［磨崖佛］이다.', 'This is a rock-carved Buddha statue carved on a rock facing the west of Byeokdo Mountain in Gyeongju.'),
    (219, 'intro', '경주 벽도산의 서쪽을 향한 바위에 삼존불［三尊佛］을 조각한 마애불［磨崖佛］이다. 이 불상은 가까운 곳에 있는 경주 굴불사지 석조사면불상(보물)의 양식을 그대로 계승하고 있는 통일신라시대의 대표적인 작품으로 서방 극락세계를 다스린다는 아미타불을 가운데에 새기고, 양쪽에 관음보살과 대세지보살을 새겼다.', 'This is a rock-carved Buddha statue carved on a rock facing the west of Byeokdo Mountain in Gyeongju. This Buddha statue is a representative work of the Unified Silla period, inheriting the style of the stone face Buddha statue (treasure) at Gyeongju Gulbulsa Temple located nearby. Amitabha Buddha, who is said to rule over the western world of paradise, is engraved in the center, and Avalokitesvara Bodhisattva and Bodhisattva Great Seji are engraved on both sides.'),
    (219, 'story', '아미타불의 머리는 아주 큼직하며, 정수리 부근에는 상투 모양의 머리(육계)가 낮게 있어 모자를 쓴 듯한데, 이는 굴불사지의 석조사면불상과 같은 양식이다.
얼굴은 볼에 살이 올라서 매우 풍만하게 보이며 미소가 남아 있다.
어깨는 넓고 반듯하며 양 어깨를 감싸고 있는 옷은 얇게 표현되어 몸의 굴곡을 잘 드러낸다.', 'The head of Amitabha Buddha is very large, and the top of the head has a low topknot-shaped head (yukgye), making it look like he is wearing a hat, which is the same style as the stone face-faced Buddha statue at Gulbulsa Temple Site.
The face looks very voluptuous with flesh on the cheeks, and a smile remains.
The shoulders are wide and straight, and the clothes covering both shoulders are thin, revealing the curves of the body.'),
    (219, 'tip', '경주 율동 마애여래삼존입상에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'At the Rock-carved Buddha Triad in Yuldong, Gyeongju, rather than just quickly looking at the building, take a look at the arrangement of the tower and pavilion and the mountain landscape behind it. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (219, 'did_you_know', '이 불상은 경주 굴불사지석조사면불상과 기본적으로는 같지만, 풍만성이나 발의 모양, 옷주름의 모양 등으로 보아 제작 시기가 조금은 다르다는 것을 알 수 있어요.', 'This Buddha statue is basically the same as the Gyeongju Gulbulsaji Stone Carved Buddha Statue, but the voluptuousness, shape of the feet, and the shape of the folds of the clothes show that it was made at a slightly different time.'),
    (220, 'summary', '경주시 산내면에 위치한 반딧불이캠핑장은 자연을 벗 삼아 캠핑을 즐길 수 있는 곳이다.', 'Firefly Camping Site, located in Sannae-myeon, Gyeongju-si, is a place where you can enjoy camping with nature as your friend.'),
    (220, 'intro', '경주시 산내면에 위치한 반딧불이캠핑장은 자연을 벗 삼아 캠핑을 즐길 수 있는 곳이다. 봄엔 벚꽃, 여름엔 푸르게 우거진 나무 그늘, 가을엔 형형색색 물든 낙엽, 겨울엔 운치 있는 눈까지 모두 감상할 수 있는 캠핑장이다.', 'Firefly Camping Site, located in Sannae-myeon, Gyeongju-si, is a place where you can enjoy camping with nature as your friend. This is a campsite where you can enjoy cherry blossoms in the spring, the shade of lush trees in the summer, colorful leaves in the fall, and the charming snow in the winter.'),
    (220, 'story', '캠핑장은 일반야영장과 방갈로가 준비되어 있다.
사이트의 크기는 구역 별로 조금씩 다르기 때문에 방문 전에 확인하는 것이 좋다.
오늘의 반딧불이캠핑장은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The campsite has general campsites and bungalows.
The size of the site varies slightly depending on the area, so it is best to check before visiting.
Today''s Firefly Camping Site remains a different memory for each person visiting Gyeongju.'),
    (220, 'tip', '반딧불이캠핑장은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'Firefly Camping Sites may vary in site type and equipment provided. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (220, 'did_you_know', '사이트의 크기는 구역 별로 조금씩 다르기 때문에 방문 전에 확인하는 것이 좋다고 해요.', 'The size of the site varies slightly depending on the area, so it is best to check before visiting.'),
    (221, 'summary', '신라 제30대 문무왕(재위 661~681년)의 수중릉으로 신라인들의 창의적인 생각을 엿볼 수 있는 곳이다.', 'This is the underwater tomb of King Munmu, the 30th king of Silla (reigned 661-681), and is a place where you can get a glimpse of the creative thinking of the Silla people.'),
    (221, 'intro', '신라 제30대 문무왕(재위 661~681년)의 수중릉으로 신라인들의 창의적인 생각을 엿볼 수 있는 곳이다. 동해 봉길리 앞바다에서 200m 떨어진 곳에 있으며, 해수면 위로 동서 35m, 남북 36m, 높이 5.3m 정도 노출되어 있다.', 'This is the underwater tomb of King Munmu, the 30th king of Silla (reigned 661-681), and is a place where you can get a glimpse of the creative thinking of the Silla people. It is located 200m off the coast of Bonggil-ri in the East Sea, and is exposed 35m east-west, 36m north-south, and 5.3m above sea level.'),
    (221, 'story', '문무왕은 아버지인 태종 무열왕의 업적을 이어받아 고구려를 멸망시키고, 당의 침략을 막아 삼국 통일을 이루었다.
또한 병부, 창부 등 중앙 관청을 창설하였고, 지방 통치를 위한 5소경 제도와 9서당 10정의 군사 제도의 기틀을 마련하는 등 국가 체제 완성의 기초를 제공하였다.
삼국 통일을 이룬 문무왕이 자신이 용이 되어 침입해 들어오는 왜구를 막겠다며, 자신의 시신을 불교식으로 화장하고 유골을 동해에 묻어 달라고 한 유언을 따라 장사한 것이다.', 'King Munmu inherited the achievements of his father, King Taejong Muyeol, and destroyed Goguryeo and prevented the Tang invasion, unifying the three kingdoms.
In addition, he created central government offices such as military officials and courtesans, and provided the basis for completing the national system by laying the foundation for a military system of 5 minor officers for local governance and 10 administrative officers in 9 schools.
King Munmu, who achieved the unification of the three kingdoms, said that he would become a dragon to stop the invading Japanese pirates, and was buried according to his will, which called for his body to be cremated in Buddhist style and his ashes to be buried in the East Sea.'),
    (221, 'tip', '경주 문무대왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Royal Tomb of King Munmu in Gyeongju, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (221, 'did_you_know', '신라 제30대 문무왕(재위 661~681년)의 수중릉으로 신라인들의 창의적인 생각을 엿볼 수 있는 곳이에요.', 'This is the underwater tomb of King Munmu, the 30th king of Silla (reigned 661-681), and is a place where you can get a glimpse of the creative thinking of the Silla people.'),
    (222, 'summary', '경주 감포읍에 있는 오류고아라해변은 1㎞의 백사장과 1.5m 안팎의 수심에 소나무 숲이 우거진 해변으로, 모래가 부드러워 모래찜질로 유명한 곳이다.', 'Oryugoara Beach, located in Gampo-eup, Gyeongju, is a 1km long white sand beach with a depth of about 1.5m and a pine forest, and is famous for sand baths due to the soft sand.'),
    (222, 'intro', '경주 감포읍에 있는 오류고아라해변은 1㎞의 백사장과 1.5m 안팎의 수심에 소나무 숲이 우거진 해변으로, 모래가 부드러워 모래찜질로 유명한 곳이다. 소나무숲에는 오류캠핑장이 조성되어 있어 텐트, 카라반캠핑이 가능하고, 여름철에는 바나나보트, 모터보트와 같은 수상레저를 즐길 수 있다.', 'Oryugoara Beach, located in Gampo-eup, Gyeongju, is a 1km long white sand beach with a depth of about 1.5m and a pine forest, and is famous for sand baths due to the soft sand. There is an Oryu Camping Site in the pine forest where tent and caravan camping are possible, and in the summer, you can enjoy water leisure activities such as banana boats and motor boats.'),
    (222, 'story', '주변 관광지로는 감포항, 감포공설시장 등이 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 오류고아라해변은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Nearby tourist attractions include Gampo Port and Gampo Public Market.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Oryu Goara Beach remains a different memory for each person visiting Gyeongju.'),
    (222, 'tip', '오류고아라해변에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Oryu Goara Beach, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (222, 'did_you_know', '소나무숲에는 오류캠핑장이 조성되어 있어 텐트, 카라반캠핑이 가능하고, 여름철에는 바나나보트, 모터보트와 같은 수상레저를 즐길 수 있어요.', 'There is an Oryu Camping Site in the pine forest where tent and caravan camping are possible, and in the summer, you can enjoy water leisure activities such as banana boats and motor boats.'),
    (223, 'summary', '경상북도 경주시 감포항 북쪽에 있는 송대말 등대는 육지 끝에서부터 암초들이 길게 뻗어 있어 작은 선박들의 사고가 빈번한 감포 앞바다의 해상 안전을 위해 처음에는 무인 등대로 건립되었으며, 이후 유인등대로 승격되어 운영하였고, 현재는 그 기능을 다', 'Songdaemal Lighthouse, located on the north side of Gampo Port in Gyeongju-si, Gyeongsangbuk-do, was initially built as an unmanned lighthouse to ensure maritime safety in the waters off Gampo, where accidents by small ships are frequent due to long reefs extending from the end of the land. It was later promoted to a manned lighthouse and is currently performing its function.'),
    (223, 'intro', '경상북도 경주시 감포항 북쪽에 있는 송대말 등대는 육지 끝에서부터 암초들이 길게 뻗어 있어 작은 선박들의 사고가 빈번한 감포 앞바다의 해상 안전을 위해 처음에는 무인 등대로 건립되었으며, 이후 유인등대로 승격되어 운영하였고, 현재는 그 기능을 다 하여 사용되지 않고 있다.', 'Songdaemal Lighthouse, located on the north of Gampo Port in Gyeongju-si, Gyeongsangbuk-do, was initially built as an unmanned lighthouse to ensure maritime safety in the waters off Gampo, where accidents by small ships are frequent due to long reefs extending from the end of the land. It was later promoted to a manned lighthouse and is currently not in use as it has fulfilled its function.'),
    (223, 'story', '대신 그 옆에 경주시 감포읍의 상징인 감은사지 석탑 모형을 본떠 새롭게 만든 5층 등대 건물을 지어 1, 2층은 빛 체험 전시관으로 관광객들에게 색다른 볼거리를 제공하고 3, 4, 5층은 기존 등대의 역할을 대신해 감포 앞바다를 비추고 있다.
전시관 1층에는 감포항과 송대말 등대의 역사에 대해 내용이 자세히 기록되어 있다.
송대말이란 소나무가 펼쳐진 끝자락이라는 뜻으로 수령 300년~400년 정도 된 아름드리 해송림이 등대 주변을 포근하게 감싸고 있으며 등대 앞에는 관람객을 위한 나무 데크길이 설치되어 있어 산책하며 주변 경관을 둘러보기 좋으며 무엇보다', 'Instead, a new 5-story lighthouse building was built next to it, modeled after the stone pagoda of Gameunsa Temple, a symbol of Gampo-eup, Gyeongju-si. The 1st and 2nd floors are a light experience exhibition hall to provide tourists with a unique attraction, and the 3rd, 4th, and 5th floors take on the role of the existing lighthouse and illuminate the sea off Gampo.
On the first floor of the exhibition hall, there is a detailed record of the history of Gampo Port and the Songdaemal Lighthouse.
Songdaemal means the end of the pine trees, and a 300 to 400-year-old pine forest is wrapped around the lighthouse. There is a wooden deck path for visitors in front of the lighthouse, so it is great for taking a walk and looking at the surrounding scenery.'),
    (223, 'tip', '송대말 등대에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Songdaemal Lighthouse, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (223, 'did_you_know', '경상북도 경주시 감포항 북쪽에 있는 송대말 등대는 육지 끝에서부터 암초들이 길게 뻗어 있어 작은 선박들의 사고가 빈번한 감포 앞바다의 해상 안전을 위해 처음에는 무인 등대로 건립되었으며, 이후 유인등대로 승격되어 운영하였고, 현재는 그 기능을 다', 'Songdaemal Lighthouse, located on the north side of Gampo Port in Gyeongju-si, Gyeongsangbuk-do, was initially built as an unmanned lighthouse to ensure maritime safety in the waters off Gampo, where accidents by small ships are frequent due to long reefs extending from the end of the land. It was later promoted to a manned lighthouse and is currently performing its function.'),
    (224, 'summary', '제1대 신라 전통음식 명인 차은정 대표와 2대 김정훈 셰프가 함께 전통 음식의 대중화와 한식 세계화를 목표로 설립한 유니크 베뉴이다.', 'It is a unique venue founded by CEO Cha Eun-jeong, the first Silla traditional food master, and chef Kim Jeong-hoon, the second generation, with the goal of popularizing traditional food and globalizing Korean food.'),
    (224, 'intro', '라선재는 제1대 신라 전통음식 명인 차은정 대표와 2대 김정훈 셰프가 함께 전통 음식의 대중화와 한식 세계화를 목표로 설립한 유니크 베뉴이다. 이곳에서는 화랑과 신라 음식을 주제로 한 ‘풍월주 50찬’, 신라 왕들의 역사 이야기를 들으며 음식을 맛보는 ‘신라 12왕 체험프로그램’, 외국인이 직접 한식을 만들고 맛보며 문화를 체험하는 ‘K-Food 쿠킹 클래스’, 한식 디저트를 직접 만드는 ‘풍월주 쿠킹 클래스’ 등 다채로운 프로그램을 운영한다.', 'Raseonjae is a unique venue founded by Cha Eun-jeong, the first Silla traditional food master, and Chef Jeong-hoon Kim, the second generation, with the goal of popularizing traditional food and globalizing Korean food. Here, a variety of programs are run, including ‘50 Pungwolju Chan’ with the theme of Hwarang and Silla food, ‘Silla 12 Kings Experience Program’ where you can taste food while listening to the history of Silla kings, ‘K-Food Cooking Class’ where foreigners experience culture by making and tasting Korean food, and ‘Pungwolju Cooking Class’ where you can make Korean desserts yourself.'),
    (224, 'story', '방문 전 반드시 사전 예약이 필요하다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 라선재은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Advance reservation is required before visiting.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Raseonjae remains a different memory for each person who visits Gyeongju.'),
    (224, 'tip', '라선재은 현장 방문만으로 참여하기 어려울 수 있어요. 원하는 프로그램과 해설 시간을 먼저 확인하고 사전 예약을 마친 뒤 방문해 보세요.', 'It may be difficult to participate in Rasunjae just by visiting the site. Please check the desired program and commentary time first and make a reservation in advance before visiting.'),
    (224, 'did_you_know', '이곳에서는 화랑과 신라 음식을 주제로 한 ‘풍월주 50찬’, 신라 왕들의 역사 이야기를 들으며 음식을 맛보는 ‘신라 12왕 체험프로그램’, 외국인이 직접 한식을 만들고 맛보며 문화를 체험하는 ‘K-Food 쿠킹 클래스’, 한식 디저트를 직접 만드는 ‘풍월주 쿠킹 클래스’ 등 다채로운 프로그램을 운영해요.', 'Here, a variety of programs are run, including ‘50 Pungwolju Chan’ with the theme of Hwarang and Silla food, ‘Silla 12 Kings Experience Program’ where you can taste food while listening to the history of Silla kings, ‘K-Food Cooking Class’ where foreigners experience culture by making and tasting Korean food, and ‘Pungwolju Cooking Class’ where you can make Korean desserts yourself.'),
    (225, 'summary', '주렁주렁은 동물원을 뜻하는 ZOO와 삭막한 도심의 한가운데 산소를 공급하는 녹지대를 뜻하는 Green Lung의 합성어이다.', 'Zurungjulung is a compound word of ZOO, which means zoo, and Green Lung, which means a green area that supplies oxygen in the middle of a bleak city center.'),
    (225, 'intro', '주렁주렁은 동물원을 뜻하는 ZOO와 삭막한 도심의 한가운데 산소를 공급하는 녹지대를 뜻하는 Green Lung의 합성어이다. 주렁주렁은 도심 속에서 살아 숨 쉬는 생명들을 만날 수 있는 대한민국 최초의 애니멀 테마파크이다.', 'Zurungjulung is a compound word of ZOO, which means zoo, and Green Lung, which means a green area that supplies oxygen in the middle of a bleak city center. Jurungjureong is Korea''s first animal theme park where you can meet living, breathing creatures in the city center.'),
    (225, 'story', '단순히 동물을 관찰하는 동물원을 넘어 울타리 없는 가까운 교감을 통해 생명의 소중함을 느껴보는 장소로 도심의 한가운데서 현대인들에게 휴식과 힐링이 되는 애니멀 테마파크를 추구한다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 주렁주렁 경주점은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'We pursue an animal theme park that goes beyond simply observing animals to a place where you can feel the preciousness of life through close interaction without fences, providing relaxation and healing to modern people in the middle of the city.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s sprawling Gyeongju branch leaves a different memory for each person who visits Gyeongju.'),
    (225, 'tip', '주렁주렁 경주점을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Gyeongju branch, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (225, 'did_you_know', '주렁주렁은 도심 속에서 살아 숨 쉬는 생명들을 만날 수 있는 대한민국 최초의 애니멀 테마파크이에요.', 'Jurungjureong is Korea''s first animal theme park where you can meet living, breathing creatures in the city center.'),
    (226, 'summary', '경북 경주시 감포읍에 위치한 캠핑장이다.', 'This is a camping site located in Gampo-eup, Gyeongju-si, Gyeongbuk.'),
    (226, 'intro', '에덴 오토 캠핑장은 경북 경주시 감포읍에 위치한 캠핑장이다. 캠핑장 안에서도 푸르른 바다를 조망할 수 있으며 파도소리가 노래처럼 들려오는 곳이다.', 'Eden Auto Campground is a camping site located in Gampo-eup, Gyeongju-si, Gyeongsangbuk-do. You can see the blue sea even from inside the campsite, and the sound of the waves can be heard like a song.'),
    (226, 'story', '캠핑장뿐만 아니라 펜션도 이용할 수 있다.
수영장과 놀이터, 물놀이 시설이 있어 여름에 아이들과 함께 즐기기에도 좋다.
주변의 경주 유명 관광지를 즐기기에도 좋다.', 'Not only camping sites but also pensions are available.
There is a swimming pool, playground, and water play facilities, making it a great place to enjoy with children in the summer.
It is also good for enjoying famous tourist attractions in nearby Gyeongju.'),
    (226, 'tip', '에덴 오토 캠핑장에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Eden Auto Camping Site, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (226, 'did_you_know', '반려동물 동반은 불가하다고 해요.', 'They say pets are not allowed.'),
    (227, 'summary', '산내 자연캠프는 경북 경주시 산내면 대현리에 자리 잡고 있다.', 'Sannae Nature Camp is located in Daehyeon-ri, Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (227, 'intro', '산내 자연캠프는 경북 경주시 산내면 대현리에 자리 잡고 있다. 캠핑장은 사방이 숲으로 둘러싸여 있으며 계곡을 끼고 있어 더없이 자연 친화적이다.', 'Sannae Nature Camp is located in Daehyeon-ri, Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do. The campsite is surrounded by forests on all sides and is located next to a valley, making it extremely nature-friendly.'),
    (227, 'story', '글램핑 10개 동이 갖추어져 있으며 객실 내부에는 침대, 화장실, 샤워실, 개수대, 취사도구 등 일상생활이 가능할 정도의 시설이 들어차 있다.
파쇄석으로 이루어진 오토캠핑 사이트도 4면이다.
부대시설로는 한여름 무더위를 날리기 그만인 수영장을 비롯해 트램펄린, 매점, 바비큐장 등이 있다.', 'There are 10 glamping buildings, and the rooms are equipped with facilities for everyday life, such as beds, toilets, showers, sinks, and cooking utensils.
There are also four auto camping sites made of crushed stone.
Auxiliary facilities include a swimming pool, perfect for beating the summer heat, a trampoline, a concession stand, and a barbecue area.'),
    (227, 'tip', '산내자연캠프에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Sannae Nature Camp, check the operation status and conditions of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (227, 'did_you_know', '글램핑 10개 동이 갖추어져 있으며 객실 내부에는 침대, 화장실, 샤워실, 개수대, 취사도구 등 일상생활이 가능할 정도의 시설이 들어차 있어요.', 'There are 10 glamping buildings, and the rooms are equipped with facilities for everyday life, such as beds, toilets, showers, sinks, and cooking utensils.'),
    (228, 'summary', '학문을 숭상한다는 의미로, 신라시대 왕실도서를 보관 및 관리하고 동궁에 대한 교육을 담당하던 관청이다.', 'With the meaning of revering learning, it is a government office that stored and managed the royal books of the Silla Dynasty and was in charge of education for the Donggung Palace.'),
    (228, 'intro', '숭문대는 학문을 숭상한다는 의미로, 신라시대 왕실도서를 보관 및 관리하고 동궁에 대한 교육을 담당하던 관청이다. 경주시와 문화재청은 찬란했던 신라 천년의 역사를 널리 알리고 계승하고자 월성발굴조사 운영시설의 이름을 숭문대로 명명했다고 설명했다.', 'Sungmoon University, meaning reverence for learning, is a government office that stored and managed the royal books of the Silla Dynasty and was in charge of education for the Donggung Palace. Gyeongju City and the Cultural Heritage Administration explained that they named the Wolseong excavation operation facility Sungmundae to widely publicize and inherit the glorious thousand-year history of Silla.'),
    (228, 'story', '신라왕궁 발굴 과정에서 출토된 유물의 전시와 연구성과를 공개할 수 있는 신라왕궁 출토유물 전시관으로서 역할을 기대하고 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 숭문대은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'It is expected to serve as an exhibition hall for relics excavated from the Silla Royal Palace, where the relics excavated during the excavation process of the Silla Royal Palace can be displayed and research results can be made public.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Soongmoon University leaves a different memory for each person who visits Gyeongju.'),
    (228, 'tip', '숭문대에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At Soongmoon University, decide on the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (228, 'did_you_know', '경주시와 문화재청은 찬란했던 신라 천년의 역사를 널리 알리고 계승하고자 월성발굴조사 운영시설의 이름을 숭문대로 명명했다고 설명했다고 해요.', 'Gyeongju City and the Cultural Heritage Administration explained that they named the Wolseong excavation operation facility Sungmundae to widely publicize and inherit the glorious thousand-year history of Silla.'),
    (229, 'summary', '2025년 APEC 정상회의를 기념하여 열리는 이번 전시는 “미래유산_우리가 남기고자 하는 것들에 관하여”를 주제로 한국공예의 폭넓은 스펙트럼을 선보인다.', 'This exhibition, held in commemoration of the 2025 APEC Summit, showcases a broad spectrum of Korean crafts under the theme “Future Heritage: About the Things We Want to Leave Behind.”'),
    (229, 'intro', '2025년 APEC 정상회의를 기념하여 열리는 이번 전시는 “미래유산_우리가 남기고자 하는 것들에 관하여”를 주제로 한국공예의 폭넓은 스펙트럼을 선보인다. 총 36명(31팀)의 작가가 참여해 66점의 작품을 전시하며, 한국 공예의 과거-현재-미래를 한자리에서 조망할 수 있다.', 'This exhibition, held in commemoration of the 2025 APEC Summit, showcases a broad spectrum of Korean crafts under the theme “Future Heritage: About the Things We Want to Leave Behind.” A total of 36 artists (31 teams) will participate and exhibit 66 works, allowing you to view the past, present, and future of Korean crafts in one place.'),
    (229, 'story', '파트1에서는 분야별 최고의 전문가가 참여해 한국공예의 정수를 선보이며, 파트2에서는 전통 기술과 현대 디자인/미술의 협업 또는 전승을, 파트3에서는 업사이클 공예작품을 소개한다.
전시는 경주 보문단지 내 천군복합문화공간에서 10월 27일부터 11월 30일까지 진행되며, 누구나 무료로 관람할 수 있다.
오늘의 2025 한국공예전 은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'In Part 1, the best experts in each field will participate to showcase the essence of Korean crafts, Part 2 will introduce collaboration or transmission between traditional techniques and modern design/art, and Part 3 will introduce upcycled craft works.
The exhibition will be held from October 27 to November 30 at the Cheongun Cultural Complex within the Bomun Complex in Gyeongju, and anyone can view it for free.
Today’s 2025 Korea Craft Fair leaves a different memory for each person visiting Gyeongju.'),
    (229, 'tip', '2025 한국공예전 은 산길이나 오르막 구간을 지나야 할 수 있어요. 미끄러지지 않는 신발과 물을 준비하고, 해가 지기 전에 돌아올 수 있도록 소요 시간을 넉넉히 잡으세요.', 'The 2025 Korea Craft Fair may require passing through mountain paths or uphill sections. Bring non-slip shoes and water, and allow plenty of time to return before sunset.'),
    (229, 'did_you_know', '2025년 APEC 정상회의를 기념하여 열리는 이번 전시는 “미래유산_우리가 남기고자 하는 것들에 관하여”를 주제로 한국공예의 폭넓은 스펙트럼을 선보인다고 해요.', 'This exhibition, held to commemorate the 2025 APEC Summit, is said to showcase a broad spectrum of Korean crafts under the theme of “Future Heritage: What We Want to Leave Behind.”'),
    (230, 'summary', '경주시에 위치한 월성원자력홍보관은 우리 곁에 늘 있지만 잘 알지 못했던 에너지와 원자력에 대해 깊이 있게 배울 수 있는 공간이다.', 'The Wolseong Nuclear Power Promotion Center, located in Gyeongju-si, is a space where you can learn in depth about energy and nuclear power, which are always with us but we are not familiar with.'),
    (230, 'intro', '경주시에 위치한 월성원자력홍보관은 우리 곁에 늘 있지만 잘 알지 못했던 에너지와 원자력에 대해 깊이 있게 배울 수 있는 공간이다. 에너지의 역사와 함께 전기에너지의 발생 원리, 원자력 발전이 이뤄지는 과정, 그리고 방사선의 신비한 세계에 이르기까지 다양한 주제를 전시하고 있다.', 'The Wolseong Nuclear Power Promotion Center, located in Gyeongju-si, is a space where you can learn in depth about energy and nuclear power, which are always with us but we are not familiar with. In addition to the history of energy, various topics are on display, including the principles of electrical energy generation, the process of nuclear power generation, and the mysterious world of radiation.'),
    (230, 'story', '특히 아이들과 청소년들이 쉽고 재미있게 이해할 수 있도록 구성된 전시물과 영상자료, 체험형 게임 등이 풍부하게 마련되어 있어 교육적인 효과도 뛰어나다.
현장학습이나 가족 단위의 방문에도 매우 적합한 이 홍보관은 과학에 대한 호기심을 자극하고, 에너지에 대한 올바른 인식을 심어주는 장소이다.
오늘의 월성원자력홍보관은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'In particular, there are a wealth of exhibits, video materials, and experiential games designed to be easy and fun for children and teenagers to understand, so the educational effect is excellent.
This promotional center, which is ideal for field trips or family visits, is a place that stimulates curiosity about science and instills correct awareness of energy.
Today''s Wolseong Nuclear Power Promotion Center leaves a different memory for each person who visits Gyeongju.'),
    (230, 'tip', '월성원자력홍보관을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Wolseong Nuclear Power Promotion Center, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (230, 'did_you_know', '현장학습이나 가족 단위의 방문에도 매우 적합한 이 홍보관은 과학에 대한 호기심을 자극하고, 에너지에 대한 올바른 인식을 심어주는 장소이에요.', 'This promotional center, which is ideal for field trips or family visits, is a place that stimulates curiosity about science and instills correct awareness of energy.'),
    (231, 'summary', '신라 선덕여왕 때 창건된 사찰이며, 처음에는 임정사라 불리다', 'This temple was founded during the reign of Queen Seondeok of Silla, and was initially called Imjeongsa Temple.'),
    (231, 'intro', '기림사는 신라 선덕여왕 때 창건된 사찰이며, 처음에는 임정사라 불리다 원효가 도량을 확장하면서 기림사로 개칭하였다.', 'Girimsa Temple is a temple founded during the reign of Queen Seondeok of Silla. It was initially called Imjeongsa Temple, but was renamed Girimsa Temple when Wonhyo expanded the temple.'),
    (231, 'story', '기림사는 크게 두 구역으로 나뉘어 있는데, 비로자나불을 모신 대적광전이랑 500년 이상 된 큰 보리수나무가 있는 지역과 보 박물관, 삼성각, 명부전, 관음전 등이 있는 지역이다.
대적광전은 기림사의 본전으로 배흘림기둥의 다포식 단층 맞배지붕의 건물이며 조선 초기 불상의 전형을 갖춘 삼존불을 모시고 있다.
대적광전과 진남루 사이 서쪽에 오백나한전이 있고, 그 바로 앞에 3층 석탑이 있다.', 'Girimsa Temple is largely divided into two areas: Daejeokgwangjeon Hall, which houses Vairocana Buddha, a large Bodhi tree over 500 years old, and Bo Museum, Samseonggak, Myeongbujeon Hall, and Gwaneumjeon Hall.
Daejeokgwangjeon is the main shrine of Girimsa Temple. It is a multi-layered, single-story, gable-roofed building with double-angled pillars, and enshrines a triad of Buddha typical of early Joseon Dynasty Buddha statues.
There is Obaeknahanjeon on the west between Daejeokgwangjeon and Jinnamru, and there is a three-story stone pagoda right in front of it.'),
    (231, 'tip', '기림사을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Girimsa Temple, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (231, 'did_you_know', '기림사는 크게 두 구역으로 나뉘어 있는데, 비로자나불을 모신 대적광전이랑 500년 이상 된 큰 보리수나무가 있는 지역과 보 박물관, 삼성각, 명부전, 관음전 등이 있는 지역이에요.', 'Girimsa Temple is largely divided into two areas: Daejeokgwangjeon Hall, which houses the Vairocana Buddha, an area with a large Bodhi tree that is over 500 years old, and an area with Bo Museum, Samseonggak, Myeongbujeon Hall, and Gwaneumjeon Hall.'),
    (232, 'summary', '경주 굴불사터에 있는 통일신라시대 바위 불상으로 약 높이 3미터의 바위 네 면에 불상이 조각되어 있어서 사면석불이라 부른다.', 'It is a rock Buddha statue from the Unified Silla period located at the site of Gulbulsa Temple in Gyeongju. It is called the Four-faced Stone Buddha because the Buddha statues are carved on four sides of a rock about 3 meters high.'),
    (232, 'intro', '경주 굴불사지 석조사면불상은 경주 굴불사터에 있는 통일신라시대 바위 불상으로 약 높이 3미터의 바위 네 면에 불상이 조각되어 있어서 사면석불이라 부른다. 이 사면불의 서쪽은 서방 극락세계의 아미타삼존불, 동쪽은 유리광세계의 약사여래불, 북쪽은 미륵불, 남쪽은 석가모니불을 각각 새긴 사방불의 형태이다.', 'The stone Buddha statue at Gulbulsa Temple site in Gyeongju is a rock Buddha statue from the Unified Silla period located at the site of Gulbulsa Temple in Gyeongju. It is called the four-faced stone Buddha statue because the Buddha statues are carved on four sides of a rock about 3 meters high. The west side of this four-faced Buddha is the Amitabha Triad Buddha of the Western Paradise World, the east side is the Medicine Buddha of the Glass Light World, the north side is the Maitreya Buddha, and the south side is the Buddha Shakyamuni Buddha.'),
    (232, 'story', '〈삼국유사〉에 의하면 신라 경덕왕이 백률사를 찾았을 때 땅속에서 염불 소리가 들려왔다고 한다.
땅을 파보니 이 바위가 나와서 바위의 사방에 불상을 새기고 절을 지어 굴불사라 하였다고 전한다.
이 기록만으로는 분명하지 않지만, 여러 가지 여건으로 보아 이때쯤 불상이 만들어졌을 것으로 추정된다.', 'According to Samgukyusa, when King Gyeongdeok of Silla visited Baengnyulsa Temple, the sound of chanting was heard from the ground.
It is said that when they dug into the ground, this rock came out, so they carved Buddha images on all sides of the rock and built a temple, calling it Gulbulsa Temple.
It is not clear from this record alone, but considering various circumstances, it is presumed that the Buddha statue was created around this time.'),
    (232, 'tip', '경주 굴불사지 석조사면불상을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Stone Face Buddha Statue at Gulbulsa Temple Site, Gyeongju, check the latest operating information and travel directions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (232, 'did_you_know', '굴불사지 석조사면불상은 불상조각에 있어 입체의 표현, 음각과 양각의 표현, 좌상과 입상의 표현 등을 변화 있게 배치해 매우 특색이 있으며 풍만하고 부드러우면서 생기를 잃지 않은 솜씨를 볼 때 통일신라 초기의 특징을 잘 보여주고 있는 작품이에요.', 'The stone-faced Buddha statue at Gulbulsa Temple is very unique in its varied arrangement of three-dimensional expressions, engravings and reliefs, and sitting and standing figures. It is a work that shows the characteristics of the early Unified Silla period in terms of its voluptuous, soft, and lively workmanship.'),
    (233, 'summary', '경주 동천동에 있는 신라 제4대 탈해왕(재위 57~80)의 무덤으로 소나무 숲으로 둘러싸여 있다.', 'This is the tomb of King Talhae, the 4th king of Silla (reign 57-80), located in Dongcheon-dong, Gyeongju, and is surrounded by a pine forest.'),
    (233, 'intro', '경주 동천동에 있는 신라 제4대 탈해왕(재위 57~80)의 무덤으로 소나무 숲으로 둘러싸여 있다. 무덤의 형식 자체는 일반적이나, 신라 초기의 왕릉이고 특히 최초의 석 씨 왕릉이라는 점에서 중요하다.', 'This is the tomb of King Talhae, the 4th king of Silla (reign 57-80), located in Dongcheon-dong, Gyeongju, and is surrounded by a pine forest. The form of the tomb itself is common, but it is particularly important in that it is a royal tomb from the early Silla Dynasty and is the first royal tomb of the Seok clan.'),
    (233, 'story', '이 무덤은 높이 4.5m, 지름 14.3m 크기로 둥글게 흙을 쌓아 올린 봉토무덤이다.
주변에 아무런 시설을 하지 않았으며, 겉으로 보아 굴식돌방무덤(횡혈식석실묘)으로 추측된다.
왕릉 초입에는 탈해왕의 제사를 모시기 위한 전각 숭신전이 있다.', 'This tomb is a circular tomb with earth measuring 4.5m in height and 14.3m in diameter.
There were no facilities built around it, and from the outside, it is presumed to be a cave-style stone chamber tomb (horizontal stone chamber tomb).
At the entrance to the royal tomb, there is a pavilion called Sungsinjeon to hold the ancestral rites of King Talhae.'),
    (233, 'tip', '경주 탈해왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Talhae’s Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (233, 'did_you_know', '경주 동천동에 있는 신라 제4대 탈해왕(재위 57~80)의 무덤으로 소나무 숲으로 둘러싸여 있어요.', 'This is the tomb of King Talhae, the 4th king of Silla (reign 57-80), located in Dongcheon-dong, Gyeongju, and is surrounded by a pine forest.'),
    (234, 'summary', '대왕암을 의미 있게 눈여겨볼 수 있는 곳이 두 군데 있다.', 'There are two places where you can take a meaningful look at Daewangam Hermitage.'),
    (234, 'intro', '대왕암을 의미 있게 눈여겨볼 수 있는 곳이 두 군데 있다. 대본 초등학교 앞쪽에 있는 이견대와 동해구(東海口)라는 표지석 아래 ‘나의 잊히지 못하는 바다’라는 기념비가 서 있는 자리이다.', 'There are two places where you can take a meaningful look at Daewangam Hermitage. This is where a monument called ‘My Unforgettable Sea’ stands under the sign that says Igyeondae and Donghaegu (東海口) in front of Daebon Elementary School.'),
    (234, 'story', '이견대는 화려한 능묘를 마다하고 동해 바다의 용이 되어 나라를 지키겠다고 한 문무왕이 용으로 변한 모습을 보였다는 곳이며 그의 아들 신문왕이 천금과도 바꿀 수 없는 값진 보배 만파식적을 얻었다는 유서 깊은 곳이다.
이견대라는 이름은 ‘주역’의 ‘비룡재천 이견대인(飛龍在天 利見大人)’이라는 이름에서 따온 것이며 현재의 건물은 1970년 발굴조사 때 드러난 초석에 근거하여 최근에 지은 것이다.
동해구 표지석 아래로 내려가면 우현 고유섭 선생의 반일 의지를 기리기 위해 1985년 제자들이 세운 기념비 ‘나의 잊히지 못하는 바다’가 보인다.', 'Igyeondae is a place with a long history where King Munmu, who refused to build a splendid tomb and became a dragon of the East Sea to protect his country, is said to have transformed into a dragon, and where his son, King Sinmun, acquired the Manpasikjeok, a precious treasure worth a thousand pieces of gold.
The name Igyeondae is taken from the name ‘Biryongjaecheon Igyeondaein (飛龍在天 利見大人)’ in ‘Juyeok’, and the current building was recently built based on the cornerstone revealed during an excavation in 1970.
If you go down the Donghae-gu marker, you will see the monument ‘My Unforgettable Sea’ erected by Woohyun Yoo Yoo-seop’s students in 1985 to commemorate his anti-Japanese will.'),
    (234, 'tip', '경주 이견대에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Igyeondae in Gyeongju, the perceived environment changes greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (234, 'did_you_know', '이견대라는 이름은 ‘주역’의 ‘비룡재천 이견대인(飛龍在天 利見大人)’이라는 이름에서 따온 것이며 현재의 건물은 1970년 발굴조사 때 드러난 초석에 근거하여 최근에 지은 것이에요.', 'The name Igyeondae is taken from the name ‘Biryongjaecheon Igyeondaein (飛龍在天 利見大人)’ in ‘Juyeok’, and the current building was recently built based on the cornerstone revealed during an excavation in 1970.'),
    (235, 'summary', '원성왕릉은 낮은 구릉의 남쪽 소나무 숲에 있는 것으로 신라 제38대 원성왕(재위 785∼798)의 무덤으로 추정된다.', 'King Wonseong''s tomb is located in a pine forest on the southern side of a low hill and is presumed to be the tomb of King Wonseong, the 38th king of Silla (reigned 785-798).'),
    (235, 'intro', '원성왕릉은 낮은 구릉의 남쪽 소나무 숲에 있는 것으로 신라 제38대 원성왕(재위 785∼798)의 무덤으로 추정된다. 원성왕의 이름은 경신이며 내물왕의 12대 후손으로 독서삼품과를 새로 설치하고 벽골제를 늘려쌓는 등 많은 업적을 남겼다.', 'King Wonseong''s tomb is located in a pine forest on the southern side of a low hill and is presumed to be the tomb of King Wonseong, the 38th king of Silla (reigned 785-798). King Wonseong''s name is Gyeongshin, and he is the 12th generation descendant of King Naemul. He left behind many achievements, such as establishing a new Doksampoomgwa and increasing Byeokgolje.'),
    (235, 'story', '왕릉이 만들어지기 전에 원래는 작은 연못이 있었는데, 연못의 모습을 변경하지 않고 왕의 시체를 수면 위에 걸어 장례 하였다는 속설에 따라 괘릉이라는 이름이 붙여졌다.
이 능은 원형 봉토분으로 지름 약 23m, 높이 약 6m이다.
흙으로 덮은 둥근 모양의 무덤 아래에는 무덤의 보호를 위한 둘레석이 있는데, 이 돌에 12 지신상이 조각되어 있다.', 'Before the royal tomb was built, there was originally a small pond, and it was named Gwaereung based on the popular belief that the king''s body was hung on the water for burial without changing the shape of the pond.
This tomb is a circular mound with a diameter of approximately 23m and a height of approximately 6m.
Under the round tomb covered with earth, there is a surrounding stone to protect the tomb, and the 12 earthly gods are carved into this stone.'),
    (235, 'tip', '경주 원성왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting King Wonseong''s Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (235, 'did_you_know', '원성왕릉은 낮은 구릉의 남쪽 소나무 숲에 있는 것으로 신라 제38대 원성왕(재위 785∼798)의 무덤으로 추정돼요.', 'King Wonseong''s tomb is located in a pine forest on the southern side of a low hill and is believed to be the tomb of King Wonseong, the 38th king of Silla (reigned 785-798).'),
    (236, 'summary', '경주 남산 서쪽에 위치한 소나무 숲으로 삼릉이 위치해 있으며, 능 주변으로 아름드리 도래솔이 군무하듯 조화를 이루고 있는 곳이다.', 'Samneung is located in a pine forest located on the west side of Namsan Mountain in Gyeongju, and around the tomb are beautiful pine trees dancing in harmony.'),
    (236, 'intro', '삼릉숲은 경주 남산 서쪽에 위치한 소나무 숲으로 삼릉이 위치해 있으며, 능 주변으로 아름드리 도래솔이 군무하듯 조화를 이루고 있는 곳이다. 경주 남산은 북쪽의 금오산과 남쪽의 고위산 모두를 이르는 것으로 고대국가 신라의 중요한 국사를 의논하던 사령지이면서 초기 궁궐지, 왕릉, 불교 조각 등 수많은 문화유산이 분포되어 있는 신라와 경주의 신령스러운 공간이다.', 'Samneung Forest is a pine forest located on the west side of Namsan Mountain in Gyeongju, where Samneung is located. It is a place where beautiful pine trees dance in harmony around the tomb. Gyeongju Namsan, which covers both Geumosan Mountain in the north and Gowisan Mountain in the south, is a military base where important national affairs of the ancient nation of Silla were discussed, and is a sacred space for Silla and Gyeongju where numerous cultural heritages such as early palace sites, royal tombs, and Buddhist sculptures are distributed.'),
    (236, 'story', '그리고 김시습이 남산 금오산실에 머물면서 우리나라 최초 소설 금오신화 등 다양한 저술 활동을 한 문학적 고향이기도 하다.
경주는 다양한 역사 수림을 간직한 역사 도시로 사진작가들에게 숲 촬영지로 가장 유명하다.
구불구불한 소나무들 사이로 내리는 햇빛은 가히 환상적이며 봄날 소나무 사이로 피는 진달래도 진풍경 중 하나이다.', 'It is also the literary hometown where Kim Si-seup stayed at Geumosansil on Namsan Mountain and wrote various works, including Korea''s first novel, Geumosinhwa.
Gyeongju is a historical city with a variety of historical forests and is the most famous forest location for photographers.
The sunlight falling between the winding pine trees is truly fantastic, and the azalea blooming between the pine trees in spring is also one of the most beautiful sights.'),
    (236, 'tip', '삼릉숲에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'In Samneung Forest, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (236, 'did_you_know', '그리고 김시습이 남산 금오산실에 머물면서 우리나라 최초 소설 금오신화 등 다양한 저술 활동을 한 문학적 고향이기도 하다고 해요.', 'It is also said to be the literary hometown of Kim Si-seup, who stayed at Geumosansil on Namsan Mountain and wrote various works, including Korea''s first novel, Geumosinhwa.'),
    (237, 'summary', '황룡사는 6세기 신라시대 때 만들어져 고려 13세기 몽고의 침입으로 불타 없어진 사찰로 지금은 그 규모를 짐작할 수 있는 터만 남아있다.', 'Hwangnyongsa Temple was built during the Silla Dynasty in the 6th century and burned down during the Mongolian invasion in the 13th century during the Goryeo Dynasty. Now only the site remains, which gives an idea of ​​its size.'),
    (237, 'intro', '황룡사는 6세기 신라시대 때 만들어져 고려 13세기 몽고의 침입으로 불타 없어진 사찰로 지금은 그 규모를 짐작할 수 있는 터만 남아있다. 면적 8,800평 규모에 불국사의 8배나 되는 대형 사찰로 추정된다.', 'Hwangnyongsa Temple was built during the Silla Dynasty in the 6th century and burned down during the Mongolian invasion in the 13th century during the Goryeo Dynasty. Now only the site remains, which gives an idea of its size. It is estimated to be a large temple with an area of ​​8,800 pyeong, eight times larger than Bulguksa Temple.'),
    (237, 'story', '왕명으로 553년(신라 진흥왕 14)에 창건하기 시작하여 566년에 주요 전당들이 완성되었고, 금당은 584년(진평왕 6)에 완성되었다.
선덕여왕 14년(645년) 탑의 건조까지 모두 완성된 황룡사는 신라의 호국 신앙의 중심지였다.
황룡사 경내에는 신라 보물 중 하나인 황룡사 구층 목탑이 있었으며 이는 당나라 유학 후 돌아온 승려 자장대사의 건의로 백제의 아비지에 의해 3년 만에 완성된 신라의 상징물이었다.', 'Construction began in 553 (the 14th year of King Jinheung''s reign of Silla) by royal order, and the main halls were completed in 566, and Geumdang was completed in 584 (6th year of King Jinpyeong''s reign).
Hwangnyongsa Temple, which was completed including the construction of the pagoda in the 14th year of Queen Seondeok (645), was the center of Silla''s religious beliefs.
Within the grounds of Hwangnyongsa Temple was the nine-story wooden pagoda of Hwangryongsa Temple, one of Silla''s treasures. It was a symbol of Silla that was completed in three years by the father of Baekje at the suggestion of the monk Jajangdaesa, who returned from studying abroad in the Tang Dynasty.'),
    (237, 'tip', '경주 황룡사지을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Hwangnyongsa Temple Site in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (237, 'did_you_know', '황룡사는 6세기 신라시대 때 만들어져 고려 13세기 몽고의 침입으로 불타 없어진 사찰로 지금은 그 규모를 짐작할 수 있는 터만 남아있어요.', 'Hwangnyongsa Temple was built during the Silla Dynasty in the 6th century and burned down during the Mongolian invasion in the 13th century during the Goryeo Dynasty. Now only the site remains, which gives an idea of its size.'),
    (238, 'summary', '경주에서 불국사로 가는 길의 북쪽 구릉자락에 위치한 통일신라시대의 무덤이다.', 'It is a tomb from the Unified Silla period located at the foot of a hill on the north side of the road from Gyeongju to Bulguksa Temple.'),
    (238, 'intro', '경주 구정동 방형분은 경주에서 불국사로 가는 길의 북쪽 구릉자락에 위치한 통일신라시대의 무덤이다. 이 방형분은 한 변의 길이가 9.5m 높이가 2m이다.', 'The square tomb in Gujeong-dong, Gyeongju is a tomb from the Unified Silla period located at the foot of a hill on the north side of the road from Gyeongju to Bulguksa Temple. This square has a side length of 9.5m and a height of 2m.'),
    (238, 'story', '무덤의 형태는 정사각형이고 흙을 덮어 만든 봉분 아래에는 무덤을 보호하는 의미를 갖는 12지신상이 조각된 둘레돌이 배치되어 있다.
둘레돌을 배치하는 것은 삼국시대 이후부터 내려오는 전통인데, 통일신라시대 경주지방의 왕릉에서는 12지신상을 조각한 둘레돌을 흔히 볼 수 있다.
무덤 내부에는 봉분의 남쪽으로 치우쳐 직사각형의 상자형으로 축조된 굴식돌방무덤(횡혈식석실분)이 있다.', 'The shape of the tomb is square, and under the earthen mound, there is a surrounding stone carved with the 12 zodiac signs, which is meant to protect the tomb.
Arranging circumference stones is a tradition that has been passed down since the Three Kingdoms period, and circumference stones with 12 zodiac signs carved into them can often be seen in the royal tombs of the Gyeongju region during the Unified Silla Dynasty.
Inside the tomb, there is a cave-style stone chamber tomb (horizontal stone chamber tomb) built in the shape of a rectangular box, oriented towards the south of the burial mound.'),
    (238, 'tip', '경주 구정동 방형분에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At the square tomb in Gujeong-dong, Gyeongju, walk around comparing the sizes and spacing of the mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (238, 'did_you_know', '무덤의 형태는 정사각형이고 흙을 덮어 만든 봉분 아래에는 무덤을 보호하는 의미를 갖는 12지신상이 조각된 둘레돌이 배치되어 있어요.', 'The shape of the tomb is square, and under the earthen mound, there is a surrounding stone carved with the 12 zodiac signs, which is meant to protect the tomb.'),
    (239, 'summary', '신라 26대 진평왕(재위 579∼632)의 무덤이다.', 'This is the tomb of King Jinpyeong, the 26th king of Silla (reigned 579-632).'),
    (239, 'intro', '경주 진평왕릉은 신라 26대 진평왕(재위 579∼632)의 무덤이다. 진평왕은 독자적 왕권을 확립하기 위해 새로운 중앙 행정부서를 설치하였다.', 'King Jinpyeong''s Tomb in Gyeongju is the tomb of King Jinpyeong, the 26th king of Silla (reigned 579-632). King Jinpyeong established a new central administrative department to establish independent royal authority.'),
    (239, 'story', '또한 중국의 수·당나라와의 외교관계를 통해 백제와 고구려의 침공을 효율적으로 막았고, 경주 명활성을 보수하여 수도 방위에 힘썼다.
높이 7.9m, 지름 36.4m의 둥글게 흙을 쌓은 원형 봉토무덤이다.
무덤 밑둘레에는 자연석을 이용해 둘레돌을 둘렀으나 현재 몇 개만 남아있다.', 'In addition, through diplomatic relations with China''s Sui and Tang dynasties, the invasion of Baekje and Goguryeo was effectively prevented, and the Gyeongju Myeonghyeong Fortress was repaired to defend the capital.
It is a circular earthen tomb with a height of 7.9m and a diameter of 36.4m.
Natural stones were used to surround the bottom of the tomb, but only a few remain.'),
    (239, 'tip', '경주 진평왕릉에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At the Royal Tomb of King Jinpyeong in Gyeongju, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (239, 'did_you_know', '경주 진평왕릉은 신라 26대 진평왕(재위 579∼632)의 무덤이에요.', 'King Jinpyeong''s Tomb in Gyeongju is the tomb of King Jinpyeong, the 26th king of Silla (reigned 579-632).'),
    (240, 'summary', '경주의 분황사 주변에는 매년 봄 싱그러운 청보리밭이 펼쳐진다.', 'Every spring, fresh green barley fields unfold around Bunhwangsa Temple in Gyeongju.'),
    (240, 'intro', '경주의 분황사 주변에는 매년 봄 싱그러운 청보리밭이 펼쳐진다. 추석 직후에 파종한 보리가 이듬해 봄부터 초여름까지 색다른 볼거리를 제공하는 것으로 분황사 주차장에서 황룡사지 방향을 바라보면 황룡사 역사문화관을 배경으로 짙푸른 청보리밭이 끝도 없이 펼쳐진다.', 'Every spring, fresh green barley fields unfold around Bunhwangsa Temple in Gyeongju. Barley sown right after Chuseok provides a unique attraction from the spring to early summer of the following year. If you look toward the Hwangnyongsa Temple Site from the Bunhwangsa Temple parking lot, the deep green green barley fields spread out endlessly with the Hwangnyongsa History and Culture Museum in the background.'),
    (240, 'story', '파란 하늘과 따스한 햇살, 봄바람에 일렁이는 청보리가 보는 이들의 마음을 설레게 한다.
해 질 무렵에는 노을에 물든 청보리가 황금빛으로 반짝이며 천년 경주의 매력을 더한다.
오늘의 분황사 청보리밭은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The blue sky, warm sunlight, and green barley swaying in the spring breeze thrill the hearts of those who see it.
At dusk, the green barley colored by the sunset sparkles in golden light, adding to the charm of the thousand-year-old Gyeongju.
Today’s Bunhwangsa Temple green barley field remains a different memory for each person visiting Gyeongju.'),
    (240, 'tip', '분황사 청보리밭에서는 건축물만 빠르게 보고 나오기보다 탑과 전각의 배치, 뒤편 산세를 함께 살펴보세요. 안내문을 먼저 읽으면 남아 있는 터와 돌의 의미를 찾기 쉬워요.', 'In the green barley field of Bunhwangsa Temple, rather than just quickly looking at the buildings, take a look at the arrangement of the pagodas and pavilions and the mountain landscape behind them. If you read the notice first, it is easy to find the meaning of the remaining grounds and stones.'),
    (240, 'did_you_know', '해 질 무렵에는 노을에 물든 청보리가 황금빛으로 반짝이며 천년 경주의 매력을 더해요.', 'At sunset, the green barley colored by the sunset sparkles golden, adding to the charm of the thousand-year-old Gyeongju.'),
    (241, 'summary', '경주 시내에서 동쪽으로 떨어진 대종 하구에 자리한 봉길해수욕장은 백사장 길이 500m, 폭 40m이다.', 'Bonggil Beach, located at the mouth of Daejong, east of downtown Gyeongju, has a white sand beach of 500m in length and 40m in width.'),
    (241, 'intro', '경주 시내에서 동쪽으로 떨어진 대종 하구에 자리한 봉길해수욕장은 백사장 길이 500m, 폭 40m이다. 동해안의 다른 해수욕장에 비해 피서객이 적어 여유로운 휴가를 보내고 싶은 사람에게 추천한다.', 'Bonggil Beach, located at the mouth of Daejong, east of downtown Gyeongju, has a white sand beach of 500m in length and 40m in width. Compared to other beaches on the east coast, there are fewer vacationers, so it is recommended for those who want to spend a leisurely vacation.'),
    (241, 'story', '여름이면 비치 방갈로와 튜브 대여소, 간이음식점들이 자리해 피서객에게 편의를 제공한다.
모래사장에서 조금 떨어진 바다에는 문무대왕의 바다
위 무덤인 대왕암이 있다.', 'In summer, beach bungalows, tube rentals, and snack bars are located here to provide convenience to vacationers.
The sea a little away from the sandy beach is the sea of King Munmu.
There is Daewangam, the tomb above.'),
    (241, 'tip', '봉길대왕암해변에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Bonggil Daewangam Beach, the perceived environment changes greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (241, 'did_you_know', '경주 시내에서 동쪽으로 떨어진 대종 하구에 자리한 봉길해수욕장은 백사장 길이 500m, 폭 40m이에요.', 'Bonggil Beach, located at the mouth of Daejong, east of downtown Gyeongju, has a white sand beach of 500m in length and 40m in width.'),
    (242, 'summary', '지난 2004년 정부의 어촌관광단지 조성 사업지구로 선정되어 관광어항으로 거듭나기 시작했다.', 'In 2004, it was selected as a fishing village tourism complex development project area by the government and began to be reborn as a tourist fishing port.'),
    (242, 'intro', '전촌항은 지난 2004년 정부의 어촌관광단지 조성 사업지구로 선정되어 관광어항으로 거듭나기 시작했다. 2009년에는 리모델링 사업을 진행하여 주차장, 광장, 바닥분수, 파고라, 정자, 나무데크산책로, 전망대 등을 갖췄다.', 'Jeonchon Port was selected as a fishing village tourism complex development project area by the government in 2004 and began to be reborn as a tourist fishing port. In 2009, a remodeling project was carried out and a parking lot, plaza, floor fountain, pergola, pavilion, wooden deck walkway, and observatory were installed.'),
    (242, 'story', '특히, 전촌항 전망대에서 내려다보는 평화로운 항구의 풍경이 인상적이다.
방파제에 야간경관조명도 설치해 밤에도 아름답게 빛난다.
전촌항 입구의 말 조형물, 일명 거마상도 볼거리이다.', 'In particular, the peaceful harbor view from the Jeonchon Port observatory is impressive.
Night scenery lighting has also been installed on the breakwater, so it glows beautifully at night.
The horse sculpture at the entrance to Jeonchon Port, also known as the Geomasang, is also a must-see.'),
    (242, 'tip', '전촌항은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at Jeonchon Port just before sunset, you can see the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (242, 'did_you_know', '전촌항은 지난 2004년 정부의 어촌관광단지 조성 사업지구로 선정되어 관광어항으로 거듭나기 시작했다고 해요.', 'Jeonchon Port was selected as a fishing village tourism complex development project site by the government in 2004 and began to be reborn as a tourist fishing port.'),
    (243, 'summary', '황성공원에 위치한 ‘경주축구공원’은 유소년 축구 경기부터 프로 축구 경기까지 크고 작은 축구 경기가 열릴 수 있도록 6면의 축구 경기장과 1면의 풋살경기장을 지닌 축구 공원이다.', '‘Gyeongju Soccer Park’, located in Hwangseong Park, is a soccer park with six soccer fields and one futsal field so that large and small soccer games can be held, from youth soccer games to professional soccer games.'),
    (243, 'intro', '황성공원에 위치한 ‘경주축구공원’은 유소년 축구 경기부터 프로 축구 경기까지 크고 작은 축구 경기가 열릴 수 있도록 6면의 축구 경기장과 1면의 풋살경기장을 지닌 축구 공원이다. 축구 경기장 6면(천연잔디 3면, 인조잔디 3면), 풋살장 1면(인조잔디)으로 구성되어 있다.', '‘Gyeongju Soccer Park’, located in Hwangseong Park, is a soccer park with six soccer fields and one futsal field so that large and small soccer games can be held, from youth soccer games to professional soccer games. It consists of 6 sides of the soccer stadium (3 sides of natural grass, 3 sides of artificial grass) and 1 side of the futsal field (artificial grass).'),
    (243, 'story', '경주공공서비스예약 사이트를 통해 예약 완료 후 사용 가능하다.
넉넉하고 넓은 시설로 이루어져 있어 운동하기에 안성맞춤인 곳이다.
오늘의 경주축구공원은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'It can be used after making a reservation through the Gyeongju public service reservation site.
It is a perfect place for exercising as it has ample and spacious facilities.
Today''s Gyeongju Soccer Park leaves a different memory for each person who visits Gyeongju.'),
    (243, 'tip', '경주축구공원은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'If you walk to Gyeongju Soccer Park in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (243, 'did_you_know', '넉넉하고 넓은 시설로 이루어져 있어 운동하기에 안성맞춤인 곳이에요.', 'It has ample and spacious facilities, making it a perfect place to exercise.'),
    (244, 'summary', '경북 경주시 경주엑스포공원 내 장보고관에 자리 잡고 있다.', 'It is located in the Jangbogo Hall in Gyeongju Expo Park, Gyeongju-si, Gyeongbuk.'),
    (244, 'intro', '또봇정크아트뮤지엄은 경북 경주시 경주엑스포공원 내 장보고관에 자리 잡고 있다. 뮤지엄은 변신 자동차 또봇을 모델로 하고 있어서 어린이들이 정크아트와 아트 트릭 미술을 쉽게 이해하고 경험할 수 있다.', 'Tobot Junk Art Museum is located in the Jangbogo Hall in Gyeongju Expo Park, Gyeongju-si, Gyeongsangbuk-do. The museum is modeled after the transforming car Tobot, so children can easily understand and experience junk art and art trick art.'),
    (244, 'story', '거대한 또봇을 눈앞에서 볼 수 있어 아이와 함께 방문하기 좋다.
배지 만들기, 권투 로봇 체험, 로봇 자동차 체험 등도 마련되어 있다.
주변에는 블루원 디아너스 CC, 경주블루원블루스카이글램핑이 있어 함께 방문하기 좋다.', 'It is great to visit with children as you can see the huge Tobot right in front of you.
Badge making, boxing robot experience, and robot car experience are also available.
Nearby are Blue One Theanus CC and Gyeongju Blue One Blue Sky Glamping, making it a good place to visit together.'),
    (244, 'tip', '또봇정크아트뮤지엄은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'At Tobot Junk Art Museum, the site format and equipment provided may vary depending on the site. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (244, 'did_you_know', '주변에는 블루원 디아너스 CC, 경주블루원블루스카이글램핑이 있어 함께 방문하기 좋다고 해요.', 'Nearby are Blue One Deaners CC and Gyeongju Blue One Blue Sky Glamping, making it a good place to visit together.'),
    (245, 'summary', '역사와 문화의 도시 경주에 위치하고 있으며 지하 1층부터 지상 3층까지 총 네 개층으로 구성되어 있다.', 'It is located in Gyeongju, a city of history and culture, and consists of a total of four floors, from the first basement floor to the third floor above ground.'),
    (245, 'intro', '한국대중음악박물관은 역사와 문화의 도시 경주에 위치하고 있으며 지하 1층부터 지상 3층까지 총 네 개층으로 구성되어 있다. 1층은 음악감상실에서 전설의 스피커 미로포닉에서 흘러나오는 노래를 감상할 수 있는 곳이다.', 'The Korean Popular Music Museum is located in Gyeongju, a city of history and culture, and consists of a total of four floors, from the first basement floor to the third floor above ground. The first floor is a music listening room where you can listen to songs coming from the legendary Mirophonic speaker.'),
    (245, 'story', '2층 전시실은 한국대중음악 100년사관으로 1896년 대한민국의 최초 노래가 녹음된 에디슨 실린더 음반부터 2000년대 k-pop음반까지 시대순으로 전시되어 있고 노래 듣기 체험을 할 수 있으며, 3층 전시실은 오디오 100년사관으로 1926년 제작된 인류 최초 스피커, 1936년 제작된 스피커의 전설이라고 하는 미국의 웨스턴 일렉트릭의 미로포닉, 제2차 세계대전 당시 히틀러가 연설할 때 사용하던 스피커 등 각종 희귀 스피커를 전시 및 청음할…
지하는 악기 체험관, 어린이 체험관, 동전노래방, 포토존으로 구성되어 있어 체험과 재미를 느낄 수 있다.
오늘의 한국대중음악박물관은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The 2nd floor exhibition room is a 100-year history of Korean popular music, and displays items in chronological order from the Edison cylinder album on which Korea''s first song was recorded in 1896 to the K-pop albums of the 2000s, and allows you to experience listening to songs. The 3rd floor exhibition room is a 100-year history of audio, including mankind''s first speaker manufactured in 1926, American Western Electric''s Myrophonic, a legendary speaker manufactured in 1936, and Various rare speakers, including those used by Hitler during his speeches during World War II, are on display and available for listening…
The basement consists of a musical instrument experience center, a children''s experience center, a coin karaoke room, and a photo zone, allowing you to experience and have fun.
Today''s Korean Popular Music Museum leaves a different memory for each person who visits Gyeongju.'),
    (245, 'tip', '한국대중음악박물관에서는 관심 있는 전시부터 정한 뒤 관람 동선을 잡아보세요. 해설 시간을 맞출 수 있다면 전시물을 본 뒤 주변 실제 유적까지 연결해 둘러보는 코스가 좋아요.', 'At the Korea Popular Music Museum, choose the exhibition you are interested in and then plan your viewing route. If you can fit in the commentary time, a course that connects you to the actual surrounding ruins after viewing the exhibits is a good option.'),
    (245, 'did_you_know', '2층 전시실은 한국대중음악 100년사관으로 1896년 대한민국의 최초 노래가 녹음된 에디슨 실린더 음반부터 2000년대 k-pop음반까지 시대순으로 전시되어 있고 노래 듣기 체험을 할 수 있으며, 3층 전시실은 오디오 100년사관으로 1926년 제작된 인류 최초 스피커, 1936년 제작된 스피커의 전설이라고 하는 미국의 웨스턴 일렉트릭의 미로포닉, 제2차 세계대전 당시 히틀러가 연설할 때 사용하던 스피커 등 각종 희귀 스피커를 전시 및 청음할 수 있어요.', 'The 2nd floor exhibition room is a 100-year history of Korean popular music, and displays items in chronological order from the Edison cylinder album on which Korea''s first song was recorded in 1896 to the K-pop albums of the 2000s, and allows you to experience listening to songs. The 3rd floor exhibition room is a 100-year history of audio, including mankind''s first speaker manufactured in 1926, American Western Electric''s Myrophonic, a legendary speaker manufactured in 1936, and You can exhibit and listen to various rare speakers, including those used by Hitler during his speeches during World War II.'),
    (246, 'summary', '경주엑스포대공원에서 할로윈 시즌마다', 'Every Halloween season at Gyeongju Expo Grand Park'),
    (246, 'intro', '경주엑스포대공원에서 할로윈 시즌마다 열리는 체험형 콘텐츠로 올해 5년째 이어지고 있다.', 'This is an experiential content held every Halloween season at Gyeongju Expo Grand Park and has been running for the fifth year.'),
    (246, 'story', '어린이를 동반한 가족 단위 관람객이 많이 찾는 대표 프로그램이며, 2024년부터는 ‘EX-펌킨나잇’이라는 브랜드로 운영되어 전 연령층이 함께 즐길 수 있는 축제로 자리매김하였다.
2025년에는 온 세상이 호박으로 이루어진 신비한 나라 매직킹덤을 탐험하는 콘셉트로, 행사장 전체를 하나의 국가처럼 구성하였다.
소방서, 경찰서, 방송국 등 국가의 필수 기관을 할로윈 분위기와 결합하여 재해석함으로써 단순한 볼거리를 넘어 참여와 체험의 기회를 제공한다.', 'It is a representative program frequently visited by families with children, and from 2024, it will be operated under the brand ‘EX-Pumpkin Night’, establishing itself as a festival that all age groups can enjoy together.
In 2025, the entire event venue was organized like one country, with the concept of exploring Magic Kingdom, a mysterious country made entirely of pumpkins.
By reinterpreting the nation''s essential institutions such as fire stations, police stations, and broadcasting stations by combining them with the Halloween atmosphere, it provides opportunities for participation and experience beyond simple attractions.'),
    (246, 'tip', 'EX-펌킨나잇 : 매직킹덤은 아침이나 늦은 오후에 걸으면 빛과 그늘이 만든 풍경을 여유롭게 볼 수 있어요. 전체를 서두르기보다 물가나 숲길처럼 마음에 드는 구간을 골라 천천히 걸어보세요.', 'EX-Pumpkin Night: If you walk to Magic Kingdom in the morning or late afternoon, you can leisurely enjoy the scenery created by light and shade. Rather than rushing through the whole thing, choose a section you like, such as a waterside or forest path, and walk slowly.'),
    (246, 'did_you_know', '어린이를 동반한 가족 단위 관람객이 많이 찾는 대표 프로그램이며, 2024년부터는 ‘EX-펌킨나잇’이라는 브랜드로 운영되어 전 연령층이 함께 즐길 수 있는 축제로 자리매김했어요.', 'It is a representative program frequently visited by families with children, and from 2024, it will be operated under the brand ‘EX-Pumpkin Night’, establishing itself as a festival that all age groups can enjoy together.'),
    (247, 'summary', '경주 정혜사터에 세워져 있는 통일신라시대 특수한 형태의 석조 불탑이다.', 'It is a special type of stone pagoda from the Unified Silla period erected at the site of Jeonghyesa Temple in Gyeongju.'),
    (247, 'intro', '경주 정혜사터에 세워져 있는 통일신라시대 특수한 형태의 석조 불탑이다. 흙으로 쌓은 1단의 기단 위에 13층의 탑신을 올린 모습으로 통일신라시대에서는 그 비슷한 예를 찾아볼 수 없는 독특한 모습이다.', 'It is a special type of stone pagoda from the Unified Silla period erected at the site of Jeonghyesa Temple in Gyeongju. It has a 13-story pagoda body built on a single stylobate made of earth, and is unique in that no similar example can be found in the Unified Silla period.'),
    (247, 'story', '1층 탑몸돌이 거대한데 비해 2층부터는 몸돌과 지붕돌 모두가 급격히 작아져서 2층 이상은 마치 1층탑 위에 덧붙여진 머리 장식처럼 보인다.
큰 규모로 만들어진 1층 몸돌은 네 모서리에 사각형의 돌기둥을 세웠으며, 그 안에 다시 보조 기둥을 붙여 세워 문을 만들어 놓았다.
이렇듯 문을 마련해 놓은 것은 열린 공간을 추구하고자 한 의지의 표현으로 보고 있다.', 'While the body stones of the first floor are huge, both the body and roof stones become drastically smaller from the second floor, so that the second floor and higher look like a headdress added to the first floor of the pagoda.
The large-scale first floor body stone had square stone pillars at the four corners, and auxiliary pillars were placed inside them to create a door.
The provision of a door like this is seen as an expression of the will to pursue open space.'),
    (247, 'tip', '경주 정혜사지 십삼층석탑을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Thirteen-story Stone Pagoda at Jeonghyesa Temple Site, Gyeongju, check the latest operating information and transportation instructions. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (247, 'did_you_know', '흙으로 쌓은 1단의 기단 위에 13층의 탑신을 올린 모습으로 통일신라시대에서는 그 비슷한 예를 찾아볼 수 없는 독특한 모습이에요.', 'It has a 13-story pagoda body built on a single stylobate made of earth, and is unique in that there are no similar examples from the Unified Silla period.'),
    (248, 'summary', '경주 남산 자락에 자리한 보리사는 남북국시대 통일신라 시기에 창건됐으며 남산에서 가장 규모가 큰 사찰이다.', 'Bodhi Temple, located at the foot of Namsan Mountain in Gyeongju, was founded during the Unified Silla period of the North and South Korea era and is the largest temple in Namsan.'),
    (248, 'intro', '경주 남산 자락에 자리한 보리사는 남북국시대 통일신라 시기에 창건됐으며 남산에서 가장 규모가 큰 사찰이다. 신라 헌강왕과 정강왕의 능이 보리사 동남쪽에 위치한다는 내용이 등장할 정도로 유서 깊다.', 'Bodhi Temple, located at the foot of Namsan Mountain in Gyeongju, was founded during the Unified Silla period of the North and South Korea era and is the largest temple in Namsan. It is so historic that it is said that the tombs of King Heongang and King Jeonggang of Silla are located southeast of Borisa Temple.'),
    (248, 'story', '현존하는 건물로는 대웅전과 산신각, 선원, 종각, 요사채 등이 있고 유물로는 통일신라 때 제작된 경주 남산 미륵곡 석조여래좌상과 보리사마애석불이 있다.
경주 남산 미륵곡 석조여래좌상은 남산에서 가장 잘생긴 부처님이라는 별명이 붙을 정도로 얼굴의 윤곽이 뚜렷하고 정교하게 조각되어 있고 전체적인 보존 상태가 좋다.
또, 보리사에서 산길을 따라 35m쯤 오르면 바위에 새긴 마애석불이 있다.', 'Existing buildings include Daeungjeon, Sansingak, Seonwon, Jonggak, and Yosachae, and relics include the stone seated Buddha of Mireukgok in Namsan, Gyeongju, and the Bodhisama Ae Stone Buddha, made during the Unified Silla Dynasty.
The stone seated Buddha in Mireukgok, Namsan Mountain, Gyeongju is nicknamed the most handsome Buddha in Namsan, and has a clear and elaborately carved face, and is in a good overall state of preservation.
Also, if you go up about 35 meters along the mountain path from Bodhi Temple, there is a rock-carved Buddha statue carved into a rock.'),
    (248, 'tip', '보리사(경주)을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Borisa (Gyeongju), check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (248, 'did_you_know', '또, 보리사에서 산길을 따라 35m쯤 오르면 바위에 새긴 마애석불이 있어요.', 'Also, if you go up about 35 meters along the mountain path from Bodhi Temple, there is a rock-carved Buddha carved into a rock.'),
    (249, 'summary', '경북 경주시 강동면에 위치한 캠프 ing는 경주시청을 기점으로 13㎞가량 떨어진 곳에 있다.', 'Camp ing, located in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do, is about 13km away from Gyeongju City Hall.'),
    (249, 'intro', '경북 경주시 강동면에 위치한 캠프 ing는 경주시청을 기점으로 13㎞가량 떨어진 곳에 있다. 숲 속 폐교를 캠핑장으로 개장해 옛 추억을 자극하는 볼거리가 많은 것이 특징이다.', 'Camp ing, located in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do, is about 13km away from Gyeongju City Hall. The abandoned school in the forest has been converted into a camping site, so there are many things to see that bring back memories of the past.'),
    (249, 'story', '캠핑장은 자동차 야영장 30면으로 이뤄져 있고 바닥은 파쇄석 28면과 데크 2면이다.
사이트 크기는 파쇄석이 가로 8m 세로 10m, 데크는 가로 5m 세로 5m다.
개인 트레일러와 카라반의 동반 입장이 가능하며 관리소에서 릴선, 화로대, 난방기구 등 캠핑 장비를 대여하고 있다.', 'The campsite consists of 30 car campsites, with 28 crushed stone floors and 2 decks on the floor.
The size of the site is the crushed stone is 8m wide and 10m high, and the deck is 5m wide and 5m high.
Personal trailers and caravans are allowed to enter, and camping equipment such as reel lines, fire stands, and heaters are available for rent at the management office.'),
    (249, 'tip', '캠프ING에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'Please first check the age, clothing, and equipment requirements for the activity you want to experience at Camp ING. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (249, 'did_you_know', '경북 경주시 강동면에 위치한 캠프 ing는 경주시청을 기점으로 13㎞가량 떨어진 곳에 있어요.', 'Camp ing, located in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do, is about 13km away from Gyeongju City Hall.'),
    (250, 'summary', '경주시 보문동에 자리한 숲 머리 마을은 명활산이 병풍처럼 감싸고 옆으로는 드넓은 보문들이 펼쳐진 아름다운 자연마을이다.', 'Supmeori Village, located in Bomun-dong, Gyeongju-si, is a beautiful natural village with Myeonghwal Mountain surrounding it like a folding screen and wide Bomun gates spreading out to the sides.'),
    (250, 'intro', '경주시 보문동에 자리한 숲 머리 마을은 명활산이 병풍처럼 감싸고 옆으로는 드넓은 보문들이 펼쳐진 아름다운 자연마을이다. 진평왕릉과 보문 사지, 명활산성, 신라왕경 숲과 인접해 여행자들도 가볍게 들르기 좋다.', 'Supmeori Village, located in Bomun-dong, Gyeongju-si, is a beautiful natural village with Myeonghwal Mountain surrounding it like a folding screen and wide Bomun gates spreading out to the sides. It is adjacent to King Jinpyeong''s Tomb, Bomun Temple Site, Myeonghwalsanseong Fortress, and Silla Wanggyeong Forest, making it a good place for travelers to stop by as well.'),
    (250, 'story', '특히 명활산성에서 진평왕릉을 잇는 숲 머리 마을 뒤편 둑에는 ‘선덕여왕길’이란 이름이 붙었는데, 해마다
봄이면 겹벚꽃이 만발해 현지인들에게 숨은 봄꽃 명소로 사랑받는 곳이다.
핑크색 겹벚꽃이 만발한 길을 천천히 걷다', 'In particular, the bank at the back of the village at the head of the forest, which connects Myeonghwalsanseong Fortress to King Jinpyeong’s tomb, was named ‘Queen Seondeok’s Road,’ and it is rebuilt every year.
In spring, double cherry blossoms are in full bloom, making it a popular spot for hidden spring flowers among locals.
Slowly walking down a path filled with pink double cherry blossoms'),
    (250, 'tip', '보문숲머리먹거리촌에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At Bomun Forest Meori Food Village, walk around comparing the sizes and spacing of burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (250, 'did_you_know', '푸짐한 상차림의 한정식을 비롯해 숯불갈비와 매운탕, 오리구이, 순두부, 막국수 등 다양한 먹거리가 모여 있어 든든한 한 끼를 즐기기 좋다고 해요.', 'It is said that it is a good place to enjoy a hearty meal as there are a variety of foods including charcoal-grilled ribs, maeuntang, roast duck, soft tofu, and makguksu, as well as a generous set of Korean dishes.'),
    (251, 'summary', '산내별빛 오토캠핑장은 경북 경주시 산내면에 자리 잡고 있다.', 'Sannae Starlight Auto Camping Site is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (251, 'intro', '산내별빛 오토캠핑장은 경북 경주시 산내면에 자리 잡고 있다. 경주시청을 기점으로 약 46㎞ 거리에 있으며 차량을 이용해 경부고속도로, 단석로, 문복로를 차례로 달리면 도착한다.', 'Sannae Starlight Auto Camping Site is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 46km away from Gyeongju City Hall and can be reached by driving on Gyeongbu Expressway, Danseok-ro, and Munbok-ro in order.'),
    (251, 'story', '이동시간은 50분정도 걸린다.
이곳은 도로와 인접해 접근이 쉽다.
야영장을 숲에 조성해서 자연과 함께 캠핑과 휴식을 할 수 있다.', 'Travel time takes about 50 minutes.
This place is close to the road and is easy to access.
By creating a campsite in the forest, you can camp and relax with nature.'),
    (251, 'tip', '산내별빛오토캠핑장은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'Sannae Starlight Auto Camping Site may vary in site type and equipment provided. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (251, 'did_you_know', '경주시청을 기점으로 약 46㎞ 거리에 있으며 차량을 이용해 경부고속도로, 단석로, 문복로를 차례로 달리면 도착해요.', 'It is about 46km away from Gyeongju City Hall, and can be reached by driving on the Gyeongbu Expressway, Danseok-ro, and Munbok-ro in that order.'),
    (252, 'summary', '용천토리 오토캠핑장은 경북 경주시 산내면에 자리 잡고 있다.', 'Yongcheon-tori Auto Camping Site is located in Sannae-myeon, Gyeongju-si, Gyeongbuk.'),
    (252, 'intro', '용천토리 오토캠핑장은 경북 경주시 산내면에 자리 잡고 있다. 경주 시청을 기점으로 42㎞가량 떨어져 있는데 자동차를 타고 용담로, 건포산업로, 단석로, 문복로를 차례로 달리면 1시간 안팎에 도착할 수 있다.', 'Yongcheon-tori Auto Camping Site is located in Sannae-myeon, Gyeongju-si, Gyeongbuk. It is about 42km away from Gyeongju City Hall, and you can get there in about an hour by car by driving along Yongdam-ro, Geonpo Industrial-ro, Danseok-ro, and Munbok-ro in order.'),
    (252, 'story', '이곳은 사방이 숲으로 둘러싸여 청정한 기분을 느끼게 하고 몇 발자국만 걸어가면 계곡이 있어 한여름 무더위를 날리기에 좋다.
그뿐만 아니라 사과 수확철에는 사과 따기 체험을 진행하는데 일정 비용의 체험료만 내면 1㎏의 사과를 수확해 가져갈 수 있다.
캠핑장에는 파쇄석으로 이뤄진 자동차 야영장 18면이 마련되어 있다.', 'This place is surrounded by forests on all sides, giving you a clean feeling, and there is a valley just a few steps away, making it a great place to beat the midsummer heat.
In addition, during the apple harvest season, there is an apple picking experience where you can harvest 1kg of apples and take them home by paying a certain fee.
The campsite has 18 car campsites made of crushed stone.'),
    (252, 'tip', '용천토리오토캠핑장은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'Yongcheon Tori Auto Camping Site may vary in site type and equipment provided at each site. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (252, 'did_you_know', '경주 시청을 기점으로 42㎞가량 떨어져 있는데 자동차를 타고 용담로, 건포산업로, 단석로, 문복로를 차례로 달리면 1시간 안팎에 도착할 수 있어요.', 'It is about 42km away from Gyeongju City Hall, and you can get there in about an hour by driving along Yongdam-ro, Geonpo Industrial-ro, Danseok-ro, and Munbok-ro in that order.'),
    (253, 'summary', '그린하우스펜션 오토캠핑장은 경북 경주시 산내면에 자리 잡고 있다.', 'Green House Pension Auto Camping Site is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (253, 'intro', '그린하우스펜션 오토캠핑장은 경북 경주시 산내면에 자리 잡고 있다. 경주 시청을 기점으로 39㎞가량 떨어졌다.', 'Green House Pension Auto Camping Site is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 39km away from Gyeongju City Hall.'),
    (253, 'story', '이곳은 물 맑은 청정 계곡과 싱그러운 숲이 조화를 이룬 캠핑장이다.
이 덕택에 휴가철이면 청량감 가득한 숲 속에서 계곡 물놀이를 만끽하며 캠핑을 즐기려는 이들이 끊이지 않는다.
캠핑장에는 일반 야영장 25면을 마련했다.', 'This is a camping site where a clean valley with clear water and a fresh forest are in harmony.
Thanks to this, during the vacation season, there is a constant stream of people who want to enjoy camping while enjoying the water in the valley in a refreshing forest.
The camping site has 25 general campsites.'),
    (253, 'tip', '그린하우스캠핑장에서 체험하려는 활동의 연령·복장·장비 조건을 먼저 확인하세요. 시작 시간보다 여유 있게 도착해 현장 안전 안내를 듣는 것이 좋아요.', 'First check the age, clothing, and equipment requirements for the activity you want to experience at Green House Camping Site. It is a good idea to arrive ahead of the start time and listen to the on-site safety information.'),
    (253, 'did_you_know', '경주 시청을 기점으로 39㎞가량 떨어졌다고 해요.', 'It is said to be about 39km away from Gyeongju City Hall.'),
    (254, 'summary', '경북 경주시 산내면에 자리 잡고 있다.', 'It is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (254, 'intro', '경주힐링캠프는 경북 경주시 산내면에 자리 잡고 있다. 경주시청을 기점으로 31㎞가량 떨어졌다.', 'Gyeongju Healing Camp is located in Sannae-myeon, Gyeongju-si, Gyeongbuk. It is about 31km away from Gyeongju City Hall.'),
    (254, 'story', '자동차에 몸을 싣고 용담로, 건포산업로, 단석로, 장사길을 차례로 달리면 닿는다.
도착까지 소요되는 시간은 40분 안팎이다.
이곳은 체험휴양마을이자 23개의 봉우리에 둘러싸인 다봉마을에 위치했다.', 'You can get there by getting in a car and driving along Yongdam-ro, Geonpo Industrial-ro, Danseok-ro, and Jangsa-gil in order.
It takes about 40 minutes to arrive.
This is an experiential resort village and is located in Dabong Village, surrounded by 23 peaks.'),
    (254, 'tip', '경주힐링캠프은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'Gyeongju Healing Camp''s site type and provided equipment may vary depending on the site. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (254, 'did_you_know', '경주시청을 기점으로 31㎞가량 떨어졌다고 해요.', 'It is said to be about 31km away from Gyeongju City Hall.'),
    (255, 'summary', '경주텐타우스 글램핑은 경북 경주시 강동면에 자리 잡고 있다.', 'Gyeongju Tentaus Glamping is located in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (255, 'intro', '경주텐타우스 글램핑은 경북 경주시 강동면에 자리 잡고 있다. 경주시청을 기점으로 17㎞가량 떨어졌다.', 'Gyeongju Tentaus Glamping is located in Gangdong-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 17km away from Gyeongju City Hall.'),
    (255, 'story', '자동차에 몸을 싣고 산업로, 건포산업로, 천강로를 차례로 달리면 닿는다.
도착까지 걸리는 시간은 20분 안팎이다.
폐교였던 공간을 캠핑장으로 탈바꿈한 이곳은 깔끔하고 고급스러운 느낌이 강하다.', 'You can get there by getting in your car and driving along Saneop-ro, Geonpo-sangno, and Cheongang-ro in order.
It takes about 20 minutes to arrive.
This place, which was an abandoned school, was transformed into a camping site and has a clean and luxurious feel.'),
    (255, 'tip', '경주텐타우스글램핑은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'At Gyeongju Tentaus Glamping, the site type and equipment provided may vary from site to site. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (255, 'did_you_know', '경주시청을 기점으로 17㎞가량 떨어졌다고 해요.', 'It is said to be about 17km away from Gyeongju City Hall.'),
    (256, 'summary', '오류캠핑장은 경북 경주시 감포읍에 자리 잡고 있다.', 'Oryu Camping Site is located in Gampo-eup, Gyeongju-si, Gyeongsangbuk-do.'),
    (256, 'intro', '오류캠핑장은 경북 경주시 감포읍에 자리 잡고 있다. 경주시청을 기점으로 35㎞가량 떨어졌다.', 'Oryu Camping Site is located in Gampo-eup, Gyeongju-si, Gyeongsangbuk-do. It is about 35km away from Gyeongju City Hall.'),
    (256, 'story', '자동차에 몸을 싣고 경감로, 토함산로, 31번 국도를 번갈아 달리면 닿는다.
도착까지 소요 시간은 50분 안팎이다.
경주를 대표하는 해변 가운데 하나인 오류고아라해변 앞에 터를 잡은 이곳은 여름철이면 해수욕과 더불어 캠핑을 즐기려는 이들의 발길이 끊이지 않는다.', 'You can get there by getting in your car and driving alternately along Gyeonggam-ro, Tohamsan-ro, and National Highway 31.
It takes about 50 minutes to arrive.
This place, located in front of Oryugoara Beach, one of the representative beaches of Gyeongju, is constantly visited by people who want to enjoy camping as well as swimming in the sea during the summer.'),
    (256, 'tip', '경주오류캠핑장에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Gyeongju Oryu Camping Site, the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (256, 'did_you_know', '경주시청을 기점으로 35㎞가량 떨어졌다고 해요.', 'It is said to be about 35km away from Gyeongju City Hall.'),
    (257, 'summary', '문복산 캠핑장은 경북 경주시 산내면에 자리 잡고 있다.', 'Munboksan Campground is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (257, 'intro', '문복산 캠핑장은 경북 경주시 산내면에 자리 잡고 있다. 경주시청을 기점으로 도착까지 소요되는 시간은 1시간 안팎이다.', 'Munboksan Campground is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do. It takes about 1 hour to arrive from Gyeongju City Hall.'),
    (257, 'story', '문복산 기슭에 터를 잡은 덕분에 청정한 자연의 이로움을 마음껏 만끽할 수 있다.
변하는 풍광이 두 눈을 즐겁게 해 준다.
캠핑장에는 일반 야영장 70면을 마련했다.', 'Thanks to being located at the foot of Munboksan Mountain, you can fully enjoy the benefits of clean nature.
The changing scenery is a feast for the eyes.
The camping site has 70 general campsites.'),
    (257, 'tip', '문복산캠핑장은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'Munboksan Camping Site may vary in site type and equipment provided. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (257, 'did_you_know', '캠핑장에는 일반 야영장 70면을 마련했다고 해요.', 'It is said that the camping site has 70 general campsites.'),
    (258, 'summary', '경주 별빛마루는 경북 경주시 천북면에 자리 잡고 있다.', 'Gyeongju Byeolbitmaru is located in Cheonbuk-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (258, 'intro', '경주 별빛마루는 경북 경주시 천북면에 자리 잡고 있다. 경주시청을 기점으로 11㎞가량 떨어졌다.', 'Gyeongju Byeolbitmaru is located in Cheonbuk-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 11km away from Gyeongju City Hall.'),
    (258, 'story', '자동차에 몸을 싣고 산업로, 천북로, 천갈로를 차례로 달리면 닿는다.
소요시간은 20분 안팎이다.
숲 속에 위치한 이곳에는 글램핑 18개 동이 있다.', 'You can get there by getting in a car and driving along Saneop-ro, Cheonbuk-ro, and Cheongal-ro in order.
The time required is approximately 20 minutes.
Located in the forest, there are 18 glamping units.'),
    (258, 'tip', '경주별빛마루글램핑장과펜션에 반려동물과 동행할 때는 출입 가능 구역과 목줄·배변 처리 규정을 먼저 확인하세요. 다른 방문객과 동물이 놀라지 않도록 한적한 동선부터 살펴보는 것이 좋아요.', 'When accompanying your pet to Gyeongju Byeolbitmaru Glamping Site and Pension, first check the entry area and leash/disposal regulations. It is a good idea to start from a quiet area so as not to startle other visitors and animals.'),
    (258, 'did_you_know', '경주시청을 기점으로 11㎞가량 떨어졌다고 해요.', 'It is said to be about 11km away from Gyeongju City Hall.'),
    (259, 'summary', '가온누리 캠핑 체험장은 경북 경주시 안강읍에 자리 잡고 있다.', 'Gaonnuri Camping Experience Center is located in Angang-eup, Gyeongju-si, Gyeongsangbuk-do.'),
    (259, 'intro', '가온누리 캠핑 체험장은 경북 경주시 안강읍에 자리 잡고 있다. 경주 시청을 기점으로 19㎞가량 떨어졌다.', 'Gaonnuri Camping Experience Center is located in Angang-eup, Gyeongju-si, Gyeongsangbuk-do. It is about 19km away from Gyeongju City Hall.'),
    (259, 'story', '자동차를 이용해 백률로, 용담로, 새안현로를 차례로 달리면 닿는다.
도착까지 걸리는 시간은 30분 안팎이다.
폐교를 리모델링해 캠핑장으로 새롭게 단장한 이곳은 이색적인 부대시설이 차고 넘친다.', 'You can reach it by driving on Baengnyul-ro, Yongdam-ro, and Saeanhyeon-ro in order.
It takes about 30 minutes to arrive.
This place, which was a remodeled abandoned school and renovated into a camping ground, is full of unique facilities.'),
    (259, 'tip', '가온누리캠핑체험장은 사이트 형태와 제공 비품이 자리마다 다를 수 있어요. 전기 사용, 주차 위치, 취사 규정과 주변 장보기 장소를 예약 전에 함께 확인하세요.', 'Gaon Nuri Camping Experience Center’s site type and provided equipment may vary depending on the site. Please check electricity usage, parking location, cooking regulations, and nearby grocery locations before making a reservation.'),
    (259, 'did_you_know', '경주 시청을 기점으로 19㎞가량 떨어졌다고 해요.', 'It is said to be about 19km from Gyeongju City Hall.'),
    (260, 'summary', '경북 경주시 산내면에 자리 잡고 있다.', 'It is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do.'),
    (260, 'intro', '곤달비캠프는 경북 경주시 산내면에 자리 잡고 있다. 경주시청을 기점으로 37㎞가량 떨어졌다.', 'Gondalbi Camp is located in Sannae-myeon, Gyeongju-si, Gyeongsangbuk-do. It is about 37km away from Gyeongju City Hall.'),
    (260, 'story', '자동차에 몸을 싣고 용담로, 건포산업로, 단석로를 차례로 달리면 닿는다.
도착까지 걸리는 시간은 50분 안팎이다.
이곳은 숲으로 둘러싸여 있어 자연친화적인 캠핑을 만끽할 수 있다.', 'You can get there by getting in a car and driving along Yongdam-ro, Geonpo Industrial-ro, and Danseok-ro in order.
It takes about 50 minutes to arrive.
This place is surrounded by a forest, so you can enjoy nature-friendly camping.'),
    (260, 'tip', '곤달비캠프에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Gondalbi Camp, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (260, 'did_you_know', '경주시청을 기점으로 37㎞가량 떨어졌다고 해요.', 'It is said to be about 37km away from Gyeongju City Hall.'),
    (261, 'summary', '경주 마동큰마을에 조성된 곳으로 접근성이 좋고, 불국사 인근 경주 유적지 탐방하기에도 좋은 위치에 있다.', 'It is a place built in Madong Big Village, Gyeongju, and has good accessibility, and is also in a good location for exploring Gyeongju historical sites near Bulguksa Temple.'),
    (261, 'intro', '경주 마동큰마을에 조성된 곳으로 접근성이 좋고, 불국사 인근 경주 유적지 탐방하기에도 좋은 위치에 있다. 텐트 없이 당일 피크닉도 즐길 수 있는 자유로운 캠핑장이다.', 'It is a place built in Madong Big Village, Gyeongju, and has good accessibility, and is also in a good location for exploring Gyeongju historical sites near Bulguksa Temple. It is a free camping site where you can enjoy a day picnic without a tent.'),
    (261, 'story', '물놀이를 위한 수영장, 보트를 타고 놀 수 있는 보트장 등 아이들이 즐길 수 있는 시설들이 준비되어 있다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 용천수캠핑장은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'There are facilities for children to enjoy, including a swimming pool for water play and a boating area for boating.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today’s Yongcheonsu Camping Site remains a different memory for each person visiting Gyeongju.'),
    (261, 'tip', '용천수캠핑장에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at Yongcheonsu Campground, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (261, 'did_you_know', '경주 마동큰마을에 조성된 곳으로 접근성이 좋고, 불국사 인근 경주 유적지 탐방하기에도 좋은 위치에 있어요.', 'It is a place built in Madong Big Village, Gyeongju, and is easily accessible, and is also in a good location for exploring Gyeongju historical sites near Bulguksa Temple.'),
    (262, 'summary', '경주 더숲캠핑장은 물놀이가 가능한 계곡이 가까이에 있고 넓은 잔디광장과 트램펄린, 야외 수영장, 모래 놀이터를 갖춰 어린이들이 즐길 수 있는 캠핑장이다.', 'Gyeongju The Forest Camping Site is a camping site that children can enjoy, with a nearby valley where they can play in the water, and a large lawn plaza, trampoline, outdoor swimming pool, and sand playground.'),
    (262, 'intro', '경주 더숲캠핑장은 물놀이가 가능한 계곡이 가까이에 있고 넓은 잔디광장과 트램펄린, 야외 수영장, 모래 놀이터를 갖춰 어린이들이 즐길 수 있는 캠핑장이다. 사이트 사이 간격이 넓어 쾌적하다.', 'Gyeongju The Forest Camping Site is a camping site that children can enjoy, with a nearby valley where they can play in the water, and a large lawn plaza, trampoline, outdoor swimming pool, and sand playground. The space between sites is wide so it is comfortable.'),
    (262, 'story', '실시간 인터넷 예약이나 전화로 예약해야 한다.
사이트 예약 후에는 선착순으로 자리 지정이 가능하다.
오늘의 더숲캠핑장은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'Reservations must be made in real time online or by phone.
After site reservation, seats can be assigned on a first-come, first-served basis.
Today’s The Forest Camping Site remains a different memory for each person visiting Gyeongju.'),
    (262, 'tip', '더숲캠핑장에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to play in the water at The Forest Campground, check the operation status and terms of use first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (262, 'did_you_know', '사이트 예약 후에는 선착순으로 자리 지정이 가능하다고 해요.', 'After making a site reservation, seats can be assigned on a first-come, first-served basis.'),
    (263, 'summary', '「2026 경주국가유산야행」은 경주의 역사와 문화유산을 밤의 풍경 속에서 만나볼 수 있는 행사이다.', '“2026 Gyeongju National Heritage Night Tour” is an event where you can experience the history and cultural heritage of Gyeongju in the night scenery.'),
    (263, 'intro', '「2026 경주국가유산야행」은 경주의 역사와 문화유산을 밤의 풍경 속에서 만나볼 수 있는 행사이다. 이번 행사의 공식 부제는 「파편(破片) - 지켜 온, 그리고 지켜낼」이며, 경주에 남아 있는 다양한 국가유산과 역사문화자원을 활용하여 야간에 문화유산을 경험할 수 있도록 마련된 행사이다.', '“2026 Gyeongju National Heritage Night Tour” is an event where you can experience the history and cultural heritage of Gyeongju in the night scenery. The official subtitle of this event is “Fragments – What has been preserved and what will be preserved,” and it is an event designed to allow people to experience cultural heritage at night by utilizing the various national heritage and historical and cultural resources remaining in Gyeongju.'),
    (263, 'story', '주요 행사 장소는 월정교, 계림, 교촌마을, 경주읍성 일원이다.
특히 신라 시대의 역사적 장소와 경주의 대표적인 문화유산이 행사 공간으로 활용된다는 점이 특징이다.
행사에서는 국가유산을 배경으로 야간 경관을 감상하고 역사와 전통문화를 체험할 수 있는 다양한 프로그램이 운영된다.', 'The main event locations are Woljeong Bridge, Gyerim, Gyochon Village, and Gyeongju-eupseong Fortress.
In particular, it is characterized by the fact that historical places from the Silla period and representative cultural heritage of Gyeongju are used as event spaces.
At the event, a variety of programs will be operated where you can enjoy the night view and experience history and traditional culture against the backdrop of national heritage.'),
    (263, 'tip', '경주 국가유산야행은 해가 지기 직전 도착하면 낮 풍경과 조명이 켜지는 순간을 함께 볼 수 있어요. 완전히 어두워지기 전 동선을 익혀두면 사진과 산책을 더 여유롭게 즐길 수 있어요.', 'If you arrive at the Gyeongju National Heritage Night Tour just before sunset, you can see both the daytime scenery and the moment the lights turn on. If you learn the route before it gets completely dark, you can enjoy taking pictures and walking more leisurely.'),
    (263, 'did_you_know', '「2026 경주국가유산야행」은 경주의 역사와 문화유산을 밤의 풍경 속에서 만나볼 수 있는 행사이에요.', 'The 「2026 Gyeongju National Heritage Night Tour」 is an event where you can experience the history and cultural heritage of Gyeongju in the night scenery.'),
    (264, 'summary', '골굴암은 경주시 양북면에 위치한 국내 최초의 석굴사원으로 6세기 무렵 인도에서 온 광유선인 일행이 이곳에 있던 자연굴(타포니)을 이용하여 만든 것으로 알려져 있다.', 'Golgulam is Korea''s first cave temple located in Yangbuk-myeon, Gyeongju-si. It is known to have been built around the 6th century by a group of Gwangyu Seon-in from India using a natural cave (taponi) found here.'),
    (264, 'intro', '골굴암은 경주시 양북면에 위치한 국내 최초의 석굴사원으로 6세기 무렵 인도에서 온 광유선인 일행이 이곳에 있던 자연굴(타포니)을 이용하여 만든 것으로 알려져 있다. 골굴암 일대에 분포하는 안산암질 응회암은 한반도와 붙어있던 일본이 잡아당기는 힘으로 떨어져 나가면서 동해가 형성되었을 때 만들어졌다.', 'Golgulam is Korea''s first cave temple located in Yangbuk-myeon, Gyeongju-si. It is known to have been built around the 6th century by a group of Gwangyu Seon-in from India using a natural cave (taponi) found here. The andesite tuff distributed in the Golgulam area was created when Japan, which was attached to the Korean Peninsula, broke away due to the pulling force and the East Sea was formed.'),
    (264, 'story', '잡아당기는 힘은 골굴암 일대에 영향을 주어 땅이 벌어지게 되었고 벌어진 틈에 주변에 있던 화산퇴적물이 쌓이면서 안산암질 응회암이 만들어진 것이다.
비바람에 비교적 약해서 보다
쉽게 깎여 나가는 성질을 가지고 있다.', 'The pulling force affected the area around Golgulam Rock, causing the ground to open, and surrounding volcanic sediments piled up in the gap, creating andesitic tuff.
It appears to be relatively weak against wind and rain.
It has the property of being easily chipped.'),
    (264, 'tip', '골굴암 타포니 (경북 동해안 국가지질공원)에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Golgulam Taponi (Gyeongbuk East Coast National Geopark), the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (264, 'did_you_know', '골굴암은 경주시 양북면에 위치한 국내 최초의 석굴사원으로 6세기 무렵 인도에서 온 광유선인 일행이 이곳에 있던 자연굴(타포니)을 이용하여 만든 것으로 알려져 있어요.', 'Golgulam is Korea''s first cave temple located in Yangbuk-myeon, Gyeongju-si. It is said to have been built around the 6th century by a group of Gwangyu Seon-in from India using a natural cave (taponi) found here.'),
    (265, 'summary', '신라 제35대 경덕왕(재위 742∼765)의 무덤이라 전해지는 곳으로 경주 시가지에서 서남쪽으로 멀리 떨어진 구릉에 자리하고 있다.', 'It is said to be the tomb of King Gyeongdeok, the 35th king of Silla (reign 742-765), and is located on a hill far southwest of the city of Gyeongju.'),
    (265, 'intro', '신라 제35대 경덕왕(재위 742∼765)의 무덤이라 전해지는 곳으로 경주 시가지에서 서남쪽으로 멀리 떨어진 구릉에 자리하고 있다. 신라 왕실의 전제왕권이 쇠퇴하기 시작하는 시기에 왕위에 올라 행정구역과 관직제도를 개편했다.', 'It is said to be the tomb of King Gyeongdeok, the 35th king of Silla (reign 742-765), and is located on a hill far southwest of the city of Gyeongju. He ascended to the throne at a time when the absolute kingship of the Silla royal family was beginning to decline and reorganized the administrative district and official system.'),
    (265, 'story', '봉분은 둥근 모양이며 무덤 주위에 봉분을 보호하기 위한 둘레돌을 둘렀다.
둘레돌은 목조건축물의 돌기단 같은 형태로 되어 있는데 바닥돌을 깔고 그 위에 면석을 둘렀다.
면석 사이에는 기둥 역할을 하는 탱석을 배치하였다.', 'The burial mound is round in shape and is surrounded by stones to protect it.
The circumference stone is shaped like a stone platform of a wooden building, and a floor stone is laid and a cotton stone is placed on top of it.
Between the face stones, tank stones were placed to act as pillars.'),
    (265, 'tip', '경주 경덕왕릉에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At Gyeongdeok Royal Tomb in Gyeongju, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (265, 'did_you_know', '신라 제35대 경덕왕(재위 742∼765)의 무덤이라 전해지는 곳으로 경주 시가지에서 서남쪽으로 멀리 떨어진 구릉에 자리하고 있어요.', 'It is said to be the tomb of King Gyeongdeok, the 35th king of Silla (reign 742-765), and is located on a hill far southwest of Gyeongju city.'),
    (266, 'summary', '경주 남산 서쪽 약간 경사진 지점에 있는 일성왕릉은 신라 제7대 일성왕(재위 134∼154)을 모신 곳이다.', 'The Royal Tomb of King Ilseong, located on a slightly sloping western side of Namsan Mountain in Gyeongju, is the shrine to King Ilseong, the 7th king of Silla (reigned 134-154).'),
    (266, 'intro', '경주 남산 서쪽 약간 경사진 지점에 있는 일성왕릉은 신라 제7대 일성왕(재위 134∼154)을 모신 곳이다. 봉분의 높이 7m, 직경 10m이며 하단에는 석축을 쌓았다.', 'The Royal Tomb of King Ilseong, located on a slightly sloping western side of Namsan Mountain in Gyeongju, is the shrine to King Ilseong, the 7th king of Silla (reigned 134-154). The burial mound is 7m high and 10m in diameter, and a stone wall is built at the bottom.'),
    (266, 'story', '봉분 전면에는 자연석으로 쌓은 호석으로 보이는 석열이 있고 봉분 주위에도 그러한 돌을 돌렸던 듯하다.
중단의 석상은 후세에 설치한 것이며 그 뒤에는 장대석으로 얕은 1단의 석축이 있으나 이것은 석상을 놓으면서 쌓은 듯하다.
하단의 석축은 잡석으로 쌓았는데 이것도 후세에 손댄 것으로 보인다.', 'In front of the burial mound, there is a row of stones that appear to be made of natural stones, and it appears that such stones were also placed around the mound.
The stone statue in the middle was installed later, and behind it there is a shallow single-tier stone wall made of pole stones, which appears to have been built while the stone statue was placed.
The stone walls at the bottom were made of rubble, and this also appears to have been retouched in later generations.'),
    (266, 'tip', '경주 일성왕릉에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At the Royal Tomb of King Ilseong in Gyeongju, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (266, 'did_you_know', '경주 남산 서쪽 약간 경사진 지점에 있는 일성왕릉은 신라 제7대 일성왕(재위 134∼154)을 모신 곳이에요.', 'The Royal Tomb of King Ilseong, located on a slightly sloping western side of Namsan Mountain in Gyeongju, is the shrine to King Ilseong, the 7th king of Silla (reigned 134-154).'),
    (267, 'summary', '신라 천년고도 경주 보문관광단지 내에 위치한 호텔이다.', 'This hotel is located within the Bomun Tourist Complex in Gyeongju, the Millennium Ancient Town of Silla.'),
    (267, 'intro', '더케이경주호텔 스파온천은 신라 천년고도 경주 보문관광단지 내에 위치한 호텔이다. 호텔은 2001년 6월에 개장하였으며 스파월드는 사우나, 노천탕, 헬스, 수영장 등의 시설이 있다.', 'The K Gyeongju Hotel Spa Hot Springs is a hotel located within the Bomun Tourist Complex in Gyeongju, the 1,000-year old town of Shilla. The hotel opened in June 2001, and Spa World has facilities such as a sauna, open-air bath, gym, and swimming pool.'),
    (267, 'story', '자체 개발한 온천수는 지하 630m에서 용출되는 100% 천연 온천수로 1일 900톤의 풍부한 온천자원을 보유하고 있으며 높은 온도와 구성 암석의 용해 및 유화수소의 혼입으로 천연 나트륨, 염소, 유화 성분이 함유된 천연 알칼리성 온천으로 유명하다.
또한 장치를 통하여 물속의 중금속과 불순물을 제거하여 류머티즘, 신경통, 근육통, 피부병, 노화 방지에 효험이 있는 것으로 알려져 있다.
오늘의 더케이경주호텔 스파온천은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'The self-developed hot spring water is 100% natural hot spring water that gushes out from 630m underground, and has abundant hot spring resources of 900 tons per day. It is famous as a natural alkaline hot spring containing natural sodium, chlorine, and emulsified components due to high temperature, dissolution of constituent rocks, and mixing of hydrogen emulsification.
It is also known to be effective in preventing rheumatism, neuralgia, muscle pain, skin disease, and aging by removing heavy metals and impurities in the water through the device.
Today’s spa at The K Gyeongju Hotel leaves a different memory for each person who visits Gyeongju.'),
    (267, 'tip', '더케이경주호텔 스파온천에서 물놀이를 계획한다면 운영 여부와 이용 조건을 먼저 확인하세요. 젖은 뒤 갈아입을 옷과 수건, 미끄럼 방지 신발을 챙기면 한결 편해요.', 'If you plan to take a dip in the spa at The K Gyeongju Hotel, check the operation status and usage conditions first. It will be much more comfortable if you bring a change of clothes after getting wet, a towel, and non-slip shoes.'),
    (267, 'did_you_know', '호텔은 2001년 6월에 개장하였으며 스파월드는 사우나, 노천탕, 헬스, 수영장 등의 시설이 있어요.', 'The hotel opened in June 2001, and Spa World has facilities such as a sauna, open-air bath, gym, and swimming pool.'),
    (268, 'summary', '경주시 충효동 옥녀봉 능선에 위치한 김유신 장군의 묘로 674년(문무왕 14) 축조되었다.', 'This is the tomb of General Kim Yu-sin, located on the ridge of Oknyebong Peak in Chunghyo-dong, Gyeongju, and was built in 674 (the 14th year of King Munmu''s reign).'),
    (268, 'intro', '경주시 충효동 옥녀봉 능선에 위치한 김유신 장군의 묘로 674년(문무왕 14) 축조되었다. 김유신은 신라의 장군이자 재상으로 삼국을 통일한 공로가 컸으므로 문무왕은 비단 1,000필, 벼 2,000석을 내리고 군악고취 100명을 보내어 장사를 지내게 하며 비를 세워 공적을 새겨두고 수묘하는 백성을 배정해 주는 등 최고의 예를 베풀었다.', 'This is the tomb of General Kim Yu-sin, located on the ridge of Oknyebong Peak in Chunghyo-dong, Gyeongju, and was built in 674 (the 14th year of King Munmu''s reign). As Kim Yu-sin was a general and prime minister of Silla, his contribution to unifying the three kingdoms was great, so King Munmu gave him 1,000 rolls of silk and 2,000 kok of rice, sent 100 military musicians to his funeral, erected a monument inscribed on his achievements, and assigned people to mourn him.'),
    (268, 'story', '후에 흥덕왕대에 그를 흥무대왕으로 추봉하였다.
봉분은 30m에 달하는 큰 원형분으로 둘레에는 24장의 호석과 돌난간을 둘렀고 호석과 돌난간 사이의 바닥에는 돌을 깔았다.
그 무덤의 양식 또한 왕릉이나 다름없는 규모와 형태이다.', 'Later, during the reign of King Heungdeok, he was honored as King Heungmu.
The burial mound is a large circular mound measuring 30 meters, with 24 stones and a stone railing surrounding it, and stones were laid on the floor between the stones and the stone railing.
The style of the tomb is also similar in size and shape to that of a royal tomb.'),
    (268, 'tip', '경주 김유신묘에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At Kim Yu-sin''s Tomb in Gyeongju, walk around comparing the sizes and spacing of the burial mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (268, 'did_you_know', '경주시 충효동 옥녀봉 능선에 위치한 김유신 장군의 묘로 674년(문무왕 14) 축조되었다고 해요.', 'It is said to be the tomb of General Kim Yu-sin, located on the ridge of Oknyebong Peak in Chunghyo-dong, Gyeongju, and was built in 674 (14th year of King Munmu''s reign).'),
    (269, 'summary', '경주 양동마을 내에 위치한 무첨당은 조선시대 성리학자이며 문신이었던 회재 이언적(1491∼1553)의 종가의 일부로 조선 중기에 세운 건물이다.', 'Mucheomdang, located in Yangdong Village, Gyeongju, is a building built in the mid-Joseon Dynasty as part of the head house of Hoejae Lee Eon-jeok (1491-1553), a Neo-Confucian scholar and civil servant during the Joseon Dynasty.'),
    (269, 'intro', '경주 양동마을 내에 위치한 무첨당은 조선시대 성리학자이며 문신이었던 회재 이언적(1491∼1553)의 종가의 일부로 조선 중기에 세운 건물이다. 앞면 5칸·옆면 2칸 규모로 건물 내부를 세 부분으로 구분하여, 가운데 3칸은 대청이고 좌우 1칸씩은 온돌방이다.', 'Mucheomdang, located in Yangdong Village, Gyeongju, is a building built in the mid-Joseon Dynasty as part of the head house of Hoejae Lee Eon-jeok (1491-1553), a Neo-Confucian scholar and civil servant during the Joseon Dynasty. The interior of the building is divided into three parts, with 5 rooms on the front and 2 rooms on the sides. The three rooms in the middle are the main hall and one room on each side is an ondol room.'),
    (269, 'story', '대청은 앞면 기둥 사이를 개방하고 누마루에서도 대청을 향한 쪽은 개방되어 있으며 뒤쪽과 옆면은 벽을 쳐서 문짝을 달았다.
평면은 ㄱ자형을 띠고 있고 둥근 기둥과 네모기둥을 세워 방과 마루를 배치하고 있다.
이 건물의 기능은 상류주택에 속해있는 사랑채의 연장 건물로 손님접대, 쉼터, 책읽기를 즐기는 등 여러 용도로 사용되던 곳이다.', 'The space between the front pillars of the main hall is open, and the side facing the main hall of the numaru is open, and the back and sides have walls and doors.
The floor plan is L-shaped, and the rooms and floors are arranged with round and square pillars.
The function of this building is that it is an extension of the sarangchae belonging to an upper-class residence and was used for various purposes such as entertaining guests, resting, and reading books.'),
    (269, 'tip', '경주 양동 무첨당을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Yangdong Mucheomdang in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (269, 'did_you_know', '경주 양동마을 내에 위치한 무첨당은 조선시대 성리학자이며 문신이었던 회재 이언적(1491∼1553)의 종가의 일부로 조선 중기에 세운 건물이에요.', 'Mucheomdang, located in Yangdong Village, Gyeongju, is a building built in the mid-Joseon Dynasty as part of the head house of Hoejae Lee Eon-jeok (1491-1553), a Neo-Confucian scholar and civil servant during the Joseon Dynasty.'),
    (270, 'summary', '신라 42대 흥덕왕(재위 826∼836)의 무덤으로 지름 20.8m, 높이 6m로 신라 역대 왕릉 중에서 규모가 크고 형식이 완전히 갖추어진 대표적 왕릉이다.', 'This is the tomb of King Heungdeok, the 42nd king of Silla (reigned 826-836). With a diameter of 20.8m and a height of 6m, it is the largest and most fully formal royal tomb among all the royal tombs of Silla''s past.'),
    (270, 'intro', '신라 42대 흥덕왕(재위 826∼836)의 무덤으로 지름 20.8m, 높이 6m로 신라 역대 왕릉 중에서 규모가 크고 형식이 완전히 갖추어진 대표적 왕릉이다. 삼국사기와 삼국유사에 따르면 왕비와 합장한 것으로 되어 있어 봉분의 규모가 비교적 크다.', 'This is the tomb of King Heungdeok, the 42nd king of Silla (reigned 826-836). With a diameter of 20.8m and a height of 6m, it is the largest and most fully formal royal tomb among all the royal tombs of Silla''s past. According to the Samguk Sagi and Samguk Yusa, the burial mound is relatively large as it is said to have been buried jointly with the queen.'),
    (270, 'story', '봉분 밑에는 판석을 세워 둘레돌을 삼고, 판석과 판석 사이에 탱주를 세워 판석을 고정하였으며 위에 갑석을 얹었고 탱석에 각각 방향을 따라 십이지신상을 조각하였다.
둘레돌의 주변에 방사형으로 박석을 깔고 그 주위에 난간을 돌렸다.
난간 기둥에는 상하 2개의 둥근 구멍을 뚫어 관석을 끼우게 되어 있었는데 지금은 하나도 없다.', 'A flagstone was erected at the bottom of the burial mound to serve as a surrounding stone, and a tank was erected between the flagstones to secure the flagstone. A capstone was placed on top, and statues of the zodiac gods were carved into the tankstones along each direction.
Pebbles were laid radially around the circumference stone and a railing was built around it.
The railing pillar was supposed to have two round holes drilled at the top and bottom to insert the capstone, but now there are none.'),
    (270, 'tip', '경주 흥덕왕릉을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Heungdeok Royal Tomb in Gyeongju, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (270, 'did_you_know', '신라 42대 흥덕왕(재위 826∼836)의 무덤으로 지름 20.8m, 높이 6m로 신라 역대 왕릉 중에서 규모가 크고 형식이 완전히 갖추어진 대표적 왕릉이에요.', 'This is the tomb of King Heungdeok, the 42nd king of Silla (r. 826-836). With a diameter of 20.8m and a height of 6m, it is a representative royal tomb with a large scale and complete formality among all the royal tombs of Silla''s past.'),
    (271, 'summary', '신라의 시조 박혁거세가 태어난 전설을 간직한 우물이다.', 'It is a well that preserves the legend of the birth of Park Hyeokgeose, the founder of Silla.'),
    (271, 'intro', '신라의 시조 박혁거세가 태어난 전설을 간직한 우물이다. 박혁거세를 기리는 유허비를 비롯해 신궁터로 추정되는 팔각건물지, 우물지, 담장지, 부속건물지, 배수로 등이 남아 있다.', 'It is a well that preserves the legend of the birth of Park Hyeokgeose, the founder of Silla. In addition to the monument commemorating Park Hyeokgeose, the site of an octagonal building presumed to be the site of a shrine, a well, a fence, an annex building, and a drainage ditch remain.'),
    (271, 'story', '특히 팔각건물지는 한 변의 길이가 8m나 되고 네모난 담장을 두른 것으로 보아 신라의 신궁터로 추정되며 이곳 나정을 박혁거세를 제사 지내는 신전으로 짐작할 수 있다.
와 에 나정에 대해 다음과 같은 기록이 있다.
신라 건국의 주역인 6촌의 촌장들이 모여 군주를 선출하고 도읍을 정하자고 결정한 뒤 일행이 높은 곳에 올랐다.', 'In particular, the octagonal building site is believed to be the site of a shrine from Silla, as one side is 8m long and is surrounded by a square wall, and Najeong here can be assumed to be a shrine where Park Hyeokgeose is worshiped.
There are the following records about Najeong in and .
After the village chiefs of the six villages, the main players in the founding of Silla, gathered to elect a monarch and decide on a capital city, the group ascended to a high place.'),
    (271, 'tip', '경주 나정을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting Gyeongju Najeong, check the latest operating information and transportation information. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (271, 'did_you_know', '아이가 13살이 되던 해인 BC 57년 왕의 자리에 올라 나를 세우고 서라벌이라고 이름지었다고 해요.', 'It is said that in 57 BC, when the child was 13 years old, he ascended to the throne of King Seorabeol and named him Seorabeol.'),
    (272, 'summary', '신라의 금관이 출토되어 붙은 이름이다.', 'It is named after a gold crown from Silla that was excavated.'),
    (272, 'intro', '신라의 금관이 출토되어 붙은 이름이다. 1921년 9월 가옥공사 중 우연히 발견된 것인데, 이미 파괴된 고분인 데다', 'It is named after a gold crown from Silla that was excavated. It was accidentally discovered during house construction in September 1921, and the tomb had already been destroyed.'),
    (272, 'story', '정식으로 발굴조사된 것이 아니어서 묘의 구조나 유물의 정확한 상황은 밝혀지지 않았다.
출토물은 금관을 비롯하여 장신구·무구(武具)·용기 등이며, 특히 구슬 종류만 총 3만 개가 넘게 나왔다.
금관총의 원형은 지름이 50m, 높이 13m 정도이고, 신라 때만 있었던 돌무지무덤[積石塚]으로 알려져 있으며, 그 속에 덧널[木槨]을 마련하여 옻칠한 널 [木棺]이 있었던 것으로 추측한다.', 'Because it was not officially excavated, the structure of the tomb and the exact condition of the relics were not revealed.
The excavated items include gold crowns, accessories, weapons, and containers. In particular, a total of over 30,000 beads were found.
The original form of Geumgwanchong Tomb is about 50m in diameter and 13m in height, and is known to be a stone mound tomb that only existed during the Silla Dynasty. It is presumed that there was a lacquered wooden board in it.'),
    (272, 'tip', '금관총에서는 봉분을 한 곳씩 보기보다 크기와 간격을 비교하며 걸어보세요. 낮은 시선으로 능선과 하늘을 함께 담으면 고분의 부드러운 곡선이 더 잘 보여요.', 'At Geumgwanchong Tomb, walk around comparing the sizes and spacing of the mounds rather than looking at them one by one. If you capture the ridge and sky together from a low perspective, you can see the soft curves of the tomb better.'),
    (272, 'did_you_know', '1921년 9월 가옥공사 중 우연히 발견된 것인데, 이미 파괴된 고분인 데다', 'It was accidentally discovered during house construction in September 1921, and the tomb had already been destroyed.'),
    (273, 'summary', '경주시의 남쪽에 위치한 남산은 금오봉과 고위봉을 중심으로 한 긴 타원형의 화강암 바위산이다.', 'Namsan, located in the south of Gyeongju-si, is a long oval-shaped granite rock mountain centered on Geumobong and Gowibong peaks.'),
    (273, 'intro', '경주시의 남쪽에 위치한 남산은 금오봉과 고위봉을 중심으로 한 긴 타원형의 화강암 바위산이다. 화강암은 석재로 흔히 쓰이는 대리암이나 석회암에 비해 단단하고 비와 바람에 잘 깎여나가지 않는 특성을 가진다.', 'Namsan, located in the south of Gyeongju-si, is a long oval-shaped granite rock mountain centered on Geumobong and Gowibong peaks. Granite is harder than marble or limestone, which are commonly used as stones, and is resistant to wear and tear by rain and wind.'),
    (273, 'story', '따라서 남산의 수많은 문화재들이 오랜 시간 동안 잘 보존된 것은 화강암의 이러한 특성 덕분이라 할 수 있다.
그 뿐만 아니라 남산 화강암은 신라 문화를 대표하는 문화재로 손꼽히는 석가탑과 다보탑을 만들 때도 쓰였기 때문에 신라인들이 남산 화강암을 문화재의 재료로 많이 사용하였다는 것을 알 수 있다.
신라인들은 남산의 바위절벽을 이용하여 남산 문화재 중 으뜸으로 꼽히는 마애삼존불좌상, 선각여래좌상, 마애석가여래좌상과 같은 불상들을 만들었는데 이러한 바위 절벽은 남산 화강암에 흔히 잘 발달하는 수직 틈에 의해서 자연적으로 형성된 것이다.', 'Therefore, it can be said that it is thanks to these characteristics of granite that Namsan''s numerous cultural assets have been well preserved for a long time.
In addition, Namsan granite was used to build the Seokgatap and Dabotap pagodas, which are considered cultural assets representing Silla culture, so we can see that the Silla people used Namsan granite a lot as a material for cultural assets.
The Silla people used the rock cliffs of Namsan to create Buddha statues such as the Rock-carved Buddha Triad, Seongak Seated Buddha, and Rock-carved Buddha Seated Buddha, which are considered the best cultural assets of Namsan. These rock cliffs were naturally formed by vertical cracks that commonly develop in the Namsan granite.'),
    (273, 'tip', '남산 화강암 (경북 동해안 국가지질공원)에서는 바람과 파도에 따라 체감 환경이 크게 달라져요. 미끄럽지 않은 신발을 신고 안전한 탐방 구역을 이용하며, 수평선 쪽 빛이 부드러운 시간에 풍경을 감상해 보세요.', 'At Namsan Granite (Gyeongbuk East Coast National Geopark), the perceived environment varies greatly depending on the wind and waves. Wear non-slip shoes, use safe areas to explore, and enjoy the scenery when the light on the horizon is soft.'),
    (273, 'did_you_know', '남산에 분포하는 화강암이 특히 수직 틈을 많이 가지는 이유는 아주 오래 전 이 지역에 단층활동이 일어났기 때문으로 추정돼요.', 'It is presumed that the reason the granite distributed in Namsan especially has many vertical cracks is because fault activity occurred in this area a long time ago.'),
    (274, 'summary', '경주시 황남동에 위치한 교육기관으로, 창의적 발명 교육과 체험을 통해 학생들의 창의력과 융합적 사고를 키우는 것을 목표로 한다.', 'It is an educational institution located in Hwangnam-dong, Gyeongju-si, and aims to foster students'' creativity and convergent thinking through creative invention education and experience.'),
    (274, 'intro', '경상북도교육청 발명체험교육관은 경주시 황남동에 위치한 교육기관으로, 창의적 발명 교육과 체험을 통해 학생들의 창의력과 융합적 사고를 키우는 것을 목표로 한다. 다양한 체험 프로그램과 전시를 제공하며, 미래 인재 양성을 위한 교육의 장으로 활용되고 있다.', 'The Gyeongsangbuk-do Office of Education Invention Experience Education Center is an educational institution located in Hwangnam-dong, Gyeongju-si, and aims to foster students'' creativity and convergent thinking through creative invention education and experience. It offers a variety of experience programs and exhibitions, and is used as an educational venue to nurture future talent.'),
    (274, 'story', '이곳은 주변의 풍경과 어우러져 방문객에게 특별한 장면을 보여줍니다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
오늘의 경상북도교육청 발명체험교육관은 경주를 찾는 사람들에게 저마다 다른 기억으로 남습니다.', 'This place blends in with the surrounding landscape and presents a special scene to visitors.
If you slowly look at the characteristics of a place, the meaning of your trip becomes clearer.
Today''s Gyeongsangbuk-do Office of Education Invention Experience Center leaves a different memory for each person who visits Gyeongju.'),
    (274, 'tip', '경상북도교육청 발명체험교육관을 방문하기 전 최신 운영 정보와 이동 방법을 확인하세요. 현장 안내판을 먼저 읽고 주변까지 천천히 걸으면 이 장소만의 특징을 더 쉽게 발견할 수 있어요.', 'Before visiting the Gyeongsangbuk-do Office of Education Invention Experience Education Center, check the latest operating information and transportation methods. If you read the on-site information board first and walk slowly around the area, you can more easily discover the unique features of this place.'),
    (274, 'did_you_know', '경상북도교육청 발명체험교육관은 경주시 황남동에 위치한 교육기관으로, 창의적 발명 교육과 체험을 통해 학생들의 창의력과 융합적 사고를 키우는 것을 목표로 해요.', 'The Gyeongsangbuk-do Office of Education''s Invention Experience Education Center is an educational institution located in Hwangnam-dong, Gyeongju-si. Its goal is to foster students'' creativity and convergent thinking through creative invention education and experience.'),
    (275, 'summary', '경주 내 대표적인 번화가로 롯데시네마, 메가박스 등 영화관과 다수의 프랜차이즈 상점, 음식점, 의류 판매점이 위치해있으며 버스킹, 퍼포먼스 공연 등 다양한 즐길거리와 볼거리 및 넓은 공영주차장, 쾌적한 숙박시설 등이 위치한 관광에 특화된 상권이다.', 'It is a representative downtown area in Gyeongju and is home to movie theaters such as Lotte Cinema and Megabox, as well as a number of franchise stores, restaurants, and clothing stores. It is a commercial district specialized in tourism with a variety of things to enjoy and see, such as busking and performance performances, as well as a spacious public parking lot and comfortable accommodations.'),
    (275, 'intro', '경주 내 대표적인 번화가로 롯데시네마, 메가박스 등 영화관과 다수의 프랜차이즈 상점, 음식점, 의류 판매점이 위치해있으며 버스킹, 퍼포먼스 공연 등 다양한 즐길거리와 볼거리 및 넓은 공영주차장, 쾌적한 숙박시설 등이 위치한 관광에 특화된 상권이다. 또한 경주 대표 관광지인 봉황대, 천마총 등 다양한 유적지와 인접해있으며 경주 관광 단지 중앙에 위치하여 경주 시외버스 터미널과 신경주역, 기타 다양한 관광 유적지들 방문에 용이한 상권이다.', 'It is a representative downtown area in Gyeongju and is home to movie theaters such as Lotte Cinema and Megabox, as well as a number of franchise stores, restaurants, and clothing stores. It is a commercial district specialized in tourism with a variety of things to enjoy and see, such as busking and performance performances, as well as a spacious public parking lot and comfortable accommodations. In addition, it is adjacent to various historical sites such as Bonghwangdae and Cheonmachong, which are representative tourist attractions in Gyeongju, and is located in the center of the Gyeongju tourist complex, making it a convenient commercial area for visiting the Gyeongju intercity bus terminal, Singyeongju Station, and various other tourist sites.'),
    (275, 'story', '이곳은 주변의 풍경과 어우러져 방문객에게 특별한 장면을 보여줍니다.
장소에 담긴 특징을 천천히 살펴보면 여행의 의미가 더욱 선명해집니다.
